/* ============================================================
   Numbers of Magic — 스킬 스레드 표준 레지스트리 (계약 파일)
   CURRICULUM_DESIGN.md §2 의 스레드 체계를 코드로 고정한다.
   - gen: engine/threads/*.js 가 window.NM_TGEN[gen]으로 구현해야 하는 키
   - prereq: 전제 스레드 (진입 시 mastery 확인 → 워밍업 "안내", 잠금 아님)
   - widgets: 허용 위젯, 맨 앞이 그 스레드 레벨1의 기본 위젯
     (구체물 → 기호 → 암산: cubes/array → steps → numpad 순 추상화)
   - levels: 수 범위 단계. 시험/인쇄에서 레벨 선택으로 범위 확장.
   생성기 계약(엄수): NM_TGEN[gen] = (params, rng) => problem
     · Math.random 사용 금지 — 반드시 주입된 rng만 사용 (인쇄 재현성)
     · prompt는 {ko,en,zh} 3개 언어 필수, 수치는 문자열에 포함
     · steps의 blank는 항상 정수 (분수·소수도 정수 빈칸으로 분해)
   ============================================================ */
(function(){
'use strict';

window.NM_THREADS = {

/* ── NS 수 감각 ───────────────────────────── */
/* 유아(수의 나라)와 초등의 이음매(2026-09-19) — NS1·NS2 의 선수가 비어 있어, 데이터상
   과정 0(유아)과 과정 1(초등)이 아무 연결고리 없이 따로 서 있었다. 유아 과정을 끝내고
   무엇으로 이어지는지가 어디에도 안 적혀 있던 것이다. prereq 는 잠그는 장치가 아니라
   사다리의 순서를 적어 두는 자리다(앱은 이 값으로 아무것도 막지 않는다 — 책·레벨은 자유
   선택 원칙 그대로). check-ladder.js 가 이 순서를 지킨다. */
NS1:{ name:{ko:'자릿값 읽기',en:'Place Value',zh:'位值'}, gen:'ns1_placeValue', prereq:['NL1','NL4'],
  concept:{ko:'수는 서 있는 자리에 따라 크기가 달라져요. 472에서 4는 백의 자리라 400을, 7은 십의 자리라 70을 뜻해요.',
    en:'A digit means a different amount depending on its place. In 472 the 4 sits in the hundreds place, so it means 400.',
    zh:'数字所在的位置决定它的大小。472中的4在百位，表示400；7在十位，表示70。'},
  widgets:['missing','base10','numpad'],
  levels:[{id:1,label:{ko:'두세 자리',en:'2-3 digits',zh:'两三位'},params:{max:999}},
          {id:2,label:{ko:'네 자리',en:'4 digits',zh:'四位'},params:{max:9999}},
          {id:3,label:{ko:'큰 수',en:'Big numbers',zh:'大数'},params:{max:99999}},
          /* 과정-로드맵.md §4 다함식 위젯 — 십진블록(백판·십막대·낱개)으로 수 읽기.
             2026-08-27 Phase 3 신규. */
          {id:4,label:{ko:'십진블록 읽기',en:'Read base-10 blocks',zh:'读十进制方块'},params:{mode:'base10'},
           concept:{ko:'십진블록은 백 판·십 막대·낱개를 세어 자릿값을 더해요 — 200+50+4는 254예요.',
             en:'With base-ten blocks, count the hundred-flats, ten-rods and ones and add their place values: 200+50+4 is 254.',
             zh:'十进制方块要数百板、十条和单个，再把位值相加：200+50+4是254。'}}] },
NS2:{ name:{ko:'모으기·가르기',en:'Compose & Split',zh:'合与分'}, gen:'ns2_split', prereq:['NL2'],
  concept:{ko:'두 수를 모으면 하나가 되고, 한 수를 둘로 가를 수 있어요. 3과 4를 모으면 7, 7은 3과 4로 갈라져요.',
    en:'Two numbers join into one, and one number splits into two. 3 and 4 make 7, and 7 splits into 3 and 4.',
    zh:'两个数合起来成为一个数，一个数也能分成两个。3和4合成7，7可以分成3和4。'},
  widgets:['cubes','split','numpad'],
  levels:[{id:1,label:{ko:'5까지',en:'to 5',zh:'到5'},params:{max:5}},
          {id:2,label:{ko:'9까지',en:'to 9',zh:'到9'},params:{max:9}}] },
NS3:{ name:{ko:'보수 5·10',en:'Bonds of 5 & 10',zh:'5和10的组成'}, gen:'ns3_comp510', prereq:['NS2'],
  concept:{ko:'더해서 5나 10이 되는 짝을 외워 두면 셈이 빨라져요. 5의 짝은 1과 4, 2와 3 / 10의 짝은 1과 9, 2와 8, 3과 7, 4와 6이에요.',
    en:'Memorize the pairs that make 5 or 10 and adding gets much faster. For 5: 1 and 4, 2 and 3. For 10: 1 and 9, 2 and 8, 3 and 7, 4 and 6.',
    zh:'记住凑5和凑10的数对，计算就会变快。凑5：1和4、2和3；凑10：1和9、2和8、3和7、4和6。'},
  widgets:['tenframe','cubes','numpad'],
  levels:[{id:1,label:{ko:'보수 5',en:'bonds of 5',zh:'凑5'},params:{target:5}},
          {id:2,label:{ko:'보수 10',en:'bonds of 10',zh:'凑10'},params:{target:10}}] },
NS4:{ name:{ko:'보수 100·1000',en:'Bonds of 100/1000',zh:'凑100/1000'}, gen:'ns4_comp100', prereq:['NS3','NS1'],
  concept:{ko:'100이나 1000을 채우는 짝도 같은 방법이에요. 100의 짝은 십의 자리끼리 더해 9, 일의 자리끼리 더해 10이 돼요. 37과 63처럼요.',
    en:'Pairs that fill 100 or 1000 work the same way. For 100 the tens add to 9 and the ones add to 10, like 37 and 63.',
    zh:'凑100和凑1000也是同样的方法。凑100时十位相加得9、个位相加得10，比如37和63。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'보수 100(몇십)',en:'100 by tens',zh:'凑100(几十)'},params:{target:100,step:10}},
          {id:2,label:{ko:'보수 100',en:'bonds of 100',zh:'凑100'},params:{target:100,step:1}},
          {id:3,label:{ko:'보수 1000',en:'bonds of 1000',zh:'凑1000'},params:{target:1000,step:1}}] },
NS5:{ name:{ko:'두 배 수(twin)',en:'Doubles',zh:'翻倍数'}, gen:'ns5_twin', prereq:['AD1'],
  concept:{ko:'같은 수를 두 번 더한 것이 두 배 수예요. 6+6=12를 알면 6+7은 그보다 1 큰 13이라고 바로 알 수 있어요.',
    en:'A double is the same number added twice. Once you know 6+6=12, you know 6+7 is one more, 13.',
    zh:'同一个数加两次就是翻倍数。知道6+6=12，就能立刻知道6+7比它多1，是13。'},
  widgets:['cubes','numpad'],
  levels:[{id:1,label:{ko:'1~10',en:'1-10',zh:'1~10'},params:{min:1,max:10}},
          {id:2,label:{ko:'15~95(몇십몇)',en:'15-95',zh:'15~95'},params:{min:15,max:95}}] },

/* ── AD 덧셈 ───────────────────────────── */
AD1:{ name:{ko:'한 자리 덧셈(올림×)',en:'1-digit + (no carry)',zh:'一位加法(不进位)'}, gen:'ad1_add1d', prereq:['NS2'],
  concept:{ko:'두 수를 더해도 10을 넘지 않는 덧셈이에요. 구슬을 이어 세듯 하나씩 세어 보면 답이 보여요. 3+2=5예요.',
    en:'Adding where the total stays under 10. Count on like joining beads and the answer appears. 3+2=5.',
    zh:'两数相加不超过10的加法。像串珠子一样接着数，答案就出来了。3+2=5。'},
  widgets:['cubes','numpad'],
  levels:[{id:1,label:{ko:'합 9까지',en:'sum ≤9',zh:'和≤9'},params:{maxSum:9}}] },
AD2:{ name:{ko:'받아올림 덧셈(한 자리)',en:'1-digit + (carry)',zh:'一位加法(进位)'}, gen:'ad2_addCarry1d', prereq:['NS3','AD1'],
  concept:{ko:'합이 10을 넘으면 먼저 10을 만들어요. 8+5는 8에 2를 주어 10을 만들고, 남은 3을 더해 13이에요.',
    en:'When the sum passes 10, make a ten first. For 8+5, give 2 to the 8 to make 10, then add the leftover 3 to get 13.',
    zh:'和超过10时先凑十。8+5先给8一个2凑成10，再加剩下的3，得13。'},
  widgets:['cubes','steps','tenframe','numpad'],
  levels:[{id:1,label:{ko:'한 자리',en:'1-digit',zh:'一位'},params:{}},
          {id:2,label:{ko:'세 수',en:'3 numbers',zh:'三个数'},params:{terms:3}}] },
AD3:{ name:{ko:'두 자리+한 자리',en:'2-digit + 1-digit',zh:'两位加一位'}, gen:'ad3_add2d1d', prereq:['AD2','NS1'],
  concept:{ko:'일의 자리끼리 먼저 더하고, 10이 넘으면 십의 자리로 1을 올려요. 27+5는 7+5=12이므로 30+2=32예요.',
    en:'Add the ones first, and carry 1 to the tens when they pass 10. For 27+5, since 7+5=12, the answer is 30+2=32.',
    zh:'先加个位，超过10就向十位进1。27+5中7+5=12，所以是30+2=32。'},
  widgets:['steps','base10','numpad'],
  levels:[{id:1,label:{ko:'올림×',en:'no carry',zh:'不进位'},params:{carry:false},
           concept:{ko:'일의 자리 합이 9를 넘지 않으면 십의 자리는 그대로예요. 32+5는 2+5=7이라 37 — 올릴 것이 없어요.',
             en:'If the ones add to 9 or less the tens do not change: 32+5 gives 2+5=7, so 37 — nothing to carry.',
             zh:'个位相加不超过9时十位不变：32+5中2+5=7，得37——没有要进的位。'}},
          {id:2,label:{ko:'올림',en:'carry',zh:'进位'},params:{carry:true},
           concept:{ko:'일의 자리 합이 10을 넘으면 10을 십의 자리로 보내요. 27+5는 7+5=12라 2를 쓰고 십의 자리를 하나 올려 32예요.',
             en:'When the ones pass 10, send that ten up: 27+5 gives 7+5=12, write 2 and the tens go up by one — 32.',
             zh:'个位相加满10就把这个十送到十位：27+5中7+5=12，写2、十位加1，得32。'}},
          {id:3,label:{ko:'세 자리+한 자리',en:'3d+1d',zh:'三位加一位'},params:{carry:true,threeDigit:true}},
          /* §4 다함식 위젯 — 십진블록으로 두 수 더하기(올림=새 십막대로 묶임을 눈으로 봄).
             2026-08-27 Phase 3 신규. */
          {id:4,label:{ko:'십진블록 더하기',en:'Add with base-10 blocks',zh:'用十进制方块相加'},params:{mode:'base10'},
           concept:{ko:'십진블록 그림에서 낱개끼리 먼저 모아요. 10개가 되면 막대 하나로 묶어 십의 자리로 보내요 — 76+8은 낱개 14개 중 10개를 묶어 84예요.',
             en:'On the block picture, gather the single cubes first; ten of them become one rod that moves to the tens. 76+8 makes 14 singles, so ten of them bundle up to give 84.',
             zh:'在方块图里先把单个的凑在一起，满10个就捆成一根移到十位——76+8是14个单个，把其中10个捆起来就是84。'}},
          {id:5,label:{ko:'가로셈(올림)',en:'horizontal, with carry',zh:'横式(进位)'},params:{carry:true,orient:'h'},
           concept:{ko:'가로로 쓰인 식도 일의 자리부터예요. 47+8은 47에 3을 더해 50을 만들고 남은 5를 더해 55 — 10을 만들어 넘어가는 길이 가로셈에서 빠릅니다.',
             en:'A horizontal sum still starts at the ones: for 47+8, add 3 to make 50 and the remaining 5 gives 55 — making a ten first is quickest written across.',
             zh:'横式也从个位开始：47+8先加3凑成50，再加剩下的5得55——横式先凑十最快。'}},
          {id:6,label:{ko:'세로셈(올림)',en:'column, with carry',zh:'竖式(进位)'},params:{carry:true,orient:'v'},
           concept:{ko:'세로로 쓸 때는 한 자리 수를 일의 자리 아래에 맞춰 써요. 7+8=15라 5를 쓰고 1을 십의 자리 위에 올려 적습니다.',
             en:'In column form put the single digit under the ones. 7+8=15, so write 5 and put the carried 1 above the tens.',
             zh:'竖式要把一位数写在个位下面。7+8=15，写5并把进位的1写在十位上方。'}}] },
AD4:{ name:{ko:'몇십·몇백 덧뺄',en:'Tens & hundreds ±',zh:'整十整百加减'}, gen:'ad4_addTens', prereq:['NS1'],
  concept:{ko:'뒤의 0을 잠시 떼고 앞의 수만 계산한 뒤 0을 다시 붙여요. 40+30은 4+3=7이니 70이에요.',
    en:'Set the zeros aside, add the front numbers, then put the zeros back. For 40+30, 4+3=7, so the answer is 70.',
    zh:'先把末尾的0放一边，只算前面的数，再把0补回去。40+30中4+3=7，所以是70。'},
  widgets:['steps','numline','numpad'],
  levels:[{id:1,label:{ko:'몇십±몇십(올림 없음)',en:'tens, no carry',zh:'几十(不进位)'},params:{unit:10},
           concept:{ko:'0을 떼고 앞의 수만 더하면 돼요. 40+30은 4+3=7이니 70이에요. 앞의 수를 더해 10이 넘지 않으니 올릴 것이 없어요.',
             en:'Drop the zero and add the front numbers: 40+30 is 4+3=7, so 70. The fronts stay under 10, so nothing carries.',
             zh:'去掉0只加前面的数：40+30是4+3=7，所以是70。前面的数不到10，不用进位。'}},
          {id:2,label:{ko:'몇십+몇십(올림)',en:'tens with carry',zh:'几十(进位)'},params:{unit:10,carry:true},
           concept:{ko:'앞의 수를 더해 10이 넘으면 백의 자리가 생겨요. 70+50은 7+5=12이니 120이에요. 12의 1이 백의 자리로 올라간 거예요.',
             en:'When the fronts add past 10 a hundreds digit appears: 70+50 is 7+5=12, so 120 — the 1 of 12 has moved up to the hundreds.',
             zh:'前面的数相加超过10就出现百位：70+50是7+5=12，所以是120，12的1进到百位。'}},
          {id:3,label:{ko:'몇백±몇백',en:'hundreds',zh:'几百'},params:{unit:100},
           concept:{ko:'0을 두 개 떼고 계산한 뒤 다시 붙여요. 300+400은 3+4=7이니 700이에요.',
             en:'Set two zeros aside, add, then put them back: 300+400 is 3+4=7, so 700.',
             zh:'把两个0放一边再算，然后补回去：300+400是3+4=7，所以是700。'}},
          {id:4,label:{ko:'몇백+몇백(올림)',en:'hundreds with carry',zh:'几百(进位)'},params:{unit:100,carry:true},
           concept:{ko:'앞의 수가 10을 넘으면 천의 자리가 생겨요. 700+500은 7+5=12이니 1200이에요.',
             en:'If the fronts pass 10 a thousands digit appears: 700+500 is 7+5=12, so 1200.',
             zh:'前面的数超过10就出现千位：700+500是7+5=12，所以是1200。'}},
          /* §4 다함식 위젯 — 수직선 점프(+n씩 뛰어세기, 두 자리 범위). 유아 nl2_seq의
             칩 나열을 실제 점프 아치로 확장한 독립 위젯. 2026-08-27 Phase 3 신규. */
          {id:5,label:{ko:'수직선 점프',en:'Number-line hops',zh:'数轴跳跃'},params:{mode:'numline'},
           concept:{ko:'수직선을 같은 간격으로 뛰어요. 앞뒤 수의 차를 보면 한 번에 몇씩 뛰는지 알 수 있어요 — 33·□·37이면 2씩 뛰니 35예요.',
             en:'Jump along the number line in equal steps: the gap between the numbers tells you the step — 33, □, 37 steps by 2, so 35.',
             zh:'在数轴上等距离地跳：看前后两数的差就知道每次跳几——33、□、37是每次跳2，所以是35。'}}] },
AD9:{ name:{ko:'10 이용 덧셈(보정 전략)',en:'Compensation Addition (use 10)',zh:'借助10的加法(补偿策略)'}, gen:'ad9_compAdd', prereq:['AD3'],
  concept:{ko:'9나 11을 더할 땐 10을 먼저 더하고 살짝 빼거나 더해요. 24+9는 24+10-1, 24+11은 24+10+1이에요.',
    en:'Adding 9 or 11? Add 10 first, then nudge back or forward. 24+9 = 24+10-1, and 24+11 = 24+10+1.',
    zh:'加9或11时，先加10再稍微减或加一点。24+9=24+10-1，24+11=24+10+1。'},
  widgets:['compareSteps','steps','numpad'],
  levels:[{id:1,label:{ko:'나란히 비교',en:'side by side',zh:'并排比较'},params:{mode:'compare'},
           concept:{ko:'먼저 10을 더한 다음, 10과의 차이만큼 덜어내거나 더해요. 62+9는 62+10=72에서 1을 빼 71, 17+12는 17+10=27에 2를 더해 29예요.',
             en:'Add 10 first, then take off (or put on) the gap to 10. 62+9 is 62+10=72 minus 1, so 71; 17+12 is 17+10=27 plus 2, so 29.',
             zh:'先加10，再按与10的差减去或加上。62+9是62+10=72再减1得71；17+12是17+10=27再加2得29。'}},
          {id:2,label:{ko:'암산 단계',en:'mental steps',zh:'心算步骤'},params:{mode:'abstract'},
           concept:{ko:'그림 없이 머릿속으로 해요. 10을 더한 뒤 10과의 차이만큼 덜거나 더해요 — 48+12는 48+10=58에 2를 더해 60이에요.',
             en:'Do it in your head without the picture: add 10, then adjust by the gap to 10 — 48+12 is 48+10=58 plus 2, so 60.',
             zh:'不用图在心里算：先加10，再按与10的差调整——48+12是48+10=58再加2，得60。'}}] },
AD5:{ name:{ko:'두 자리+두 자리',en:'2d + 2d',zh:'两位加两位'}, gen:'ad5_add2d2d', prereq:['AD3','AD4'],
  concept:{ko:'자리를 맞춰 일의 자리부터 더하고, 10이 넘을 때마다 윗자리로 1을 올려요. 47+38은 47+30=77에 8을 더해 85예요.',
    en:'Line up the places, add from the ones, and carry 1 up each time you pass 10. For 47+38, 47+30=77, then add 8 to get 85.',
    zh:'对齐数位，从个位开始加，每超过10就向上一位进1。47+38先算47+30=77，再加8得85。'},
  widgets:['steps','vertical','numpad'],
  levels:[{id:1,label:{ko:'올림 없음',en:'no carry',zh:'不进位'},params:{carries:0},
           concept:{ko:'올림이 없으면 자리끼리 그냥 더하면 끝이에요. 23+45는 일의 자리 3+5=8, 십의 자리 2+4=6이라 68이에요. 윗자리로 보낼 것이 없어요.',
             en:'With no carry you just add each place: 23+45 gives ones 3+5=8 and tens 2+4=6, so 68. Nothing moves up a place.',
             zh:'不进位时各位直接相加：23+45个位3+5=8，十位2+4=6，所以是68。没有要进到上一位的数。'}},
          {id:2,label:{ko:'일의 자리 올림',en:'carry from the ones',zh:'个位进位'},params:{carries:1},
           concept:{ko:'일의 자리 합이 10을 넘으면 10을 묶어 십의 자리로 1을 올려요. 47+38은 7+8=15라 5를 쓰고 1을 올려, 4+3+1=8 → 85예요.',
             en:'When the ones pass 10, bundle the ten and carry 1 to the tens: 47+38 gives 7+8=15, write 5 and carry 1, then 4+3+1=8 → 85.',
             zh:'个位满10就捆成一个十进到十位：47+38中7+8=15，写5进1，再算4+3+1=8→85。'}},
          {id:3,label:{ko:'십의 자리 올림',en:'carry from the tens',zh:'十位进位'},params:{carries:'tens'},
           concept:{ko:'일의 자리는 그냥 더해지는데 십의 자리가 10을 넘는 경우예요. 53+82는 3+2=5, 5+8=13이라 백의 자리 1이 생겨 135예요.',
             en:'Here the ones add cleanly but the tens pass 10: 53+82 gives 3+2=5 and 5+8=13, so a hundreds digit appears — 135.',
             zh:'个位直接相加，十位却满10：53+82中3+2=5，5+8=13，出现百位——135。'}},
          {id:4,label:{ko:'올림 두 번(연속)',en:'two carries',zh:'连续进位'},params:{carries:2},
           concept:{ko:'올린 1을 더한 십의 자리가 또 10을 넘는 경우예요. 47+68은 7+8=15(1 올림), 4+6+1=11이라 또 1을 올려 115예요. 올림 1을 빠뜨리기 쉬우니 작게 적어 두세요.',
             en:'The carried 1 makes the tens pass 10 again: 47+68 gives 7+8=15 (carry 1), then 4+6+1=11 — carry again for 115. Jot the carried 1 down so it is not forgotten.',
             zh:'进上来的1让十位再次满10：47+68中7+8=15（进1），4+6+1=11再进1，得115。把进位的1写小一点记下来。'}},
          {id:5,label:{ko:'올림 섞기',en:'carries mixed',zh:'进位混合'},params:{carries:'mix'},
           concept:{ko:'이번에는 올림이 어디서 나는지 문항마다 달라요. 먼저 일의 자리를 더해 10이 넘는지부터 확인하고 시작하세요.',
             en:'Now the carry can happen anywhere, so check the ones first: do they pass 10 or not? Start from that.',
             zh:'这次每题进位的位置都不同。先看个位相加是否满10，再动笔。'}},
          {id:6,label:{ko:'가로셈(올림 섞기)',en:'horizontal, mixed carries',zh:'横式(进位混合)'},params:{carries:'mix',orient:'h'},
           concept:{ko:'가로로 쓰인 식도 머릿속에서는 자리를 맞춰 더해요. 47+38은 47+30=77에 8을 더해 85 — 십의 자리부터 더해 가는 길이 가로셈에서는 더 편해요.',
             en:'A horizontal sum is still added place by place in your head: 47+38 is 47+30=77, then add 8 for 85 — going tens-first is easier when it is written across.',
             zh:'横式也要在心里对齐数位：47+38先算47+30=77，再加8得85——横式先加十位更方便。'}},
          {id:7,label:{ko:'세로셈(올림 섞기)',en:'column, mixed carries',zh:'竖式(进位混合)'},params:{carries:'mix',orient:'v'},
           concept:{ko:'세로로 쓸 때는 자리를 정확히 맞춰 쓰고 일의 자리부터 더해요. 올린 1은 십의 자리 위 작은 칸에 적어 두면 빠뜨리지 않아요.',
             en:'In column form line the places up exactly and add from the ones. Write the carried 1 in the small box above the tens so you do not lose it.',
             zh:'竖式要把数位对齐，从个位开始加。把进位的1写在十位上方的小格里就不会漏。'}}] },
AD6:{ name:{ko:'세 자리 덧셈',en:'3-digit +',zh:'三位加法'}, gen:'ad6_add3d', prereq:['AD5'],
  concept:{ko:'자리가 늘어도 방법은 똑같아요. 일의 자리부터 십, 백의 순서로 더하고 올림은 바로 윗자리로 보내요.',
    en:'More digits does not change the method. Add ones, then tens, then hundreds, sending each carry to the next place up.',
    zh:'位数变多方法也一样。从个位到十位再到百位依次相加，进位送到上一位。'},
  widgets:['steps','vertical','numpad'],
  levels:[{id:1,label:{ko:'3d+2d(올림 없음)',en:'3d+2d, no carry',zh:'三位加两位(不进位)'},params:{b:'2d',carry:'none'},
           concept:{ko:'자리를 맞춰 쓰는 것이 먼저예요. 342+25는 일 2+5=7, 십 4+2=6, 백은 3 그대로라 367이에요. 올릴 것이 없으니 자리끼리 더하면 끝이에요.',
             en:'Line the places up first: 342+25 gives ones 2+5=7, tens 4+2=6, and the 3 hundreds stay — 367. Nothing carries, so each place stands alone.',
             zh:'先对齐数位：342+25个位2+5=7，十位4+2=6，百位保持3——367。没有进位，各位分别相加即可。'}},
          {id:2,label:{ko:'3d+2d(올림)',en:'3d+2d with carry',zh:'三位加两位(进位)'},params:{b:'2d',carry:'one'},
           concept:{ko:'올림이 한 번 나는 경우예요. 348+25는 8+5=13이라 3을 쓰고 1을 올려 4+2+1=7 → 373. 올린 1을 다음 자리에 꼭 더해 주세요.',
             en:'One carry happens: 348+25 gives 8+5=13, write 3 and carry 1, then 4+2+1=7 → 373. Remember to add the carried 1 to the next place.',
             zh:'只进位一次：348+25中8+5=13，写3进1，再算4+2+1=7→373。别忘了把进上来的1加到下一位。'}},
          {id:3,label:{ko:'3d+3d(올림 없음)',en:'3d+3d, no carry',zh:'三位加三位(不进位)'},params:{b:'3d',carry:'none'},
           concept:{ko:'세 자리끼리라도 올림이 없으면 자리마다 따로 더하면 돼요. 324+153은 4+3=7, 2+5=7, 3+1=4라 477이에요.',
             en:'Even with three digits each, no carry means each place adds on its own: 324+153 gives 7, 7 and 4 — 477.',
             zh:'都是三位数但不进位时，各位分别相加：324+153得7、7、4——477。'}},
          {id:4,label:{ko:'3d+3d(올림 한 번)',en:'3d+3d, one carry',zh:'三位加三位(进位一次)'},params:{b:'3d',carry:'one'},
           concept:{ko:'한 자리에서만 10을 넘는 경우예요. 어느 자리에서 올림이 나는지 먼저 살펴보고, 그 자리만 조심하면 돼요.',
             en:'Only one place passes 10. Spot which place carries before you start, and watch just that one.',
             zh:'只有一位满10。先看清哪一位会进位，专心处理那一位就行。'}},
          {id:5,label:{ko:'3d+3d(연속 올림)',en:'3d+3d, carries in a row',zh:'三位加三位(连续进位)'},params:{b:'3d',carry:'all'},
           concept:{ko:'일의 자리에서 올리고 십의 자리에서 또 올리는 경우예요. 478+365는 8+5=13(1 올림), 7+6+1=14(1 올림), 4+3+1=8 → 843. 올림이 연달아 나므로 작게 적어 두고 가세요.',
             en:'A carry from the ones and another from the tens: 478+365 gives 8+5=13 (carry 1), 7+6+1=14 (carry 1), 4+3+1=8 → 843. Jot each carry down as you go.',
             zh:'个位进位后十位又进位：478+365中8+5=13（进1），7+6+1=14（进1），4+3+1=8→843。每次进位都写下来。'}},
          {id:6,label:{ko:'세 자리 덧셈(가로셈)',en:'3d addition horizontal',zh:'三位加法(横式)'},params:{b:'3d',carry:'all',orient:'h'},
           concept:{ko:'가로로 쓰인 세 자리 덧셈은 큰 자리부터 묶어 더하면 편해요. 478+365는 478+300=778, +60=838, +5=843.',
             en:'Written across, add the big places first: 478+365 is 478+300=778, +60=838, +5=843.',
             zh:'横式的三位加法先加大的数位：478+365是478+300=778，+60=838，+5=843。'}},
          {id:7,label:{ko:'세 자리 덧셈(세로셈)',en:'3d addition vertical',zh:'三位加法(竖式)'},params:{b:'3d',carry:'all',orient:'v'},
           concept:{ko:'세로로 쓰면 일·십·백이 한 줄로 서요. 오른쪽 끝부터 더하고 올린 1은 윗칸에 작게 적어요.',
             en:'In column form ones, tens and hundreds line up. Add from the right-hand end and note each carried 1 in the box above.',
             zh:'竖式让个位、十位、百位排成一列。从最右边开始加，把进位的1写在上面的小格里。'}}] },
AD7:{ name:{ko:'네 자리 덧뺄',en:'4-digit ±',zh:'四位加减'}, gen:'ad7_add4d', prereq:['AD6'],
  unit:'T-AD1',
  concept:{ko:'수가 커져도 방법은 똑같아요. 천의 자리는 천의 자리끼리, 백의 자리는 백의 자리끼리 자리를 맞춰 더하고 빼요.',
    en:'Bigger numbers use the same method — line up thousands with thousands, hundreds with hundreds, and add or subtract place by place.',
    zh:'数字变大方法不变，千位对千位，百位对百位，按数位相加或相减。'},
  widgets:['vertical','steps','numpad'],
  levels:[{id:1,label:{ko:'4d+4d(올림 없음)',en:'4d+4d, no carry',zh:'四位加(不进位)'},params:{op:'+',carry:'none'},
           concept:{ko:'네 자리라도 올림이 없으면 자리마다 따로 더하면 끝이에요. 3241+2536은 1+6, 4+3, 2+5, 3+2를 차례로 — 5777.',
             en:'Four digits with no carry still add place by place: 3241+2536 is 1+6, 4+3, 2+5, 3+2 — 5777.',
             zh:'四位数不进位时也是各位分别相加：3241+2536依次算1+6、4+3、2+5、3+2——5777。'}},
          {id:2,label:{ko:'4d+4d(올림)',en:'4d+4d with carry',zh:'四位加(进位)'},params:{op:'+',carry:'any'},
           concept:{ko:'자리가 넷이라 올림이 여러 번 날 수 있어요. 오른쪽 끝에서 왼쪽으로 한 자리씩 가며 올린 1을 빠뜨리지 않는 것이 전부예요.',
             en:'With four places a carry can happen several times. Work right to left, one place at a time, and never drop a carried 1.',
             zh:'四位数可能多次进位。从右往左一位一位算，别漏掉进上来的1。'}},
          {id:3,label:{ko:'4d±4d(섞기)',en:'4d±4d mixed',zh:'四位加减'},params:{op:'±',carry:'any'},
           concept:{ko:'덧셈과 뺄셈이 섞여 나와요. 부호를 먼저 보고, 덧셈이면 올림·뺄셈이면 내림을 챙기세요.',
             en:'Addition and subtraction are mixed here. Check the sign first: carry for a plus, borrow for a minus.',
             zh:'这里加法和减法混在一起。先看符号：加法要进位，减法要退位。'}}] },
AD8:{ name:{ko:'여러 수 덧셈(짝 묶기)',en:'Multi-add (pairing)',zh:'多数相加(配对)'}, gen:'ad8_multiAdd10', prereq:['NS3'],
  concept:{ko:'더하는 순서를 바꿔도 합은 같아요. 10이 되는 짝부터 묶으면 훨씬 빨라져요. 7+4+3+6은 (7+3)과 (4+6)으로 묶어 20이에요.',
    en:'Changing the order does not change the sum. Group the pairs that make 10 first. For 7+4+3+6, group (7+3) and (4+6) to get 20.',
    zh:'改变相加的顺序，和不变。先把凑成10的数对配起来会快得多。7+4+3+6可分成(7+3)和(4+6)，得20。'},
  widgets:['selectPairs','steps','numpad'],
  levels:[{id:1,label:{ko:'4개 수',en:'4 terms',zh:'四个数'},params:{terms:4}},
          {id:2,label:{ko:'5~6개 수',en:'5-6 terms',zh:'五六个数'},params:{terms:6}},
          {id:3,label:{ko:'두 자리 포함',en:'with 2-digit',zh:'含两位数'},params:{terms:5,twoDigit:true}},
          /* L4·L5(2026-09-26) — 초급 C-1 새치기 덧셈(A-09) · B-1 100의 짝(A-05). 생성기는 engine/threads/cre.js.
             mode 로 갈라 둔 까닭: 짝 묶기 계단(L1~L3)의 다음 칸이 아니라 다른 단원이라 과정 안 자동 오름이 넘어오면 안 된다. */
          {id:4,label:{ko:'새치기 덧셈',en:'jump-the-queue addition',zh:'插队加法'},params:{mode:'jump'},unit:'A-09',
           concept:{ko:'더해서 몇십이 되는 짝을 먼저 새치기시켜 더해요. 37+19+24+33은 37+33=70을 먼저 하고 19와 24를 더해 113이에요.',
             en:'Let the pair that makes a whole ten jump the queue: for 37+19+24+33, do 37+33=70 first, then add 19 and 24 — 113.',
             zh:'让凑成整十的一对先"插队"相加：37+19+24+33先算37+33=70，再加19和24，得113。'}},
          {id:5,label:{ko:'100 짝 묶기',en:'pairs that make 100',zh:'凑成100的一对'},params:{mode:'hundred'},unit:'A-05',
           concept:{ko:'더해서 100이 되는 짝부터 묶어요. 35+48+65는 35+65=100을 먼저 하고 48을 더해 148이에요.',
             en:'Bundle the pairs that make 100 first: for 35+48+65, do 35+65=100, then add 48 — 148.',
             zh:'先把凑成100的一对捆起来：35+48+65先算35+65=100，再加48，得148。'}}] },
/* AD10 — 연이은 덧셈·뺄셈. 2026-08-29 신규(빈 곳 메우기). AD8은 덧셈만 내는
   짝 묶기 전략 유형이고 MX1은 레벨1부터 곱셈이 섞이는 초5 유형이라,
   `8-3+2` 같은 작은 수 세 항 혼합 덧뺄이 어느 스레드에도 없었다. */
AD10:{ name:{ko:'연이은 덧셈·뺄셈',en:'Add & subtract in a row',zh:'连加连减'}, gen:'ad10_chainAddSub', prereq:['AD1','SB1'],
  concept:{ko:'덧셈과 뺄셈이 섞여 있으면 앞에서부터 차례로 계산해요. 8−3+2는 먼저 8−3=5, 그다음 5+2=7이에요.',
    en:'When adding and subtracting are mixed, work from left to right. For 8−3+2, first 8−3=5, then 5+2=7.',
    zh:'加法和减法混在一起时，从前往后依次计算。8−3+2先算8−3=5，再算5+2=7。'},
  widgets:['steps','cubes','numpad'],
  levels:[{id:1,label:{ko:'세 수(10까지)',en:'3 numbers (to 10)',zh:'三个数(到10)'},params:{terms:3,max:10}},
          {id:2,label:{ko:'세 수(20까지)',en:'3 numbers (to 20)',zh:'三个数(到20)'},params:{terms:3,max:20,cross:true}},
          {id:3,label:{ko:'네 수(20까지)',en:'4 numbers (to 20)',zh:'四个数(到20)'},params:{terms:4,max:20,cross:true}}] },

/* ── 창의 연산 초급 기법(2026-09-26) — 설계 docs/creative-stages-design-2026-09-26.md §2-2·§5 T2 ──
   원장 "창의수연 재탕인 것들 조치해". 초급 38단원의 기법이 앱 전용 NM_GEN 에만 있어 과정 1~10 의
   창의 칸이 구구단·필산 드릴로 채워졌다. 같은 절차를 engine/threads/cre.js 로 옮겨 스레드로 등록한다.
   unit: 그 유닛(앱 마법 노트)이 **모든 레벨과 같은 절차**일 때만 스레드에 단다 — 학습지 개념 칸
   (exam.js resolveConceptUnit)이 스레드 unit 의 마법 노트 단계를 그대로 싣기 때문이다. 레벨마다 원본
   단원이 다르거나 앱 유닛의 절차가 원본과 다르면 레벨에만 unit 을 단다(courses.js roleOf 가 읽는다).
   레벨은 모두 mode 로 갈라 둔다 — 레벨이 곧 다른 기법(단원)이라 회차 램프·과정 안 자동 오름을 막는다. */
AD11:{ name:{ko:'수를 이사시켜 10 만들기',en:'Move a Number to Make 10',zh:'搬数凑十'}, gen:'cre_ad11_moveTen', prereq:['NS3','AD2'],
  unit:'A-02',
  concept:{ko:'작은 수를 둘로 갈라 한 조각을 큰 수에 옮겨 주면 10(몇십)이 먼저 생겨요. 8+7은 7을 2와 5로 갈라 8+2=10, 10+5=15예요.',
    en:'Split the smaller number and move one part to the bigger one so it becomes 10 (a whole ten) first. For 8+7, split 7 into 2 and 5: 8+2=10, then 10+5=15.',
    zh:'把小的数分成两份，搬一份给大的数，先凑成10(整十)。8+7把7分成2和5：8+2=10，10+5=15。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'한 자리+한 자리',en:'1-digit + 1-digit',zh:'一位加一位'},params:{mode:'one'},unit:'A-02'},
          {id:2,label:{ko:'두 자리+한 자리',en:'2-digit + 1-digit',zh:'两位加一位'},params:{mode:'twoOne'},unit:'A-02',
           concept:{ko:'두 자리 수도 같아요. 27+8은 8을 3과 5로 갈라 27+3=30을 먼저 만들고 30+5=35예요.',
             en:'Two-digit numbers work the same way: for 27+8, split 8 into 3 and 5, make 27+3=30 first, then 30+5=35.',
             zh:'两位数也一样：27+8把8分成3和5，先凑27+3=30，再30+5=35。'}},
          {id:3,label:{ko:'두 자리+두 자리',en:'2-digit + 2-digit',zh:'两位加两位'},params:{mode:'twoTwo'},unit:'A-08',
           concept:{ko:'39+25는 25에서 1을 옮겨 39를 40으로 만들어요. 40+24=64 — 몇십이 먼저 생기면 나머지는 쉬워요.',
             en:'For 39+25, move 1 from 25 to make 39 into 40; then 40+24=64. Once a whole ten appears the rest is easy.',
             zh:'39+25从25里搬1过去，把39凑成40；40+24=64。先凑出整十，剩下的就容易了。'}}] },
AD12:{ name:{ko:'계단식 덧셈',en:'Staircase Addition',zh:'阶梯加法'}, gen:'cre_ad12_stair', prereq:['AD3'],
  unit:'A-04',
  concept:{ko:'더하는 수를 십과 일로 갈라 십을 먼저, 일을 나중에 계단처럼 더해요. 24+13은 24+10=34, 34+3=37이에요.',
    en:'Split the number you add into tens and ones, and add the tens first, then the ones — like stairs. 24+13: 24+10=34, then 34+3=37.',
    zh:'把加数分成十和一，先加十，再加一，像上台阶一样。24+13：24+10=34，34+3=37。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'두 수',en:'two numbers',zh:'两个数'},params:{mode:'two'},unit:'A-04'},
          {id:2,label:{ko:'세 수',en:'three numbers',zh:'三个数'},params:{mode:'three'},unit:'A-04',
           concept:{ko:'수가 셋이어도 같아요. 첫 수에서 출발해 다음 수의 십, 그다음 일을 차례로 더하고, 셋째 수도 같은 계단을 밟아요.',
             en:'Three numbers work the same way: start from the first, add the next number\'s tens, then its ones, and climb the same stairs for the third.',
             zh:'三个数也一样：从第一个数出发，依次加下一个数的十和一，第三个数也走同样的台阶。'}}] },
AD13:{ name:{ko:'끼리끼리 더하기',en:'Add Place by Place',zh:'同位相加'}, gen:'cre_ad13_placewise', prereq:['AD5'],
  unit:'A-07',
  concept:{ko:'십은 십끼리, 일은 일끼리 모아서 더한 뒤 합쳐요. 23+17은 20+10=30, 3+7=10이라 40이에요.',
    en:'Add the tens together and the ones together, then combine. 23+17: 20+10=30 and 3+7=10, so 40.',
    zh:'十和十放在一起加，一和一放在一起加，再合起来。23+17：20+10=30，3+7=10，所以是40。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'두 자리 두 수',en:'two 2-digit numbers',zh:'两个两位数'},params:{mode:'two'},unit:'A-07'},
          {id:2,label:{ko:'두 자리 세 수',en:'three 2-digit numbers',zh:'三个两位数'},params:{mode:'three'},unit:'A-07',
           concept:{ko:'세 수도 십끼리, 일끼리 모아요. 34+25+47은 30+20+40=90, 4+5+7=16이라 90+16=106이에요.',
             en:'With three numbers, still gather tens and ones: 34+25+47 gives 30+20+40=90 and 4+5+7=16, so 90+16=106.',
             zh:'三个数也是十和十、一和一放在一起：34+25+47，30+20+40=90，4+5+7=16，所以90+16=106。'}},
          {id:3,label:{ko:'세 자리 세 수',en:'three 3-digit numbers',zh:'三个三位数'},params:{mode:'hundreds'},unit:'A-07',
           concept:{ko:'세 자리면 백끼리, 십끼리, 일끼리 세 무리로 모아서 더한 뒤 합쳐요.',
             en:'With 3-digit numbers, make three groups — hundreds, tens and ones — add each group, then combine.',
             zh:'三位数就分成百、十、一三组，每组相加后再合起来。'}}] },
AD14:{ name:{ko:'끊어서 더하기',en:'Chunk Addition',zh:'分段相加'}, gen:'cre_ad14_chunkAdd', prereq:['AD6'],
  unit:'A-17',
  concept:{ko:'긴 수를 끊어서 부분끼리 따로 더한 뒤 마지막에 합쳐요. 올림을 머릿속에 들고 있지 않아도 돼요.',
    en:'Cut long numbers into parts, add the matching parts separately, and combine at the end — no carrying to hold in your head.',
    zh:'把长的数分段，对应的部分分别相加，最后再合起来——不用在脑子里记进位。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'자리마다 따로(세 자리)',en:'each place apart (3-digit)',zh:'每位分开(三位)'},params:{mode:'place'},unit:'A-16',
           concept:{ko:'세 자리 두 수를 백·십·일 자리마다 따로 더해요. 368+475는 700, 130, 13을 구한 뒤 모두 더해 843이에요.',
             en:'Add two 3-digit numbers one place at a time: for 368+475 find 700, 130 and 13, then add them all to get 843.',
             zh:'两个三位数按百、十、个位分别相加：368+475先得700、130、13，再全部加起来得843。'}},
          {id:2,label:{ko:'두 자리씩(네 자리)',en:'two digits at a time (4-digit)',zh:'两位一段(四位)'},params:{mode:'pairs'},unit:'A-17',
           concept:{ko:'네 자리 수는 앞 두 자리와 뒤 두 자리로 끊어요. 1234+5678은 1200+5600=6800, 34+78=112라 6800+112=6912예요.',
             en:'Cut 4-digit numbers into the front two digits and the back two: 1234+5678 gives 1200+5600=6800 and 34+78=112, so 6800+112=6912.',
             zh:'四位数分成前两位和后两位：1234+5678，1200+5600=6800，34+78=112，所以6800+112=6912。'}}] },
AD15:{ name:{ko:'앞부터 계산하기',en:'Front-First Calculation',zh:'从高位算起'}, gen:'cre_ad15_frontFirst', prereq:['AD7','SB6'],
  concept:{ko:'큰 자리부터 차례로 계산해요. 357+468은 357+400=757, 757+60=817, 817+8=825 — 앞자리부터 답이 모양을 갖춰요.',
    en:'Work from the biggest place first. 357+468: 357+400=757, 757+60=817, 817+8=825 — the answer takes shape from the front.',
    zh:'从最高位开始依次计算。357+468：357+400=757，757+60=817，817+8=825——答案从前面开始成形。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'앞부터 더하기(세 자리)',en:'add from the front (3-digit)',zh:'从高位加(三位)'},params:{mode:'add3'},unit:'A-18'},
          {id:2,label:{ko:'앞부터 더하기(네 자리)',en:'add from the front (4-digit)',zh:'从高位加(四位)'},params:{mode:'add4'},unit:'A-18',
           concept:{ko:'네 자리도 천의 자리부터 한 자리씩 더해 가요. 3584+5685는 3584+5000, +600, +80, +5 순서예요.',
             en:'Four digits work the same: add one place at a time from the thousands — 3584+5685 is +5000, +600, +80, +5.',
             zh:'四位数也从千位开始一位一位加：3584+5685依次+5000、+600、+80、+5。'}},
          {id:3,label:{ko:'앞부터 빼기(세 자리)',en:'subtract from the front (3-digit)',zh:'从高位减(三位)'},params:{mode:'sub3'},unit:'A-30',
           concept:{ko:'빼기도 큰 자리부터 해요. 837−545는 837−500=337, 337−40=297, 297−5=292예요.',
             en:'Subtraction can go from the front too: 837−545 is 837−500=337, 337−40=297, 297−5=292.',
             zh:'减法也可以从高位开始：837−545，837−500=337，337−40=297，297−5=292。'}},
          {id:4,label:{ko:'앞부터 빼기(네 자리)',en:'subtract from the front (4-digit)',zh:'从高位减(四位)'},params:{mode:'sub4'},unit:'A-30',
           concept:{ko:'네 자리 빼기도 천의 자리부터 한 자리씩 빼요. 5342−1267은 −1000, −200, −60, −7 순서예요.',
             en:'Four-digit subtraction also goes one place at a time from the thousands: 5342−1267 is −1000, −200, −60, −7.',
             zh:'四位数减法也从千位开始一位一位减：5342−1267依次−1000、−200、−60、−7。'}},
          {id:5,label:{ko:'빼기 쉬운 수부터 빼기',en:'subtract the easy pair first',zh:'先减好减的数'},params:{mode:'subEasy'},unit:'A-31',
           concept:{ko:'두 수를 빼야 할 때, 빼는 두 수를 먼저 더해 몇십이 되면 한 번에 빼요. 90−35−5는 35+5=40, 90−40=50이에요.',
             en:'When you take away two numbers, add them first; if they make a whole ten, subtract once. 90−35−5: 35+5=40, then 90−40=50.',
             zh:'要减两个数时，先把两个减数加起来，凑成整十就一次减掉。90−35−5：35+5=40，90−40=50。'}}] },
AD16:{ name:{ko:'기준수로 더하기',en:'Adding with a Base Number',zh:'用基准数相加'}, gen:'cre_ad16_anchorSum', prereq:['AD6'],
  unit:'A-24',
  concept:{ko:'크기가 비슷한 수는 모두 기준수로 보고 더한 뒤, 많은 만큼 더하고 모자란 만큼 빼요. 104+97+109+93은 100×4=400에 4와 9를 더하고 3과 7을 빼서 403이에요.',
    en:'When numbers are close in size, treat them all as a base number, then add what is over and take away what is under. 104+97+109+93: 100×4=400, add 4 and 9, take away 3 and 7 — 403.',
    zh:'大小差不多的数都看作基准数，再把多的加上、少的减去。104+97+109+93：100×4=400，加4和9，减3和7，得403。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'세 수(기준 50·100)',en:'3 numbers (base 50/100)',zh:'三个数(基准50·100)'},params:{mode:'three'},unit:'A-24'},
          {id:2,label:{ko:'네 수(기준 100~800)',en:'4 numbers (base 100-800)',zh:'四个数(基准100~800)'},params:{mode:'four'},unit:'A-24',
           concept:{ko:'기준수는 100이 아니어도 돼요. 355+369+357+363은 350을 기준으로 350×4=1400에 5·19·7·13을 더해요.',
             en:'The base need not be 100: 355+369+357+363 uses 350, so 350×4=1400 plus 5, 19, 7 and 13.',
             zh:'基准数不一定是100：355+369+357+363以350为基准，350×4=1400，再加5、19、7、13。'}},
          {id:3,label:{ko:'다섯 수(기준수 고르기)',en:'5 numbers (choose the base)',zh:'五个数(自选基准)'},params:{mode:'five'},unit:'A-24',
           concept:{ko:'이번엔 기준수를 스스로 골라요. 수들이 모여 있는 한가운데의 몇십·몇백을 기준으로 하면 차가 작아져요.',
             en:'Now choose the base yourself: pick the round number in the middle of the group so the differences stay small.',
             zh:'这次自己选基准数：选这些数中间的整十、整百数，差就会很小。'}}] },

/* ── SB 뺄셈 ───────────────────────────── */
SB1:{ name:{ko:'한 자리 뺄셈',en:'1-digit −',zh:'一位减法'}, gen:'sb1_sub1d', prereq:['NS2'],
  concept:{ko:'큰 수에서 작은 수만큼 덜어내는 것이 뺄셈이에요. 7에서 3을 덜어내면 4가 남아요.',
    en:'Subtraction takes away from the bigger number. Take 3 away from 7 and 4 is left.',
    zh:'减法就是从大数中拿走一些。从7里拿走3，还剩4。'},
  widgets:['cubes','numpad'],
  levels:[{id:1,label:{ko:'9까지',en:'to 9',zh:'到9'},params:{max:9}}] },
SB2:{ name:{ko:'몇십−한 자리·100−수',en:'Tens−1d, 100−n',zh:'几十减一位'}, gen:'sb2_subTens', prereq:['NS3','NS4'],
  concept:{ko:'몇십에서 뺄 땐 10을 하나 풀어 써요. 40-7은 30과 10으로 나눠 10-7=3을 구하고 30을 더해 33이에요.',
    en:'Subtracting from a ten, break one ten open. For 40-7, split into 30 and 10, do 10-7=3, then add 30 to get 33.',
    zh:'从整十数里减，先拆开一个十。40-7分成30和10，先算10-7=3，再加30得33。'},
  widgets:['steps','tenframe','numpad'],
  levels:[{id:1,label:{ko:'몇십−1d',en:'tens−1d',zh:'几十减一位'},params:{mode:'tens'}},
          {id:2,label:{ko:'100−1d/2d',en:'100−n',zh:'100减'},params:{mode:'hundred'},
           concept:{ko:'100에서 뺄 땐 99에서 빼고 1을 더하면 받아내림이 없어요 — 100−29는 99−29=70에 1을 더해 71이에요.',
             en:'To subtract from 100, subtract from 99 and add 1 — no borrowing needed: 100−29 is 99−29=70 plus 1, so 71.',
             zh:'从100减时可以先从99减再加1，就不用退位：100−29是99−29=70再加1，得71。'}}] },
SB3:{ name:{ko:'두 자리−한 자리',en:'2d−1d',zh:'两位减一位'}, gen:'sb3_sub2d1d', prereq:['SB2'],
  concept:{ko:'일의 자리끼리 못 빼면 십의 자리에서 10을 빌려요. 52-7은 2에서 못 빼니 12-7=5, 답은 45예요.',
    en:'When the ones are too small, borrow 10 from the tens. For 52-7, since 2 is too small, do 12-7=5, giving 45.',
    zh:'个位不够减就向十位借10。52-7中2不够减，用12-7=5，得45。'},
  widgets:['cubes','steps','numpad'],
  levels:[{id:1,label:{ko:'내림×',en:'no borrow',zh:'不退位'},params:{borrow:false},
           concept:{ko:'일의 자리가 충분하면 그냥 빼면 돼요. 47−3은 7−3=4라 44 — 십의 자리는 그대로예요.',
             en:'If the ones are big enough, just subtract: 47−3 gives 7−3=4, so 44 — the tens do not change.',
             zh:'个位够减就直接减：47−3中7−3=4，得44——十位不变。'}},
          {id:2,label:{ko:'내림',en:'borrow',zh:'退位'},params:{borrow:true},
           concept:{ko:'일의 자리가 모자라면 십의 자리에서 10을 빌려요. 52−7은 2에서 못 빼니 12−7=5, 십의 자리는 하나 줄어 4 → 45예요.',
             en:'When the ones are short, borrow 10 from the tens: in 52−7 you cannot take 7 from 2, so 12−7=5 and the tens drop to 4 — 45.',
             zh:'个位不够减就向十位借10：52−7中2减不了7，借后12−7=5，十位减1变4——45。'}},
          {id:3,label:{ko:'가로셈(내림)',en:'horizontal, with borrow',zh:'横式(退位)'},params:{borrow:true,orient:'h'},
           concept:{ko:'가로로 쓰였어도 일의 자리가 모자라면 10을 풀어 써요. 52−7은 52에서 2를 먼저 빼 50, 남은 5를 더 빼 45 — 10을 지나며 끊어 빼면 쉬워요.',
             en:'Even written across, a short ones place means opening a ten: 52−7 takes 2 to reach 50, then 5 more for 45 — breaking the jump at the ten is easiest.',
             zh:'横式中个位不够减也要拆开一个十：52−7先减2到50，再减5得45——在整十处断开来减最简单。'}},
          {id:4,label:{ko:'세로셈(내림)',en:'column, with borrow',zh:'竖式(退位)'},params:{borrow:true,orient:'v'},
           concept:{ko:'세로로 쓸 때는 십의 자리에서 10을 빌려 온 것을 숫자 위에 표시해요. 빌린 자리는 1이 줄어든다는 것을 꼭 적어 두세요.',
             en:'In column form mark the ten you borrowed above the digit, and write down that the lending place is now one smaller.',
             zh:'竖式要在数字上方标出借来的10，并记下被借的那一位少了1。'}}] },
SB4:{ name:{ko:'두 자리−두 자리',en:'2d−2d',zh:'两位减两位'}, gen:'sb4_sub2d2d', prereq:['SB3'],
  concept:{ko:'자리를 맞춰 일의 자리부터 빼고, 모자라면 윗자리에서 10을 빌려요. 63-28은 13-8=5, 5-2=3이라 35예요.',
    en:'Line up the places, subtract from the ones, and borrow 10 when short. For 63-28, 13-8=5 and 5-2=3, giving 35.',
    zh:'对齐数位从个位减，不够就向上一位借10。63-28中13-8=5、5-2=3，得35。'},
  widgets:['steps','vertical','numpad'],
  levels:[{id:1,label:{ko:'내림×',en:'no borrow',zh:'不退位'},params:{borrow:false},
           concept:{ko:'두 자리끼리라도 각 자리가 충분하면 그냥 빼면 끝이에요. 46−12는 6−2=4, 4−1=3이라 34예요.',
             en:'Two digits each, but if every place is big enough you just subtract: 46−12 gives 6−2=4 and 4−1=3 — 34.',
             zh:'都是两位数，只要每位都够减就直接减：46−12中6−2=4，4−1=3——34。'}},
          {id:2,label:{ko:'내림',en:'borrow',zh:'退位'},params:{borrow:true},
           concept:{ko:'일의 자리가 모자라면 십의 자리에서 10을 빌리고, 빌려준 십의 자리는 1을 줄여 빼요. 63−28은 13−8=5, 5−2=3이라 35예요.',
             en:'Borrow 10 from the tens when the ones are short, and subtract with the tens one smaller: 63−28 gives 13−8=5 and 5−2=3 — 35.',
             zh:'个位不够就向十位借10，十位减1后再减：63−28中13−8=5，5−2=3——35。'}},
          {id:3,label:{ko:'가로셈(내림)',en:'horizontal, with borrow',zh:'横式(退位)'},params:{borrow:true,orient:'h'},
           concept:{ko:'가로로 쓰인 두 자리 뺄셈은 십의 자리부터 빼면 편해요. 63−28은 63−20=43에서 8을 더 빼 35 — 43에서 3을 빼 40, 남은 5를 더 빼면 35예요.',
             en:'Written across, take the tens away first: 63−28 is 63−20=43, then 8 more — drop 3 to reach 40 and 5 more gives 35.',
             zh:'横式的两位减法先减十位：63−28先算63−20=43，再减8——先减3到40，再减5得35。'}},
          {id:4,label:{ko:'세로셈(내림)',en:'column, with borrow',zh:'竖式(退位)'},params:{borrow:true,orient:'v'},
           concept:{ko:'세로로 쓸 때는 자리를 맞춰 쓰고 일의 자리부터 빼요. 모자라면 십의 자리에서 10을 빌리고, 빌려준 자리는 1을 줄여 적습니다.',
             en:'Line the places up and subtract from the ones. If it is short, borrow 10 from the tens and write that place one smaller.',
             zh:'竖式对齐数位后从个位开始减。不够就向十位借10，并把那一位改小1。'}}] },
SB5:{ name:{ko:'더 빼고 돌려받기',en:'Compensation −',zh:'补偿减法'}, gen:'sb5_subAdjust', prereq:['SB3'],
  concept:{ko:'7·8·9를 뺄 땐 10을 먼저 빼고 남은 만큼 돌려줘요. 52-9는 52-10=42에 1을 돌려받아 43이에요.',
    en:'To subtract 7, 8 or 9, take 10 first and give the rest back. For 52-9, do 52-10=42 and give back 1 to get 43.',
    zh:'减7、8、9时先减10再还回多减的部分。52-9先算52-10=42，再还回1，得43。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'2d−(7~9)',en:'2d−(7-9)',zh:'两位减7~9'},params:{small:true}},
          {id:2,label:{ko:'3d−2d',en:'3d−2d',zh:'三位减两位'},params:{small:false}}] },
SB6:{ name:{ko:'큰 수 뺄셈(3·4자리)',en:'Big −',zh:'大数减法'}, gen:'sb6_subBig', prereq:['SB4'],
  concept:{ko:'세 자리, 네 자리도 방법은 같아요. 자리를 맞춰 오른쪽부터 빼고 빌림은 바로 윗자리에서 가져와요.',
    en:'Three and four digit numbers work the same. Line up the places, subtract from the right, and borrow from the next place up.',
    zh:'三位数、四位数方法相同。对齐数位从右边开始减，不够时向上一位借。'},
  widgets:['vertical','steps','numpad'],
  levels:[{id:1,label:{ko:'3d−3d(내림 없음)',en:'3d−3d, no borrow',zh:'三位减(不退位)'},params:{d:3,borrow:'none'},
           concept:{ko:'윗수의 각 자리가 아랫수보다 크면 그냥 빼면 돼요. 768−342는 8−2=6, 6−4=2, 7−3=4라 426이에요.',
             en:'When every digit on top is bigger, just subtract: 768−342 gives 8−2=6, 6−4=2, 7−3=4 — 426.',
             zh:'上面每一位都比下面大时直接减：768−342得8−2=6，6−4=2，7−3=4——426。'}},
          {id:2,label:{ko:'3d−3d(내림 한 번)',en:'3d−3d, one borrow',zh:'三位减(退位一次)'},params:{d:3,borrow:'one'},
           concept:{ko:'한 자리가 모자라면 바로 윗자리에서 10을 빌려요. 742−328은 2에서 8을 못 빼니 십의 자리에서 10을 빌려 12−8=4, 십의 자리는 하나 줄어 3−2=1 → 414.',
             en:'If one place is short, borrow 10 from the place above: in 742−328 you cannot take 8 from 2, so borrow — 12−8=4, and the tens drop by one: 3−2=1 → 414.',
             zh:'某一位不够减就向上一位借10：742−328中2减不了8，借来后12−8=4，十位少了1变成3−2=1→414。'}},
          {id:3,label:{ko:'3d−3d(연속 내림)',en:'3d−3d, borrows in a row',zh:'三位减(连续退位)'},params:{d:3,borrow:'all'},
           concept:{ko:'빌리고 또 빌리는 경우예요. 723−489는 3에서 9를 못 빼 13−9=4, 그런데 십의 자리도 1로 줄어 9를 못 빼니 또 빌려 11−8=3, 백은 6−4=2 → 234.',
             en:'You borrow, then borrow again: 723−489 gives 13−9=4, but the tens are now 1 and still short, so borrow again — 11−8=3, and 6−4=2 → 234.',
             zh:'借了还要再借：723−489中13−9=4，十位变成1仍不够减，再借一次11−8=3，百位6−4=2→234。'}},
          {id:4,label:{ko:'0에서 빌리기',en:'borrowing across a zero',zh:'跨0退位'},params:{d:3,borrow:'zero'},
           concept:{ko:'빌리려는 자리가 0이면 그 윗자리에서 먼저 빌려 와야 해요. 302−147은 십의 자리가 0이라 백에서 빌려 10으로 만든 뒤, 거기서 다시 일의 자리로 빌려 줍니다 — 12−7=5, 9−4=5, 2−1=1 → 155. 가장 많이 틀리는 자리예요.',
             en:'If the place you want to borrow from is 0, it must borrow first. In 302−147 the tens are 0, so they borrow from the hundreds to become 10, then lend to the ones — 12−7=5, 9−4=5, 2−1=1 → 155. This is the step children miss most.',
             zh:'要借的那一位是0时，它得先向上一位借。302−147中十位是0，先从百位借变成10，再借给个位——12−7=5，9−4=5，2−1=1→155。这是最容易错的地方。'}},
          {id:5,label:{ko:'4d−4d(연속 내림)',en:'4d−4d, borrows in a row',zh:'四位减(连续退位)'},params:{d:4,borrow:'all'},
           concept:{ko:'자리가 넷으로 늘어도 방법은 같아요. 오른쪽 끝부터 한 자리씩, 빌린 자리는 1이 줄었다는 것만 잊지 마세요.',
             en:'Four places work the same way: right to left, one place at a time, and remember every place you borrowed from is one smaller.',
             zh:'四位数方法相同：从右往左一位一位算，记住被借的那一位少了1。'}},
          {id:6,label:{ko:'세 자리 뺄셈(세로셈)',en:'3d subtraction vertical',zh:'三位减法(竖式)'},params:{d:3,borrow:'all',orient:'v'},
           concept:{ko:'세로로 쓰면 빌린 흔적을 숫자 위에 적어 둘 수 있어요. 지운 자리에 작게 고쳐 쓰는 습관이 실수를 크게 줄여 줘요.',
             en:'Column form lets you mark each borrow above the digit. Crossing out and writing the new digit small prevents most mistakes.',
             zh:'竖式可以把退位的痕迹写在数字上方。划掉后在旁边写小字，能大大减少错误。'}},
          {id:7,label:{ko:'네 자리 뺄셈(세로셈)',en:'4d subtraction vertical',zh:'四位减法(竖式)'},params:{d:4,borrow:'all',orient:'v'},
           concept:{ko:'네 자리 세로셈도 자리 맞추기가 반이에요. 천·백·십·일이 한 줄씩 서도록 쓰고 오른쪽부터 빼세요.',
             en:'Half the work in a four-digit column sum is lining it up: put thousands, hundreds, tens and ones each in their own column, then subtract from the right.',
             zh:'四位竖式一半功夫在对齐：千、百、十、个各占一列，再从右边开始减。'}}] },
SB7:{ name:{ko:'식의 변형',en:'Transform the Expression',zh:'变形算式'}, gen:'sb7_transform', prereq:['AD8'],
  concept:{ko:'두 수에 같은 수를 더하거나 빼도 차는 그대로예요. 63-28은 둘에 2를 더해 65-30=35로 쉽게 바꿀 수 있어요.',
    en:'Adding the same amount to both numbers keeps the difference. Turn 63-28 into 65-30=35 by adding 2 to each.',
    zh:'两个数同时加或减同一个数，差不变。63-28两边都加2变成65-30=35，更好算。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'끼리끼리',en:'group like terms',zh:'同类相聚'},params:{mode:'group'}},
          {id:2,label:{ko:'10s 만들기',en:'make tens',zh:'凑整十'},params:{mode:'tens'},
           concept:{ko:'더해서 10이 되는 짝부터 묶으면 몇십이 되어 계산이 쉬워져요 — 27+3+9+1은 (27+3)과 (9+1)로 묶어 30+10=40이에요.',
             en:'Bundle the pairs that make 10 first so you land on tens: 27+3+9+1 groups into (27+3) and (9+1), giving 30+10 = 40.',
             zh:'先把凑成10的一对捆起来就变成整十，计算更容易：27+3+9+1分成(27+3)与(9+1)，得30+10=40。'}}] },

/* ── 창의 연산 초급 뺄셈 기법(2026-09-26, engine/threads/cre.js) — 위 AD11~AD16 머리말 참고 ── */
SB8:{ name:{ko:'자리별 빼기·쉬었다 빼기',en:'Place-by-Place & Rest-Stop Subtraction',zh:'按位减·歇一歇再减'}, gen:'cre_sb8_placeSub', prereq:['SB3'],
  concept:{ko:'빼는 수를 갈라서 두 번에 나눠 빼요. 57−23은 십을 먼저 빼서 57−20=37, 일을 나중에 빼서 37−3=34예요.',
    en:'Split the number you take away and subtract in two goes. 57−23: take the tens first, 57−20=37, then the ones, 37−3=34.',
    zh:'把减数分开，分两次减。57−23：先减十，57−20=37，再减一，37−3=34。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'자리별 따로 빼기',en:'subtract place by place',zh:'按位分开减'},params:{mode:'place'},unit:'A-10'},
          {id:2,label:{ko:'쉬었다 빼기',en:'rest-stop subtraction',zh:'歇一歇再减'},params:{mode:'rest'},unit:'A-11',
           concept:{ko:'몇십까지만 먼저 빼고, 쉬었다가 남은 만큼 빼요. 43−8은 8을 3과 5로 갈라 43−3=40, 40−5=35예요.',
             en:'Subtract just down to a whole ten first, rest, then take away the rest. 43−8: split 8 into 3 and 5, 43−3=40, 40−5=35.',
             zh:'先只减到整十，歇一下再减剩下的。43−8把8分成3和5：43−3=40，40−5=35。'}},
          {id:3,label:{ko:'세 자리−두 자리 자리별',en:'3-digit − 2-digit by place',zh:'三位减两位按位减'},params:{mode:'place3'},unit:'A-10',
           concept:{ko:'세 자리에서도 빼는 수의 십을 먼저, 일을 나중에 빼요. 352−47은 352−40=312, 312−7=305예요.',
             en:'From a 3-digit number, still take the tens first and the ones after: 352−47 is 352−40=312, then 312−7=305.',
             zh:'三位数也是先减减数的十，再减一：352−47，352−40=312，312−7=305。'}}] },
/* SB9 — 반대로 채우기(초급 E-3, A-19). 설계는 EL1 의 새 레벨(countUp)로 적었지만, EL1 의 선수 DV3(나눗셈, 과정 9)
   때문에 과정 6 에 둘 수 없어(check-ladder 선수 순서) 뺄셈 스레드로 따로 세웠다. 역연산(EL1, 과정 12·16)의 씨앗이다. */
SB9:{ name:{ko:'반대로 채우기',en:'Count Up to Subtract',zh:'反过来补'}, gen:'cre_sb9_countUp', prereq:['SB2','AD3'],
  unit:'A-19',
  concept:{ko:'뺄셈을 덧셈으로 거꾸로 생각해요. 73−48은 48+□=73 — 48에서 50까지 2, 50에서 73까지 23을 채워 25예요.',
    en:'Think of a subtraction as an addition backwards: 73−48 is 48+□=73 — fill 2 up to 50, then 23 up to 73, so 25.',
    zh:'把减法反过来想成加法：73−48就是48+□=73——从48补2到50，再从50补23到73，所以是25。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'몇십까지 채우고 나머지 채우기',en:'fill to a ten, then the rest',zh:'先补到整十再补剩下的'},params:{mode:'countUp'},unit:'A-19'}] },
/* SB10 — 설계의 L2 자릿수 이동(A-14)·L3 수를 풀어서 쓰기(A-15)는 원장 결정 Q1(초급 C·D권 사진) 뒤에 더한다. */
SB10:{ name:{ko:'백을 떼어 빼기',en:'Take Out a Hundred',zh:'拿出一百来减'}, gen:'cre_sb10_borrowHundred', prereq:['SB4'],
  unit:'A-13',
  concept:{ko:'일의 자리·십의 자리에서 빼기 어려우면 100을 하나 떼어 거기서 빼고, 남은 수와 더해요. 234−78은 100−78=22, 134+22=156이에요.',
    en:'If the tens and ones are too small to subtract from, take out one hundred, subtract from it, and add what is left. 234−78: 100−78=22, then 134+22=156.',
    zh:'个位、十位不够减时，拿出一个100来减，再和剩下的数相加。234−78：100−78=22，134+22=156。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'백 쪼개기',en:'split off a hundred',zh:'分出一百'},params:{mode:'hundred'},unit:'A-13'}] },
SB12:{ name:{ko:'같은 수 더해서·빼서 빼기',en:'Same Change, Same Difference',zh:'同加同减差不变'}, gen:'cre_sb12_constDiff', prereq:['SB4'],
  concept:{ko:'두 수에 같은 수를 더하거나 빼도 차는 그대로예요. 53−38은 둘에 2를 더해 55−40=15로 바꿔요.',koMid:'두 수에 같은 수를 더하거나 빼도 차는 변하지 않습니다. 53−38은 두 수에 2를 더해 55−40=15로 바꿉니다.',
    en:'Adding or subtracting the same number on both keeps the difference. Turn 53−38 into 55−40=15 by adding 2 to each.',
    zh:'两个数同时加上或减去同一个数，差不变。53−38两个数都加2，变成55−40=15。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'같은 수 더해서 빼기',en:'add the same to both',zh:'同加一个数'},params:{mode:'add'},unit:'A-20'},
          {id:2,label:{ko:'같은 수 빼서 빼기',en:'take the same from both',zh:'同减一个数'},params:{mode:'sub'},unit:'A-21',
           concept:{ko:'이번엔 두 수에서 같은 수를 빼서 빼지는 수를 몇십으로 만들어요. 62−28은 둘에서 2를 빼 60−26=34예요.',koMid:'이번에는 두 수에서 같은 수를 빼서 빼지는 수를 몇십으로 만듭니다. 62−28은 두 수에서 2를 빼 60−26=34입니다.',
             en:'This time take the same number from both so the first number becomes a whole ten: 62−28 becomes 60−26=34.',
             zh:'这次两个数同时减去同一个数，让被减数变成整十：62−28两个都减2，变成60−26=34。'}},
          {id:3,label:{ko:'세 자리·방향 고르기',en:'3-digit, choose the way',zh:'三位数·选方向'},params:{mode:'choose'},unit:'A-21',
           concept:{ko:'더할지 뺄지 스스로 골라요. 조금만 바꿔도 되는 쪽이 쉬워요 — 826−129는 둘에 1을 더해 827−130, 933−764는 둘에서 3을 빼 930−761이에요.',koMid:'더할지 뺄지 스스로 고릅니다. 조금만 바꿔도 되는 쪽이 쉽습니다 — 826−129는 두 수에 1을 더해 827−130, 933−764는 두 수에서 3을 빼 930−761입니다.',
             en:'Choose for yourself whether to add or subtract — the side that needs the smaller change is easier: 826−129 becomes 827−130, and 933−764 becomes 930−761.',
             zh:'自己选择加还是减——变化小的一边更容易：826−129都加1变成827−130，933−764都减3变成930−761。'}}] },
SB13:{ name:{ko:'쪼개서 빼기',en:'Split the First Number',zh:'拆开被减数'}, gen:'cre_sb13_splitMinuend', prereq:['SB4','SB6'],
  concept:{ko:'끝이 0인 수에서 뺄 때는 빼는 수보다 조금 큰 몇십을 떼어 내 거기서 빼요. 460−29는 460을 430과 30으로 쪼개 30−29=1, 430+1=431이에요.',
    en:'When subtracting from a number ending in 0, break off a round number just above what you subtract and take it from there. 460−29: split 460 into 430 and 30, 30−29=1, 430+1=431.',
    zh:'从末尾是0的数里减时，分出一个比减数稍大的整十数，从它里面减。460−29：把460分成430和30，30−29=1，430+1=431。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'세 자리',en:'3-digit',zh:'三位数'},params:{mode:'three'},unit:'A-22'},
          {id:2,label:{ko:'네 자리',en:'4-digit',zh:'四位数'},params:{mode:'four'},unit:'A-22',
           concept:{ko:'네 자리는 몇백을 떼어 내요. 4800−2325는 4800을 2400과 2400으로 쪼개 2400−2325=75, 2400+75=2475예요.',
             en:'With 4-digit numbers break off hundreds: 4800−2325 splits 4800 into 2400 and 2400, 2400−2325=75, then 2400+75=2475.',
             zh:'四位数就分出整百：4800−2325把4800分成2400和2400，2400−2325=75，2400+75=2475。'}}] },
SB14:{ name:{ko:'999 마법과 부족한 수',en:'The 999 Trick & Shortfalls',zh:'999魔法与差几'}, gen:'cre_sb14_nines', prereq:['NS4'],
  concept:{ko:'1000에서 빼기는 999에서 빼고 1을 더해요. 999에서는 받아내림이 없어요 — 1000−349는 999−349=650, 650+1=651이에요.',
    en:'To subtract from 1000, subtract from 999 and add 1 — no borrowing from 999. 1000−349: 999−349=650, then 650+1=651.',
    zh:'从1000里减，就从999里减再加1——从999减不用退位。1000−349：999−349=650，650+1=651。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'100−□',en:'100 − □',zh:'100−□'},params:{mode:'n100'},unit:'A-26',
           concept:{ko:'100에서 빼기는 99에서 빼고 1을 더해요. 100−59는 99−59=40, 40+1=41이에요.',
             en:'To subtract from 100, subtract from 99 and add 1: 100−59 is 99−59=40, then 40+1=41.',
             zh:'从100里减，就从99里减再加1：100−59是99−59=40，40+1=41。'}},
          {id:2,label:{ko:'1000−□',en:'1000 − □',zh:'1000−□'},params:{mode:'n1000'},unit:'A-26',
           concept:{ko:'1000에서 빼기는 999에서 빼고 1을 더해요. 1000−349는 999−349=650, 650+1=651이에요.',
             en:'To subtract from 1000, subtract from 999 and add 1: 1000−349 is 999−349=650, then 650+1=651.',
             zh:'从1000里减，就从999里减再加1：1000−349是999−349=650，650+1=651。'}},
          {id:3,label:{ko:'10000·100000−□',en:'10000 / 100000 − □',zh:'10000·100000−□'},params:{mode:'big'},unit:'A-26',
           concept:{ko:'자리가 늘어도 같아요. 10000은 9999+1, 100000은 99999+1로 보고 9에서 빼요.',
             en:'More digits, same trick: see 10000 as 9999+1 and 100000 as 99999+1, and subtract from the nines.',
             zh:'位数多了也一样：把10000看成9999+1，100000看成99999+1，从9里减。'}},
          {id:4,label:{ko:'10에서 부족한 수',en:'shortfall from 10',zh:'与10的差'},params:{mode:'short'},unit:'A-29',
           concept:{ko:'자리마다 10에서 얼마나 부족한지 구하고, 일의 자리가 아니면 1을 더 빼요. 1000−349는 10−3−1=6, 10−4−1=5, 10−9=1이라 651이에요.',
             en:'For each place find how far the digit is from 10, and take 1 more except in the ones place. 1000−349: 10−3−1=6, 10−4−1=5, 10−9=1, so 651.',
             zh:'每一位求与10的差，个位以外再减1。1000−349：10−3−1=6，10−4−1=5，10−9=1，所以是651。'}}] },

/* ── ML 곱셈 ───────────────────────────── */
ML1:{ name:{ko:'배와 반(×2·÷2)',en:'Double & Half',zh:'翻倍与减半'}, gen:'ml1_double', prereq:['AD1'],
  concept:{ko:'두 배는 같은 수를 한 번 더 더한 것, 반은 똑같이 둘로 나눈 것이에요. 34의 두 배는 68, 68의 반은 34예요.',
    en:'Doubling adds a number to itself, halving splits it into two equal parts. Double 34 is 68, and half of 68 is 34.',
    zh:'翻倍就是把同一个数再加一次，减半就是平均分成两份。34的两倍是68，68的一半是34。'},
  widgets:['array','cubes','numpad'],
  levels:[{id:1,label:{ko:'한두 자리×2',en:'×2',zh:'乘2'},params:{op:'x2',max:99}},
          {id:2,label:{ko:'짝수÷2',en:'even ÷2',zh:'偶数除2'},params:{op:'d2',max:98}},
          {id:3,label:{ko:'네 자리×2·÷2',en:'4d ×2 ÷2',zh:'四位'},params:{op:'mix',max:9999}},
          /* L4(2026-09-26) — 초급 H-3 둘로 쪼개기(자리마다 반). 생성기는 engine/threads/cre.js */
          {id:4,label:{ko:'둘로 쪼개기(자리마다 반)',en:'halve place by place',zh:'按位平分'},params:{mode:'halvePlace'},unit:'A-32',
           concept:{ko:'자리마다 따로 반으로 나눠 모아요. 846의 반은 400+20+3=423, 456의 반은 200+25+3=228 — 십의 자리가 홀수면 50의 반 25를 써요.',
             en:'Halve each place separately and put them together: half of 846 is 400+20+3=423, half of 456 is 200+25+3=228 — an odd tens digit gives 25 from 50.',
             zh:'每一位分别除以2再合起来：846的一半是400+20+3=423，456的一半是200+25+3=228——十位是奇数时50的一半是25。'}}] },
ML2:{ name:{ko:'곱셈구구 2~5단',en:'Times tables 2-5',zh:'乘法口诀2~5'}, gen:'ml2_tt25', prereq:['ML1'],
  concept:{ko:'곱셈은 같은 수를 여러 번 더한 것이에요. 3×4는 3을 네 번 더한 12예요.',
    en:'Multiplication is repeated addition. 3×4 means adding 3 four times, which is 12.',
    zh:'乘法就是把同一个数加好几次。3×4是把3加四次，等于12。'},
  widgets:['array','numpad'],
  levels:[{id:1,label:{ko:'2·3단',en:'2,3',zh:'2·3'},params:{tables:[2,3]}},
          {id:2,label:{ko:'4·5단',en:'4,5',zh:'4·5'},params:{tables:[4,5]}},
          {id:3,label:{ko:'2~5단 mix',en:'2-5 mix',zh:'2~5混合'},params:{tables:[2,3,4,5]}},
          /* 2026-07-13: 디딤돌 연산 2B 실제 목차(2·5단→3·6단→4·8단→7·9단) 반영.
             동일 생성기(ml2_tt25/ml3_tt69)가 임의 tables 배열을 받으므로 레벨만 추가 */
          {id:4,label:{ko:'2·5단',en:'2,5',zh:'2·5'},params:{tables:[2,5]}},
          {id:5,label:{ko:'3·6단',en:'3,6',zh:'3·6'},params:{tables:[3,6]}}] },
ML3:{ name:{ko:'곱셈구구 6~9단',en:'Times tables 6-9',zh:'乘法口诀6~9'}, gen:'ml3_tt69', prereq:['ML2'],
  concept:{ko:'큰 단도 아는 단에서 옮겨 갈 수 있어요. 7×8은 7×4=28의 두 배인 56이에요.',
    en:'Reach the harder tables from ones you know. 7×8 is double 7×4=28, which is 56.',
    zh:'较大的乘法口诀可以从已知的推出来。7×8是7×4=28的两倍，等于56。'},
  widgets:['array','numpad'],
  levels:[{id:1,label:{ko:'6·7단',en:'6,7',zh:'6·7'},params:{tables:[6,7]}},
          {id:2,label:{ko:'8·9단',en:'8,9',zh:'8·9'},params:{tables:[8,9]}},
          {id:3,label:{ko:'6~9단 mix',en:'6-9 mix',zh:'6~9混合'},params:{tables:[6,7,8,9]}},
          {id:4,label:{ko:'4·8단',en:'4,8',zh:'4·8'},params:{tables:[4,8]}},
          {id:5,label:{ko:'7·9단',en:'7,9',zh:'7·9'},params:{tables:[7,9]}}] },
ML4:{ name:{ko:'구구 mix·□채우기',en:'Tables mix & missing',zh:'口诀混合与填空'}, gen:'ml4_ttMix', prereq:['ML3'],
  concept:{ko:'곱셈을 거꾸로 물으면 나눗셈이 돼요. □×6=42는 42÷6=7이므로 □는 7이에요.',
    en:'Asking multiplication backwards is division. For □×6=42, since 42÷6=7, the missing number is 7.',
    zh:'把乘法反过来问就是除法。□×6=42中，42÷6=7，所以□是7。'},
  widgets:['missing','numpad'],
  levels:[{id:1,label:{ko:'2~9단 mix',en:'2-9 mix',zh:'2~9混合'},params:{missing:false}},
          {id:2,label:{ko:'□채우기(역구구)',en:'missing factor',zh:'填空(逆口诀)'},params:{missing:true}}] },
ML5:{ name:{ko:'몇십 곱',en:'Multiplying tens',zh:'整十乘法'}, gen:'ml5_tensMul', prereq:['ML2','NS1'],
  concept:{ko:'뒤의 0을 떼고 곱한 뒤 뗀 0을 그대로 붙여요. 30×40은 3×4=12에 0을 두 개 붙여 1200이에요.',
    en:'Drop the zeros, multiply, then put them back. For 30×40, 3×4=12 and two zeros return, giving 1200.',
    zh:'先去掉末尾的0相乘，再把0补回去。30×40中3×4=12，补两个0得1200。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'10s×1d',en:'tens×1d',zh:'几十乘一位'},params:{mode:'t1'}},
          {id:2,label:{ko:'10s×10s',en:'tens×tens',zh:'几十乘几十'},params:{mode:'tt'},
           concept:{ko:'양쪽 모두 0을 떼고 곱한 뒤 뗀 0을 **모두** 붙여요 — 40×90은 4×9=36에 0 두 개를 붙여 3600이에요.',
             en:'Drop the zeros from both numbers, multiply, then put all of them back: 40×90 is 4×9=36 with two zeros, so 3600.',
             zh:'两边的0都去掉相乘，再把去掉的0全部补回：40×90是4×9=36加两个0，得3600。'}}] },
ML6:{ name:{ko:'두 자리×한 자리(분배 암산)',en:'2d×1d mental',zh:'两位乘一位(心算)'}, gen:'ml6_mul2d1dMental', prereq:['ML4','ML5'],
  concept:{ko:'두 자리 수를 몇십과 몇으로 나눠 각각 곱한 뒤 더해요. 34×6은 30×6=180과 4×6=24를 더해 204예요.',
    en:'Split the two digit number into tens and ones, multiply each, then add. For 34×6, 30×6=180 plus 4×6=24 gives 204.',
    zh:'把两位数拆成几十和几分别相乘再相加。34×6中30×6=180，4×6=24，合起来是204。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'올림 없음',en:'no carry',zh:'不进位'},params:{carry:'none'},
           concept:{ko:'올림이 없으면 몇십과 몇을 따로 곱해 더하면 끝이에요. 23×3은 20×3=60과 3×3=9를 더해 69예요.',
             en:'With no carry, multiply the tens and the ones separately and add: 23×3 is 20×3=60 plus 3×3=9 — 69.',
             zh:'不进位时，几十和几分别相乘再相加：23×3是20×3=60加3×3=9——69。'}},
          {id:2,label:{ko:'십의 자리에서 올림',en:'carry from the tens',zh:'十位进位'},params:{carry:'tens'},
           concept:{ko:'일의 자리는 그대로인데 십의 자리 곱이 10을 넘는 경우예요. 51×2는 1×2=2를 쓰고, 5×2=10이라 십의 자리에 0, 백의 자리에 1을 써 102예요.',
             en:'The ones stay put but the tens product passes 10: for 51×2 write 1×2=2, then 5×2=10 puts 0 in the tens and 1 in the hundreds — 102.',
             zh:'个位不变，十位相乘却满10：51×2先写1×2=2，5×2=10所以十位写0、百位写1——102。'}},
          {id:3,label:{ko:'일의 자리에서 올림',en:'carry from the ones',zh:'个位进位'},params:{carry:'ones'},
           concept:{ko:'일의 자리 곱이 10을 넘으면 올린 수를 십의 자리 곱에 더해요. 15×2는 5×2=10이라 0을 쓰고 1을 올려, 1×2+1=3 → 30이에요.',
             en:'When the ones product passes 10, add the carry to the tens product: 15×2 gives 5×2=10, write 0 and carry 1, then 1×2+1=3 — 30.',
             zh:'个位相乘满10就把进位加到十位：15×2中5×2=10，写0进1，再算1×2+1=3——30。'}},
          {id:4,label:{ko:'올림이 번져 100을 넘음',en:'carry spills past 100',zh:'进位使积超过100'},params:{carry:'over'},
           concept:{ko:'십의 자리 곱은 10을 안 넘는데 올린 수 때문에 넘는 경우예요. 34×3은 4×3=12라 1을 올리고, 3×3=9에 1을 더해 10 → 102. 올린 수를 빠뜨리면 답이 크게 틀려요.',
             en:'The tens product alone stays under 10, but the carry tips it over: 34×3 gives 4×3=12 (carry 1), then 3×3=9 plus 1 is 10 — 102. Drop the carry and the answer is badly wrong.',
             zh:'十位相乘本身不到10，加上进位才超过：34×3中4×3=12（进1），3×3=9加1等于10——102。漏掉进位答案会差很多。'}},
          {id:5,label:{ko:'올림 두 번',en:'two carries',zh:'两次进位'},params:{carry:'both'},
           concept:{ko:'일의 자리에서도, 십의 자리에서도 올림이 나는 경우예요. 45×3은 5×3=15(1 올림), 4×3=12에 1을 더해 13 → 135. 올린 수를 작게 적어 두고 가세요.',
             en:'Both places carry: 45×3 gives 5×3=15 (carry 1), then 4×3=12 plus 1 is 13 — 135. Jot each carry down as you go.',
             zh:'个位和十位都要进位：45×3中5×3=15（进1），4×3=12加1等于13——135。把进位写小一点记下来。'}},
          {id:6,label:{ko:'올림 섞기',en:'carries mixed',zh:'进位混合'},params:{easy:false},
           concept:{ko:'이번에는 올림이 어디서 나는지 문항마다 달라요. 일의 자리 곱부터 세어 보고 올릴 것이 있는지 먼저 확인하세요.',
             en:'Now the carry can land anywhere. Work out the ones product first and check whether anything carries.',
             zh:'这次每题进位的位置都不同。先算个位的积，看有没有要进的数。'}},
          {id:7,label:{ko:'쉬운 수(몇십 곱)',en:'easy tens',zh:'整十数'},params:{easy:true},
           concept:{ko:'몇십에 한 자리를 곱하면 0을 떼고 곱한 뒤 다시 붙이면 돼요. 40×6은 4×6=24이니 240이에요.',
             en:'Multiplying a multiple of ten: drop the zero, multiply, put it back. 40×6 is 4×6=24, so 240.',
             zh:'整十数乘一位数：去掉0再乘，然后补回去。40×6是4×6=24，所以是240。'}}] },
ML7:{ name:{ko:'세 자리×한 자리',en:'3d×1d',zh:'三位乘一位'}, gen:'ml7_mul3d1d', prereq:['ML6'],
  concept:{ko:'백·십·일로 나눠 곱한 뒤 더해요. 자리마다 생기는 올림을 윗자리로 잊지 않고 보내요.',
    en:'Split into hundreds, tens and ones, multiply each, then add. Remember to send each carry to the place above.',
    zh:'拆成百位、十位、个位分别相乘再相加。每位产生的进位别忘了送到上一位。'},
  widgets:['steps','vertical','numpad'],
  levels:[{id:1,label:{ko:'올림 없음',en:'no carry',zh:'不进位'},params:{carry:'none'},
           concept:{ko:'올림이 없으면 백·십·일을 따로 곱해 더하면 끝이에요. 123×3은 300×3=900, 20×3=60, 3×3=9를 더해 969예요.',
             en:'With no carry, multiply hundreds, tens and ones separately and add: 123×3 is 900 + 60 + 9 — 969.',
             zh:'不进位时百位、十位、个位分别相乘再相加：123×3是900+60+9——969。'}},
          {id:2,label:{ko:'올림 한 번',en:'one carry',zh:'进位一次'},params:{carry:'one'},
           concept:{ko:'한 자리에서만 10을 넘는 경우예요. 어느 자리에서 올림이 나는지 먼저 살펴보고 그 자리만 조심하면 돼요. 214×4는 4×4=16이라 1을 올리고, 1×4+1=5, 2×4=8 → 856.',
             en:'Only one place passes 10 — spot which before you start. For 214×4, 4×4=16 carries 1, then 1×4+1=5 and 2×4=8 — 856.',
             zh:'只有一位满10，先看清是哪一位。214×4中4×4=16进1，1×4+1=5，2×4=8——856。'}},
          {id:3,label:{ko:'올림 두 번(연속)',en:'two carries',zh:'连续进位'},params:{carry:'two'},
           concept:{ko:'일의 자리에서 올리고 십의 자리에서 또 올리는 경우예요. 156×2는 6×2=12(1 올림), 5×2+1=11(1 올림), 1×2+1=3 → 312. 올린 수를 작게 적어 두고 가세요.',
             en:'A carry from the ones and another from the tens: 156×2 gives 6×2=12 (carry 1), 5×2+1=11 (carry 1), 1×2+1=3 — 312. Jot each carry down.',
             zh:'个位进位后十位又进位：156×2中6×2=12（进1），5×2+1=11（进1），1×2+1=3——312。把进位写下来。'}},
          {id:4,label:{ko:'가로 분배(섞기)',en:'horizontal, mixed',zh:'横式(混合)'},params:{},
           concept:{ko:'가로로 쓸 때는 백·십·일로 쪼개 곱한 뒤 더해요. 큰 자리부터 더해 가면 어림이 쉬워요 — 247×3은 600+120+21.',
             en:'Written across, split into hundreds, tens and ones, multiply each and add. Starting from the big place makes estimating easy — 247×3 is 600+120+21.',
             zh:'横式要拆成百位、十位、个位分别乘再相加。从大的数位加起便于估算——247×3是600+120+21。'}},
          {id:5,label:{ko:'세로셈(섞기)',en:'column, mixed',zh:'竖式(混合)'},params:{vertical:true},
           concept:{ko:'세로로 쓸 때는 일의 자리부터 한 자리씩 곱하고, 올린 수는 윗자리 위 작은 칸에 적어요. 자리를 맞춰 쓰는 것이 반이에요.',
             en:'In column form multiply place by place from the ones, writing each carry in the small box above. Half the work is lining it up.',
             zh:'竖式从个位开始逐位相乘，进位写在上方小格里。一半功夫在对齐数位。'}}] },
ML8:{ name:{ko:'두 자리×두 자리',en:'2d×2d',zh:'两位乘两位'}, gen:'ml8_mul2d2d', prereq:['ML6'],
  concept:{ko:'뒤의 수를 몇십과 몇으로 나눠 두 번 곱하고 더해요. 23×45는 23×40=920과 23×5=115를 더해 1035예요.',
    en:'Split the second number into tens and ones, multiply twice, then add. For 23×45, 23×40=920 plus 23×5=115 gives 1035.',
    zh:'把第二个数拆成几十和几，乘两次再相加。23×45中23×40=920，23×5=115，合得1035。'},
  widgets:['steps','vertical','numpad'],
  /* 올림 횟수로 가른 사다리(2026-09-19) — 창의수연 C11 "올림 없는 (두)×(두)" + D권 올림 1~4회.
     세로셈 부분곱이 둘이라 올림 자리가 넷이다(_ml8Carries). 엑스맨(확장)은 그 뒤로 밀렸다 —
     과정 26의 핀도 ML8@3 → ML8@6 으로 같이 옮겼다. */
  levels:[{id:1,label:{ko:'몇십 곱하기',en:'× tens',zh:'乘几十'},params:{tens:true},
           concept:{ko:'몇십을 곱할 때는 십의 자리만 곱하고 끝에 0을 하나 붙여요. 24×30은 24×3=72에 0을 붙여 720이에요.',
             en:'To multiply by a ten, multiply by the tens digit and add one zero: 24×30 is 24×3=72 then a zero — 720.',
             zh:'乘几十时只乘十位数字，末尾添一个0：24×30先算24×3=72，添0得720。'}},
          {id:2,label:{ko:'올림 없음',en:'no carry',zh:'不进位'},params:{carry:'none'},
           concept:{ko:'어느 자리에서도 10을 넘지 않는 경우예요. 12×34는 12×30=360과 12×4=48을 더해 408이에요. 곱할 때 올림이 없으니 자리만 잘 맞추면 돼요.',
             en:'No place passes 10. For 12×34, 12×30=360 plus 12×4=48 makes 408 — with no carry to track, just line the places up.',
             zh:'各位都不满10。12×34中12×30=360加12×4=48得408——没有进位，只要对齐数位。'}},
          {id:3,label:{ko:'올림 한 번',en:'one carry',zh:'进位一次'},params:{carry:'one'},
           concept:{ko:'네 자리 중 한 곳에서만 10을 넘어요. 어느 부분곱에서 올림이 나는지 먼저 보고 그 자리만 조심해요. 13×24는 13×4=52에서 올림이 한 번 나요.',
             en:'Only one of the four spots passes 10 — find which partial product carries, and watch just that one. In 13×24, the carry comes from 13×4=52.',
             zh:'四处中只有一处满10。先看清哪个部分积进位，只盯住那一处。13×24中13×4=52产生进位。'}},
          {id:4,label:{ko:'올림 두 번',en:'two carries',zh:'进位两次'},params:{carry:'two'},
           concept:{ko:'올림이 두 곳에서 나요. 한 부분곱 안에서 연달아 나기도 하고, 두 부분곱에 하나씩 나기도 해요. 올린 수를 부분곱마다 따로 적어 두세요 — 섞이면 답이 어긋나요.',
             en:'Two spots carry — sometimes twice inside one partial product, sometimes once in each. Jot each carry beside its own row; mixing them up breaks the answer.',
             zh:'有两处进位——可能在同一个部分积里连续两次，也可能两个部分积各一次。把进位分别记在各自那一行旁边，混了答案就错。'}},
          {id:5,label:{ko:'올림 세 번 이상',en:'three or more carries',zh:'进位三次以上'},params:{carry:'many'},
           concept:{ko:'두 부분곱 모두에서 올림이 거듭 나는 경우예요. 67×48처럼 큰 수끼리 곱할 때죠. 부분곱 두 줄을 끝까지 따로 구한 뒤 마지막에 더하면 헷갈리지 않아요.',
             en:'Both partial products carry more than once — the big-by-big case like 67×48. Finish each of the two rows on its own, then add at the end.',
             zh:'两个部分积都多次进位，就像67×48这样的大数相乘。先把两行各自算完，最后再相加就不会乱。'}},
          /* 고급 C '엑스맨 곱셈' 확장 — 3자리×2자리 · 3자리×3자리 (정독 수치 범위) */
          {id:6,label:{ko:'엑스맨(3자리×2자리)',en:'X-cross (3d×2d)',zh:'X交叉(三位×两位)'},params:{digits:'3x2'}},
          {id:7,label:{ko:'엑스맨(3자리×3자리)',en:'X-cross (3d×3d)',zh:'X交叉(三位×三位)'},params:{digits:'3x3'}}] },
ML9:{ name:{ko:'세 자리×두 자리',en:'3d×2d',zh:'三位乘两位'}, gen:'ml9_mul3d2d', prereq:['ML8'],
  concept:{ko:'자리를 맞춰 두 번 곱하고 더해요. 두 번째 곱은 십의 자리를 곱한 것이라 한 칸 왼쪽에서 시작해요.',
    en:'Multiply twice with the places lined up, then add. The second product comes from the tens, so it starts one column to the left.',
    zh:'对齐数位乘两次再相加。第二次乘的是十位，所以要从左边一格开始写。'},
  widgets:['vertical','steps','numpad'],
  /* 올림 횟수 사다리(2026-09-19) — 교재 D07 "올림 4회", E01 "올림 6회"가 이 자리다.
     한 줄에 최대 3회(백→천 포함)라 최대 6회. 1·2회, 3·4회, 5·6회를 한 계단씩으로 묶었다. */
  levels:[{id:1,label:{ko:'몇십 곱하기',en:'× tens',zh:'乘几十'},params:{tens:true},
           concept:{ko:'몇십을 곱할 때는 십의 자리만 곱하고 끝에 0을 하나 붙여요. 164×50은 164×5=820에 0을 붙여 8200이에요.',
             en:'To multiply by a ten, multiply by the tens digit and add one zero: 164×50 is 164×5=820 then a zero — 8200.',
             zh:'乘几十时只乘十位数字，末尾添一个0：164×50先算164×5=820，添0得8200。'}},
          {id:2,label:{ko:'올림 없음',en:'no carry',zh:'不进位'},params:{carry:'none'},
           concept:{ko:'어느 자리에서도 10을 넘지 않아요. 123×12는 123×2=246과 123×10=1230을 더해 1476이에요. 두 번째 줄이 한 칸 왼쪽에서 시작하는 것만 지키면 돼요.',
             en:'No place passes 10. For 123×12, 123×2=246 plus 123×10=1230 makes 1476 — just keep the second row shifted one column left.',
             zh:'各位都不满10。123×12中123×2=246加123×10=1230得1476——只要第二行向左错一格。'}},
          {id:3,label:{ko:'올림 한두 번',en:'one or two carries',zh:'进位一两次'},params:{carry:'few'},
           concept:{ko:'올림이 한두 곳에서만 나요. 두 줄 중 어느 줄에서 나는지 먼저 보고 그 줄만 조심해요. 올린 수는 그 줄 옆에 따로 적어 두세요.',
             en:'Only one or two spots carry. Spot which of the two rows carries and watch that one; jot its carry beside that row.',
             zh:'只有一两处进位。先看清是哪一行进位，只盯住那一行，把进位记在那行旁边。'}},
          {id:4,label:{ko:'올림 서너 번',en:'three or four carries',zh:'进位三四次'},params:{carry:'mid'},
           concept:{ko:'두 줄 모두에서 올림이 나요. 164×55는 164×5=820, 164×50=8200 — 줄마다 두 번씩 올렸어요. 한 줄을 끝까지 구한 뒤 다음 줄로 가면 덜 헷갈려요.',
             en:'Both rows carry. In 164×55, 164×5=820 and 164×50=8200 — two carries in each row. Finish one row before starting the next.',
             zh:'两行都进位。164×55中164×5=820、164×50=8200——每行各进位两次。先算完一行再算下一行。'}},
          {id:5,label:{ko:'올림 다섯 번 이상',en:'five or more carries',zh:'进位五次以上'},params:{carry:'many'},
           concept:{ko:'백의 자리에서도 올림이 나서 자리가 하나 더 늘어나요. 432×56은 432×6=2592, 432×50=21600 — 줄마다 세 번씩 올렸어요. 올린 수를 작게 적어 두고 가세요.',
             en:'The hundreds place carries too, so the answer grows a digit: 432×56 gives 432×6=2592 and 432×50=21600 — three carries per row. Write each carry down.',
             zh:'百位也进位，位数又多一位：432×56中432×6=2592、432×50=21600——每行各进位三次。把进位写下来。'}}] },
ML10:{ name:{ko:'특수곱(19단·99단·기준곱)',en:'Special products',zh:'特殊乘法'}, gen:'ml10_specialMul', prereq:['ML8'],
  concept:{ko:'가까운 기준 수를 잡으면 큰 곱도 빨라져요. 19×7은 20×7=140에서 7을 빼 133이에요.',
    en:'Pick a nearby round number and the product comes fast. For 19×7, take 20×7=140 and subtract 7 to get 133.',
    zh:'找一个相近的整数作基准，大数相乘也很快。19×7用20×7=140再减7，得133。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'19단',en:'11-19 table',zh:'19段'},params:{mode:'t19'}},
          {id:2,label:{ko:'99단·기준곱',en:'91-99, anchors',zh:'99段·基准'},params:{mode:'t99'},
           concept:{ko:'99를 곱할 땐 100을 곱하고 원래 수를 한 번 빼요 — 99×34는 3400−34=3366이에요.',
             en:'To multiply by 99, multiply by 100 and take the number away once: 99×34 is 3400−34 = 3366.',
             zh:'乘99时先乘100再减去原数一次：99×34是3400−34=3366。'}},
          {id:3,label:{ko:'25×4·37×3 활용',en:'25×4, 37×3 tricks',zh:'25×4·37×3'},params:{mode:'anchor'},
           concept:{ko:'25×4=100, 37×3=111처럼 딱 떨어지는 짝을 알아 두면 큰 곱이 한 번에 풀려요 — 16×25는 16÷4=4에 100을 곱해 400이에요.',
             en:'Knowing the neat pairs — 25×4=100, 37×3=111 — cracks bigger products at once: 16×25 is 16÷4=4 times 100, so 400.',
             zh:'记住25×4=100、37×3=111这样的整齐搭配，大乘法一下就解开：16×25是16÷4=4再乘100，得400。'}}] },
ML11:{ name:{ko:'제곱수·거듭제곱',en:'Squares & powers',zh:'平方数与乘方'}, gen:'ml11_squares', prereq:['ML8'],
  unit:'C-01',
  concept:{ko:'같은 수를 여러 번 곱하는 걸 거듭제곱이라 해요. aⁿ은 a를 n번 곱한 것, 10ⁿ은 1 뒤에 0이 n개예요.',
    en:'Multiplying the same number over and over is called a power. aⁿ means a multiplied n times, and 10ⁿ is a 1 followed by n zeros.',
    zh:'同一个数乘好几次叫乘方。aⁿ就是a连乘n次，10ⁿ就是1后面跟n个0。'},
  widgets:['array','steps','numpad'],
  levels:[{id:1,label:{ko:'11²~20²',en:'11²-20²',zh:'11²~20²'},params:{lo:11,hi:20}},
          {id:2,label:{ko:'21²~40²',en:'21²-40²',zh:'21²~40²'},params:{lo:21,hi:40}},
          {id:3,label:{ko:'2·3·5 거듭제곱',en:'powers of 2,3,5',zh:'2·3·5的乘方'},params:{powers:true}},
          /* 고급 A '1로 끝나는 수의 제곱' 확장 (11²~991², 정독 수치 범위) */
          {id:4,label:{ko:'1로 끝나는 수의 제곱',en:'Squares ending in 1',zh:'尾数1的平方'},params:{mode:'end1'},
           concept:{ko:'1로 끝나는 수의 제곱은 앞자리의 제곱, 앞자리의 2배, 1을 이어 붙여요 — 251²은 25²=625, 2×25=50, 1이라 63001이에요.',
             en:'To square a number ending in 1: square the front part, double it, then 1 — 251² is 25²=625, 2×25=50 and 1, giving 63001.',
             zh:'以1结尾的数的平方：前段的平方、前段的2倍、再加1——251²是25²=625、2×25=50、1，得63001。'}},
          /* 고급 D '제곱수 점화식' 확장 (11²~501², 방향 자유 선택) */
          {id:5,label:{ko:'제곱수 점화식',en:'Square recurrence',zh:'平方数递推'},params:{mode:'adjacent'},
           concept:{ko:'이웃한 제곱수를 알면 다음 제곱수는 앞 제곱수에 두 수의 합을 더하면 나와요 — 223²은 222²에 222+223=445를 더한 값이에요.',
             en:'If you know the square next door, add the two numbers together to step up: 223² is 222² plus 222+223 = 445.',
             zh:'知道相邻的平方数时，加上两数之和就能算下一个：223²是222²加上222+223=445。'}}] },

/* ── DV 나눗셈 ───────────────────────────── */
DV1:{ name:{ko:'반으로 나누기(÷2)',en:'Halving',zh:'除以2'}, gen:'dv1_half', prereq:['ML1'],
  concept:{ko:'똑같이 둘로 나누는 것이 반이에요. 짝수는 딱 떨어지지만 홀수를 반으로 나누면 0.5가 남아요.',
    en:'Halving splits a number into two equal parts. Even numbers split cleanly, but an odd number leaves 0.5.',
    zh:'减半就是平均分成两份。偶数正好分完，奇数分一半会多出0.5。'},
  widgets:['array','cubes','numpad'],
  levels:[{id:1,label:{ko:'짝수÷2',en:'even÷2',zh:'偶数'},params:{odd:false}},
          {id:2,label:{ko:'홀수÷2(=0.5)',en:'odd÷2',zh:'奇数(0.5)'},params:{odd:true}}] },
DV2:{ name:{ko:'두 자리÷한 자리',en:'2d÷1d',zh:'两位除一位'}, gen:'dv2_div2d1d', prereq:['ML4'],
  concept:{ko:'큰 자리부터 차례로 나눠요. 84÷4는 80÷4=20과 4÷4=1을 더해 21이에요.',
    en:'Divide place by place, starting from the largest. For 84÷4, 80÷4=20 plus 4÷4=1 gives 21.',
    zh:'从最高位开始依次去除。84÷4中80÷4=20，4÷4=1，合得21。'},
  widgets:['array','steps','numpad'],
  levels:[{id:1,label:{ko:'나머지×',en:'no remainder',zh:'无余数'},params:{rem:false}}] },
DV3:{ name:{ko:'나머지 있는 나눗셈',en:'Division w/ remainder',zh:'有余数除法'}, gen:'dv3_divRem', prereq:['DV2'],
  concept:{ko:'똑같이 나누고 남는 것이 나머지예요. 나머지는 나누는 수보다 항상 작아요. 17÷5는 몫 3에 나머지 2예요.',
    en:'What is left over after sharing equally is the remainder, and it is always smaller than the divisor. 17÷5 gives 3 remainder 2.',
    zh:'平均分后剩下的就是余数，余数总比除数小。17÷5商3余2。'},
  widgets:['array','steps','numpad'],
  levels:[{id:1,label:{ko:'2d÷1d(나)',en:'2d÷1d rem',zh:'两位(余)'},params:{d:2}}] },
DV4:{ name:{ko:'세 자리÷한 자리',en:'3d÷1d',zh:'三位除一位'}, gen:'dv4_div3d1d', prereq:['DV3'],
  concept:{ko:'백의 자리부터 차례로 내려가며 나눠요. 남은 수는 다음 자리 숫자와 함께 내려서 이어 나눠요.',
    en:'Work down from the hundreds place. Bring each leftover down together with the next digit and keep dividing.',
    zh:'从百位开始逐位相除。把余下的数和下一位一起落下来继续除。'},
  widgets:['steps','vertical','numpad'],
  levels:[{id:1,label:{ko:'나머지×',en:'no rem',zh:'无余数'},params:{rem:false}},
          {id:2,label:{ko:'나머지',en:'remainder',zh:'有余数'},params:{rem:true}}] },
DV5:{ name:{ko:'두 자리로 나누기',en:'÷2-digit',zh:'除以两位数'}, gen:'dv5_div2d', prereq:['DV4','ML8'],
  concept:{ko:'나누는 수가 두 자리면 앞의 두 자리와 견줘 몫을 짐작해요. 어림한 몫을 곱해 보며 맞춰 가요.',
    en:'With a two digit divisor, compare it with the first two digits to estimate the quotient, then multiply to check and adjust.',
    zh:'除数是两位数时，先和前两位比较来估商，再乘一乘验证调整。'},
  widgets:['steps','numpad'],
  /* 교재 D12·D13(세 자리÷두 자리, 나머지 유무)이 이 자리다(2026-09-20).
     네 자리(D14·D15)는 자릿수만 늘어난 것이라 한 레벨로 합쳤다. */
  levels:[{id:1,label:{ko:'두 자리 ÷ 두 자리',en:'2d ÷ 2d',zh:'两位除两位'},params:{d:2},
           concept:{ko:'나누는 수가 두 자리면 몫이 한 자리예요. 나누는 수를 2배, 3배… 해 보며 나누어지는 수를 넘지 않는 가장 큰 배수를 찾아요.',
             en:'With a two-digit divisor on a two-digit number the quotient is one digit — double it, triple it, and find the largest multiple that does not pass the dividend.',
             zh:'两位数除以两位数时商是一位数。把除数乘2、乘3……找出不超过被除数的最大倍数。'}},
          {id:2,label:{ko:'세 자리 ÷ 두 자리 (나머지 없음)',en:'3d ÷ 2d, exact',zh:'三位除两位(整除)'},params:{d:3,rem:false},
           concept:{ko:'앞의 두 자리를 나누는 수와 견줘 몫이 몇 자리인지 먼저 정해요. 441÷21은 44가 21보다 크니 몫이 두 자리예요.',
             en:'Compare the first two digits with the divisor to fix how many digits the quotient has: in 441÷21, 44 is bigger than 21, so the quotient has two digits.',
             zh:'先把前两位和除数比一比，定下商是几位数：441÷21中44大于21，所以商是两位数。'}},
          {id:3,label:{ko:'세 자리 ÷ 두 자리 (나머지 있음)',en:'3d ÷ 2d, remainder',zh:'三位除两位(有余数)'},params:{d:3,rem:true},
           concept:{ko:'몫을 구한 뒤 남은 수가 나머지예요. 나머지는 나누는 수보다 항상 작아야 해요 — 크면 몫을 하나 더 세울 수 있다는 뜻이에요.',
             en:'What is left after the quotient is the remainder, and it must always be smaller than the divisor — if it is not, the quotient can go up by one.',
             zh:'求出商后剩下的就是余数。余数必须小于除数——否则说明商还能再大一。'}},
          {id:4,label:{ko:'네 자리 ÷ 두 자리',en:'4d ÷ 2d',zh:'四位除两位'},params:{d:4},
           concept:{ko:'자릿수가 늘어도 방법은 같아요. 천의 자리부터 두 자리씩 견줘 몫의 자리를 잡고, 내려오며 같은 일을 반복해요.',
             en:'More digits, same method: compare two digits at a time from the thousands, set that place of the quotient, bring the next digit down and repeat.',
             zh:'位数变多方法不变：从千位起每次比两位定下商的一位，再落下一位重复同样的步骤。'}}] },
DV6:{ name:{ko:'배수판별법',en:'Divisibility rules',zh:'整除判别'}, gen:'dv6_divisibility', prereq:['ML4'],
  concept:{ko:'나눠 보지 않아도 배수인지 알 수 있어요. 끝자리가 짝수면 2의 배수, 0이나 5면 5의 배수, 각 자리 숫자의 합이 3의 배수면 3의 배수예요. 7은 뒷자리를 떼고 그 2배를 남은 수에서 빼면 되고(203 → 20−6=14, 7의 배수!), 11은 홀수번째 자리의 합과 짝수번째 자리의 합의 차를 봐요(8195 → 17−6=11, 11의 배수!).',
    en:'You can spot multiples without dividing. Even last digit means a multiple of 2, ending in 0 or 5 means 5, and digits summing to a multiple of 3 means 3. For 7, drop the last digit and subtract twice it (203 → 20−6=14, a multiple of 7!). For 11, take the difference between the odd-place and even-place digit sums (8195 → 17−6=11, a multiple of 11!).',
    zh:'不用真的去除也能判断倍数。末位是偶数就是2的倍数，末位是0或5就是5的倍数，各位数字之和是3的倍数就是3的倍数。判断7时，去掉末位再减去它的2倍（203 → 20−6=14，是7的倍数！）；判断11时，看奇数位之和与偶数位之和的差（8195 → 17−6=11，是11的倍数！）。'},
  widgets:['missing','numpad'],
  levels:[{id:1,label:{ko:'2·5·10',en:'2,5,10',zh:'2·5·10'},params:{rules:[2,5,10]}},
          {id:2,label:{ko:'3·6·9',en:'3,6,9',zh:'3·6·9'},params:{rules:[3,6,9]}},
          {id:3,label:{ko:'7 — 뒷자리 2배 빼기',en:'7 — subtract twice the last digit',zh:'7 — 减末位的2倍'},params:{mode:'rule7'},
           concept:{ko:'7의 배수는 끝자리를 떼고 그 2배를 남은 수에서 빼 봐요. 남은 값이 7의 배수면 처음 수도 7의 배수예요 — 983은 98−2×3=92라 7의 배수가 아니에요.',
             en:'For 7, chop off the last digit and subtract twice it from what is left; if that result is a multiple of 7 so is the original. 983 gives 98−2×3=92, which is not a multiple of 7.',
             zh:'判断7的倍数：去掉末位，用剩下的数减去末位的2倍；结果若是7的倍数，原数也是。983是98−2×3=92，不是7的倍数。'}},
          {id:4,label:{ko:'11 — 홀·짝 자리의 차',en:'11 — odd vs even place difference',zh:'11 — 奇偶位之差'},params:{mode:'rule11'},
           concept:{ko:'11의 배수는 홀수 자리 합과 짝수 자리 합의 차를 봐요. 그 차가 0이거나 11의 배수면 11의 배수예요 — 9843은 (9+4)−(8+3)=2라 아니에요.',
             en:'For 11, compare the sum of the odd places with the sum of the even places; if the difference is 0 or a multiple of 11, the number is too. 9843 gives (9+4)−(8+3)=2, so it is not.',
             zh:'判断11的倍数：看奇数位之和与偶数位之和的差，差是0或11的倍数就是。9843是(9+4)−(8+3)=2，所以不是。'}}] },
DV7:{ name:{ko:'약수·배수·최대공약·최소공배',en:'Factors, GCD & LCM',zh:'因数倍数'}, gen:'dv7_gcdLcm', prereq:['DV6'],
  concept:{ko:'나누어떨어지게 하는 수가 약수, 몇 배 한 수가 배수예요. 두 수의 공통 약수 중 가장 큰 것이 최대공약수예요.',
    en:'A divisor divides with no remainder, and a multiple is the number times something. The largest shared divisor is the greatest common divisor.',
    zh:'能整除的数是约数，成倍数关系的是倍数。两数公共约数中最大的就是最大公约数。'},
  widgets:['array','steps','numpad'],
  levels:[{id:1,label:{ko:'약수 찾기',en:'factors',zh:'找因数'},params:{mode:'factors'}},
          {id:2,label:{ko:'최대공약수',en:'GCD',zh:'最大公因数'},params:{mode:'gcd'},
           concept:{ko:'두 수를 모두 나누어떨어지게 하는 수 가운데 가장 큰 것이 최대공약수예요 — 45와 36의 공약수는 1·3·9이고 가장 큰 9가 최대공약수예요.',
             en:'The greatest common divisor is the largest number that divides both: 45 and 36 share 1, 3 and 9, so it is 9.',
             zh:'能同时整除两个数的数中最大的就是最大公约数：45和36的公约数是1、3、9，最大的是9。'}},
          {id:3,label:{ko:'최소공배수',en:'LCM',zh:'最小公倍数'},params:{mode:'lcm'},
           concept:{ko:'두 수의 배수 가운데 공통으로 나오는 가장 작은 수가 최소공배수예요 — 15와 5는 15에서 처음 만나니 15예요.',
             en:'The least common multiple is the smallest number that appears in both times tables: 15 and 5 first meet at 15.',
             zh:'两个数的倍数中最先共同出现的数就是最小公倍数：15和5在15处第一次相遇。'}}] },
DV8:{ name:{ko:'소인수분해·약수의 개수',en:'Prime factorization',zh:'质因数分解'}, gen:'dv8_primeFact', prereq:['DV7'],
  concept:{ko:'1과 자기 자신으로만 나뉘는 수가 소수예요. 수를 소수의 곱으로 쪼개는 것이 소인수분해로, 12는 2×2×3이에요.',
    en:'A prime divides only by 1 and itself. Breaking a number into a product of primes is prime factorization, so 12 is 2×2×3.',
    zh:'只能被1和自身整除的数是质数。把一个数拆成质数的乘积就是质因数分解，12=2×2×3。'},
  widgets:['array','steps','numpad'],
  levels:[{id:1,label:{ko:'소수 판별',en:'prime or not',zh:'质数判别'},params:{mode:'isPrime'}},
          {id:2,label:{ko:'소인수분해',en:'factorize',zh:'分解'},params:{mode:'factorize'},
           concept:{ko:'수를 소수의 곱으로만 쪼개는 것이 소인수분해예요. 작은 소수부터 나눠 보면 돼요 — 82는 2×41이에요.',
             en:'Factorizing into primes means writing a number as a product of primes only; try the small primes in turn — 82 is 2×41.',
             zh:'质因数分解就是把一个数写成只有质数相乘的形式，从小的质数开始试：82是2×41。'}},
          {id:3,label:{ko:'약수의 개수',en:'count divisors',zh:'因数个数'},params:{mode:'count'},
           concept:{ko:'소인수분해에서 각 지수에 1을 더해 모두 곱하면 약수의 개수예요 — 242=2¹×11²이니 (1+1)×(2+1)=6개예요.',
             en:'Add one to each exponent in the prime factorization and multiply: 242 = 2¹×11², so (1+1)×(2+1) = 6 divisors.',
             zh:'把质因数分解中每个指数加1再相乘就是约数个数：242=2¹×11²，所以(1+1)×(2+1)=6个。'}}] },

/* ── FR 분수 ───────────────────────────── */
FR1:{ name:{ko:'진분수 합·차',en:'Proper fraction ±',zh:'真分数加减'}, gen:'fr1_properAddSub', prereq:['AD5','SB4'],
  concept:{ko:'분모가 같으면 분자끼리만 더하고 빼요. 분모는 그대로 두어요. 2/5+1/5는 3/5예요.',
    en:'With the same denominator, add or subtract only the numerators and keep the denominator. 2/5+1/5 is 3/5.',
    zh:'分母相同时只把分子相加减，分母不变。2/5+1/5=3/5。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'분모가 같은 분수',en:'same denominator',zh:'同分母'},params:{}}] },
FR2:{ name:{ko:'가분수↔대분수',en:'Improper↔Mixed',zh:'假分数与带分数'}, gen:'fr2_improperMixed', prereq:['FR1','DV3'],
  concept:{ko:'분자가 분모보다 크면 가분수, 자연수와 진분수로 나눠 쓰면 대분수예요. 7/3은 2와 1/3이에요.',
    en:'A top heavy fraction is improper, and writing it as a whole number plus a proper fraction makes it mixed. 7/3 is 2 and 1/3.',
    zh:'分子大于分母是假分数，写成整数加真分数就是带分数。7/3就是2又1/3。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'변환',en:'convert',zh:'互换'},params:{}}] },
FR3:{ name:{ko:'대분수 덧·뺄',en:'Mixed number ±',zh:'带分数加减'}, gen:'fr3_mixedAddSub', prereq:['FR2'],
  concept:{ko:'자연수는 자연수끼리, 분수는 분수끼리 계산해요. 분수 부분이 모자라면 자연수에서 1을 빌려 와요.',
    en:'Handle whole numbers with whole numbers and fractions with fractions. If the fraction part is too small, borrow 1 from the whole number.',
    zh:'整数和整数算，分数和分数算。分数部分不够减时，就从整数借1。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'올림·내림×',en:'no regroup',zh:'不进退位'},params:{regroup:false}},
          {id:2,label:{ko:'올림·내림',en:'regroup',zh:'进退位'},params:{regroup:true}}] },
FR4:{ name:{ko:'분모가 다른 분수 덧·뺄',en:'Unlike denominators ±',zh:'异分母加减'}, gen:'fr4_unlikeAddSub', prereq:['FR3','DV7'],
  concept:{ko:'분모가 다르면 먼저 통분해요. 두 분모의 최소공배수를 공통분모로 삼아요. 1/2+1/3은 3/6+2/6=5/6이에요.',
    en:'Different denominators need a common one first, using the least common multiple. So 1/2+1/3 becomes 3/6+2/6=5/6.',
    zh:'分母不同要先通分，用两个分母的最小公倍数作公分母。1/2+1/3=3/6+2/6=5/6。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'진분수',en:'proper',zh:'真分数'},params:{mixed:false}},
          {id:2,label:{ko:'대분수',en:'mixed',zh:'带分数'},params:{mixed:true}}] },
/* 약분과 통분은 초5의 한 단원이고 방향만 반대인 같은 조작이라 한 스레드에 둔다.
   통분 레벨은 2026-08-29 신규 — FR4가 이분모 덧뺄을 하며 속으로 통분하고 있었을 뿐
   통분 자체를 묻는 유형이 없었다. prereq(DV7)가 최소공배수까지 이미 대 준다. */
FR5:{ name:{ko:'약분·통분',en:'Reducing & common denominators',zh:'约分与通分'}, gen:'fr5_simplify', prereq:['DV7'],
  concept:{ko:'분자와 분모를 같은 수로 나누는 것이 약분, 같은 수를 곱해 분모를 맞추는 것이 통분이에요. 6/8은 약분하면 3/4이고, 1/2과 1/3은 통분하면 3/6과 2/6이에요.',
    en:'Dividing numerator and denominator by the same number is reducing; multiplying both to match denominators is finding a common denominator. 6/8 reduces to 3/4, and 1/2 and 1/3 become 3/6 and 2/6.',
    zh:'分子分母同除以一个数是约分，同乘一个数把分母变一样是通分。6/8约分成3/4，1/2和1/3通分成3/6和2/6。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'약분·기약분수',en:'reduce to lowest terms',zh:'约分'},params:{}},
          {id:2,label:{ko:'통분(최소공배수)',en:'common denominator (LCM)',zh:'通分(最小公倍数)'},params:{mode:'common'},
           concept:{ko:'통분은 두 분모의 최소공배수로 분모를 맞추는 거예요. 분모에 곱한 수를 분자에도 똑같이 곱해요 — 1/2을 분모 10으로 맞추려면 5를 곱해 5/10이에요.',
             en:'To find a common denominator, use the least common multiple of the two denominators and multiply the numerator by whatever you multiplied the denominator by: 1/2 becomes 5/10.',
             zh:'通分就是把分母化成两个分母的最小公倍数，分母乘几分子也乘几：1/2化成分母10就是5/10。'}}] },
FR6:{ name:{ko:'분수 곱셈',en:'Fraction ×',zh:'分数乘法'}, gen:'fr6_frMul', prereq:['FR5','ML6'],
  concept:{ko:'분자는 분자끼리, 분모는 분모끼리 곱해요. 대분수가 있으면 먼저 가분수로 바꿔서 곱해요.',
    en:'Multiply numerators together and denominators together. Turn any mixed number into an improper fraction first.',
    zh:'分子乘分子，分母乘分母。有带分数时先化成假分数再乘。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'진분수×진분수',en:'proper×proper',zh:'真×真'},params:{mode:'pp'}},
          {id:2,label:{ko:'대분수·자연수 포함',en:'mixed/whole',zh:'带分数'},params:{mode:'mixed'},
           concept:{ko:'자연수는 분모가 1인 분수로 보면 돼요. 8×5/6은 8/1×5/6이니 분자끼리 40, 분모끼리 6이고 약분하면 20/3이에요.',
             en:'Treat a whole number as a fraction over 1: 8×5/6 is 8/1×5/6, giving 40 over 6, which reduces to 20/3.',
             zh:'整数可以看作分母是1的分数：8×5/6就是8/1×5/6，得40/6，约分后是20/3。'}},
          {id:3,label:{ko:'세 분수',en:'3 fractions',zh:'三个分数'},params:{mode:'three'},
           concept:{ko:'세 분수도 방법은 같아요. 분자는 분자끼리 모두 곱하고 분모는 분모끼리 모두 곱해요 — 3/4×1/4×3/4의 분자는 3×1×3=9예요.',
             en:'Three fractions work the same way: multiply all the numerators together and all the denominators together — the top of 3/4×1/4×3/4 is 3×1×3=9.',
             zh:'三个分数也一样：分子全部相乘、分母全部相乘——3/4×1/4×3/4的分子是3×1×3=9。'}}] },
FR7:{ name:{ko:'분수 나눗셈',en:'Fraction ÷',zh:'分数除法'}, gen:'fr7_frDiv', prereq:['FR6'],
  concept:{ko:'나눗셈은 뒤의 분수를 뒤집어 곱하면 돼요. 2/3÷4/5는 2/3×5/4와 같아요.',
    en:'To divide, flip the second fraction and multiply. So 2/3÷4/5 is the same as 2/3×5/4.',
    zh:'除以一个分数就是乘它的倒数。2/3÷4/5等于2/3×5/4。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'기본',en:'basic',zh:'基本'},params:{}}] },
FR8:{ name:{ko:'분수↔소수',en:'Fraction↔Decimal',zh:'分数与小数'}, gen:'fr8_frDec', prereq:['FR5','DC1'],
  unit:'C-35',
  concept:{ko:'분모 속에 숨은 2와 5를 찾아, 분모가 10이나 100이 되도록 분자·분모에 똑같이 곱하면 소수로 바뀌어요.',
    en:'Find the hidden 2s and 5s in the denominator, then multiply top and bottom equally to make the denominator 10, 100, or 1000 — that turns it into a decimal.',
    zh:'找到分母里藏着的2和5，把分子分母同时乘大，让分母变成10、100或1000，就变成小数了。'},
  widgets:['steps','decimal'],
  levels:[{id:1,label:{ko:'변환',en:'convert',zh:'互换'},params:{}}] },

/* ── DC 소수 ───────────────────────────── */
DC1:{ name:{ko:'소수 덧·뺄',en:'Decimal ±',zh:'小数加减'}, gen:'dc1_decAddSub', prereq:['AD5','SB4'],
  concept:{ko:'소수점끼리 세로로 맞추고 같은 자리끼리 더하고 빼요. 빈 자리는 0으로 채우면 헷갈리지 않아요.',
    en:'Line up the decimal points and work place by place. Filling empty places with 0 keeps it clear.',
    zh:'把小数点对齐，相同数位相加减。空位补0就不会混乱。'},
  widgets:['steps','vertical','decimal'],
  levels:[{id:1,label:{ko:'소수 한 자리',en:'1 place',zh:'一位小数'},params:{places:1}},
          {id:2,label:{ko:'소수 두 자리',en:'2 places',zh:'两位小数'},params:{places:2}}] },
DC2:{ name:{ko:'소수 곱셈',en:'Decimal ×',zh:'小数乘法'}, gen:'dc2_decMul', prereq:['ML8','DC1'],
  concept:{ko:'소수점을 없애고 곱한 뒤, 두 수의 소수 자릿수를 합한 만큼 소수점을 왼쪽으로 옮겨요. 0.3×0.4는 0.12예요.',
    en:'Multiply as whole numbers, then move the decimal point left by the total number of decimal places. So 0.3×0.4 is 0.12.',
    zh:'先当整数相乘，再把小数点向左移动两个因数小数位数之和。0.3×0.4=0.12。'},
  widgets:['steps','decimal'],
  levels:[{id:1,label:{ko:'기본',en:'basic',zh:'基本'},params:{}}] },
DC3:{ name:{ko:'소수 나눗셈',en:'Decimal ÷',zh:'小数除法'}, gen:'dc3_decDiv', prereq:['DV5','DC2'],
  concept:{ko:'나누는 수가 정수가 되도록 두 수에 같은 수를 곱한 뒤 나눠요. 1.2÷0.4는 12÷4와 같아 3이에요. 자연수끼리도 나누어떨어지지 않으면 나머지로 끝내지 않고 몫을 소수로 이어 나눠요 — 3÷4는 0.75예요.',
    en:'Multiply both numbers by the same amount until the divisor is whole, then divide. So 1.2÷0.4 is the same as 12÷4, which is 3. When whole numbers do not divide evenly, carry on instead of stopping at a remainder — 3÷4 is 0.75.',
    zh:'两数同时乘同一个数，使除数变成整数再除。1.2÷0.4等于12÷4，得3。整数相除除不尽时，不要停在余数上，把商继续写成小数——3÷4=0.75。'},
  widgets:['steps','decimal'],
  levels:[{id:1,label:{ko:'(소수)÷(자연수)',en:'decimal ÷ whole',zh:'小数÷整数'},params:{}},
          /* 2026-08-29 신규 — 레벨1은 몫이 늘 `0.□` 꼴이라 3÷4=0.75 같은
             (자연수)÷(자연수)가 어디에도 없었다. */
          {id:2,label:{ko:'몫이 소수인 (자연수)÷(자연수)',en:'whole ÷ whole, decimal quotient',zh:'整数÷整数(商是小数)'},params:{mode:'natural'},
           concept:{ko:'자연수끼리도 나누어떨어지지 않으면 나머지로 끝내지 않고 0을 내려 몫을 소수로 이어 나눠요 — 58÷25는 2 남고 8, 80을 25로 나눠 3, 다시 50을 나눠 2라서 2.32예요.',
             en:'When whole numbers do not divide evenly, do not stop at a remainder — bring down a zero and carry the quotient into decimals: 58÷25 gives 2 remainder 8, then 80÷25=3 and 50÷25=2, so 2.32.',
             zh:'整数相除除不尽时不要停在余数，补0继续除下去得到小数：58÷25商2余8，再80÷25=3、50÷25=2，所以是2.32。'}}] },

/* ── MX 혼합 ───────────────────────────── */
MX1:{ name:{ko:'사칙 혼합계산',en:'Order of operations',zh:'四则混合'}, gen:'mx1_orderOps', prereq:['ML7','DV4'],
  concept:{ko:'괄호 안을 가장 먼저, 그다음 곱셈과 나눗셈, 마지막에 덧셈과 뺄셈이에요. 순위가 같으면 왼쪽부터 계산해요.',
    en:'Brackets come first, then multiplication and division, then addition and subtraction. Equal ranks are done left to right.',
    zh:'先算括号，再算乘除，最后算加减。同级运算从左往右依次进行。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'괄호×',en:'no brackets',zh:'无括号'},params:{brackets:0}},
          {id:2,label:{ko:'소괄호',en:'( )',zh:'小括号'},params:{brackets:1}},
          {id:3,label:{ko:'중괄호',en:'{ }',zh:'中括号'},params:{brackets:2}}] },
MX2:{ name:{ko:'수열의 합',en:'Series sums',zh:'数列求和'}, gen:'mx2_series', prereq:['AD7','ML11'],
  concept:{ko:'1부터 n까지 더한 합은 n×(n+1)÷2예요. 양 끝에서 짝을 지으면 합이 모두 같아지는 것을 이용한 식이에요.',
    en:'The sum from 1 to n is n×(n+1)÷2. Pairing the ends gives the same total every time, which is where the formula comes from.',
    zh:'从1加到n的和是n×(n+1)÷2。把首尾配对，每对的和都相同，公式就是这样来的。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'1~n 합',en:'1..n',zh:'1~n'},params:{mode:'nat'}},
          {id:2,label:{ko:'홀·짝의 합',en:'odd/even',zh:'奇偶数和'},params:{mode:'oddEven'},
           concept:{ko:'짝수의 합 2+4+…+2n은 n×(n+1), 홀수의 합 1+3+…+(2n−1)은 n²이에요. 먼저 몇 개를 더했는지(n)부터 세요 — 2+4+…+50은 25개라 25×26=650이에요.',
             en:'Even sums 2+4+…+2n equal n×(n+1) and odd sums 1+3+…+(2n−1) equal n²; count the terms first — 2+4+…+50 has 25 terms, so 25×26 = 650.',
             zh:'偶数和2+4+…+2n等于n×(n+1)，奇数和1+3+…+(2n−1)等于n²；先数项数——2+4+…+50有25项，所以25×26=650。'}}] },
MX3:{ name:{ko:'비와 비율·백분율',en:'Ratio & percent',zh:'比与百分率'}, gen:'mx3_ratio', prereq:['FR8','DC2'],
  concept:{ko:'비율은 기준량에 대해 비교하는 양이 얼마인지를 나타내요. 비율 = 비교하는 양 ÷ 기준량이고, 백분율은 비율에 100을 곱한 것으로 0.25는 25%예요. 비는 공약수로 나누어 가장 간단한 자연수의 비로 만들어요 — 12:18은 2:3이에요.',
    en:'A ratio tells how much the compared amount is against the base amount: ratio = compared ÷ base. A percentage is that ratio times 100, so 0.25 is 25%. Divide both terms by a common factor to reach the simplest whole-number ratio — 12:18 becomes 2:3.',
    zh:'比率表示比较量相对于基准量是多少：比率 = 比较量 ÷ 基准量。百分率是比率乘100，0.25就是25%。把比的两项同除以公因数就得到最简整数比——12:18化成2:3。'},
  widgets:['steps','decimal'],
  /* 레벨 3~5는 2026-08-29 신규. 비율→백분율·할푼리만 있어서 정작 비 자체를 간단히
     하는 것도, 비율 정의(비교하는 양 ÷ 기준량)를 양쪽에서 되짚는 것도 없었다. */
  levels:[{id:1,label:{ko:'비율→백분율',en:'to %',zh:'化百分数'},params:{mode:'toPct'}},
          {id:2,label:{ko:'할푼리',en:'K. decimal ratio',zh:'割分厘'},params:{mode:'hpl'},
           concept:{ko:'소수 첫째 자리가 할, 둘째가 푼, 셋째가 리예요 — 0.788은 7할 8푼 8리예요.',
             en:'The first decimal place is hal, the second pun and the third ri: 0.788 is 7 hal 8 pun 8 ri.',
             zh:'小数第一位是"成"、第二位是"分"、第三位是"厘"：0.788是7成8分8厘。'}},
          {id:3,label:{ko:'가장 간단한 자연수의 비',en:'simplest whole-number ratio',zh:'最简整数比'},params:{mode:'simpleRatio'},
           concept:{ko:'비의 두 수를 최대공약수로 나누면 가장 간단한 자연수의 비가 돼요. 분수나 소수면 먼저 자연수로 고쳐요 — 64:56은 8로 나눠 8:7이에요.',
             en:'Divide both parts of a ratio by their greatest common divisor; turn fractions or decimals into whole numbers first — 64:56 divided by 8 is 8:7.',
             zh:'把比的两个数同除以最大公约数就得到最简整数比；分数或小数要先化成整数——64:56同除以8得8:7。'}},
          {id:4,label:{ko:'비교하는 양 구하기',en:'find the compared amount',zh:'求比较量'},params:{mode:'compQty'},
           concept:{ko:'비교하는 양 = 기준량 × 비율이에요. 백분율은 100으로 나눠 비율로 고쳐요 — 50의 20%는 50×0.2=10이에요.',
             en:'The compared amount is the base times the rate; turn a percent into a rate by dividing by 100 — 20% of 50 is 50×0.2 = 10.',
             zh:'比较量=基准量×比率；百分数要除以100化成比率——50的20%是50×0.2=10。'}},
          {id:5,label:{ko:'기준량 구하기',en:'find the base amount',zh:'求基准量'},params:{mode:'baseQty'},
           concept:{ko:'기준량 = 비교하는 양 ÷ 비율이에요 — 40이 25%이면 40÷0.25=160이 기준량이에요.',
             en:'The base is the compared amount divided by the rate: if 40 is 25%, the base is 40÷0.25 = 160.',
             zh:'基准量=比较量÷比率：40是25%时，基准量是40÷0.25=160。'}}] },
MX4:{ name:{ko:'제곱근',en:'Square roots',zh:'平方根'}, gen:'mx4_sqrt', prereq:['ML11'],
  concept:{ko:'제곱해서 그 수가 되는 수가 제곱근이에요. 12×12=144이므로 144의 제곱근은 12예요.',
    en:'A square root is the number that gives the value when multiplied by itself. Since 12×12=144, the square root of 144 is 12.',
    zh:'平方后等于某数的数就是它的平方根。12×12=144，所以144的平方根是12。'},
  widgets:['array','numpad'],
  levels:[{id:1,label:{ko:'√4~√400',en:'√4-√400',zh:'√4~√400'},params:{hi:400}},
          {id:2,label:{ko:'√4~√1600',en:'√4-√1600',zh:'√4~√1600'},params:{hi:1600}}] },
MX5:{ name:{ko:'분수·소수 혼합 총정리',en:'Mixed review',zh:'分数小数综合'}, gen:'mx5_mixedReview', prereq:['FR7','DC3','MX1'],
  concept:{ko:'분수와 소수가 섞이면 한쪽으로 통일해요. 나눗셈이 섞였을 땐 분수로 바꾸는 편이 계산이 깔끔해요.',
    en:'When fractions and decimals mix, convert everything to one form. Fractions usually keep division cleaner.',
    zh:'分数和小数混在一起时，先统一成一种形式。有除法时化成分数计算更清楚。'},
  widgets:['steps','decimal'],
  levels:[{id:1,label:{ko:'기본',en:'basic',zh:'基本'},params:{}}] },

/* ── 창의수연 중급 전략 (학습지 지원용) ─────────────── */
ML12:{ name:{ko:'곱해서 10·100·1000 만들기',en:'Pairs of 10, 100 & 1000',zh:'凑10凑100凑1000'}, gen:'ml_pair10', prereq:['ML4'],
  /* 레벨마다 다른 유닛(10→C-02, 100→C-04, 1000→C-34)과 연결된다 — 정확한 매칭은
     main.js의 UNIT_OVERRIDE_BY_LEVEL이 처리하고, 이 unit은 레벨 정보가 없을 때의 대표값 */
  unit:'C-02',
  concept:{ko:'2와 5는 친구예요. 둘이 한 번 만나면 10, 두 번 만나면 100, 세 번 만나면 1000이 돼요.',
    en:'2 and 5 are friends — meet once and you get 10, twice and you get 100, three times and you get 1000.',
    zh:'2和5是朋友。见一次面变10，两次变100，三次变1000。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'10 짝꿍',en:'pairs of 10',zh:'凑10'},params:{level:'practice',target:10}},
          {id:2,label:{ko:'100 짝꿍',en:'pairs of 100',zh:'凑100'},params:{level:'main',target:100}},
          {id:3,label:{ko:'1000 짝꿍',en:'pairs of 1000',zh:'凑1000'},params:{level:'main',target:1000}}] },
ML13:{ name:{ko:'"9"를 곱하라',en:'Multiply by 9',zh:'乘9'}, gen:'ml_x9', prereq:['ML4'],
  unit:'C-06',
  concept:{ko:'9를 곱할 땐 10을 곱하고 원래 수를 한 번 빼요. ×9는 ×10보다 딱 하나 적게 곱하는 거니까요.',
    en:'To multiply by 9, multiply by 10 first and then subtract the original number once — ×9 is just one less group than ×10.',
    zh:'乘9的时候，先乘10再减一次原来的数——乘9就是比乘10少乘一组。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
ML14:{ name:{ko:'더 곱해주고 빼기',en:'Over-multiply & subtract',zh:'多乘再减'}, gen:'ml_overmul', prereq:['ML13'],
  unit:'C-08',
  concept:{ko:'딱 떨어지는 수(10·20·100)로 올려서 곱한 다음, 더 곱해준 만큼을 다시 빼줘요.',
    en:'Round up to a friendly number (10, 20, 100), multiply, then subtract back the extra amount you added.',
    zh:'先把数凑成整十整百再乘，然后把多乘的那部分减回去。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
ML15:{ name:{ko:'"11"의 곱셈법',en:'Multiply by 11',zh:'乘11'}, gen:'ml_x11', prereq:['ML8'],
  unit:'C-13',
  concept:{ko:'11=10+1이니까, 두 자리 수에 11을 곱할 땐 앞뒤 숫자를 벌리고 그 합을 가운데 끼워 넣어요.',
    en:"Since 11=10+1, multiplying a 2-digit number by 11 means spreading its digits apart and slipping their sum in the middle.",
    zh:'11=10+1，两位数乘11时把两个数字分开，把它们的和夹在中间。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
ML16:{ name:{ko:'"5"의 변신 곱셈',en:'×5 transform',zh:'×5变身'}, gen:'ml_x5', prereq:['ML4'],
  /* 레벨1(×5)→C-16, 레벨2(÷5)→C-28 — main.js의 UNIT_OVERRIDE_BY_LEVEL 참조 */
  unit:'C-16',
  concept:{ko:'5는 10의 반쪽 친구예요. ×5는 ×10 한 다음 반으로 나누고, ÷5는 ×2 한 다음 ÷10 하면 돼요.',
    en:"5 is 10's half-friend. To ×5, multiply by 10 then halve; to ÷5, double first then divide by 10.",
    zh:'5是10的一半朋友。乘5就是乘10再减半，除以5就是先乘2再除以10。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'×5',en:'×5',zh:'×5'},params:{level:'practice',mode:'mul'}},
          {id:2,label:{ko:'÷5',en:'÷5',zh:'÷5'},params:{level:'main',mode:'div'},
           concept:{ko:'÷5는 ×2 한 다음 ÷10 하면 돼요 — 8860÷5는 17720÷10=1772예요.',
             en:'To divide by 5, double and then divide by 10: 8860÷5 is 17720÷10 = 1772.',
             zh:'除以5就是先乘2再除以10：8860÷5是17720÷10=1772。'}}] },
ML17:{ name:{ko:'"25"의 변신 곱셈',en:'×25 transform',zh:'×25变身'}, gen:'ml_x25', prereq:['ML16'],
  /* 레벨1(×25)→C-17, 레벨2(÷25)→C-29 — main.js의 UNIT_OVERRIDE_BY_LEVEL 참조 */
  unit:'C-17',
  concept:{ko:'25는 100을 네 조각으로 나눈 친구예요. ×25는 ×100 한 다음 ÷4, ÷25는 ×4 한 다음 ÷100 하면 돼요.',
    en:'25 is a friend that splits 100 into four. To ×25, multiply by 100 then divide by 4; to ÷25, multiply by 4 then divide by 100.',
    zh:'25是把100分成四份的朋友。乘25就是乘100再除以4，除以25就是先乘4再除以100。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'×25',en:'×25',zh:'×25'},params:{level:'practice',mode:'mul'}},
          {id:2,label:{ko:'÷25',en:'÷25',zh:'÷25'},params:{level:'main',mode:'div'},
           concept:{ko:'÷25는 ×4 한 다음 ÷100 하면 돼요 — 425÷25는 1700÷100=17이에요.',
             en:'To divide by 25, multiply by 4 and then divide by 100: 425÷25 is 1700÷100 = 17.',
             zh:'除以25就是先乘4再除以100：425÷25是1700÷100=17。'}}] },
ML18:{ name:{ko:'자리 이동 곱셈',en:'Place-shift multiplication',zh:'位移乘法'}, gen:'ml_placeshift', prereq:['ML8'],
  unit:'C-15',
  concept:{ko:'22, 55, 99처럼 숫자가 반복되는 수를 곱할 땐, 숫자 하나로 한 번만 곱한 뒤 한 칸 밀어(×10) 더하면 돼요.',
    en:'For repeated-digit numbers like 22, 55, or 99, multiply by just one digit, shift it over (×10), and add.',
    zh:'遇到22、55、99这样数字重复的数，只用一个数字乘一次，再移一位（×10）加起来就行。'},
  widgets:['steps','vertical','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}},
          /* 고급 D '피라미드 곱셈' 확장 — 반복숫자끼리의 곱(2~6자리, 정독 수치 범위) */
          {id:3,label:{ko:'피라미드 곱셈(연습)',en:'Pyramid multiplication (practice)',zh:'金字塔乘法(练习)'},params:{mode:'pyramid',level:'practice'},
           concept:{ko:'같은 숫자가 반복되는 두 수의 곱은 한 숫자끼리 곱한 값을 자리마다 밀어 더한 모양이에요 — 33×88은 3×8=24를 세 자리에 걸쳐 쌓아 2904예요.',
             en:'Multiplying two repdigits stacks one digit-product across the places: 33×88 builds from 3×8=24 to give 2904.',
             zh:'两个重复数字相乘就是把一位数的乘积按位错开叠加：33×88由3×8=24叠成2904。'}},
          {id:4,label:{ko:'피라미드 곱셈(실전)',en:'Pyramid multiplication (main)',zh:'金字塔乘法(实战)'},params:{mode:'pyramid',level:'main'}}] },
ML19:{ name:{ko:'VEDA 1로 끝나는 곱',en:'VEDA ending-in-1',zh:'VEDA尾数1'}, gen:'ml_veda', prereq:['ML8'],
  unit:'C-23',
  concept:{ko:'일의 자리끼리, 교차로 곱해 더한 값, 십의 자리끼리 — 이 세 걸음이면 두 자리 수 곱셈이 한 번에 끝나요.',
    en:'Ones times ones, the criss-cross sum, then tens times tens — three steps and a two-digit multiplication is done.',
    zh:'个位乘个位、交叉相乘再相加、十位乘十位——三步就能算完两位数乘法。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
ML20:{ name:{ko:'차가 2인 두 수의 곱',en:'Difference-of-2 product',zh:'差2之积'}, gen:'ml_diff2sq', prereq:['ML11'],
  unit:'C-24',
  concept:{ko:'차가 2인 두 수를 곱할 땐 가운데 수를 제곱하고 1만 빼면 답이 나와요.',
    en:'To multiply two numbers that are 2 apart, square the number in between and subtract 1.',
    zh:'两个相差2的数相乘，只要把中间那个数平方再减1就是答案。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}},
          /* 고급 B-1 '같은 수만큼 큰/작은 수의 곱' 확장 — 기준수 제시형(차이 k 일반화) */
          {id:3,label:{ko:'기준수 제시형(연습)',en:'Given-anchor form (practice)',zh:'给定基准数(练习)'},params:{mode:'anchorGiven',level:'practice'},
           concept:{ko:'기준수에서 같은 만큼 작고 큰 두 수의 곱은 기준수의 제곱에서 그 차의 제곱을 빼요. 29×39는 기준수 34에서 5씩 떨어져 있으니 34²−5²=1131이에요.',
             en:'Two numbers the same distance below and above an anchor multiply to the anchor squared minus that distance squared. 29×39 sits 5 from 34, so 34²−5²=1131.',
             zh:'与基准数相距相同的两个数相乘，等于基准数的平方减去这个差的平方。29×39与基准数34相距5，所以34²−5²=1131。'}},
          {id:4,label:{ko:'기준수 제시형(실전)',en:'Given-anchor form (main)',zh:'给定基准数(实战)'},params:{mode:'anchorGiven',level:'main'},
           concept:{ko:'수가 커져도 같아요. 기준수의 제곱에서 떨어진 만큼의 제곱을 빼요 — 728×744는 기준수 736에서 8씩 떨어져 있으니 736²−8²=541632예요.',
             en:'Bigger numbers change nothing: subtract the gap squared from the anchor squared — 728×744 sits 8 from 736, so 736²−8² = 541632.',
             zh:'数变大也一样：用基准数的平方减去差的平方——728×744与基准数736相距8，所以736²−8²=541632。'}},
          /* 고급 E-2 '평균값을 이용한 곱셈 1' 확장 — 평균 직접 계산형 */
          {id:5,label:{ko:'평균 계산형(연습)',en:'Average-calc form (practice)',zh:'求平均值(练习)'},params:{mode:'avgCalc',level:'practice'},
           concept:{ko:'두 수의 평균(가운데 수)을 먼저 구해요. 곱은 평균의 제곱에서 평균과의 차의 제곱을 뺀 값이에요 — 15×21은 평균 18에서 3씩 떨어져 있으니 18²−3²=315예요.',
             en:'Find the average of the two numbers first: the product is that average squared minus the gap squared — 15×21 averages 18 with a gap of 3, so 18²−3² = 315.',
             zh:'先求两数的平均数：乘积等于平均数的平方减去差的平方——15×21的平均数是18、相距3，所以18²−3²=315。'}},
          {id:6,label:{ko:'평균 계산형(실전)',en:'Average-calc form (main)',zh:'求平均值(实战)'},params:{mode:'avgCalc',level:'main'},
           concept:{ko:'두 수가 많이 떨어져 있어도 평균을 잡으면 돼요 — 49×87은 평균 68에서 19씩 떨어져 있으니 68²−19²=4263이에요.',
             en:'Even when the two numbers are far apart, the average still works: 49×87 averages 68 with a gap of 19, so 68²−19² = 4263.',
             zh:'两数相距较远时用平均数依然成立：49×87的平均数是68、相距19，所以68²−19²=4263。'}},
          /* 고급 A-6 '유명한 제곱수와 1 차이 나는 수의 제곱' 확장 — 유명 기준수 근처(★칸 일반화) */
          {id:7,label:{ko:'유명 기준수 근처',en:'Near a famous square',zh:'靠近熟知的平方数'},params:{mode:'famousNear'},
           concept:{ko:'50·100·200처럼 외우기 쉬운 기준수 근처의 제곱이에요. 기준수의 제곱에서 떨어진 만큼을 조정해요 — 196²은 200²에서 2×200×4를 빼고 4²을 더해 38416이에요.',
             en:'These are squares near easy anchors like 50, 100 or 200: adjust the anchor’s square by the gap — 196² is 200² minus 2×200×4 plus 4², giving 38416.',
             zh:'这些是靠近50、100、200等好记基准数的平方：用基准数的平方按差调整——196²是200²减2×200×4再加4²，得38416。'}},
          /* 고급 E '평균값을 이용한 곱셈 2·3' 확장 — 3·4자리 제곱(재귀형) */
          {id:8,label:{ko:'세 자리 수의 제곱',en:'3-digit squares',zh:'三位数的平方'},params:{mode:'sq3d'},
           concept:{ko:'세 자리 수의 제곱도 가까운 기준수를 잡아요 — 405²은 400²에 2×400×5를 더하고 5²을 더해 164025예요.',
             en:'Three-digit squares use a nearby anchor too: 405² is 400² plus 2×400×5 plus 5², giving 164025.',
             zh:'三位数的平方同样取邻近的基准数：405²是400²加2×400×5再加5²，得164025。'}},
          {id:9,label:{ko:'네 자리 수의 제곱',en:'4-digit squares',zh:'四位数的平方'},params:{mode:'sq4d'},
           concept:{ko:'네 자리도 같아요. 1000이나 1500 같은 기준수를 잡고 (기준수±차)² = 기준수² ± 2×기준수×차 + 차²로 펴요.',
             en:'Four digits work the same: take an anchor such as 1000 or 1500 and expand (anchor±gap)² = anchor² ± 2×anchor×gap + gap².',
             zh:'四位数也一样：取1000或1500这样的基准数，按(基准数±差)² = 基准数² ± 2×基准数×差 + 差²展开。'}}] },
ML21:{ name:{ko:'몇 자리 수일까요',en:'Digit prediction',zh:'几位数'}, gen:'ml_digit_pred', prereq:['ML8'],
  unit:'C-09',
  concept:{ko:'계산하기 전에 앞자리끼리 곱해 크기부터 어림해요. 답이 몇 자리 수일지 미리 알면 검산도 쉬워져요.',
    en:'Before you calculate, multiply the leading digits to estimate the size — knowing how many digits the answer will have makes checking easy.',
    zh:'计算前先把最高位相乘估一估大小，先知道答案是几位数，检查起来就容易。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
ML22:{ name:{ko:'두 자리×한 자리 암산',en:'2d×1d mental',zh:'两位乘一位口算'}, gen:'ml6_mul2d1dMental', prereq:['ML4'],
  concept:{ko:'종이 없이 머리로 나눠 곱해요. 47×3은 40×3=120에 7×3=21을 더해 141이에요.',
    en:'Split and multiply in your head, no paper needed. For 47×3, 40×3=120 plus 7×3=21 gives 141.',
    zh:'不用纸，在脑中拆开相乘。47×3中40×3=120，7×3=21，合得141。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'쉬움',en:'easy',zh:'简单'},params:{easy:true}},
          {id:2,label:{ko:'보통',en:'normal',zh:'普通'},params:{easy:false}}] },
DV9:{ name:{ko:'분해 나눗셈',en:'Split division',zh:'分解除法'}, gen:'ml_div_decomp', prereq:['DV4'],
  unit:'C-18',
  concept:{ko:'나누어지는 수를 나누는 수의 배수 조각들로 쪼개요. 큰 조각(몇백)부터 나누고 몫을 다 더하면 끝!',
    en:'Split the number being divided into chunks that are multiples of the divisor — start with the big chunks and add up the quotients.',
    zh:'把被除数拆成除数的倍数块，先分大块（几百），再把各块的商加起来。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
DV10:{ name:{ko:'약분 나눗셈',en:'Reduce division',zh:'约分除法'}, gen:'ml_div_simplify', prereq:['DV9'],
  unit:'C-19',
  concept:{ko:'나누어지는 수와 나누는 수를 같은 수로 나눠도 몫은 그대로예요. 둘 다 짝수면 ÷2, 둘 다 3의 배수면 ÷3부터 해봐요.',
    en:'Dividing both numbers by the same amount does not change the quotient — try ÷2 if both are even, ÷3 if both are multiples of 3.',
    zh:'被除数和除数同时除以同一个数，商不变。两个都是偶数就先除以2，都是3的倍数就先除以3。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
DV11:{ name:{ko:'부풀려 나눗셈',en:'Scale-up division',zh:'放大除法'}, gen:'ml_div_expand', prereq:['DV10'],
  unit:'C-20',
  concept:{ko:'나누어지는 수와 나누는 수에 같은 수를 곱해도 몫은 그대로예요. ÷5는 ×2로, ÷25는 ×4로 부풀려 10이나 100으로 나눠요.',
    en:'Multiplying both numbers by the same amount does not change the quotient — scale ÷5 up with ×2, or ÷25 up with ×4, to divide by 10 or 100 instead.',
    zh:'被除数和除数同时乘以同一个数，商也不变。除以5就乘2，除以25就乘4，把它们变成除以10或100。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
/* ── DV12~DV15 나눗셈의 뜻 (2026-09-17, 원장 "직접 나누기·같은 수 빼기·묶어서 나누기") ──
   processFirst: 앱의 계산 회차(과정 드릴·점검)에서도 답만 받지 않고 위젯(배열·단계 카드)으로
     과정을 밟게 한다 — 뜻을 묻는 유형이라 숫자패드로 답만 찍으면 DV2와 같아진다(main.js useWidget).
   noVertical: 인쇄에서 세로셈 판정에서 뺀다 — `12 ÷ 3 = □`가 세로셈 상자로 찍히면
   뜻을 묻는 문항이 필산 문항이 된다. instr: 학습지 회차 첫 장 안내문. */
DV12:{ name:{ko:'똑같이 나누기',en:'Sharing equally',zh:'平均分'}, gen:'dv12_share', prereq:['ML4'],
  unit:'B-24', noVertical:true, processFirst:true,
  instr:{ko:'이야기를 읽고 한 명이 몇 개씩 가지는지 구하시오.',en:'Read the story and find how many each child gets.',zh:'读题，求每人分到几个。'},
  concept:{ko:'똑같이 나누어 주는 것이 나눗셈이에요. 사탕 12개를 3명에게 하나씩 돌아가며 주면 한 명이 4개씩 — 12÷3=4예요. "한 명이 몇 개?"를 물을 때는 사람 수만큼 줄을 만들어요.',
    en:'Sharing equally is division. Deal 12 candies to 3 children one at a time and each gets 4 — that is 12÷3=4. When the question is "how many each?", make one row per child.',
    zh:'平均分就是除法。把12颗糖一颗一颗轮流分给3个人，每人4颗——12÷3=4。问"每人几个"时，人数就是行数。'},
  widgets:['array','numpad'],
  levels:[{id:1,label:{ko:'2~5명',en:'2–5 kids',zh:'2~5人'},params:{hi:false}},
          {id:2,label:{ko:'2~9명',en:'2–9 kids',zh:'2~9人'},params:{hi:true}},
          {id:3,label:{ko:'몫이 두 자리',en:'2-digit share',zh:'两位数的份'},params:{big:true}}] },
DV13:{ name:{ko:'묶어서 나누기',en:'Grouping',zh:'分组'}, gen:'dv13_group', prereq:['DV12'],
  unit:'B-24', noVertical:true, processFirst:true,
  instr:{ko:'이야기를 읽고 몇 묶음인지, 또는 한 명이 몇 개씩인지 구하시오.',en:'Read the story and find how many groups, or how many each.',zh:'读题，求几组或每人几个。'},
  concept:{ko:'몇 개씩 묶어 세는 것도 나눗셈이에요. 12개를 3개씩 묶으면 3, 6, 9, 12 — 4묶음이니까 12÷3=4예요. 똑같은 식인데 이번엔 "몇 묶음?"을 물어요. 문장을 읽고 무엇을 세는지 먼저 정해요.',
    en:'Counting in groups is division too. Bundle 12 into groups of 3: 3, 6, 9, 12 — 4 groups, so 12÷3=4. Same equation, but now the question is "how many groups?". Read first, then decide what you are counting.',
    zh:'按几个一组来数也是除法。12个每3个一组：3、6、9、12——4组，所以12÷3=4。算式一样，这次问的是"几组"。先读题，再决定数什么。'},
  widgets:['array','numpad'],
  levels:[{id:1,label:{ko:'2~5개씩',en:'groups of 2–5',zh:'每组2~5'},params:{hi:false}},
          {id:2,label:{ko:'2~9개씩',en:'groups of 2–9',zh:'每组2~9'},params:{hi:true}},
          {id:3,label:{ko:'나눠주기·묶기 섞기',en:'share & group mixed',zh:'平均分与分组混合'},params:{mix:true}}] },
DV14:{ name:{ko:'같은 수를 빼서 나누기',en:'Repeated subtraction',zh:'连续减法'}, gen:'dv14_repsub', prereq:['DV13'],
  unit:'B-24', noVertical:true, processFirst:true,
  instr:{ko:'같은 수를 차례로 빼면서 몇 번 뺐는지 세시오.',en:'Subtract the same number again and again, and count how many times.',zh:'反复减去同一个数，数一数减了几次。'},
  concept:{ko:'나눗셈은 같은 수를 여러 번 빼는 것이기도 해요. 12에서 3을 빼면 9, 또 빼면 6, 또 3, 또 0 — 네 번 뺐으니 12÷3=4예요. 더 못 뺄 때 남는 수가 나머지예요.',
    en:'Division is also subtracting the same number over and over. 12 minus 3 is 9, then 6, then 3, then 0 — four times, so 12÷3=4. Whatever is left when you can no longer subtract is the remainder.',
    zh:'除法也可以看成反复减去同一个数。12减3是9，再减是6，再减是3，再减是0——减了四次，所以12÷3=4。减不动时剩下的就是余数。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'0이 될 때까지',en:'down to 0',zh:'减到0'},params:{rem:false}},
          {id:2,label:{ko:'남는 수가 있을 때',en:'with leftover',zh:'有剩余'},params:{rem:true}}] },
DV15:{ name:{ko:'곱셈으로 나눗셈',en:'Division from multiplication',zh:'用乘法做除法'}, gen:'dv15_family', prereq:['DV12'],
  unit:'B-24', noVertical:true, processFirst:true,
  instr:{ko:'곱셈과 나눗셈의 관계를 이용해 □를 구하시오.',en:'Use the link between multiplication and division to find □.',zh:'利用乘除法的关系求□。'},
  concept:{ko:'곱셈 하나에는 나눗셈이 둘 숨어 있어요. 4×6=24이면 24÷4=6이고 24÷6=4예요. □÷6=4처럼 나누어지는 수를 모를 때는 6×4로 되돌리고, 24÷□=4처럼 나누는 수를 모를 때는 □×4=24로 생각해요.',
    en:'Every multiplication hides two divisions. If 4×6=24, then 24÷4=6 and 24÷6=4. When the number being divided is missing (□÷6=4), multiply back: 6×4. When the divisor is missing (24÷□=4), think □×4=24.',
    zh:'一个乘法里藏着两个除法。4×6=24，就有24÷4=6和24÷6=4。被除数不知道时（□÷6=4）就乘回去：6×4；除数不知道时（24÷□=4）就想□×4=24。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'나눗셈 식 둘',en:'two division facts',zh:'两个除法式'},params:{mode:'facts'}},
          {id:2,label:{ko:'□÷b=q',en:'missing dividend',zh:'缺被除数'},params:{mode:'dividend'},
           concept:{ko:'나누어지는 수를 모를 땐 곱셈으로 되돌려요. □÷5=4는 5×4=20이니 □는 20이에요.',
             en:'When the dividend is missing, go back through multiplication: □÷5=4 means 5×4=20, so □ is 20.',
             zh:'被除数未知时用乘法还原：□÷5=4就是5×4=20，所以□是20。'}},
          {id:3,label:{ko:'a÷□=q',en:'missing divisor',zh:'缺除数'},params:{mode:'divisor'},
           concept:{ko:'나누는 수를 모를 땐 나누어지는 수를 몫으로 나눠요. 30÷□=5는 30÷5=6이니 □는 6이에요.',
             en:'When the divisor is missing, divide the dividend by the quotient: 30÷□=5 means 30÷5=6, so □ is 6.',
             zh:'除数未知时用被除数除以商：30÷□=5就是30÷5=6，所以□是6。'}}] },
DV17:{ name:{ko:'곱셈식에서 몫 찾기',en:'Quotient from multiplication',zh:'从乘法找商'}, gen:'dv17_quotFromMul', prereq:['ML4'],
  unit:'B-17', noVertical:true,
  instr:{ko:'곱셈식의 빈칸을 찾아 나눗셈의 몫을 구하시오.',en:'Find the missing factor — that is the quotient.',zh:'找出乘法算式里的空格，就是除法的商。'},
  concept:{ko:'2 × □ = 10과 10 ÷ 2 = □는 같은 것을 묻습니다. 곱셈식에서 곱하는 수를 찾으면 그것이 나눗셈의 몫이에요. □ × 5 = 15처럼 곱해지는 수를 찾을 때도 15 ÷ 5 = □와 같아요.',
    en:'2 × □ = 10 and 10 ÷ 2 = □ ask the same thing. The missing factor in the multiplication is the quotient of the division — the same holds for □ × 5 = 15 and 15 ÷ 5 = □.',
    zh:'2×□=10和10÷2=□问的是同一件事。乘法算式里缺的那个数，就是除法的商；□×5=15和15÷5=□也一样。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'곱하는 수 찾기',en:'missing multiplier',zh:'找乘数'},params:{mode:'times'}},
          {id:2,label:{ko:'곱해지는 수 찾기',en:'missing multiplicand',zh:'找被乘数'},params:{mode:'timesed'},
           concept:{ko:'곱해지는 수를 찾을 때도 나눗셈이에요. □×5=20은 20÷5=4와 같은 것을 묻습니다.',
             en:'Finding the number being multiplied is also a division: □×5=20 asks the same thing as 20÷5=4.',
             zh:'找被乘数同样是除法：□×5=20问的和20÷5=4是一回事。'}},
          {id:3,label:{ko:'2~9단 섞어',en:'tables 2–9',zh:'2~9的口诀'},params:{mode:'times',hi:true}}] },
DV18:{ name:{ko:'나머지가 있는 나눗셈(묶음)',en:'Division with a remainder (grouping)',zh:'有余数的除法(分组)'}, gen:'dv18_remFixed', prereq:['DV13'],
  unit:'B-24', noVertical:true,
  instr:{ko:'묶고 남는 수를 구하시오. 몫과 나머지를 차례로 쓰시오.',en:'Group them and find what is left. Write the quotient, then the remainder.',zh:'分组后求剩余。先写商，再写余数。'},
  concept:{ko:'사과 11개를 2개씩 묶으면 5묶음이 되고 1개가 남아요 — 11 ÷ 2 = 5 … 1. 남는 수를 나머지라고 하고, 나머지는 나누는 수보다 항상 작아요. 나머지가 0이면 나누어떨어진다고 해요.',
    en:'Bundle 11 apples into groups of 2: 5 groups and 1 left over — 11 ÷ 2 = 5 r 1. What is left is the remainder, and it is always smaller than the divisor. A remainder of 0 means it divides exactly.',
    zh:'把11个苹果每2个分一组：5组还剩1个——11÷2=5…1。剩下的叫余数，余数总比除数小。余数是0就叫整除。'},
  widgets:['array','numpad'],
  levels:[{id:1,label:{ko:'나머지가 1',en:'remainder 1',zh:'余1'},params:{r:1}},
          {id:2,label:{ko:'나머지가 2',en:'remainder 2',zh:'余2'},params:{r:2}},
          {id:3,label:{ko:'나머지가 3',en:'remainder 3',zh:'余3'},params:{r:3}},
          {id:4,label:{ko:'나머지 섞어',en:'any remainder',zh:'余数混合'},params:{r:0}},
          {id:5,label:{ko:'몫이 두 자리',en:'2-digit quotient',zh:'两位数的商'},params:{r:0,q2:true}}] },
ML25:{ name:{ko:'수직선 뛰어 세기 구구',en:'Times tables on a number line',zh:'数轴跳跃口诀'}, gen:'ml_jumpTT', prereq:['ML2'],
  noVertical:true,   /* 유닛을 달지 않는다 — B-01(두 배 마법) 단계가 딸려와 6·7단 지면에 '두 배' 설명이 붙었다 */
  instr:{ko:'수직선에서 몇 번 뛰었는지 세어 □를 채우시오.',en:'Count the hops on the number line and fill the □.',zh:'数一数在数轴上跳了几次，填入□。'},
  concept:{ko:'같은 수를 여러 번 더하는 것이 곱셈이에요. 6씩 3번 뛰면 6+6+6=18이고, 이것을 6 × 3 = 18로 씁니다. 수직선에서 뛴 횟수가 곱하는 수예요.',
    en:'Adding the same number again and again is multiplication. Three hops of 6 make 6+6+6=18, written 6 × 3 = 18. The number of hops is the multiplier.',
    zh:'把同一个数加好几次就是乘法。每次跳6，跳3次是6+6+6=18，写成6×3=18。跳的次数就是乘数。'},
  widgets:['numline','numpad'],
  levels:[{id:1,label:{ko:'2·5단',en:'2s & 5s',zh:'2和5'},params:{tables:[2,5]}},
          {id:2,label:{ko:'3·4단',en:'3s & 4s',zh:'3和4'},params:{tables:[3,4]}},
          {id:3,label:{ko:'6·7단',en:'6s & 7s',zh:'6和7'},params:{tables:[6,7]}},
          {id:4,label:{ko:'8·9단',en:'8s & 9s',zh:'8和9'},params:{tables:[8,9]}}] },
DV19:{ name:{ko:'세로 나눗셈',en:'Long division',zh:'竖式除法'}, gen:'dv19_longDiv', prereq:['DV2'],
  unit:'B-24', noVertical:true,
  instr:{ko:'세로셈으로 계산하시오. 몫은 자리에 맞춰 쓰시오.',en:'Work it out in the long-division box; line the quotient up by place.',zh:'用竖式计算，商要对齐数位。'},
  concept:{ko:'몫은 십의 자리와 일의 자리를 구분해서 써야 해요. 35 ÷ 3은 3을 먼저 나눠 몫의 십의 자리 1을 쓰고, 남은 5를 나눠 일의 자리 1을 써요 — 11 … 2. 나머지는 나누는 수보다 항상 작아요.',
    en:'Write the quotient place by place. For 35 ÷ 3, divide the 3 first (tens digit 1), bring down the 5 and divide again (ones digit 1) — 11 r 2. The remainder is always smaller than the divisor.',
    zh:'商要分十位和个位来写。35÷3先除3，商的十位是1；再把5落下来除，个位是1——11…2。余数总比除数小。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'몫 한 자리(나머지 없음)',en:'1-digit quotient',zh:'一位数的商'},params:{},
           concept:{ko:'몫은 나누어지는 수의 오른쪽 끝자리 위에 써요. 40 ÷ 5는 5 × 8 = 40이니 몫 8을 0 위에 씁니다.',
             en:'Write the quotient above the last digit of the dividend. For 40 ÷ 5, 5 × 8 = 40, so the 8 goes above the 0.',
             zh:'商写在被除数末位的上面。40÷5中5×8=40，所以商8写在0的上面。'}},
          {id:2,label:{ko:'몫 한 자리(나머지)',en:'1-digit quotient, remainder',zh:'一位商有余数'},params:{rem:true},
           concept:{ko:'나누어떨어지지 않으면 넘지 않는 가장 큰 곱을 찾아 빼요. 45 ÷ 6은 6 × 7 = 42를 빼고 남은 3이 나머지예요. 나머지는 나누는 수보다 작아요.',
             en:'When it does not divide exactly, take the largest multiple that fits and subtract. For 45 ÷ 6, subtract 6 × 7 = 42 and 3 is left over. The remainder is smaller than the divisor.',
             zh:'除不尽时找不超过的最大倍数去减。45÷6减去6×7=42，剩下的3就是余数。余数比除数小。'}},
          {id:3,label:{ko:'몫 두 자리',en:'2-digit quotient',zh:'两位数的商'},params:{q2:true},
           concept:{ko:'앞자리부터 나눠요. 96 ÷ 4는 9를 먼저 나눠 몫의 십의 자리 2를 쓰고, 남은 1 옆에 6을 내려 16 ÷ 4 = 4를 일의 자리에 써요 — 24.',
             en:'Start from the front. For 96 ÷ 4, divide the 9 first (tens digit 2), bring the 6 down to make 16, and 16 ÷ 4 = 4 is the ones digit — 24.',
             zh:'从高位开始除。96÷4先除9，商的十位是2；把6落下来成16，16÷4=4写在个位——24。'}},
          {id:4,label:{ko:'몫 두 자리(나머지)',en:'2-digit quotient, remainder',zh:'两位商有余数'},params:{q2:true,rem:true},
           concept:{ko:'자리마다 나누고 빼기를 되풀이해요. 35 ÷ 3은 십의 자리 1, 내려온 5를 나눠 일의 자리 1, 남은 2가 나머지예요 — 11 … 2.',
             en:'Divide and subtract place by place. For 35 ÷ 3 the tens digit is 1, the brought-down 5 gives the ones digit 1, and 2 is left — 11 r 2.',
             zh:'每一位都重复"除—减"。35÷3十位商1，落下5后个位商1，剩2——11…2。'}},
          {id:5,label:{ko:'세 자리÷한 자리',en:'3d ÷ 1d',zh:'三位除一位'},params:{d3:true,rem:true},
           concept:{ko:'백·십·일의 자리를 차례로 나눠요. 한 자리를 내릴 때마다 몫이 한 자리씩 늘고, 나눌 수 없는 자리에는 몫 0을 꼭 써 줘야 자리가 밀리지 않아요.',
             en:'Work through hundreds, tens and ones in turn. Each digit you bring down adds a digit to the quotient — write a 0 where the divisor does not fit, or the places slide.',
             zh:'按百位、十位、个位依次除。每落下一位商就多一位；除不了的那一位要写0，否则数位会错开。'}}] },
DV20:{ name:{ko:'약수와 배수',en:'Factors and multiples',zh:'因数与倍数'}, gen:'dv20_factorMultiple', prereq:['DV17'],
  noVertical:true,
  instr:{ko:'약수·배수를 모두 찾아 쓰시오. 여러 개면 쉼표로 나누어 쓰시오.',en:'Write every factor or multiple asked for; separate several answers with commas.',zh:'写出所有的因数或倍数，多个答案用逗号分开。'},
  concept:{ko:'나누어떨어지게 하는 수가 약수, 몇 배 한 수가 배수예요. 12의 약수는 1, 2, 3, 4, 6, 12이고 3의 배수는 3, 6, 9, 12…예요. 두 수에 공통으로 있는 약수가 공약수, 그중 가장 큰 것이 최대공약수예요. 공배수 중 가장 작은 것은 최소공배수예요.',
    en:'A factor divides a number exactly; a multiple is that number times something. 12 has factors 1, 2, 3, 4, 6, 12, and the multiples of 3 are 3, 6, 9, 12… Factors shared by two numbers are common factors, the biggest is the GCF; the smallest shared multiple is the LCM.',
    zh:'能整除的数是因数，乘出来的数是倍数。12的因数是1、2、3、4、6、12，3的倍数是3、6、9、12……两数共有的因数叫公因数，最大的是最大公因数；共有的倍数中最小的是最小公倍数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'약수 모두 쓰기',en:'all factors',zh:'写出所有因数'},params:{mode:'factors'},
           concept:{ko:'나누어떨어지게 하는 수가 약수예요. 곱셈으로 짝을 지어 찾으면 빠짐없이 나와요 — 1 × 12, 2 × 6, 3 × 4이니 12의 약수는 1, 2, 3, 4, 6, 12.',
             en:'A factor divides the number exactly. Hunt in multiplication pairs so none is missed — 1 × 12, 2 × 6, 3 × 4, so 12 has factors 1, 2, 3, 4, 6, 12.',
             zh:'能整除的数就是因数。用乘法配对来找就不会漏——1×12、2×6、3×4，所以12的因数是1、2、3、4、6、12。'}},
          {id:2,label:{ko:'배수 차례로 쓰기',en:'first multiples',zh:'写出前几个倍数'},params:{mode:'multiples'},
           concept:{ko:'어떤 수를 1배, 2배, 3배… 한 수가 배수예요. 3의 배수는 3, 6, 9, 12…처럼 3씩 뛰어 세면 돼요. 배수는 끝없이 이어져요.',
             en:'Multiples are the number times 1, 2, 3, … The multiples of 3 are 3, 6, 9, 12… — just skip-count by 3. The list never ends.',
             zh:'一个数的1倍、2倍、3倍……就是它的倍数。3的倍数是3、6、9、12……按3跳着数即可，倍数是无穷的。'}},
          {id:3,label:{ko:'공약수',en:'common factors',zh:'公因数'},params:{mode:'common'},
           concept:{ko:'두 수의 약수를 각각 쓰고, 양쪽에 다 있는 수를 고르면 공약수예요. 8은 1, 2, 4, 8 / 12는 1, 2, 3, 4, 6, 12 → 공약수는 1, 2, 4.',
             en:'List each number\u2019s factors and take the ones on both lists. 8: 1, 2, 4, 8 / 12: 1, 2, 3, 4, 6, 12 → common factors 1, 2, 4.',
             zh:'分别写出两数的因数，两边都有的就是公因数。8是1、2、4、8；12是1、2、3、4、6、12→公因数是1、2、4。'}},
          {id:4,label:{ko:'최대공약수',en:'greatest common factor',zh:'最大公因数'},params:{mode:'gcd'},
           concept:{ko:'공약수 중에서 가장 큰 수가 최대공약수예요. 8과 12의 공약수 1, 2, 4 중 가장 큰 4가 최대공약수예요. 공약수는 모두 최대공약수의 약수랍니다.',
             en:'The greatest common factor is the biggest of the common factors. For 8 and 12 the common factors are 1, 2, 4, so the GCF is 4 — and every common factor divides it.',
             zh:'公因数中最大的就是最大公因数。8和12的公因数是1、2、4，最大公因数是4；每个公因数都是它的因数。'}},
          {id:5,label:{ko:'공배수',en:'common multiples',zh:'公倍数'},params:{mode:'commonMul'},
           concept:{ko:'두 수의 배수를 나란히 쓰고 같이 나오는 수를 찾으면 공배수예요. 4의 배수 4, 8, 12, 16… / 6의 배수 6, 12, 18… → 공배수는 12, 24, 36….',
             en:'Write both lists of multiples and find the ones that appear in both. 4: 4, 8, 12, 16… / 6: 6, 12, 18… → common multiples 12, 24, 36….',
             zh:'把两数的倍数并排写出，同时出现的就是公倍数。4的倍数4、8、12、16……；6的倍数6、12、18……→公倍数是12、24、36……'}},
          {id:6,label:{ko:'최소공배수',en:'least common multiple',zh:'最小公倍数'},params:{mode:'lcm'},
           concept:{ko:'공배수 중 가장 작은 수가 최소공배수예요. 두 수를 곱한 뒤 최대공약수로 나누면 바로 나와요 — 4 × 6 ÷ 2 = 12. 나머지 공배수는 모두 12의 배수예요.',
             en:'The least common multiple is the smallest common multiple. Multiply the two numbers and divide by their GCF — 4 × 6 ÷ 2 = 12; every other common multiple is a multiple of 12.',
             zh:'公倍数中最小的是最小公倍数。两数相乘再除以最大公因数即可——4×6÷2=12；其余公倍数都是12的倍数。'}}] },
FR9:{ name:{ko:'분수 덧뺄셈(같은 분모)',en:'Fractions ± same denom',zh:'同分母加减'}, gen:'ml_frac_same', prereq:['FR2'],
  unit:'C-21',
  concept:{ko:'분모는 조각 크기, 분자는 조각 개수예요. 분모가 같으면 분자끼리만 더하거나 빼고 분모는 그대로 둬요.',
    en:'The denominator is the size of each piece, the numerator is how many pieces. If denominators match, just add or subtract the numerators.',
    zh:'分母是每块的大小，分子是块数。分母相同时只把分子相加或相减，分母不变。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'덧셈',en:'add',zh:'加法'},params:{level:'practice',op:'add'}},
          {id:2,label:{ko:'뺄셈',en:'sub',zh:'减法'},params:{level:'main',op:'sub'}}] },
FR10:{ name:{ko:'분수 덧뺄셈(다른 분모)',en:'Fractions ± diff denom',zh:'异分母加减'}, gen:'ml_frac_diff', prereq:['FR9'],
  unit:'C-22',
  concept:{ko:'분모가 다르면 바로 더할 수 없어요. 분모끼리 곱해 공통분모로 통분하고, 분모에 곱한 수를 분자에도 똑같이 곱해요.',
    en:'You cannot add fractions with different denominators right away — multiply the denominators together to find a common one, and multiply each numerator the same way.',
    zh:'分母不同不能直接相加，把分母相乘找到公分母，分子也要乘上同样的数。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'덧셈',en:'add',zh:'加法'},params:{level:'practice',op:'add'}},
          {id:2,label:{ko:'뺄셈',en:'sub',zh:'减法'},params:{level:'main',op:'sub'}}] },
DC4:{ name:{ko:'소수를 곱하기',en:'Decimal multiplication',zh:'小数乘法'}, gen:'ml_decimal_mul', prereq:['DC2'],
  unit:'C-25',
  concept:{ko:'0.1을 곱하는 건 10으로 나누는 것과 같아요. 소수점 아래 자리 수만큼 소수점이 왼쪽으로 미끄러져요.',
    en:'Multiplying by 0.1 is the same as dividing by 10 — the decimal point slides left by however many decimal places there are.',
    zh:'乘以0.1就等于除以10。小数点向左滑动的位数，就是小数位数。'},
  widgets:['steps','decimal','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
MX6:{ name:{ko:'곱을 이용한 가우스 덧셈',en:'Gauss sum',zh:'高斯求和'}, gen:'ml_gauss', prereq:['ML8'],
  unit:'C-05',
  concept:{ko:'처음 수와 끝 수를 짝지으면 모든 짝의 합이 똑같아요. 그 합에 짝의 개수를 곱하면 전체 합이 한 번에 나와요.',koMid:'처음 수와 끝 수를 짝지으면 모든 짝의 합이 같습니다. 그 합에 짝의 개수를 곱하면 전체 합이 한 번에 나옵니다.',
    en:'Pair the first number with the last, and every pair adds up to the same sum — multiply that sum by the number of pairs to get the total instantly.',
    zh:'把第一个数和最后一个数配对，每一对的和都相同。这个和乘以对数，就一次得到总和。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}},
          /* 고급 B '가우스 덧셈의 응용' 확장 — 제곱 공식형(끝²−첫²+첫+끝)÷2, 연속한 자연수 전용 */
          {id:3,label:{ko:'제곱 공식(연습)',en:'Square formula (practice)',zh:'平方公式(练习)'},params:{mode:'squareForm',level:'practice'},
           concept:{ko:'1부터가 아니어도 돼요. 항의 개수를 세고 (처음+끝)×개수÷2로 구해요 — 10부터 19까지는 10개라 (10+19)×10÷2=145예요.',koMid:'1부터 시작하지 않아도 됩니다. 항의 개수를 세고 (처음+끝)×개수÷2로 구합니다 — 10부터 19까지는 10개이므로 (10+19)×10÷2=145입니다.',
             en:'It need not start at 1: count the terms and use (first+last)×count÷2 — 10 through 19 is 10 terms, so (10+19)×10÷2 = 145.',
             zh:'不一定从1开始：数出项数，用(首+尾)×项数÷2——10到19共10项，所以(10+19)×10÷2=145。'}},
          {id:4,label:{ko:'제곱 공식(실전, 세 자리)',en:'Square formula (3-digit)',zh:'平方公式(三位数)'},params:{mode:'squareForm',level:'main'},
           concept:{ko:'세 자리 수여도 같아요. 끝 수에서 처음 수를 빼고 1을 더해 개수부터 세면 나머지는 똑같아요.',koMid:'세 자리 수여도 같습니다. 끝 수에서 처음 수를 빼고 1을 더해 개수부터 세면 나머지는 똑같습니다.',
             en:'Three-digit numbers change nothing: subtract the first from the last and add 1 to count the terms, then proceed as before.',
             zh:'三位数也一样：用尾数减首数再加1数出项数，其余步骤相同。'}}] },
ML23:{ name:{ko:'차근차근 곱하기',en:'Step-by-step multiplication',zh:'逐步乘法'}, gen:'ml_partial', prereq:['ML4'],
  unit:'C-26',
  concept:{ko:'큰 수 곱셈은 두 수를 자리별로 쪼개 하나씩 곱한 다음, 마지막에 조각들을 다 더하면 돼요.',
    en:'For big multiplication, split both numbers by place value, multiply each piece, then add all the pieces at the end.',
    zh:'大数相乘时把两个数按数位拆开，逐个相乘，最后把所有部分加起来。'},
  widgets:['steps','vertical','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
ML24:{ name:{ko:'9로 끝나는 수의 곱',en:'Ending-in-9 products',zh:'尾数9之积'}, gen:'ml_end9', prereq:['ML13'],
  unit:'C-27',
  concept:{ko:'9로 끝나는 수는 1을 더해 딱 떨어지는 수로 만든 다음 곱하고, 마지막에 곱한 수만큼 한 번 빼줘요.',
    en:'For a number ending in 9, add 1 to round it up, multiply, then subtract the multiplier once at the end.',
    zh:'尾数是9的数先加1凑整再乘，最后再减一次乘数。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
FR11:{ name:{ko:'분수의 곱셈·나눗셈',en:'Fraction × ÷',zh:'分数乘除'}, gen:'ml_frac_muldiv', prereq:['FR10'],
  unit:'C-31',
  concept:{ko:'분수끼리 곱할 땐 분자는 분자끼리, 분모는 분모끼리 곱해요. 나눌 땐 뒤 분수를 뒤집어(역수) 곱하면 돼요.',
    en:'To multiply fractions, multiply the numerators together and the denominators together. To divide, flip the second fraction (its reciprocal) and multiply.',
    zh:'分数相乘时分子乘分子，分母乘分母。分数相除时把后面的分数颠倒（取倒数）再相乘。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'곱셈',en:'multiply',zh:'乘法'},params:{level:'practice',op:'mul'}},
          {id:2,label:{ko:'나눗셈',en:'divide',zh:'除法'},params:{level:'main',op:'div'}}] },
FR12:{ name:{ko:'분수 전환 나눗셈',en:'Fraction-conversion division',zh:'分数转换除法'}, gen:'ml_frac_conv', prereq:['FR11'],
  unit:'C-32',
  concept:{ko:'나눗셈을 분수로 바꿔 보면, 나누는 수의 배수로 큰 덩어리부터 쪼개 나눈 다음 다 더해 소수로 읽을 수 있어요.',
    en:'Seeing division as a fraction lets you split off big multiple-of-the-divisor chunks first, then add the pieces and read the result as a decimal.',
    zh:'把除法看成分数，就能先拆出除数的大倍数块来除，再把各部分加起来读成小数。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },
DC5:{ name:{ko:'소수를 나누기',en:'Decimal division',zh:'小数除法'}, gen:'ml_decimal_div', prereq:['DC4'],
  unit:'C-33',
  concept:{ko:'나누는 수를 자연수로 만들 만큼 두 수를 똑같이 배로 키운 다음, 자연수끼리 나누면 답이 나와요.',
    en:'Scale both numbers up by the same amount until the divisor is a whole number, then divide as whole numbers.',
    zh:'把两个数同时放大相同的倍数，让除数变成整数，再按整数相除就行。'},
  widgets:['steps','decimal','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{level:'practice'}},
          {id:2,label:{ko:'실전',en:'main',zh:'实战'},params:{level:'main'}}] },

/* ── EL 초등 신규 5종 (과정-로드맵.md §3 Level1~2 신규 소요, 2026-08-25 Phase 1) ── */
DC6:{ name:{ko:'소수의 짝꿍(1·10 만들기)',en:'Decimal bonds to 1 & 10',zh:'小数的伙伴(凑1与凑10)'}, gen:'dc6_decBond', prereq:['DC1','NS4'],
  concept:{ko:'더해서 10이 되는 짝을 소수에도 그대로 씁니다. 0.3의 1 짝꿍은 0.7이고, 0.35의 1 짝꿍은 0.65예요. 세로셈을 하지 않아도 십분의 자리끼리 10, 백분의 자리끼리 100을 채우면 바로 보여요.',
    en:'The pairs that make 10 work for decimals too. The partner of 0.3 to reach 1 is 0.7, and of 0.35 it is 0.65. You do not need column subtraction — fill the tenths to 10, the hundredths to 100, and the answer appears.',
    zh:'凑十的数对同样适用于小数。0.3凑成1的伙伴是0.7，0.35的是0.65。不用竖式，把十分位凑到10、百分位凑到100，答案就出来了。'},
  widgets:['numpad','steps'],
  levels:[{id:1,label:{ko:'1 만들기(소수 한 자리)',en:'make 1 (tenths)',zh:'凑1(十分位)'},params:{target:1,places:1}},
          {id:2,label:{ko:'1 만들기(소수 두 자리)',en:'make 1 (hundredths)',zh:'凑1(百分位)'},params:{target:1,places:2}},
          {id:3,label:{ko:'10 만들기',en:'make 10',zh:'凑10'},params:{target:10,places:1},
           concept:{ko:'10을 채울 땐 0.1이 몇 개인지로 세요. 1.3은 0.1이 13개이고 10은 100개니까, 100−13=87개가 더 필요해요.',
             en:'To reach 10, count in tenths: 1.3 is 13 tenths and 10 is 100 tenths, so you still need 100−13=87 of them.',
             zh:'凑10时用0.1来数：1.3是13个0.1，10是100个0.1，所以还差100−13=87个。'}}] },
EL1:{ name:{ko:'역연산으로 빈칸 찾기',en:'Missing Number by Inverse Operation',zh:'逆运算求空格'}, gen:'el_inverse', prereq:['AD3','DV3'],
  concept:{ko:'덧셈식의 빈칸은 뺄셈으로, 곱셈식의 빈칸은 나눗셈으로 거꾸로 찾아요.',
    en:'Find a blank in an addition by subtracting, and a blank in a multiplication by dividing — go backwards to solve it.',
    zh:'加法算式里的空格用减法倒着找，乘法算式里的空格用除法倒着找。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'덧셈·뺄셈',en:'Add & Subtract',zh:'加减法'},params:{mode:'as',max:100}},
          {id:2,label:{ko:'곱셈·나눗셈',en:'Multiply & Divide',zh:'乘除法'},params:{mode:'md',max:12},
           concept:{ko:'곱셈식의 빈칸은 나눗셈으로, 나눗셈식의 빈칸은 곱셈으로 거꾸로 찾아요 — □×5=35는 35÷5=7, □÷12=10은 12×10=120이에요.',
             en:'A blank in a multiplication is found by dividing, and a blank in a division by multiplying: □×5=35 gives 35÷5=7, and □÷12=10 gives 12×10=120.',
             zh:'乘法里的空格用除法找，除法里的空格用乘法找：□×5=35是35÷5=7，□÷12=10是12×10=120。'}},
          {id:3,label:{ko:'혼합·큰 수',en:'Mixed & Bigger',zh:'混合与大数'},params:{mode:'mix',max:999},
           concept:{ko:'수가 커져도 방법은 같아요. 빈칸이 어느 자리에 있는지 보고 그 연산의 반대로 한 번만 계산하면 돼요 — 967−□=267은 967−267=700이에요.',
             en:'Bigger numbers do not change the method: see where the blank sits and undo that one operation — 967−□=267 gives 967−267=700.',
             zh:'数变大方法不变：看空格在哪一位，用相反的运算算一次即可——967−□=267就是967−267=700。'}}] },
EL2:{ name:{ko:'검산',en:'Checking by Inverse Calculation',zh:'验算'}, gen:'el_check', prereq:['AD6','ML4'],
  concept:{ko:'계산이 맞는지 확인하려면 반대 연산으로 되짚어 봐요. 덧셈은 뺄셈으로, 곱셈은 나눗셈으로 검산해요.',
    en:'To check your answer, work backwards with the opposite operation — check addition with subtraction, multiplication with division.',
    zh:'想确认算得对不对，就用相反的运算倒着算一遍——用减法检查加法，用除法检查乘法。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'덧셈 검산',en:'Check Addition',zh:'加法验算'},params:{mode:'add',max:500}},
          {id:2,label:{ko:'뺄셈 검산',en:'Check Subtraction',zh:'减法验算'},params:{mode:'sub',max:500},
           concept:{ko:'뺄셈은 덧셈으로 되짚어요. 어떤 수에서 빼서 남은 값에 뺀 수를 다시 더하면 처음 수가 나와요 — 55+251=306이에요.',
             en:'Check a subtraction by adding: put the number you took away back onto what is left and the original returns — 55+251=306.',
             zh:'减法用加法来检验：把减去的数加回剩下的数就得到原来的数——55+251=306。'}},
          {id:3,label:{ko:'곱셈·나눗셈 검산',en:'Check Multiply & Divide',zh:'乘除法验算'},params:{mode:'muldiv',max:12},
           concept:{ko:'곱셈은 나눗셈으로 되짚어요. 곱한 결과를 한쪽 수로 나누면 다른 쪽 수가 나와요 — 어떤 수에 18을 곱해 36이면 36÷18=2예요.',
             en:'Check a multiplication by dividing: divide the product by one factor and the other factor appears — if a number times 18 is 36, then 36÷18=2.',
             zh:'乘法用除法来检验：用积除以一个因数就得到另一个因数——某数乘18等于36，则36÷18=2。'}}] },
EL3:{ name:{ko:'크기 비교',en:'Comparing Expressions',zh:'比较大小'}, gen:'el_compare', prereq:['AD3','ML2'],
  concept:{ko:'양쪽 식을 각각 계산한 다음 어느 쪽이 큰지 비교해요. 얼마나 차이 나는지도 구할 수 있어요.',
    en:'Work out both sides first, then compare which is bigger — you can even find how much they differ by.',
    zh:'先分别算出两边的式子，再比较哪边更大，还能求出两边差多少。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'기본',en:'basic',zh:'基本'},params:{mode:'simple'}},
          {id:2,label:{ko:'큰 수',en:'bigger numbers',zh:'较大的数'},params:{mode:'wide'},
           concept:{ko:'수가 커져도 양쪽을 각각 계산한 뒤 큰 쪽을 골라요 — 2×3=6과 98+98=196 중 큰 값은 196이에요.',
             en:'Bigger numbers change nothing: work out each side, then pick the larger — 2×3=6 against 98+98=196 gives 196.',
             zh:'数变大也一样：分别算出两边再选大的——2×3=6与98+98=196中较大的是196。'}},
          {id:3,label:{ko:'값과 차 구하기',en:'value & difference',zh:'求值与差'},params:{mode:'diff'},
           concept:{ko:'큰 값을 고른 뒤 두 값의 차까지 구해요 — 39+13=52와 62−48=14면 큰 값은 52, 차는 38이에요.',
             en:'Pick the larger value, then work out the gap: 39+13=52 against 62−48=14 gives 52 and a difference of 38.',
             zh:'先选出较大的值，再求两者之差：39+13=52与62−48=14，较大的是52，差是38。'}}] },
EL4:{ name:{ko:'평균',en:'Average',zh:'平均数'}, gen:'el_average', prereq:['AD6','DV4'],
  concept:{ko:'여러 수를 다 더한 다음 개수로 나누면 평균이에요. 평균과 개수를 알면 거꾸로 빠진 수도 찾을 수 있어요.',
    en:"Add all the numbers together and divide by how many there are — that's the average. Knowing the average lets you find a missing number too.",
    zh:'把几个数加起来再除以个数，就是平均数。知道平均数和个数，也能倒着找出缺失的数。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'세 수의 평균',en:'average of 3',zh:'三个数的平均'},params:{mode:'find',n:3}},
          {id:2,label:{ko:'다섯 수의 평균',en:'average of 5',zh:'五个数的平均'},params:{mode:'find',n:5}},
          {id:3,label:{ko:'평균으로 빠진 수 찾기',en:'find the missing number',zh:'由平均数求缺失的数'},params:{mode:'missing'},
           concept:{ko:'평균 × 개수 = 전체 합이에요. 전체 합에서 이미 아는 수들을 빼면 빠진 수가 나와요 — 평균 17에 5개면 합이 85, 거기서 나머지를 빼면 돼요.',
             en:'Mean × count = total. Subtract the numbers you already know from that total to get the missing one — a mean of 17 over 5 numbers means a total of 85.',
             zh:'平均数×个数=总和。用总和减去已知的数就得到缺的那个——平均17、共5个，总和就是85。'}}] },
EL5:{ name:{ko:'비례식',en:'Proportions',zh:'比例式'}, gen:'el_ratio', prereq:['MX3'],
  concept:{ko:'비례식은 겉보기엔 다른 두 비가 사실은 같다고 말해줘요. 바깥쪽 두 수를 곱한 값과 안쪽 두 수를 곱한 값은 항상 같아요. 전체를 주어진 비로 나누는 것은 비례배분이라고 해요 — 600을 2:3으로 나누면 240과 360이에요.',
    en:'A proportion says two ratios that look different are actually equal — the product of the outer two numbers always equals the product of the inner two. Splitting a whole by a given ratio is proportional sharing: 600 split 2:3 gives 240 and 360.',
    zh:'比例式是说两个看起来不同的比其实相等。外项之积永远等于内项之积。把总量按给定的比分开叫按比例分配——600按2:3分开，得240和360。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'빈 항 구하기',en:'find the term',zh:'求空项'},params:{mode:'direct'}},
          {id:2,label:{ko:'외항·내항의 곱',en:'cross products',zh:'外项内项之积'},params:{mode:'steps'},
           concept:{ko:'바깥쪽 두 수의 곱과 안쪽 두 수의 곱이 같아요 — 12:2 = 108:□ 는 12×□ = 2×108이니 □는 18이에요.',
             en:'The outer pair multiplies to the same value as the inner pair: 12:2 = 108:□ means 12×□ = 2×108, so □ is 18.',
             zh:'外项之积等于内项之积：12:2 = 108:□就是12×□ = 2×108，所以□是18。'}},
          /* 2026-08-29 신규 — 비례식 바로 다음 단원인데 문제은행에 없었다. */
          {id:3,label:{ko:'비례배분',en:'proportional sharing',zh:'按比例分配'},params:{mode:'distribute'},
           concept:{ko:'전체를 비의 합만큼 조각내고, 각자 제 몫만큼 가져가요 — 117을 6:7로 나누면 한 조각은 117÷13=9이니 54와 63이에요.',
             en:'Cut the total into as many parts as the ratio adds to, then give each its share: 117 split 6:7 has parts of 117÷13=9, giving 54 and 63.',
             zh:'把总数分成比之和那么多份，各取自己的份数：117按6:7分，每份是117÷13=9，所以是54和63。'}}] },

/* ── 창의 연산 초급 기법(2026-09-26, engine/threads/cre.js) — AD11~AD16 머리말 참고 ──
   MX7 덧셈끼리·뺄셈끼리 · MX8 수는 몇 개·짝지어 더하기 · EL6 합과 차 */
MX7:{ name:{ko:'덧셈끼리·뺄셈끼리',en:'Gather the Pluses and Minuses',zh:'加的归加，减的归减'}, gen:'cre_mx7_sortAddSub', prereq:['AD5','SB4'],
  unit:'A-12',
  concept:{ko:'더하는 수끼리, 빼는 수끼리 모아서 계산해요. 35−14+21−22는 (35+21)−(14+22)=56−36=20이에요.',
    en:'Gather the numbers you add and the numbers you take away, then calculate. 35−14+21−22 is (35+21)−(14+22)=56−36=20.',
    zh:'加的数放在一起，减的数放在一起再算。35−14+21−22就是(35+21)−(14+22)=56−36=20。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'두 자리 네 수',en:'four 2-digit numbers',zh:'四个两位数'},params:{mode:'two'},unit:'A-12'},
          {id:2,label:{ko:'세 자리 네 수',en:'four 3-digit numbers',zh:'四个三位数'},params:{mode:'three'},unit:'A-25',
           concept:{ko:'세 자리여도 같아요. 263−174+372−235는 (263+372)−(174+235)=635−409=226이에요.',
             en:'Three digits, same idea: 263−174+372−235 is (263+372)−(174+235)=635−409=226.',
             zh:'三位数也一样：263−174+372−235就是(263+372)−(174+235)=635−409=226。'}},
          {id:3,label:{ko:'소수 끼리끼리',en:'decimals, gathered',zh:'小数同类相加'},params:{mode:'dec'},unit:'A-38',
           concept:{ko:'소수도 끼리끼리 모으면 자연수가 돼요. 12.56−4.7+5.44−5.3은 12.56+5.44=18, 4.7+5.3=10이라 18−10=8이에요.',
             en:'Gathered decimals can make whole numbers: 12.56−4.7+5.44−5.3 gives 12.56+5.44=18 and 4.7+5.3=10, so 18−10=8.',
             zh:'小数同类相加也能凑成整数：12.56−4.7+5.44−5.3，12.56+5.44=18，4.7+5.3=10，所以18−10=8。'}}] },
MX8:{ name:{ko:'수는 몇 개·짝지어 더하기',en:'How Many Numbers & Pair Sums',zh:'有几个数·配对相加'}, gen:'cre_mx8_countPair', prereq:['SB4'],
  concept:{ko:'어떤 수부터 어떤 수까지의 개수는 (끝 수)−(첫 수)+1이에요. 8부터 16까지는 16−8+1=9개예요.',
    en:'The count of numbers from one number to another is (last) − (first) + 1. From 8 to 16 there are 16−8+1=9.',
    zh:'从一个数到另一个数一共有(最后一个数)−(第一个数)+1个。从8到16有16−8+1=9个。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'수는 몇 개(두 자리)',en:'how many (2-digit)',zh:'有几个(两位)'},params:{mode:'count2'},unit:'A-27'},
          {id:2,label:{ko:'수는 몇 개(세 자리)',en:'how many (3-digit)',zh:'有几个(三位)'},params:{mode:'count3'},unit:'A-27',
           concept:{ko:'세 자리여도 같아요. 257부터 965까지는 965−257+1=709개예요 — 끝의 1을 잊지 말아요.',
             en:'Three digits, same rule: from 257 to 965 there are 965−257+1=709 — do not forget the +1.',
             zh:'三位数也一样：从257到965有965−257+1=709个——别忘了加1。'}},
          {id:3,label:{ko:'짝지어 더하기',en:'pair and add',zh:'配对相加'},params:{mode:'pair'},unit:'A-28',
           concept:{ko:'첫 수와 끝 수를 짝지으면 짝마다 합이 같아요. 1+2+…+10은 1+10=11이 5짝이라 11을 다섯 번 더해 55예요.',
             en:'Pair the first number with the last and every pair has the same sum: 1+2+…+10 has five pairs of 11, so add 11 five times — 55.',
             zh:'首尾配对，每对的和都一样：1+2+…+10有5对11，把11加5次得55。'}}] },
EL6:{ name:{ko:'합과 차로 두 수 찾기',en:'Two Numbers from Sum & Difference',zh:'由和与差求两数'}, gen:'cre_el6_sumDiff', prereq:['ML1','SB4'],
  concept:{ko:'두 수의 합에서 차를 먼저 빼면 작은 수가 두 개 남아요. 합 49, 차 5면 49−5=44, 44÷2=22가 작은 수, 22+5=27이 큰 수예요.',koMid:'두 수의 합에서 차를 먼저 빼면 작은 수가 두 개 남습니다. 합 49, 차 5이면 49−5=44, 44÷2=22가 작은 수, 22+5=27이 큰 수입니다.',
    en:'Take the difference away from the sum and what is left is two copies of the smaller number. Sum 49, difference 5: 49−5=44, 44÷2=22 is the smaller, 22+5=27 the bigger.',
    zh:'从和里先减去差，剩下的是两个小数。和49、差5：49−5=44，44÷2=22是小数，22+5=27是大数。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'차 먼저 빼기',en:'take the difference first',zh:'先减去差'},params:{mode:'diffFirst'},unit:'A-33'},
          {id:2,label:{ko:'(합±차)÷2',en:'(sum ± difference) ÷ 2',zh:'(和±差)÷2'},params:{mode:'half'},unit:'A-34',
           concept:{ko:'큰 수는 (합+차)÷2, 작은 수는 (합−차)÷2예요. 합 837, 차 561이면 큰 수 (837+561)÷2=699, 작은 수 (837−561)÷2=138이에요.',koMid:'큰 수는 (합+차)÷2, 작은 수는 (합−차)÷2입니다. 합 837, 차 561이면 큰 수 (837+561)÷2=699, 작은 수 (837−561)÷2=138입니다.',
             en:'The bigger number is (sum + difference) ÷ 2 and the smaller is (sum − difference) ÷ 2: sum 837, difference 561 give 699 and 138.',
             zh:'大数是(和+差)÷2，小数是(和−差)÷2：和837、差561，大数(837+561)÷2=699，小数(837−561)÷2=138。'}},
          {id:3,label:{ko:'평균수 기준',en:'from the middle number',zh:'以平均数为基准'},params:{mode:'average'},unit:'A-34',
           concept:{ko:'합의 반은 두 수의 한가운데예요. 거기서 차의 반만큼 내려가면 작은 수, 올라가면 큰 수예요. 합과 차가 둘 다 짝수이거나 둘 다 홀수여야 두 자연수가 나와요.',koMid:'합의 반은 두 수의 한가운데입니다. 거기서 차의 반만큼 내려가면 작은 수, 올라가면 큰 수입니다. 합과 차가 둘 다 짝수이거나 둘 다 홀수여야 두 자연수가 나옵니다.',
             en:'Half the sum sits right between the two numbers; go down half the difference for the smaller, up for the bigger. The sum and difference must both be even or both odd for two whole numbers.',
             zh:'和的一半正好在两个数的中间；往下走差的一半是小数，往上走是大数。和与差必须同为偶数或同为奇数，才能得到两个自然数。'}}] },

/* ── CHALLENGE 신규 13종 (고급-목차.md 신규분, 2026-08-25 Phase 2) ──
   경시의 탑(과정 26~28) + 몰아주기 곱/어림하기/큰 수 정복(과정 19·24 보강)용.
   gen 함수는 engine/threads/adv.js — 전부 mode 파라미터로 정독에서 확인한
   원본의 여러 갈래(진법 변환+이진곱셈, 곱셈+나눗셈 역방향 등)를 한 스레드
   안에서 레벨로 나눈다(기존 ml_diff2sq·ml_gauss와 같은 설계 관례). */
CH1:{ name:{ko:'한쪽으로 모으기',en:'Gathering to One Side',zh:'移到一边'}, gen:'adv_gather', prereq:['ML8'],
  unit:'H-01',
  concept:{ko:'곱하는 수를 반씩(또는 몇 분의 일씩) 줄이는 대신, 곱해지는 수를 그만큼 키워주면 답은 그대로예요. 곱하는 수가 1이 될 때까지 계속 몰아주면 아무리 어려운 곱셈도 쉬워져요.',
    en:'Instead of shrinking the multiplier, grow the multiplicand by the same factor — the product never changes. Keep going until the multiplier reaches 1, and even a hard multiplication becomes easy.',
    zh:'与其把乘数缩小，不如把被乘数按同样的倍数放大——积不会变。一直做到乘数变成1，再难的乘法也会变简单。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'두 자리×두 자리',en:'2d×2d',zh:'两位×两位'},params:{level:'practice'}},
          {id:2,label:{ko:'세 자리×두 자리',en:'3d×2d',zh:'三位×两位'},params:{level:'main'}}] },

CH2:{ name:{ko:'100(1000) 보수 곱',en:'Complement-of-100(1000) Multiplication',zh:'100(1000)补数乘法'}, gen:'adv_comp100', prereq:['ML10'],
  unit:'H-02',
  concept:{ko:'100에서 얼마나 모자란지 각각 적어두고 엇갈려 빼면 앞자리, 모자란 두 수끼리 곱하면 뒷자리가 나와요. 한쪽이 100을 넘으면 더하는 대신 빼줘요.',
    en:'Write how far each number is from 100, cross-subtract for the front digits, and multiply the two gaps for the back digits. If one number is over 100, subtract instead of add.',
    zh:'写出两数各自比100少多少，交叉相减得到前面的数，两个差相乘得到后面的数。如果一个数超过100，就要用减法而不是加法。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'100 미만끼리(연습)',en:'both under 100 (practice)',zh:'都小于100(练习)'},params:{mode:'under',base:100}},
          {id:2,label:{ko:'100 넘는·안 넘는 수(실전)',en:'over & under 100 (main)',zh:'一大一小(实战)'},params:{mode:'mixed',base:100},
           concept:{ko:'한쪽이 100을 넘으면 모자란 만큼이 아니라 **남는 만큼**이라, 엇갈려 뺄 때 더하고 뒷자리 곱은 빼요 — 106×95는 (106−5)=101에 6×(−5)=−30이라 10070이에요.',
             en:'When one number is over 100 it has a surplus rather than a shortfall, so the cross step adds and the tail product is subtracted — 106×95 gives 101 and 6×(−5)=−30, so 10070.',
             zh:'有一个数超过100时它是"多出"而不是"差"，所以交叉时要加、尾数之积要减——106×95是101与6×(−5)=−30，得10070。'}},
          {id:3,label:{ko:'1000 미만끼리',en:'both under 1000',zh:'都小于1000'},params:{mode:'under',base:1000}},
          {id:4,label:{ko:'1000 넘는·안 넘는 수',en:'over & under 1000',zh:'一大一小(1000)'},params:{mode:'mixed',base:1000},
           concept:{ko:'1000이 기준이면 뒷자리가 **세 자리**예요. 나머지는 100 기준과 똑같이 엇갈려 빼고 모자란 두 수를 곱해요.',
             en:'With 1000 as the anchor the tail takes three digits; everything else works exactly as it does around 100.',
             zh:'以1000为基准时尾数占三位，其余步骤与以100为基准完全相同。'}}] },

CH3:{ name:{ko:'진법·진법 곱셈법',en:'Number Bases & Binary Multiplication',zh:'进制与二进制乘法'}, gen:'adv_baseSystem', prereq:['ML1'],
  unit:'H-03',
  concept:{ko:'우리가 쓰는 10개 숫자 말고도 2개·3개·5개·16개 숫자만 쓰는 셈법이 있어요. 곱하는 수를 1, 2, 4, 8처럼 두 배씩 커지는 수들의 합으로 나눠보면, 미리 구해둔 곱셈표에서 필요한 것만 골라 더하는 것으로 어려운 곱셈을 풀 수 있어요 — 이건 컴퓨터가 셈하는 이진법의 원리와 똑같아요.',
    en:'Besides our 10 digits, there are number systems using only 2, 3, 5, or 16 digits. Split a multiplier into a sum of doubling numbers like 1, 2, 4, 8 and add up only the matching pre-made products — that is exactly how computers multiply in binary.',
    zh:'除了我们常用的10个数字，还有只用2、3、5或16个数字的记数法。把乘数拆成1、2、4、8这样翻倍的数之和，再挑出对应的乘积加起来——这正是电脑用二进制做乘法的原理。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'진법→십진수',en:'base → decimal',zh:'进制→十进制'},params:{op:'convert',base:5,dir:'fromBase'},
           concept:{ko:'5진법은 자리마다 1·5·25를 뜻해요. (34)₅는 3×5+4=19처럼 자릿값을 곱해 더하면 십진수가 돼요.',
             en:'In base 5 the places mean 1, 5 and 25. Multiply each digit by its place and add: (34)₅ is 3×5+4=19.',
             zh:'五进制里每个数位分别表示1、5、25。把每个数字乘以位值再相加：(34)₅是3×5+4=19。'}},
          {id:2,label:{ko:'십진수→진법',en:'decimal → base',zh:'十进制→进制'},params:{op:'convert',base:5,dir:'toBase'}},
          {id:3,label:{ko:'16진법 읽기',en:'reading hex',zh:'读16进制'},params:{op:'convert',base:16}},
          {id:4,label:{ko:'이진법 곱셈(연습)',en:'binary multiplication (practice)',zh:'二进制乘法(练习)'},params:{op:'binaryMul',level:'practice'}},
          {id:5,label:{ko:'이진법 곱셈(실전)',en:'binary multiplication (main)',zh:'二进制乘法(实战)'},params:{op:'binaryMul',level:'main'}}] },

CH4:{ name:{ko:'1001 자릿수 이동법칙',en:'The 1001 Repeat Rule',zh:'1001重复规律'}, gen:'adv_1001', prereq:['ML9'],
  unit:'H-04',
  concept:{ko:'1001은 사실 1000과 1을 더한 수라서, 세 자리 수에 곱하면 그 수가 사이에 0을 남기고(또는 안 남기고) 통째로 한 번 더 나타나요. 1001을 7과 11과 13으로 쪼갤 수 있다는 것도 비밀이에요.',
    en:'1001 is really 1000 plus 1, so multiplying a 3-digit number by it makes the number repeat right after itself (sometimes with a zero gap). It is also secretly 7×11×13.',
    zh:'1001其实是1000加1，用它乘一个三位数，这个数就会（有时隔着0）原样再出现一次。1001还偷偷等于7×11×13。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'곱셈(연습)',en:'multiply (practice)',zh:'乘法(练习)'},params:{mode:'mul',level:'practice'}},
          {id:2,label:{ko:'곱셈(실전)',en:'multiply (main)',zh:'乘法(实战)'},params:{mode:'mul',level:'main'}},
          {id:3,label:{ko:'나눗셈(연습)',en:'divide (practice)',zh:'除法(练习)'},params:{mode:'div',level:'practice'},
           concept:{ko:'반복되는 자리를 알아채면 나눗셈이 바로 풀려요. 923923은 923이 두 번 반복된 것이니 1001로 나누면 923이에요.',
             en:'Spot the repeating block and the division is immediate: 923923 is 923 twice, so dividing by 1001 gives 923.',
             zh:'看出重复的部分，除法立刻就解开：923923是923重复两次，除以1001得923。'}},
          {id:4,label:{ko:'나눗셈(실전)',en:'divide (main)',zh:'除法(实战)'},params:{mode:'div',level:'main'},
           concept:{ko:'사이에 0이 끼어 있어도 같아요. 2110211은 211이 0 하나를 사이에 두고 두 번이니 10001로 나누면 211이에요.',
             en:'A zero gap changes nothing: 2110211 is 211 twice with one zero between, so dividing by 10001 gives 211.',
             zh:'中间隔着0也一样：2110211是211中间隔一个0重复两次，除以10001得211。'}}] },

CH5:{ name:{ko:'순환소수 나눗셈',en:'Repeating-Decimal Division',zh:'循环小数除法'}, gen:'adv_repeatDec', prereq:['DC1'],
  unit:'H-05',
  concept:{ko:'9로 나누면 몫이 나눈 수 그대로 반복되고, 99로 나누면 두 자리씩 반복돼요. 나누어 떨어지지 않아도 규칙만 알면 소수점 뒤가 어떻게 이어질지 미리 알 수 있어요.',
    en:'Divide by 9 and the quotient repeats the dividend itself; divide by 99 and it repeats two digits at a time. Even when it never ends, knowing the pattern tells you what comes next.',
    zh:'除以9，商就原样重复被除数；除以99，就两位两位地重复。就算除不尽，只要知道规律，也能提前知道小数点后会怎么继续。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'반복마디 찾기',en:'find the repeating block',zh:'找循环节'},params:{mode:'cycle'}},
          {id:2,label:{ko:'특정 자리 숫자(연습)',en:'digit at a position (practice)',zh:'求某一位(练习)'},params:{mode:'digitAt',level:'practice'},
           concept:{ko:'몫의 반복마디가 자리마다 되풀이돼요. 몇 번째 자리인지를 반복마디 길이로 나눈 나머지가 곧 그 자리의 숫자예요 — 1÷11=0.0909…이니 소수 2번째 자리는 9예요.',
             en:'The repeating block repeats place after place, so divide the place number by the block length and the remainder tells you the digit — 1÷11 = 0.0909…, so the 2nd decimal place is 9.',
             zh:'循环节会一位一位重复，用位数除以循环节长度，余数就指出那一位的数字——1÷11=0.0909…，所以小数第2位是9。'}},
          {id:3,label:{ko:'특정 자리 숫자(실전)',en:'digit at a position (main)',zh:'求某一位(实战)'},params:{mode:'digitAt',level:'main'},
           concept:{ko:'자리 수가 커져도 반복마디로 나눈 나머지만 보면 돼요 — 4÷11=0.3636…이라 소수 8번째 자리는 6이에요.',
             en:'Even for a far-off place, just divide by the block length and read the remainder — 4÷11 = 0.3636…, so the 8th decimal place is 6.',
             zh:'位数再大也只看用循环节长度除后的余数——4÷11=0.3636…，所以小数第8位是6。'}},
          {id:4,label:{ko:'분수로 되돌리기',en:'back to a fraction',zh:'化回分数'},params:{mode:'toFraction'},
           concept:{ko:'반복마디를 분자로, 그 자릿수만큼의 9를 분모로 쓰면 분수로 되돌아가요 — 0.̅5̅2̅6̅은 526/999, 0.̅6̅은 6/9예요.',
             en:'Put the repeating block on top and as many 9s as it has digits on the bottom: 0.526526… is 526/999 and 0.666… is 6/9.',
             zh:'把循环节作分子、与其位数相同个数的9作分母，就还原成分数：0.526526…是526/999，0.666…是6/9。'}}] },

CH6:{ name:{ko:'100(10·1000)에 가까운 수의 나눗셈',en:'Division Near 100 (10 · 1000)',zh:'接近100(10·1000)的除法'}, gen:'adv_divNear', prereq:['DV5'],
  unit:'H-06',
  concept:{ko:'나누는 수가 100에 가까우면, 일단 100으로 나눈 것처럼 어림한 다음 모자란 만큼을 몫에 곱해서 계속 더해주면 정확한 몫과 나머지가 나와요.',
    en:'When the divisor is close to 100, first estimate as if dividing by 100, then keep adding back the shortfall (times the quotient so far) until you land on the exact quotient and remainder.',
    zh:'当除数接近100时，先假装除以100来估算，再把不足的部分乘以商加回去，反复调整就能得到准确的商和余数。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'100 근처(연습)',en:'near 100 (practice)',zh:'接近100(练习)'},params:{anchor:100,level:'practice'}},
          {id:2,label:{ko:'100 근처(실전)',en:'near 100 (main)',zh:'接近100(实战)'},params:{anchor:100,level:'main'}},
          {id:3,label:{ko:'10 근처',en:'near 10',zh:'接近10'},params:{anchor:10}},
          {id:4,label:{ko:'1000 근처',en:'near 1000',zh:'接近1000'},params:{anchor:1000}}] },

CH7:{ name:{ko:'50·100·1000 근처 수의 제곱',en:'Squares Near 50, 100 & 1000',zh:'接近50·100·1000的平方'}, gen:'adv_nearSquare', prereq:['ML11'],
  unit:'H-07',
  concept:{ko:'50이나 100, 1000처럼 외우기 쉬운 수 근처의 제곱은, 그 기준수와 얼마나 떨어져 있는지만큼을 앞자리에 더하거나 빼고, 그 떨어진 만큼을 제곱해서 뒷자리에 붙이면 끝나요.',
    en:'For a square near a friendly anchor like 50, 100, or 1000, add or subtract the gap from a fixed front number, then square the gap and attach it as the back digits.',
    zh:'靠近50、100、1000这样好记的数的平方，只要把差距加减到固定的前面数字上，再把差距平方接到后面就行了。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'50 근처',en:'near 50',zh:'接近50'},params:{anchor:50},
           concept:{ko:'50 근처 수의 제곱은 25에서 출발해요. 50과의 차를 25에 더하거나 빼 앞자리로 쓰고, 그 차의 제곱을 뒷자리에 붙여요. 61²은 25+11=36, 11²=121이니 3721이에요.',
             en:'Squares near 50 start from 25: add (or subtract) the gap from 50 to 25 for the front, then attach the gap squared. 61² is 25+11=36 and 11²=121, so 3721.',
             zh:'接近50的平方要从25出发：把与50的差加到（或减去）25作为前段，再把这个差的平方接在后面。61²是25+11=36，11²=121，所以是3721。'}},
          {id:2,label:{ko:'100 근처',en:'near 100',zh:'接近100'},params:{anchor:100}},
          {id:3,label:{ko:'1000 근처',en:'near 1000',zh:'接近1000'},params:{anchor:1000}}] },

CH8:{ name:{ko:'제곱·세제곱 계산법',en:'Adjustable-Anchor Squares & Cubes',zh:'平方立方捷算法'}, gen:'adv_sqcube', prereq:['ML11'],
  unit:'H-08',
  concept:{ko:'제곱은 원래 수보다 얼마쯤 크고 작은 두 수를 곱한 다음 그 차이의 제곱을 더해주면 돼요. 세제곱은 거기에 원래 수를 한 번 더 곱해주면 되고, ★는 계산이 편해지도록 내가 골라도 돼요.',
    en:'For a square, multiply two numbers a bit above and below the original, then add back the square of that gap. A cube just multiplies that result by the original number once more — and you get to choose the gap ★ yourself.',
    zh:'求平方时，把比原数稍大稍小的两个数相乘，再加上那个差距的平方。求立方就在此基础上再乘一次原数——差距★可以自己挑，怎么算得顺手怎么选。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'제곱(세 자리)',en:'squares (3-digit)',zh:'平方(三位数)'},params:{mode:'square'}},
          {id:2,label:{ko:'세제곱(두 자리)',en:'cubes (2-digit)',zh:'立方(两位数)'},params:{mode:'cube'},
           concept:{ko:'세제곱은 제곱을 구한 뒤 원래 수를 한 번 더 곱해요 — 21³은 21²=441에 21을 곱해 9261이에요.',
             en:'For a cube, square first and then multiply by the number once more: 21³ is 441×21 = 9261.',
             zh:'立方是先求平方再乘一次原数：21³是441×21=9261。'}}] },

CH9:{ name:{ko:'분리 제곱법',en:'Split-Number Squares',zh:'分离平方法'}, gen:'adv_splitSquare', prereq:['ML8'],
  unit:'H-09',
  concept:{ko:'다섯 자리도 넘는 큰 수는 앞부분과 뒷부분으로 나눠서, (앞부분)²+2×앞부분×뒷부분+(뒷부분)²으로 계산하면 돼요. 각 부분은 우리가 이미 배운 마법들로 하나씩 풀 수 있어요.',
    en:'For a big number with five digits or more, split it into a front and back part and compute front²+2×front×back+back². Each piece can be solved with tricks you already know.',
    zh:'五位数以上的大数，可以拆成前面和后面两部分，用前²+2×前×后+后²来算。每一部分都能用学过的魔法解决。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'끝 두 자리 분리(연습)',en:'split last 2 digits (practice)',zh:'拆末两位(练习)'},params:{split:2,level:'practice'}},
          {id:2,label:{ko:'끝 두 자리 분리(실전)',en:'split last 2 digits (main)',zh:'拆末两位(实战)'},params:{split:2,level:'main'}},
          {id:3,label:{ko:'끝 세 자리 분리',en:'split last 3 digits',zh:'拆末三位'},params:{split:3,level:'main'}}] },

CH10:{ name:{ko:'제곱수의 합',en:'Sum of Consecutive Squares',zh:'连续平方数之和'}, gen:'adv_sumSquares', prereq:['MX2'],
  unit:'H-10',
  concept:{ko:'1부터 어떤 수까지 제곱을 다 더한 값은 공식 하나로 바로 구할 수 있어요. 1이 아닌 수부터 시작할 땐, 큰 구간의 합에서 필요 없는 앞부분 합을 빼주면 돼요.',
    en:'Adding up every square from 1 to some number has one direct formula. If you start somewhere other than 1, just subtract the unneeded front part from the bigger range’s sum.',
    zh:'从1加到某个数的所有平方，有一个公式可以直接求出来。如果不是从1开始，就用大区间的和减去不需要的前面部分。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'작은 구간',en:'small range',zh:'小区间'},params:{level:'practice'}},
          {id:2,label:{ko:'큰 구간(세 자리)',en:'big range (3-digit)',zh:'大区间(三位数)'},params:{level:'main'}}] },

CH11:{ name:{ko:'몰아주기 곱',en:'Anchor-the-Tens Multiplication',zh:'集中相乘法'}, gen:'adv_anchorTens', prereq:['ML8'],
  unit:'H-11',
  concept:{ko:'십의 자리가 같은 두 수는 그 십의 자리 값에 일의 자리 두 개를 얹어 곱하고, 일의 자리끼리 곱한 걸 더하면 끝나요. 일의 자리 합이 딱 10이거나 십의 자리 합이 딱 10이면 더 빨리 풀리는 지름길도 있어요.',
    en:'Two numbers with the same tens digit multiply by anchoring on that tens value, then adding the product of the ones. When the ones (or tens) add up to exactly 10, there is an even faster shortcut.',
    zh:'十位相同的两个数，先以那个十位为基准相乘，再加上个位之积。当个位（或十位）之和恰好是10时，还有更快的捷径。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'십의 자리 같음(일반형)',en:'same tens (general)',zh:'十位相同(通用)'},params:{mode:'sameTens'}},
          {id:2,label:{ko:'십의 자리 같고 일의 자리 합10',en:'same tens, ones sum to 10',zh:'十位相同,个位和为10'},params:{mode:'sameTensSum10'},
           concept:{ko:'십의 자리가 같고 일의 자리 합이 10이면 더 빨라요. 앞자리는 십의 자리와 그다음 수를 곱하고, 뒤에는 일의 자리끼리의 곱을 붙여요 — 52×58은 5×6=30에 2×8=16을 붙여 3016이에요.',
             en:'When the tens match and the ones add to 10 it is quicker: multiply the tens digit by the next number for the front, then attach the product of the ones — 52×58 is 5×6=30 with 2×8=16, giving 3016.',
             zh:'十位相同且个位之和为10时更快：前段用十位乘以下一个数，后面接上个位之积——52×58是5×6=30接上2×8=16，得3016。'}},
          {id:3,label:{ko:'일의 자리 같고 십의 자리 합10',en:'same ones, tens sum to 10',zh:'个位相同,十位和为10'},params:{mode:'sameOnesSum10'},
           concept:{ko:'일의 자리가 같고 십의 자리 합이 10이면, 앞자리는 십의 자리끼리 곱한 값에 일의 자리를 더하고 뒤에는 일의 자리의 제곱을 붙여요 — 73×33은 7×3+3=24에 3²=09를 붙여 2409예요.',
             en:'When the ones match and the tens add to 10: multiply the tens together, add the ones digit for the front, then attach the ones squared — 73×33 is 7×3+3=24 with 3²=09, giving 2409.',
             zh:'个位相同且十位之和为10时：前段用十位相乘再加个位，后面接上个位的平方——73×33是7×3+3=24接上3²=09，得2409。'}},
          {id:4,label:{ko:'십의 자리가 달라도(기준수 자유)',en:'different tens (free anchor)',zh:'十位不同(自选基准)'},params:{mode:'nearTens'},
           concept:{ko:'십의 자리가 달라도 돼요. 계산하기 쉬운 기준수를 스스로 골라 그 수에서 얼마나 떨어져 있는지로 풀어요.',
             en:'The tens do not have to match: pick an easy anchor yourself and work from how far each number sits from it.',
             zh:'十位不同也可以：自己选一个好算的基准数，再看两个数离它多远。'}}] },

CH12:{ name:{ko:'어림하기 곱셈법',en:'Estimate-and-Adjust Multiplication',zh:'估算调整乘法'}, gen:'adv_estimate', prereq:['ML6'],
  unit:'H-12',
  concept:{ko:'딱 맞는 수가 아니어도 괜찮아요. 계산하기 쉬운 어림수로 먼저 곱하고, 더 곱해진 만큼은 빼고 덜 곱해진 만큼은 더해주면 진짜 답이 나와요.',
    en:'You don’t need an exact round number. Multiply with an easy estimate first, then subtract what you multiplied extra or add back what you multiplied short.',
    zh:'不用凑成正好的数。先用好算的估算数相乘，多乘的部分减掉，少乘的部分加回来，就是真正的答案。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습(두 자리)',en:'practice (2-digit)',zh:'练习(两位数)'},params:{level:'practice'}},
          {id:2,label:{ko:'실전(세 자리)',en:'main (3-digit)',zh:'实战(三位数)'},params:{level:'main'}}] },

CH13:{ name:{ko:'큰 수 정복',en:'Conquering Big Numbers',zh:'征服大数'}, gen:'adv_bigscale', prereq:['NS1'],
  unit:'H-13',
  concept:{ko:'큰 수끼리 곱할 땐 0을 다 세어보면 돼요. 0이 4개씩 모일 때마다 만에서 억으로, 억에서 조로 한 계단씩 올라가요.',
    en:'When multiplying big round numbers, just count all the zeros. Every 4 more zeros climbs one step — from ten-thousand to hundred-million, and on to trillion.',
    zh:'大数相乘时，把所有的0数一数就行。每多4个0就往上跳一级——从万到亿，再到万亿。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'연습',en:'practice',zh:'练习'},params:{}}] },

/* ── MD 중등 W8(중1 정수와 유리수) 신규 9종 (2026-08-25) ──
   근거: MASTER-ROADMAP.md §5(중1 W8) + 중등연산-목차.md(G03~G25 실측 —
   이 교재는 정수·유리수 사칙연산과 거듭제곱만 다루고 문자와 식·일차방정식·
   정비례반비례는 없다, 그래서 이번 배치도 그 범위만). gen 함수는
   engine/threads/mid.js. unit은 data/units/M-01.js~M-09.js. */
MD1:{ name:{ko:'정수 개념·수직선',en:'Integers & the Number Line',zh:'整数概念与数轴'}, gen:'md1_intConcept', prereq:['NS1'],
  unit:'M-01',
  concept:{ko:'양의 정수, 0, 음의 정수를 통틀어 정수라고 합니다. 수직선에서 0(원점)의 오른쪽이 양수, 왼쪽이 음수입니다. 절댓값은 원점에서 그 수까지의 거리라 부호를 뗀 값입니다 — |+500|=500, |−500|=500.',
    en:'Positive integers, 0 and negative integers together are the integers. On the number line the right of 0 (the origin) is positive, the left is negative. The absolute value is the distance from the origin, so it is the number with its sign removed: |+500|=500, |−500|=500.',
    zh:'正整数、0、负整数统称为整数。数轴上0(原点)的右边是正数，左边是负数。绝对值是从原点到这个数的距离，也就是去掉符号的值——|+500|=500，|−500|=500。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'절댓값(연습)',en:'absolute value (practice)',zh:'绝对值(练习)'},params:{mode:'abs',level:'practice'}},
          {id:2,label:{ko:'절댓값(실전)',en:'absolute value (main)',zh:'绝对值(实战)'},params:{mode:'abs',level:'main'}},
          {id:3,label:{ko:'대소 비교',en:'comparing size',zh:'比较大小'},params:{mode:'compare'},
           concept:{ko:'수직선에서 오른쪽에 있는 수가 더 큽니다. 음수는 절댓값이 클수록 왼쪽에 있어 더 작습니다 — −12와 −14 중 작은 것은 −14입니다.',
             en:'On the number line the number further right is larger. A negative number with a larger absolute value sits further left, so it is smaller: of −12 and −14, the smaller is −14.',
             zh:'数轴上右边的数更大。负数的绝对值越大越靠左，所以越小——−12和−14中较小的是−14。'}},
          {id:4,label:{ko:'수직선 위 거리',en:'distance on the number line',zh:'数轴上的距离'},params:{mode:'distance'},
           concept:{ko:'수직선 위 두 점 사이의 거리는 두 수의 차에 절댓값을 씌운 값입니다 — 6과 −14 사이는 |6−(−14)|=20칸입니다.',
             en:'The distance between two points on the number line is the absolute value of their difference — 6 and −14 are |6−(−14)| = 20 apart.',
             zh:'数轴上两点间的距离就是两数之差的绝对值——6与−14相距|6−(−14)|=20。'}}] },

MD2:{ name:{ko:'정수의 덧셈과 뺄셈',en:'Adding & Subtracting Integers',zh:'整数的加减法'}, gen:'md2_intAddSub', prereq:['MD1'],
  unit:'M-02',
  concept:{ko:'부호가 같은 두 정수의 덧셈은 두 정수의 절댓값의 합에 공통인 부호를 붙입니다. 부호가 다른 두 정수의 덧셈은 두 정수의 절댓값의 차에 절댓값이 큰 수의 부호를 붙입니다. 정수의 뺄셈은 빼는 수의 부호를 바꾸어 덧셈으로 고쳐서 계산합니다 — (+1)−(−2)=(+1)+(+2)=+3.',
    en:'To add two integers with the same sign, add their absolute values and keep the common sign. To add two integers with different signs, subtract the absolute values and take the sign of the one with the larger absolute value. To subtract, change the sign of the number being subtracted and add: (+1)−(−2)=(+1)+(+2)=+3.',
    zh:'两个同号整数相加，把绝对值相加，再带上共同的符号。两个异号整数相加，把绝对值相减，再带上绝对值较大的数的符号。整数减法是把减数的符号改变后化为加法来算——(+1)−(−2)=(+1)+(+2)=+3。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'같은 부호(연습)',en:'same sign (practice)',zh:'同号(练习)'},params:{mode:'same',level:'practice'}},
          {id:2,label:{ko:'다른 부호(실전)',en:'different sign (main)',zh:'异号(实战)'},params:{mode:'diff',level:'main'},
           concept:{ko:'부호가 다른 두 정수의 덧셈은 절댓값의 차에 절댓값이 큰 수의 부호를 붙입니다 — (+1)+(−2)=−(2−1)=−1, 10+(−33)=−(33−10)=−23.',
             en:'To add two integers with different signs, subtract the absolute values and take the sign of the larger one: (+1)+(−2)=−(2−1)=−1, 10+(−33)=−(33−10)=−23.',
             zh:'两个异号整数相加，把绝对值相减，再带上绝对值较大的数的符号——(+1)+(−2)=−(2−1)=−1，10+(−33)=−(33−10)=−23。'}},
          {id:3,label:{ko:'괄호 풀기',en:'opening brackets',zh:'打开括号'},params:{mode:'brackets',level:'main'},
           concept:{ko:'괄호가 있는 정수의 덧셈과 뺄셈은 괄호를 풀어서 계산하는 것이 편리합니다. +(−□)=−□, −(−□)=+□ — 5−(−2)=5+2=7, −4+(−2)=−4−2=−6. 괄호를 풀 때는 부호에 주의합니다.',
             en:'With brackets it is easier to remove them first: +(−□)=−□ and −(−□)=+□, so 5−(−2)=5+2=7 and −4+(−2)=−4−2=−6. Watch the signs as you remove the brackets.',
             zh:'带括号的整数加减，先去括号更方便：+(−□)=−□，−(−□)=+□——5−(−2)=5+2=7，−4+(−2)=−4−2=−6。去括号时注意符号。'}},
          {id:4,label:{ko:'세 수 혼합',en:'three-number mix',zh:'三数混合'},params:{mode:'chain3',level:'main'},
           concept:{ko:'세 정수의 덧셈과 뺄셈 혼합 계산은 부호에 주의하여 괄호를 풀어서 앞에서부터 차례대로 계산합니다 — 3−(−6)−5=3+6−5=9−5=4.',
             en:'For three integers mixing addition and subtraction, remove the brackets carefully and work from left to right: 3−(−6)−5=3+6−5=9−5=4.',
             zh:'三个整数的加减混合运算，注意符号去掉括号后从左到右依次计算——3−(−6)−5=3+6−5=9−5=4。'}}] },

MD3:{ name:{ko:'유리수의 덧셈과 뺄셈',en:'Adding & Subtracting Rational Numbers',zh:'有理数的加减法'}, gen:'md3_ratAddSub', prereq:['MD2','FR4'],
  unit:'M-03',
  concept:{ko:'유리수의 덧셈과 뺄셈도 정수와 같습니다 — 부호가 같으면 절댓값의 합에 공통인 부호, 다르면 절댓값의 차에 절댓값이 큰 수의 부호를 붙이고, 뺄셈은 빼는 수의 부호를 바꾸어 덧셈으로 고칩니다. 분모가 다르면 분모의 최소공배수로 통분하여 계산한 후, 약분이 되면 약분하여 기약분수로 나타냅니다.',
    en:'Adding and subtracting rational numbers works like integers: same signs, add the absolute values and keep the sign; different signs, subtract them and take the sign of the larger; to subtract, change the sign and add. With different denominators, first rewrite over the least common multiple, then reduce the result to lowest terms.',
    zh:'有理数的加减和整数一样——同号把绝对值相加带共同符号，异号把绝对值相减带绝对值较大者的符号，减法把减数变号化为加法。分母不同时先用分母的最小公倍数通分，结果能约分就化成最简分数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'분모가 같음',en:'same denominator',zh:'分母相同'},params:{mode:'sameDenom'}},
          {id:2,label:{ko:'분모가 다름(통분)',en:'different denominators (LCD)',zh:'分母不同(通分)'},params:{mode:'diffDenom'},
           concept:{ko:'분모가 다른 유리수의 덧셈과 뺄셈은 분모의 최소공배수로 통분하여 계산합니다. 분모에 곱한 수를 분자에도 똑같이 곱합니다 — −3/5+(−5/8)은 분모 40으로 통분합니다.',
             en:'With different denominators, rewrite both over the least common multiple of the denominators, multiplying the numerator by the same number as the denominator: −3/5+(−5/8) goes over 40.',
             zh:'分母不同的有理数加减，用分母的最小公倍数通分，分母乘几分子也乘几——−3/5+(−5/8)通分成分母40。'}},
          {id:3,label:{ko:'세 유리수 혼합',en:'three-term mix',zh:'三数混合'},params:{mode:'chain3'},
           concept:{ko:'세 유리수의 덧셈과 뺄셈 혼합 계산은 부호에 주의하여 괄호를 푼 다음, 분모의 최소공배수로 통분하여 앞에서부터 차례대로 계산합니다. 결과가 약분이 되면 기약분수로 나타냅니다.',
             en:'For three rational numbers, remove the brackets carefully, rewrite over the least common multiple of the denominators, then work from left to right. Reduce the result to lowest terms.',
             zh:'三个有理数的加减混合运算，注意符号去括号后，用分母的最小公倍数通分，再从左到右依次计算。结果能约分就化成最简分数。'}}] },

MD4:{ name:{ko:'정수의 곱셈과 나눗셈',en:'Multiplying & Dividing Integers',zh:'整数的乘除法'}, gen:'md4_intMulDiv', prereq:['MD2','ML8'],
  unit:'M-04',
  concept:{ko:'정수의 곱셈은 부호를 먼저 결정하고, 절댓값의 곱에 결정한 부호를 붙입니다 — (+)×(+)와 (−)×(−)는 (+), (+)×(−)와 (−)×(+)는 (−). 나눗셈도 부호를 먼저 결정하고 절댓값의 나눗셈의 몫에 그 부호를 붙입니다 — (−2)×(−6)=+(2×6)=12, (−6)÷2=−(6÷2)=−3.',
    en:'To multiply integers, decide the sign first and attach it to the product of the absolute values: (+)×(+) and (−)×(−) give (+), (+)×(−) and (−)×(+) give (−). Division is the same — decide the sign, then divide the absolute values: (−2)×(−6)=+(2×6)=12, (−6)÷2=−(6÷2)=−3.',
    zh:'整数乘法先确定符号，再把绝对值的积带上这个符号——(+)×(+)和(−)×(−)得(+)，(+)×(−)和(−)×(+)得(−)。除法也是先定符号，再给绝对值的商带上符号——(−2)×(−6)=+(2×6)=12，(−6)÷2=−(6÷2)=−3。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'두 수 곱셈(연습)',en:'two-number × (practice)',zh:'两数相乘(练习)'},params:{mode:'mul2',level:'practice'}},
          {id:2,label:{ko:'두 수 나눗셈(실전)',en:'two-number ÷ (main)',zh:'两数相除(实战)'},params:{mode:'div2',level:'main'},
           concept:{ko:'정수의 나눗셈은 부호를 먼저 결정하고, 절댓값의 나눗셈의 몫에 결정한 부호를 붙입니다 — 부호가 같으면 (+), 다르면 (−). 20÷(−2)=−(20÷2)=−10입니다.',
             en:'To divide integers, decide the sign first — same signs give (+), different signs give (−) — then attach it to the quotient of the absolute values: 20÷(−2)=−(20÷2)=−10.',
             zh:'整数除法先确定符号——同号得(+)，异号得(−)——再给绝对值的商带上符号：20÷(−2)=−(20÷2)=−10。'}},
          {id:3,label:{ko:'세 수 이상 곱셈(홀짝)',en:'three+ numbers × (odd/even)',zh:'三数以上相乘(奇偶)'},params:{mode:'mulChain',level:'main'},
           concept:{ko:'세 개 이상의 정수의 곱셈에서 곱의 부호는 곱하는 수 중 음수의 개수가 짝수 개이면 (+), 홀수 개이면 (−)입니다 — (−2)×(−3)×(−1)×(−4)=+(2×3×1×4)=24. 어떤 수와 0의 곱은 항상 0입니다.',
             en:'When multiplying three or more integers, the sign of the product is (+) if the number of negative factors is even and (−) if it is odd: (−2)×(−3)×(−1)×(−4)=+(2×3×1×4)=24. Anything times 0 is 0.',
             zh:'三个以上整数相乘，负数的个数是偶数积为(+)，是奇数积为(−)——(−2)×(−3)×(−1)×(−4)=+(2×3×1×4)=24。任何数乘0都是0。'}},
          {id:4,label:{ko:'곱셈·나눗셈 혼합',en:'× and ÷ mixed',zh:'乘除混合'},params:{mode:'mixedChain',level:'main'},
           concept:{ko:'정수의 곱셈과 나눗셈 혼합 계산은 앞에서부터 차례대로 계산합니다. 음수의 개수로 부호를 먼저 정해 두면 편합니다 — (−4)×3÷(−6)×(−5)=−(4×3÷6×5)=−10. 괄호가 있으면 괄호 안을 먼저 계산합니다.',
             en:'Mixed multiplication and division of integers goes from left to right. It helps to fix the sign first from the number of negatives: (−4)×3÷(−6)×(−5)=−(4×3÷6×5)=−10. Brackets are worked out first.',
             zh:'整数的乘除混合运算从左到右依次计算。先按负数的个数定好符号更方便——(−4)×3÷(−6)×(−5)=−(4×3÷6×5)=−10。有括号先算括号里的。'}}] },

MD5:{ name:{ko:'거듭제곱과 부호',en:'Powers & Signs',zh:'乘方与符号'}, gen:'md5_signedPower', prereq:['MD4'],
  unit:'M-05',
  concept:{ko:'거듭제곱은 같은 수를 여러 번 곱한 것을 간단히 나타낸 거입니다 — 밑은 여러 번 곱한 수, 지수는 곱한 개수. 양의 정수의 거듭제곱은 (+)입니다. 음의 정수의 거듭제곱에서 부호는 지수가 정합니다 — 짝수면 (+), 홀수면 (−). 괄호가 없는 −2²은 −(2×2)=−4이고, (−2)²은 +(2×2)=4입니다.',
    en:'A power is shorthand for multiplying the same number several times — the base is the number multiplied, the exponent is how many times. A power of a positive integer is (+). For a negative integer the exponent decides the sign: even gives (+), odd gives (−). Without brackets, −2² is −(2×2)=−4, while (−2)² is +(2×2)=4.',
    zh:'乘方是把同一个数连乘几次的简写——底数是被乘的数，指数是乘的次数。正整数的乘方是(+)。负整数的乘方，符号由指数决定——偶数为(+)，奇数为(−)。没有括号的−2²是−(2×2)=−4，而(−2)²是+(2×2)=4。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'괄호형 (-a)ⁿ',en:'parenthesized (-a)ⁿ',zh:'带括号(-a)ⁿ'},params:{mode:'paren'}},
          {id:2,label:{ko:'맨 앞 -aⁿ',en:'bare -aⁿ',zh:'不带括号-aⁿ'},params:{mode:'bare'},
           concept:{ko:'−2²처럼 괄호가 없으면 지수는 2에만 걸립니다 — −(2×2)=−4. 거듭제곱을 먼저 구하고 맨 마지막에 −를 붙입니다. −24²은 −576입니다.',
             en:'Without brackets, as in −2², the exponent applies only to the 2: −(2×2)=−4. Work out the power first and attach the − at the very end: −24² is −576.',
             zh:'像−2²这样没有括号，指数只作用于2——−(2×2)=−4。先算乘方，最后再加上−：−24²是−576。'}},
          {id:3,label:{ko:'섞어서(구분하기)',en:'mixed (spot the difference)',zh:'混合(区分两种)'},params:{mode:'mixed'},
           concept:{ko:'괄호가 있는지부터 봅니다. (−2)²=+(2×2)=4, −(−2)²=−4, −13⁴=−28561 — 음의 정수의 거듭제곱은 지수가 짝수면 (+), 홀수면 (−)입니다.',
             en:'Check for brackets first. (−2)²=+(2×2)=4, −(−2)²=−4, −13⁴=−28561 — a power of a negative integer is (+) for an even exponent and (−) for an odd one.',
             zh:'先看有没有括号。(−2)²=+(2×2)=4，−(−2)²=−4，−13⁴=−28561——负整数的乘方，指数为偶数得(+)，为奇数得(−)。'}}] },

MD6:{ name:{ko:'정수의 사칙 혼합 계산',en:'Mixed Integer Operations',zh:'整数四则混合运算'}, gen:'md6_intMixed', prereq:['MD2','MD4','MX1'],
  unit:'M-06',
  concept:{ko:'네 가지 연산이 섞이면 괄호 안을 가장 먼저, 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈 순서로 계산합니다. 부호가 있는 수라도 순서는 똑같습니다.',
    en:'When all four operations mix together, brackets go first, then multiplication and division, and addition and subtraction last. Signed numbers follow the exact same order.',
    zh:'四则运算混在一起时，先算括号，再算乘除，最后算加减。有符号的数也遵循同样的顺序。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'괄호 없이(연습)',en:'no brackets (practice)',zh:'无括号(练习)'},params:{mode:'noBrackets',level:'practice'}},
          {id:2,label:{ko:'괄호 있는 혼합',en:'with brackets',zh:'带括号混合'},params:{mode:'brackets',level:'main'},
           concept:{ko:'괄호 안을 가장 먼저 계산합니다. 그다음 곱셈·나눗셈, 마지막에 덧셈·뺄셈입니다 — (3+(−15))×5−(−5)는 −12×5+5=−55입니다.',
             en:'Do the brackets first, then multiply and divide, and add and subtract last: (3+(−15))×5−(−5) is −12×5+5 = −55.',
             zh:'先算括号，再乘除，最后加减：(3+(−15))×5−(−5)是−12×5+5=−55。'}},
          {id:3,label:{ko:'나눗셈 포함 혼합',en:'with division',zh:'含除法混合'},params:{mode:'withDivChain',level:'main'},
           concept:{ko:'곱셈과 나눗셈은 **앞에서부터 차례로** 합니다 — −12+3×9÷(−27)은 27÷(−27)=−1이니 −13입니다.',
             en:'Multiplication and division are done left to right in order: −12+3×9÷(−27) gives 27÷(−27)=−1, so −13.',
             zh:'乘法和除法要从左往右依次进行：−12+3×9÷(−27)中27÷(−27)=−1，所以是−13。'}}] },

MD7:{ name:{ko:'유리수의 곱셈과 나눗셈',en:'Multiplying & Dividing Rational Numbers',zh:'有理数的乘除法'}, gen:'md7_ratMulDiv', prereq:['MD3','FR6','FR7'],
  unit:'M-07',
  concept:{ko:'유리수의 곱셈은 곱의 부호를 먼저 정한 후에 계산합니다 — 두 수의 부호가 같으면 (+), 다르면 (−). 두 수의 곱이 1이 될 때 한 수를 다른 수의 역수라고 하고, 나눗셈은 나누는 수의 역수를 이용하여 곱셈으로 고쳐 계산합니다.',
    en:'To multiply rational numbers, decide the sign of the product first — same signs give (+), different signs give (−) — then multiply. Two numbers whose product is 1 are reciprocals of each other; to divide, multiply by the reciprocal of the divisor.',
    zh:'有理数乘法先确定积的符号——两数同号得(+)，异号得(−)——再计算。两数之积为1时，一个数叫另一个数的倒数；除法利用除数的倒数化为乘法来算。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'두 유리수 곱셈',en:'two-rational ×',zh:'两个有理数相乘'},params:{mode:'mul'}},
          {id:2,label:{ko:'두 유리수 나눗셈(역수)',en:'two-rational ÷ (reciprocal)',zh:'两个有理数相除(倒数)'},params:{mode:'div'},
           concept:{ko:'두 수의 곱이 1이 될 때 한 수를 다른 수의 역수라고 합니다. 나누는 수의 역수를 취해 곱셈으로 고쳐 계산합니다 — 1/2÷4/6=1/2×6/4=3/4. 정수는 분모가 1인 분수로, 대분수는 가분수로 고친 뒤 분자와 분모를 바꿉니다.',
             en:'Two numbers whose product is 1 are reciprocals. Take the reciprocal of the divisor and multiply: 1/2÷4/6=1/2×6/4=3/4. Write an integer over 1 and a mixed number as an improper fraction before swapping numerator and denominator.',
             zh:'两数之积为1时，一个数叫另一个数的倒数。取除数的倒数化为乘法——1/2÷4/6=1/2×6/4=3/4。整数先写成分母为1的分数，带分数先化成假分数，再交换分子分母。'}},
          {id:3,label:{ko:'세 유리수 곱나눗 혼합',en:'three-rational × and ÷ mix',zh:'三个有理数乘除混合'},params:{mode:'mixedChain'},
           concept:{ko:'곱셈과 나눗셈이 섞여 있는 유리수의 계산은 음수의 개수에 따라 전체의 부호를 결정하고, 나눗셈을 곱셈으로 바꾸어 계산합니다. 괄호 안을 먼저 계산하고, 약분이 되면 약분합니다.',
             en:'When multiplication and division are mixed, decide the overall sign from the number of negatives, turn every division into multiplication by a reciprocal, then multiply. Brackets first, and cancel wherever you can.',
             zh:'乘除混合的有理数运算，先按负数的个数确定整体的符号，再把除法改成乘法来算。先算括号里的，能约分就约分。'}}] },

MD8:{ name:{ko:'유한소수 판별',en:'Terminating or Repeating?',zh:'判断有限小数'}, gen:'md8_terminating', prereq:['FR8'],
  unit:'M-08',
  concept:{ko:'분수를 기약분수로 만들었을 때 분모의 소인수가 2와 5뿐이면 유한소수, 그 외의 소인수가 하나라도 남으면 순환소수(무한소수)입니다 — "2와 5는 친구" 계보의 마지막 걸음입니다.',
    en:'Reduce a fraction to lowest terms: if the denominator’s only prime factors are 2 and 5, the decimal terminates; if any other prime factor survives, it repeats forever — the final step of the "2 and 5 are friends" lineage.',
    zh:'把分数化成最简分数后，如果分母的质因数只有2和5，就是有限小数；只要还剩别的质因数，就是循环小数(无限小数)——这是"2和5是朋友"这条家族的最后一步。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'이미 기약분수',en:'already in lowest terms',zh:'已是最简分数'},params:{level:'reduced'}},
          {id:2,label:{ko:'약분이 필요함',en:'needs simplifying first',zh:'需要先约分'},params:{level:'unreduced'}}] },

MD9:{ name:{ko:'순환소수를 분수로',en:'Repeating Decimal to Fraction',zh:'循环小数化分数'}, gen:'md9_repeatToFrac', prereq:['CH5'],
  unit:'M-09',
  concept:{ko:'반복 전 자리(비순환부)까지 있는 순환소수는, 반복 전 자리를 포함해 이어붙인 수에서 반복 전 자리의 수를 빼면 분자가 되고, 분모는 10의 거듭제곱과 (10의 거듭제곱−1)의 곱입니다 — 처음부터 반복되는 경우(CH5)를 일반화한 거입니다.',
    en:'When a repeating decimal has non-repeating digits before the repeat starts, the numerator is the concatenated number minus the non-repeating prefix, and the denominator is a power of 10 times (a power of 10 minus 1) — a generalization of the purely-repeating case (CH5).',
    zh:'循环小数如果前面有不循环的部分，分子就是"连起来的数"减去不循环的前缀，分母是10的幂乘以(10的幂−1)——这是从头就循环的情形(CH5)的推广。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'비순환 1자리·순환 1자리',en:'1 prefix digit · 1 repeat digit',zh:'前缀1位·循环1位'},params:{k:1,m:1}},
          {id:2,label:{ko:'비순환 2자리·순환 1자리',en:'2 prefix digits · 1 repeat digit',zh:'前缀2位·循环1位'},params:{k:2,m:1}},
          {id:3,label:{ko:'비순환 1자리·순환 2자리',en:'1 prefix digit · 2 repeat digits',zh:'前缀1位·循环2位'},params:{k:1,m:2}},
          {id:4,label:{ko:'비순환 2자리·순환 2자리(실전)',en:'2 prefix · 2 repeat (main)',zh:'前缀2位·循环2位(实战)'},params:{k:2,m:2}},
          {id:5,label:{ko:'소수점 아래 n번째 자리',en:'digit at the nth decimal place',zh:'小数点后第n位'},params:{mode:'digitAt'},
           concept:{ko:'순환마디가 처음부터 반복되면 **n을 순환마디의 숫자 개수로 나눈 나머지**가 자리 위치를 알려 줍니다. 나머지가 1이면 첫째, 2이면 둘째이고, **나머지가 0이면 순환마디의 마지막 숫자**입니다.',
             en:'When the repeating block starts immediately, divide n by the block length. Remainder 1 means the first digit, remainder 2 the second, and remainder 0 means the last digit of the block.',
             zh:'循环节从小数第一位开始时，用n除以循环节长度。余1看第1位，余2看第2位，余0看循环节的最后一位。'}}] },

/* ── MD 중등 W9(중2 식의 계산) 신규 5종 (2026-08-25) ──
   근거: MASTER-ROADMAP.md §5(중2 W9) — 2022 개정 교육과정 중2 '식의
   계산' 성취기준 범위의 표준 연산 유형을 자체 설계(교재 원문 없음,
   교과서 문장 인용 없음). gen 함수는 engine/threads/mid2.js. unit은
   data/units/M-10.js~M-14.js. */
MD10:{ name:{ko:'지수법칙',en:'Laws of Exponents',zh:'指数法则'}, gen:'md10_expLaw', prereq:['MD5'],
  unit:'M-10',
  concept:{ko:'밑이 같은 거듭제곱끼리 곱하면 지수를 더하고, 거듭제곱을 다시 거듭제곱하면 지수를 곱하고, 나누면 지수를 뺍니다. 밑은 그대로 두고 지수만 계산하는 게 핵심입니다.',
    en:'Multiplying same-base powers adds the exponents; a power of a power multiplies them; dividing subtracts them. The key is that the base stays put — only the exponents get computed.',
    zh:'同底数幂相乘指数相加，幂的乘方指数相乘，相除指数相减。关键是底数不变，只对指数进行运算。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'곱셈(aᵐ×aⁿ)',en:'multiplication (aᵐ×aⁿ)',zh:'乘法(aᵐ×aⁿ)'},params:{mode:'mul'}},
          {id:2,label:{ko:'거듭제곱의 거듭제곱',en:'power of a power',zh:'幂的乘方'},params:{mode:'pow'},
           concept:{ko:'거듭제곱을 다시 거듭제곱하면 지수끼리 곱합니다 — (c²)³은 c가 2개씩 세 묶음이라 c⁶입니다.',
             en:'A power raised to a power multiplies the exponents: (c²)³ is three groups of two c’s, so c⁶.',
             zh:'幂的乘方是指数相乘：(c²)³是三组各2个c，所以是c⁶。'}},
          {id:3,label:{ko:'나눗셈(aᵐ÷aⁿ)',en:'division (aᵐ÷aⁿ)',zh:'除法(aᵐ÷aⁿ)'},params:{mode:'div'},
           concept:{ko:'밑이 같은 거듭제곱끼리 나누면 지수를 뺍니다 — n¹³÷n⁸은 n⁵입니다.',
             en:'Dividing powers with the same base subtracts the exponents: n¹³÷n⁸ = n⁵.',
             zh:'同底数幂相除，指数相减：n¹³÷n⁸=n⁵。'}},
          {id:4,label:{ko:'밑 혼합(실전)',en:'mixed rules (main)',zh:'混合法则(实战)'},params:{mode:'combo'},
           concept:{ko:'한 식에 곱셈·나눗셈·거듭제곱이 섞여도 앞에서부터 지수만 더하고 빼고 곱하면 됩니다 — (a⁴)²×a⁸은 8+8=16이라 a¹⁶입니다.',
             en:'When one expression mixes multiplying, dividing and powers, just add, subtract and multiply the exponents in order: (a⁴)²×a⁸ is 8+8=16, so a¹⁶.',
             zh:'一个式子里乘、除、乘方混在一起时，按顺序对指数加减乘即可：(a⁴)²×a⁸是8+8=16，所以是a¹⁶。'}},
          /* 2026-09-21 — 디딤돌 개념연산 중2-1A 대조(p.66)로 찾은 구멍: (ab)ⁿ=aⁿbⁿ.
             이 스레드가 문자를 하나만 쓰는 관례라 두 번째 문자 대신 계수로 분배를
             가르친다 — (c·x^m)^n = cⁿ·x^(mn). */
          {id:5,label:{ko:'지수의 분배',en:'distributing an exponent',zh:'指数的分配'},params:{mode:'distribute'},
           concept:{ko:'괄호 전체를 거듭제곱하면 지수가 계수와 문자 둘 다에 나뉘어 곱해집니다 — 계수는 그 자체를 거듭제곱하고, 문자는 지수끼리 곱합니다. (2x²)³을 2x⁶으로 잘못 계산하지 않도록 주의합니다(계수도 반드시 세제곱).',
             en:'Raising the whole bracket to a power distributes it to both the coefficient and the letter — the coefficient is itself raised to the power, the letter multiplies exponents. Watch not to miscompute (2x²)³ as 2x⁶ — the coefficient must be cubed too.',
             zh:'括号整体乘方时，指数会分别分配给系数和字母——系数本身要乘方，字母的指数相乘。注意别把(2x²)³算成2x⁶——系数也必须立方。'}}] },

MD11:{ name:{ko:'단항식의 곱셈과 나눗셈',en:'Multiplying & Dividing Monomials',zh:'单项式的乘除法'}, gen:'md11_monoMulDiv', prereq:['MD10','MD4'],
  unit:'M-11',
  concept:{ko:'단항식끼리 곱하거나 나눌 땐 계수는 계수끼리, 문자는 지수법칙으로 각각 따로 계산합니다.',
    en:'Multiplying or dividing monomials: combine the coefficients separately from the letters (which use the exponent law).',
    zh:'单项式相乘或相除时，系数归系数，字母用指数法则，分别独立计算。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'곱셈(연습)',en:'multiplication (practice)',zh:'乘法(练习)'},params:{mode:'mul'}},
          {id:2,label:{ko:'나눗셈',en:'division',zh:'除法'},params:{mode:'div'},
           concept:{ko:'단항식의 나눗셈은 계수는 계수끼리 나누고 문자는 지수를 뺍니다 — 8x⁴÷(−x³)은 8÷(−1)=−8, 4−3=1이라 −8x입니다.',
             en:'Dividing monomials divides the coefficients and subtracts the exponents: 8x⁴÷(−x³) is 8÷(−1)=−8 and 4−3=1, giving −8x.',
             zh:'单项式相除：系数相除、指数相减——8x⁴÷(−x³)是8÷(−1)=−8、4−3=1，得−8x。'}},
          {id:3,label:{ko:'세 단항식 곱나눗 혼합(실전)',en:'three-monomial × ÷ mix (main)',zh:'三个单项式乘除混合(实战)'},params:{mode:'chain'},
           concept:{ko:'셋 이상이 섞여도 앞에서부터 차례로 합니다. 계수는 계수끼리, 지수는 곱하면 더하고 나누면 뺍니다 — −5x²×2x³÷10x⁴는 −x입니다.',
             en:'With three or more, work left to right: coefficients with coefficients, exponents added when multiplying and subtracted when dividing — −5x²×2x³÷10x⁴ is −x.',
             zh:'三个以上也从左往右依次算：系数归系数，指数相乘时相加、相除时相减——−5x²×2x³÷10x⁴是−x。'}},
          {id:4,label:{ko:'□ 안의 단항식 구하기',en:'find the missing monomial',zh:'求方框中的单项式'},params:{mode:'solveBox'},
           concept:{ko:'□를 하나의 단항식으로 보고 역연산합니다. A×□=B이면 □=B÷A, A÷□=B이면 □=A÷B입니다. 곱셈과 나눗셈이 함께 있으면 □만 남긴 뒤 계수와 x·y의 지수를 따로 계산합니다.',
             en:'Treat the box as one monomial and use inverse operations. From A×□=B, □=B÷A; from A÷□=B, □=A÷B. Then handle the coefficient and each variable exponent separately.',
             zh:'把方框看作一个单项式并用逆运算。A×□=B时□=B÷A，A÷□=B时□=A÷B；再分别计算系数和各字母的指数。'}},
          {id:5,label:{ko:'넓이·부피 공식에 대입(집중)',en:'substitute into area and volume formulas',zh:'代入面积和体积公式'},params:{mode:'formulaSub'},
           concept:{ko:'도형의 넓이·부피 공식을 먼저 쓰고, 주어진 길이의 단항식을 그대로 대입합니다. 그다음 계수는 곱하고 같은 문자의 지수는 더합니다. 1/2이나 1/3도 계수 계산에 포함합니다.',
             en:'Write the supplied area or volume formula, substitute each monomial length, then multiply coefficients and add exponents of like variables. Include 1/2 or 1/3 in the coefficient calculation.',
             zh:'先写出给出的面积或体积公式，代入各边的单项式，再乘系数、加同字母指数；1/2或1/3也要计入系数运算。'}}] },

MD12:{ name:{ko:'다항식의 덧셈과 뺄셈',en:'Adding & Subtracting Polynomials',zh:'多项式的加减法'}, gen:'md12_polyAddSub', prereq:['MD2'],
  unit:'M-12',
  concept:{ko:'문자와 차수가 같은 항(동류항)끼리만 계수를 더하거나 뺍니다. 괄호 앞에 −가 있으면 괄호 안 모든 항의 부호가 바뀝니다.',
    en:'Only like terms — same letter, same power — combine by adding or subtracting coefficients. A minus before the brackets flips every sign inside.',
    zh:'只有同类项(字母和次数都相同)才能相加减系数。括号前是−号，里面每一项都要变号。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'일차식 두 개(연습)',en:'two linear expressions (practice)',zh:'两个一次式(练习)'},params:{mode:'linear'}},
          {id:2,label:{ko:'이차식 두 개',en:'two quadratic expressions',zh:'两个二次式'},params:{mode:'quadratic'},
           concept:{ko:'x²항은 x²항끼리, x항은 x항끼리, 상수는 상수끼리 따로 계산합니다. 차수가 다른 항은 절대 섞이지 않습니다.',
             en:'Combine x² terms with x² terms, x terms with x terms and constants with constants — terms of different degree never mix.',
             zh:'x²项与x²项、x项与x项、常数与常数分别计算——次数不同的项绝不合并。'}},
          {id:3,label:{ko:'괄호 앞 부호 바꾸기(실전)',en:'sign flip before brackets (main)',zh:'括号前变号(实战)'},params:{mode:'brackets'},
           concept:{ko:'괄호 앞에 −가 있으면 괄호 안 **모든 항**의 부호가 바뀝니다 — −(−6x−13)은 +6x+13입니다.',
             en:'A minus in front of a bracket flips the sign of every term inside: −(−6x−13) becomes +6x+13.',
             zh:'括号前是减号时，括号里每一项都要变号：−(−6x−13)变成+6x+13。'}},
          /* 2026-09-21 — 디딤돌 개념연산 중2-1A 대조(p.88·94)로 찾은 두 구멍. */
          {id:4,label:{ko:'계수가 분수 꼴인 다항식',en:'polynomials with fraction coefficients',zh:'系数为分数的多项式'},params:{mode:'fracCoef'},
           concept:{ko:'분모의 최소공배수로 통분하고, 분자의 괄호를 푼 뒤, 동류항끼리 계산합니다 — 정수식과 순서는 같고 통분이 한 단계 앞에 붙을 뿐입니다.',
             en:'Find a common denominator, expand the numerators, then combine like terms — the same order as with integer coefficients, just with one extra step up front.',
             zh:'先通分，再展开分子的括号，最后合并同类项——步骤和整数系数相同，只是前面多了通分这一步。'}},
          {id:5,label:{ko:'여러 가지 괄호가 있는 식',en:'expressions with several kinds of brackets',zh:'含多种括号的式子'},params:{mode:'nestedBrackets'},
           concept:{ko:'소괄호(  ) → 중괄호{ } → 대괄호[ ]의 순서로 안쪽부터 괄호를 풀며 동류항끼리 정리합니다. 부호가 −이면 여는 순간 안의 모든 항의 부호가 바뀝니다.',
             en:'Remove brackets from the inside out — parentheses, then braces, then square brackets — combining like terms as you go. A minus sign flips every term inside the moment you open it.',
             zh:'按小括号→大括号(中括号)→方括号的顺序从内到外拆括号，边拆边合并同类项。前面是负号，打开的瞬间里面每一项都要变号。'}}] },

MD13:{ name:{ko:'단항식과 다항식의 곱셈·나눗셈',en:'Multiplying & Dividing Monomials and Polynomials',zh:'单项式与多项式的乘除法'}, gen:'md13_monoTimesPoly', prereq:['MD11','MD12'],
  unit:'M-13',
  concept:{ko:'곱셈은 괄호 앞의 단항식을 안의 모든 항에 하나씩 곱하고, 나눗셈은 다항식의 모든 항을 같은 단항식으로 하나씩 나눕니다. 계수와 같은 문자의 지수를 따로 계산합니다.',
    en:'For multiplication, multiply the outside monomial into every term. For division, divide every polynomial term by the same monomial. Work with coefficients and exponents of like variables separately.',
    zh:'乘法把括号外的单项式逐项乘进去；除法把多项式每一项都除以同一个单项式。系数和同字母指数分别计算。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'이항식 전개(연습)',en:'binomial expansion (practice)',zh:'二项式展开(练习)'},params:{mode:'binomial'}},
          {id:2,label:{ko:'문자가 있는 단항식으로 전개',en:'expand with a letter-bearing monomial',zh:'用带字母的单项式展开'},params:{mode:'monomialX'},
           concept:{ko:'괄호 앞의 단항식에 문자가 있으면 곱할 때 지수가 더해져 차수가 올라갑니다 — −9x×(−7x)는 63x²입니다.',
             en:'When the monomial in front carries a letter, multiplying adds the exponents and the degree goes up: −9x×(−7x) is 63x².',
             zh:'括号前的单项式带字母时，相乘要把指数相加、次数升高：−9x×(−7x)是63x²。'}},
          {id:3,label:{ko:'삼항식 전개(실전)',en:'trinomial expansion (main)',zh:'三项式展开(实战)'},params:{mode:'trinomial'},
           concept:{ko:'항이 셋이어도 하나씩 빠짐없이 곱합니다. 마지막 상수항까지 곱해야 끝입니다 — 2(−x²−3x+11)은 −2x²−6x+22입니다.',
             en:'With three terms inside, multiply each one — including the constant at the end: 2(−x²−3x+11) is −2x²−6x+22.',
             zh:'括号里有三项时要逐项相乘，最后的常数项也不能漏：2(−x²−3x+11)是−2x²−6x+22。'}},
          {id:4,label:{ko:'다항식÷단항식(기본)',en:'polynomial ÷ monomial (basic)',zh:'多项式÷单项式(基础)'},params:{mode:'divideBinomial'},
           concept:{ko:'다항식을 단항식으로 나눌 때에는 **모든 항을 하나씩 같은 단항식으로 나눕니다.** 계수는 나누고, 같은 문자의 지수는 뺍니다 — (12x²−8xy)÷4x=3x−2y입니다.',
             en:'To divide a polynomial by a monomial, divide every term by that same monomial. Divide coefficients and subtract exponents of like variables: (12x²−8xy)÷4x=3x−2y.',
             zh:'多项式除以单项式时，每一项都要除以同一个单项式。系数相除，同字母指数相减：(12x²−8xy)÷4x=3x−2y。'}},
          {id:5,label:{ko:'분수 계수 단항식으로 나누기',en:'divide by a fractional monomial',zh:'除以分数系数单项式'},params:{mode:'divideFraction'},
           concept:{ko:'분수 계수의 단항식으로 나눌 때에는 그 단항식의 **역수를 곱셈으로 바꾸어** 모든 항에 분배합니다. 부호와 분수의 분자·분모를 먼저 확인합니다.',
             en:'When the divisor is a fractional monomial, multiply by its reciprocal and distribute it to every term. Check the sign, numerator, and denominator first.',
             zh:'除数是分数系数单项式时，要改成乘它的倒数，再分配到每一项。先确认符号和分子、分母。'}},
          {id:6,label:{ko:'세 항÷두 문자 단항식(집중)',en:'three terms ÷ a two-variable monomial',zh:'三项÷二元单项式(集中)'},params:{mode:'divideTrinomial'},
           concept:{ko:'세 항도 빠짐없이 각각 나눕니다. x와 y를 따로 보고 지수를 빼며, 나누는 단항식이 음수이면 **각 항의 부호가 모두 바뀌는지** 확인합니다.',
             en:'Divide all three terms without skipping any. Track x and y separately, subtract their exponents, and if the divisor is negative check that every quotient sign changes.',
             zh:'三项都要逐项相除。x、y分别看指数相减；除数为负时，要检查每一项的商是否都变号。'}}] },

MD14:{ name:{ko:'등식의 변형',en:'Transforming Equations',zh:'等式的变形'}, gen:'md14_isolateX', prereq:['MD2'],
  unit:'M-14',
  concept:{ko:'등호를 넘어가는 항은 부호가 바뀝니다(이항). 계수가 있으면 상수항을 먼저 이항한 뒤 그 계수로 양변을 나눠 x를 구합니다.',
    en:'A term crossing the equals sign flips its sign (transposition). With a coefficient, transpose the constant first, then divide both sides by that coefficient to find x.',
    zh:'跨过等号的项要变号(移项)。有系数时先移项常数，再用这个系数除以两边求出x。'},
  widgets:['missing','steps'],
  levels:[{id:1,label:{ko:'덧셈식 이항(연습)',en:'transposing addition (practice)',zh:'加法移项(练习)'},params:{mode:'add'}},
          {id:2,label:{ko:'뺄셈식 이항',en:'transposing subtraction',zh:'减法移项'},params:{mode:'sub'},
           concept:{ko:'빼고 있던 수를 넘기면 더하기가 됩니다 — x−25=−12는 x=−12+25입니다.',
             en:'A number that was being subtracted becomes an addition when it crosses over: x−25=−12 gives x=−12+25.',
             zh:'原来在减的数移到另一边就变成加：x−25=−12得x=−12+25。'}},
          {id:3,label:{ko:'이항→나눗셈 완주(실전)',en:'transpose then divide (main)',zh:'移项后除法求解(实战)'},params:{mode:'solve'},
           concept:{ko:'상수항을 먼저 넘기고, 남은 x의 계수로 양변을 나누면 끝입니다 — 6x−10=−58은 6x=−48, x=−8입니다.',
             en:'Move the constant first, then divide both sides by the coefficient of x: 6x−10=−58 gives 6x=−48 and x=−8.',
             zh:'先把常数项移过去，再用x的系数除两边：6x−10=−58得6x=−48，x=−8。'}}] },

/* ── MD 중등 W10(중3 제곱근과 실수 · 다항식의 곱셈과 인수분해) 신규
   6종 (2026-08-25) ── 근거: MASTER-ROADMAP.md §5(중3 W10). gen 함수는
   engine/threads/mid3.js. unit은 data/units/M-15.js~M-20.js. */
MD15:{ name:{ko:'제곱근의 값과 대소 관계',en:'Square Root Values & Comparison',zh:'平方根的值与大小比较'}, gen:'md15_sqrtValue', prereq:['MD1'],
  unit:'M-15',
  concept:{ko:'완전제곱수의 제곱근은 정수입니다. 제곱근을 다시 제곱하면 근호가 사라지고, 어떤 수의 제곱을 다시 제곱근으로 풀면 그 수의 절댓값이 나옵니다(결과는 항상 0 이상).',
    en:'The square root of a perfect square is an integer. Squaring a root cancels it, and the square root of a squared number gives its absolute value (the result is always nonnegative).',
    zh:'完全平方数的平方根是整数。平方根再平方，根号消失；某数的平方再开平方，得到该数的绝对值(结果永远不小于0)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'완전제곱수의 제곱근(연습)',en:'roots of perfect squares (practice)',zh:'完全平方数的平方根(练习)'},params:{mode:'perfect'}},
          {id:2,label:{ko:'(√a)²=a',en:'(√a)²=a',zh:'(√a)²=a'},params:{mode:'squareOfSqrt'},
           concept:{ko:'제곱근을 다시 제곱하면 근호가 그대로 사라집니다 — (√111)²은 111입니다.',
             en:'Squaring a square root cancels the radical outright: (√111)² is 111.',
             zh:'把平方根再平方，根号直接消失：(√111)²就是111。'}},
          {id:3,label:{ko:'√(a²)=|a|(실전)',en:'√(a²)=|a| (main)',zh:'√(a²)=|a|(实战)'},params:{mode:'absValue'},
           concept:{ko:'제곱한 것을 다시 제곱근으로 풀면 **절댓값**이 나옵니다 — √((−18)²)은 −18이 아니라 18입니다.',
             en:'Taking the square root of a square gives the absolute value: √((−18)²) is 18, not −18.',
             zh:'对平方再开平方得到的是绝对值：√((−18)²)是18，不是−18。'}},
          {id:4,label:{ko:'양의 제곱근 대소 비교',en:'compare positive square roots',zh:'比较正平方根'},params:{mode:'comparePositive'},
           concept:{ko:'양의 제곱근끼리는 근호 안의 수를 정확히 비교하면 방향이 같습니다. 분수도 통분하거나 교차곱해 비교하고, 값이 같을 수 있으므로 ① 왼쪽 큼 ② 같음 ③ 오른쪽 큼을 모두 확인합니다.',
             en:'For nonnegative square roots, compare the radicands exactly; fractions can be compared by cross multiplication. Choose 1 for left greater, 2 for equal, or 3 for right greater.',
             zh:'比较非负平方根时，准确比较根号内的数；分数可用交叉相乘。左大选1，相等选2，右大选3。'}},
          {id:5,label:{ko:'음의 제곱근 대소 비교',en:'compare negative square roots',zh:'比较负平方根'},params:{mode:'compareNegative'},
           concept:{ko:'두 수가 모두 음수이면 절댓값이 큰 쪽이 더 작습니다. 근호 안을 비교한 뒤 **부등호 방향을 한 번 뒤집는 것**이 핵심입니다.',
             en:'When both numbers are negative, the one with the larger absolute value is smaller. Compare the radicands, then reverse the direction once.',
             zh:'两个数都是负数时，绝对值大的反而小。先比较根号内，再把不等号方向翻转一次。'}},
          {id:6,label:{ko:'유리수·제곱근 혼합 비교(실전)',en:'rational and radical comparison (main)',zh:'有理数与根式混合比较(实战)'},params:{mode:'compareMixed'},
           concept:{ko:'먼저 부호를 확인합니다. 같은 부호이면 절댓값을 제곱해 분수의 **교차곱**으로 정확히 비교하고, 둘 다 음수일 때만 방향을 뒤집습니다. 소수도 분수로 바꾸면 반올림 없이 판정할 수 있습니다.',
             en:'Check signs first. With the same sign, square the absolute values and compare the fractions exactly; reverse only when both numbers are negative. Convert decimals to fractions to avoid rounding.',
             zh:'先看符号。同号时平方绝对值并准确比较分数；只有两数都为负时才反向。把小数化成分数可避免近似误差。'}}] },

MD16:{ name:{ko:'근호의 정리',en:'Simplifying Radicals',zh:'根号的化简'}, gen:'md16_simplifyRadical', prereq:['MD15','DV7'],
  unit:'M-16',
  concept:{ko:'근호 안의 수를 소인수분해해 완전제곱 인수를 찾으면, 그 인수를 근호 밖으로 꺼내 더 간단한 꼴로 정리할 수 있습니다 — 같은 소인수가 두 번(짝) 만나면 밖으로 나온다는 점에서 "2와 5가 만나 10이 되는" 계보와 같은 이치입니다.',
    en:'Factor inside the root into primes to find a perfect-square factor, and you can pull it outside for a simpler form — the same logic as "2 and 5 meeting to make 10," since a prime pairing up (appearing twice) is what steps outside.',
    zh:'对根号内的数进行质因数分解，找出完全平方因数，就能把它提到根号外化简——同一质因数配对(出现两次)就能走出根号，这和"2与5相遇变成10"是同样的道理。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'근호 정리(연습)',en:'simplify radicals (practice)',zh:'根号化简(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'더 큰 수(실전)',en:'bigger numbers (main)',zh:'更大的数(实战)'},params:{mode:'wide'},
           concept:{ko:'수가 커져도 방법은 같습니다. 근호 안을 소인수분해해 짝을 이룬 소인수만 밖으로 꺼냅니다 — √152는 2²×38이라 2√38입니다.',
             en:'Bigger numbers change nothing: factor inside the radical and bring out only the primes that come in pairs — √152 is 2²×38, so 2√38.',
             zh:'数变大方法不变：把根号里分解质因数，只把成对的质因数拿出来——√152是2²×38，所以是2√38。'}},
          {id:3,label:{ko:'계수가 있는 근호',en:'radical with a coefficient',zh:'带系数的根号'},params:{mode:'withCoeff'},
           concept:{ko:'근호에서 꺼낸 수는 앞에 있던 계수와 곱합니다. 2√270은 √270=3√30이니 2×3=6, 곧 6√30입니다.',
             en:'Whatever comes out of the radical multiplies the coefficient already in front. 2√270: √270=3√30, so 2×3=6, giving 6√30.',
             zh:'从根号里拿出来的数要与原来的系数相乘。2√270中√270=3√30，所以2×3=6，即6√30。'}}] },

MD17:{ name:{ko:'제곱근의 곱셈과 나눗셈',en:'Multiplying & Dividing Square Roots',zh:'平方根的乘除法'}, gen:'md17_sqrtMulDiv', prereq:['MD16'],
  unit:'M-17',
  concept:{ko:'제곱근끼리 곱하거나 나눌 땐 근호 안의 수를 먼저 곱하거나 나눈 뒤 하나의 근호로 정리합니다. 결과가 완전제곱수가 아니면 근호 정리까지 이어서 합니다.',
    en:'Multiplying or dividing square roots: combine what\'s inside the roots first, then simplify into one root. If the result isn\'t a perfect square, keep simplifying the radical.',
    zh:'平方根相乘或相除时，先合并根号内的数，再化成一个根号。结果不是完全平方数就接着化简根号。'},
  widgets:['steps','numpad'],
  levels:[{id:1,label:{ko:'곱셈(정수로 떨어짐)',en:'multiplication (exact)',zh:'乘法(整除)'},params:{mode:'mul'}},
          {id:2,label:{ko:'나눗셈(정수로 떨어짐)',en:'division (exact)',zh:'除法(整除)'},params:{mode:'div'},
           concept:{ko:'근호끼리 나눌 땐 근호 안의 수를 먼저 나눕니다 — √200÷√8은 √25이고 5입니다.',
             en:'To divide radicals, divide what is inside first: √200÷√8 is √25, which is 5.',
             zh:'根号相除先把根号里的数相除：√200÷√8是√25，等于5。'}},
          {id:3,label:{ko:'근호가 남는 곱셈(실전)',en:'multiplication leaving a radical (main)',zh:'剩下根号的乘法(实战)'},params:{mode:'mixed'},
           concept:{ko:'곱한 뒤 근호 안이 완전제곱수가 아니면 근호 정리까지 이어서 합니다 — √3×√18은 √54이고 3√6입니다.',
             en:'If the product inside the radical is not a perfect square, go on to simplify it: √3×√18 is √54, which is 3√6.',
             zh:'相乘后根号里不是完全平方数就继续化简：√3×√18是√54，等于3√6。'}}] },

MD18:{ name:{ko:'분모의 유리화',en:'Rationalizing the Denominator',zh:'分母有理化'}, gen:'md18_rationalize', prereq:['MD17'],
  unit:'M-18',
  concept:{ko:'분모에 근호가 있으면 분자·분모에 같은 근호를 곱해 분모의 근호를 없앱니다(√a×√a=a). 분모의 근호가 아직 정리 안 됐으면 근호 정리부터 먼저 합니다.',
    en:'When the denominator has a root, multiply top and bottom by the same root to remove it (√a×√a=a). If the denominator\'s root isn\'t simplified yet, simplify it first.',
    zh:'分母有根号时，分子分母同乘相同根号来去掉分母的根号(√a×√a=a)。分母的根号还没化简就先化简。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'기본형(1/√n)',en:'basic form (1/√n)',zh:'基本型(1/√n)'},params:{level:'plain'}},
          {id:2,label:{ko:'분자에 계수가 있음',en:'numerator has a coefficient',zh:'分子有系数'},params:{level:'coef'}},
          {id:3,label:{ko:'분모부터 정리(실전)',en:'simplify denominator first (main)',zh:'先化简分母(实战)'},params:{level:'messyDenom'}}] },

MD19:{ name:{ko:'곱셈공식의 전개',en:'Expanding Multiplication Formulas',zh:'乘法公式的展开'}, gen:'md19_expandFormula', prereq:['MD13'],
  unit:'M-19',
  concept:{ko:'(x+a)(x+b)=x²+(a+b)x+ab — 가운데 항은 두 수의 합, 마지막 항은 두 수의 곱입니다. 부호가 반대인 두 수를 곱하면 가운데 항이 사라지는 합차공식(x+a)(x-a)=x²-a²이 됩니다.',
    en:'(x+a)(x+b)=x²+(a+b)x+ab — the middle term is the sum, the last term is the product. When the two numbers have opposite signs, the middle term cancels, giving the difference of squares (x+a)(x-a)=x²-a².',
    zh:'(x+a)(x+b)=x²+(a+b)x+ab——中间项是两数之和，最后一项是两数之积。两数符号相反时中间项消失，得到平方差公式(x+a)(x-a)=x²-a²。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'(x+a)(x+b) 전개(연습)',en:'expand (x+a)(x+b) (practice)',zh:'展开(x+a)(x+b)(练习)'},params:{mode:'twoFactors'}},
          {id:2,label:{ko:'(x+a)² 전개',en:'expand (x+a)²',zh:'展开(x+a)²'},params:{mode:'square'},
           concept:{ko:'같은 수를 두 번 더하니 가운데 항은 2a, 마지막은 a²입니다 — (x−27)²은 x²−54x+729입니다.',
             en:'The same number appears twice, so the middle term is 2a and the last is a²: (x−27)² is x²−54x+729.',
             zh:'同一个数出现两次，所以中间项是2a、最后是a²：(x−27)²是x²−54x+729。'}},
          {id:3,label:{ko:'합차공식(실전)',en:'difference of squares (main)',zh:'平方差公式(实战)'},params:{mode:'diffSquares'},
           concept:{ko:'부호가 반대인 두 수를 곱하면 가운데 항이 서로 지워집니다 — (x+36)(x−36)은 x²−1296입니다.',
             en:'With opposite signs the middle terms cancel: (x+36)(x−36) is x²−1296.',
             zh:'两个数符号相反时中间项互相抵消：(x+36)(x−36)是x²−1296。'}},
          /* 2026-09-21 — 디딤돌 개념연산 중3-1A 대조(p.104~114). 앞의 세 레벨은
             전부 "전개하는 법"이었고, 실제 교재는 그다음에 공식을 "쓰는 법"
             (활용)을 다섯 유형으로 가르친다. */
          {id:4,label:{ko:'수의 계산에 활용',en:'apply to arithmetic',zh:'用于数的计算'},params:{mode:'numApplication'},
           concept:{ko:'99×101이나 101²처럼 어림수(n) 기준으로 ±k만큼 떨어진 수는 공식으로 계산합니다. 101²=(100+1)²=10000+200+1=10201, 101×99=(100+1)(100−1)=10000−1=9999입니다.',
             en:'Numbers like 99×101 or 101² sit ±k from a round base n, so the formula computes them: 101²=(100+1)²=10000+200+1=10201, 101×99=(100+1)(100−1)=10000−1=9999.',
             zh:'99×101或101²这样的数离整数基准n差±k，用公式计算：101²=(100+1)²=10000+200+1=10201，101×99=(100+1)(100−1)=10000−1=9999。'}},
          {id:5,label:{ko:'근호를 포함한 식의 계산',en:'apply to radical expressions',zh:'用于含根号的式子'},params:{mode:'radicalApplication'},
           concept:{ko:'(√a+√b)(√a−√b)=a−b — 합차공식과 같은 자리에서 근호가 사라집니다. (√3+√2)(√3−√2)=3−2=1입니다.',
             en:'(√a+√b)(√a−√b)=a−b — the roots vanish in the same spot as the difference of squares: (√3+√2)(√3−√2)=3−2=1.',
             zh:'(√a+√b)(√a−√b)=a−b——和平方差公式同一个位置，根号消失：(√3+√2)(√3−√2)=3−2=1。'}},
          {id:6,label:{ko:'분모의 유리화(켤레)',en:'rationalize with a conjugate',zh:'用共轭式分母有理化'},params:{mode:'rationalizeConjugate'},
           concept:{ko:'분모가 두 근호의 합 또는 차로 되어 있으면, 부호만 반대인 켤레를 분자·분모에 곱해 유리화합니다 — (a+b)(a−b)=a²−b²이 분모의 근호를 없앱니다.',
             en:'When the denominator is a sum or difference of two roots, multiply top and bottom by the conjugate (opposite sign) to rationalize — (a+b)(a−b)=a²−b² clears the root.',
             zh:'分母是两个根号的和或差时，用符号相反的共轭式乘分子分母来有理化——(a+b)(a−b)=a²−b²能去掉分母的根号。'}},
          {id:7,label:{ko:'곱셈공식의 변형',en:'rearranging the formula',zh:'乘法公式的变形'},params:{mode:'formulaVariant'},
           concept:{ko:'등식의 성질로 곱셈공식을 이항하면 새 식을 만들 수 있습니다 — a²+b²=(a+b)²−2ab처럼, 외우지 말고 그때그때 이항해서 씁니다.',
             en:'Rearranging a multiplication formula by moving terms across the equals sign creates a new identity — a²+b²=(a+b)²−2ab. Do not memorize it; derive it each time.',
             zh:'利用等式的性质把乘法公式移项就能造出新的式子——比如a²+b²=(a+b)²−2ab，不必死记，每次现场移项即可。'}},
          {id:8,label:{ko:'복잡한 식의 전개(치환)',en:'expand complex expressions by substitution',zh:'用换元展开复杂的式子'},params:{mode:'substitutionExpand'},
           concept:{ko:'항이 여러 개인 두 다항식의 공통부분을 한 문자로 치환하면 지금까지 하던 곱셈공식과 같은 손동작이 됩니다 — 전개한 뒤엔 치환한 문자를 원래 식으로 되돌립니다.',
             en:'Substituting the common part of two multi-term polynomials with one letter turns it into the same multiplication-formula move as before — after expanding, substitute the original expression back in.',
             zh:'把两个多项多项式的公共部分换成一个字母，就变成之前学过的同一种乘法公式动作——展开后再把字母换回原来的式子。'}}] },

MD20:{ name:{ko:'인수분해 기초',en:'Basic Factoring',zh:'因式分解基础'}, gen:'md20_factorBasic', prereq:['MD19'],
  unit:'M-20',
  concept:{ko:'x²+bx+c=(x+p)(x+q)에서 더해서 b, 곱해서 c가 되는 두 수 p,q를 찾습니다 — 곱셈공식을 거꾸로 읽는 것과 같습니다. 곱이 음수면 부호가 반대인 두 수를 찾습니다.',
    en:'For x²+bx+c=(x+p)(x+q), find two numbers p,q that add to b and multiply to c — the same as reading a multiplication formula backward. If the product is negative, look for opposite-sign numbers.',
    zh:'在x²+bx+c=(x+p)(x+q)中，找相加得b、相乘得c的两个数p、q——就是把乘法公式反着读。乘积为负就找符号相反的两个数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'모두 양수(연습)',en:'all positive (practice)',zh:'全为正数(练习)'},params:{level:'positive'}},
          {id:2,label:{ko:'부호 섞임(실전)',en:'mixed signs (main)',zh:'符号混合(实战)'},params:{level:'mixed'}},
          /* 2026-09-21 — MD19가 전개를 세 꼴로 가르치는데 역방향이 한 꼴뿐이었다.
             완전제곱·합차는 같은 손동작(공식 거꾸로 읽기)이라 레벨로 붙이고,
             공통인수·십자곱셈은 묶어내거나 대각선으로 곱하는 다른 손동작이라 뒤에 둔다. */
          {id:3,label:{ko:'완전제곱식',en:'perfect square',zh:'完全平方式'},params:{mode:'square'},
           concept:{ko:'마지막 항이 제곱수이고 가운데 항이 그 제곱근의 2배면 완전제곱식입니다 — x²+14x+49는 √49=7이고 2×7=14이니 (x+7)²입니다.',
             en:'When the last term is a square and the middle term is twice its square root, it is a perfect square: x²+14x+49 has √49=7 and 2×7=14, so it is (x+7)².',
             zh:'最后一项是平方数、中间项是它平方根的2倍时就是完全平方式：x²+14x+49中√49=7、2×7=14，所以是(x+7)²。'}},
          {id:4,label:{ko:'합차 인수분해',en:'difference of squares',zh:'平方差因式分解'},params:{mode:'diff'},
           concept:{ko:'가운데 항이 없고 제곱의 차만 남았으면 합과 차로 갈라집니다 — x²−144는 144=12²이니 (x+12)(x−12)입니다.',
             en:'No middle term and only a difference of squares means it splits into a sum and a difference: x²−144 has 144=12², so it is (x+12)(x−12).',
             zh:'没有中间项、只剩平方差时就拆成和与差：x²−144中144=12²，所以是(x+12)(x−12)。'}},
          {id:5,label:{ko:'공통인수 묶어내기',en:'pull out the common factor',zh:'提取公因数'},params:{mode:'common'},
           concept:{ko:'세 항에 공통인수가 있으면 먼저 묶어냅니다. 묶어내고 나면 안쪽은 지금까지 하던 x²+bx+c입니다 — 3x²+15x+18은 3(x²+5x+6)이고 3(x+2)(x+3)입니다.',
             en:'If all three terms share a factor, pull it out first; what is left inside is the same x²+bx+c as before — 3x²+15x+18 is 3(x²+5x+6), which is 3(x+2)(x+3).',
             zh:'三项有公因数就先提取，剩下的括号里还是原来的x²+bx+c——3x²+15x+18是3(x²+5x+6)，即3(x+2)(x+3)。'}},
          {id:6,label:{ko:'x²의 계수가 1이 아닐 때(십자곱셈)',en:'leading coefficient ≠ 1 (cross method)',zh:'x²系数不为1时(十字相乘)'},params:{mode:'cross'},
           concept:{ko:'묶어낼 공통인수가 없으면 대각선으로 곱해 더합니다. 2x²+5x+3은 앞이 2x와 x, 뒤가 3과 1이고 2×1+3=5라 (2x+3)(x+1)입니다.',
             en:'With no common factor to pull out, cross-multiply and add: for 2x²+5x+3 the fronts are 2x and x, the backs are 3 and 1, and 2×1+3=5, so it is (2x+3)(x+1).',
             zh:'没有公因数可提取时就交叉相乘再相加：2x²+5x+3的前项是2x和x、后项是3和1，2×1+3=5，所以是(2x+3)(x+1)。'}}] },

/* ── MD83 — 제곱근의 덧셈과 뺄셈 ── 2026-09-21 추가. 디딤돌 개념연산 중3-1A
   대조(p.68~78)로 찾은 구멍 — MD15~18이 "정리하는 법"만 가르치고 "더하거나
   빼는 법"이 없었다. 번호가 82 다음이 아니라 83인 이유는 M-83 주석 참조. */
MD83:{ name:{ko:'제곱근의 덧셈과 뺄셈',en:'Adding & Subtracting Square Roots',zh:'平方根的加减法'}, gen:'md83_radicalAddSub', prereq:['MD16','MD17'],
  unit:'M-83',
  concept:{ko:'근호 안의 수가 같으면 계수끼리만 더하거나 뺍니다 — 다항식의 동류항 정리와 같은 규칙입니다. 달라 보여도 먼저 근호를 정리하면 같아지는 경우가 많습니다.',
    en:'When the number under the root matches, only the coefficients add or subtract — the same rule as combining like terms. Even when the roots look different, simplifying first often reveals a match.',
    zh:'根号内的数相同时，只把系数相加或相减——和多项式合并同类项是同一条规则。看起来不同的根号，先化简往往也会相同。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'근호 안이 같을 때(기본)',en:'same root (practice)',zh:'根号内相同(练习)'},params:{mode:'sameRadicand'}},
          {id:2,label:{ko:'정리한 뒤 결합(실전)',en:'simplify, then combine (main)',zh:'先化简再合并(实战)'},params:{mode:'simplifyThenCombine'},
           concept:{ko:'근호 안이 달라 보여도 먼저 정리하면 같아질 수 있습니다 — √12+√3은 √12=2√3으로 정리해야 2√3+√3=3√3이 됩니다.',
             en:'Roots that look different can match after simplifying — √12+√3 needs √12=2√3 first, then 2√3+√3=3√3.',
             zh:'看起来不同的根号，化简后可能相同——√12+√3要先把√12化简成2√3，才能得到2√3+√3=3√3。'}},
          {id:3,label:{ko:'세 항 결합',en:'combining three terms',zh:'三项合并'},params:{mode:'threeTerm'},
           concept:{ko:'근호 안의 수가 모두 같으면, 세 항이어도 계수끼리 순서대로 더하거나 뺍니다 — m√a+n√a−l√a=(m+n−l)√a입니다.',
             en:'When all three terms share the same root, combine the coefficients left to right just as with two — m√a+n√a−l√a=(m+n−l)√a.',
             zh:'根号内的数都相同时，三项也从左到右把系数相加或相减——m√a+n√a−l√a=(m+n−l)√a。'}},
          {id:4,label:{ko:'분배법칙',en:'the distributive law',zh:'分配律'},params:{mode:'distribute'},
           concept:{ko:'√a(√b±√c)=√ab±√ac — 다항식의 분배법칙과 같은 자리입니다. √2(√3+√5)는 √6+√10입니다.',
             en:'√a(√b±√c)=√ab±√ac — the same spot as the distributive law for polynomials: √2(√3+√5) is √6+√10.',
             zh:'√a(√b±√c)=√ab±√ac——和多项式的分配律是同一个位置：√2(√3+√5)是√6+√10。'}},
          {id:5,label:{ko:'분모의 유리화가 포함된 혼합 계산',en:'mixed calculation with rationalizing',zh:'含分母有理化的混合运算'},params:{mode:'rationalizeMixed'},
           concept:{ko:'분모에 근호가 있으면 먼저 유리화합니다 — 분자·분모에 분모의 근호를 곱한 뒤 정리합니다. (√2+√3)/√5는 (√10+√15)/5가 됩니다.',
             en:'If the denominator has a root, rationalize first — multiply top and bottom by that root, then simplify: (√2+√3)/√5 becomes (√10+√15)/5.',
             zh:'分母有根号时先有理化——分子分母同乘分母的根号，再化简：(√2+√3)/√5变成(√10+√15)/5。'}},
          {id:6,label:{ko:'무리수의 정수 부분과 소수 부분',en:'the integer and decimal parts of an irrational',zh:'无理数的整数部分与小数部分'},params:{mode:'intFracPart'},
           concept:{ko:'무리수는 정수 부분과 소수 부분으로 나뉩니다. √2=1.414…는 두 제곱수 1과 4 사이에 있으니(1<2<4), 정수 부분은 1이고 소수 부분은 √2−1입니다.',
             en:'An irrational number splits into an integer part and a decimal part. √2=1.414… sits between the squares 1 and 4 (1<2<4), so the integer part is 1 and the decimal part is √2−1.',
             zh:'无理数可分为整数部分和小数部分。√2=1.414…在两个平方数1和4之间(1<2<4)，所以整数部分是1，小数部分是√2−1。'}}] },

/* ── MD 고등 W11(공통수학1) 신규 10종 (2026-08-25) ── 근거:
   MASTER-ROADMAP.md §6(W11 공통수학1) — 2022 개정 교육과정 공통수학1
   '다항식'·'방정식과 부등식'·'행렬' 성취기준 범위의 표준 연산 유형을
   자체 설계(교과서 문장 인용 없음). 집합·명제·경우의 수는 비연산
   단원이라 제외(작업지시). gen 함수는 engine/threads/mid4.js. unit은
   data/units/M-21.js~M-30.js. 2022 개정 과목명 준수 — "고1" 표기 없음. */
MD21:{ name:{ko:'다항식의 곱셈과 나눗셈',en:'Multiplying & Dividing Polynomials',zh:'多项式的乘除法'}, gen:'md21_polyMulDiv', prereq:['MD13'],
  unit:'M-21',
  concept:{ko:'두 다항식을 곱할 땐 괄호를 각각 분배해 같은 차수끼리 모으고, 나눌 땐 조립제법으로 k를 곱하고 다음 계수를 더하는 걸 반복합니다.',
    en:'To multiply two polynomials, distribute both brackets and collect like-degree terms; to divide, use synthetic division — multiply by k and add the next coefficient, repeatedly.',
    zh:'两个多项式相乘时，分别展开括号后合并同类项；相除时用综合除法——反复乘以k再加上下一个系数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'이항식×이항식(연습)',en:'binomial × binomial (practice)',zh:'二项式×二项式(练习)'},params:{mode:'mul'}},
          {id:2,label:{ko:'조립제법 나눗셈',en:'synthetic division',zh:'综合除法'},params:{mode:'div'},
           concept:{ko:'조립제법은 나누는 수의 k를 곱해 다음 계수에 더하는 것을 되풀이합니다. 마지막에 남는 수가 나머지입니다 — (6x²−12x−10)÷(x−3)은 몫 6x+6, 나머지 8입니다.',
             en:'Synthetic division repeats one move: multiply by k and add it to the next coefficient. The last number left is the remainder — (6x²−12x−10)÷(x−3) gives 6x+6 remainder 8.',
             zh:'综合除法就是反复"乘以k再加到下一个系数"，最后剩下的数是余数——(6x²−12x−10)÷(x−3)商6x+6、余8。'}},
          {id:3,label:{ko:'이항식×삼항식(실전, 4다칸)',en:'binomial × trinomial (main, 4 slots)',zh:'二项式×三项式(实战，4格)'},params:{mode:'mulTri'},
           concept:{ko:'이항식의 두 항을 삼항식의 세 항에 각각 곱하면 여섯 개가 나옵니다. 같은 차수끼리 모으면 네 자리로 정리됩니다.',
             en:'Multiplying two terms by three terms gives six products; collect the like degrees and four terms remain.',
             zh:'二项式的两项分别乘三项式的三项得到六个乘积，把同次项合并后剩下四项。'}}] },

MD22:{ name:{ko:'곱셈공식의 확장',en:'Expanding Multiplication Formulas',zh:'乘法公式的展开'}, gen:'md22_cubeFormula', prereq:['MD19'],
  unit:'M-22', lineage:['place-magic'],
  concept:{ko:'(x+a)³ = x³+3ax²+3a²x+a³ — 가운데 두 항은 3배, 마지막은 세제곱입니다. 합·차의 세제곱 공식 x³±a³ = (x±a)(x²∓ax+a²)도 같은 분배 원리입니다.',
    en:'(x+a)³ = x³+3ax²+3a²x+a³ — the middle two terms are tripled, the last is cubed. The sum/difference-of-cubes formula x³±a³=(x±a)(x²∓ax+a²) follows the same distributive idea.',
    zh:'(x+a)³ = x³+3ax²+3a²x+a³——中间两项各乘3，最后一项是立方。立方和差公式x³±a³=(x±a)(x²∓ax+a²)也是同样的分配原理。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'(x+a)³ 전개(연습)',en:'expand (x+a)³ (practice)',zh:'展开(x+a)³(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'a가 음수(실전 준비)',en:'a is negative',zh:'a为负数'},params:{mode:'signed'},
           concept:{ko:'a가 음수여도 공식은 그대로입니다. 3a²은 양수, a³은 음수가 되니 부호가 번갈아 나옵니다 — (x−14)³은 x³−42x²+588x−2744입니다.',
             en:'The formula does not change when a is negative: 3a² stays positive while a³ turns negative, so the signs alternate — (x−14)³ is x³−42x²+588x−2744.',
             zh:'a是负数时公式不变：3a²为正、a³为负，所以符号交替出现——(x−14)³是x³−42x²+588x−2744。'}},
          {id:3,label:{ko:'합·차의 세제곱 공식(실전)',en:'sum/difference of cubes (main)',zh:'立方和差公式(实战)'},params:{mode:'sumCubeFormula'},
           concept:{ko:'(x−a)(x²+ax+a²)를 전개하면 가운데가 모두 지워지고 x³−a³만 남습니다 — (x−4)(x²+4x+16)은 x³−64입니다.',
             en:'Expanding (x−a)(x²+ax+a²) cancels everything in the middle and leaves x³−a³: (x−4)(x²+4x+16) is x³−64.',
             zh:'展开(x−a)(x²+ax+a²)时中间全部抵消，只剩x³−a³：(x−4)(x²+4x+16)是x³−64。'}}] },

MD23:{ name:{ko:'항등식과 미정계수법',en:'Identities & Undetermined Coefficients',zh:'恒等式与待定系数法'}, gen:'md23_identity', prereq:['MD12'],
  unit:'M-23',
  concept:{ko:'모든 x에서 항상 성립하는 식(항등식)이면 양변의 x계수끼리·상수항끼리 같습니다. 괄호가 있으면 먼저 전개해서 정리한 뒤 비교합니다.',
    en:'If an equation holds for every x (an identity), the x-coefficients on both sides match, and so do the constants. Expand any brackets first, then compare.',
    zh:'如果对任意x都成立(恒等式)，两边x的系数相等，常数项也相等。有括号就先展开整理，再比较。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'계수 직접 비교(연습)',en:'direct coefficient match (practice)',zh:'系数直接比较(练习)'},params:{mode:'direct'}},
          {id:2,label:{ko:'전개 후 비교',en:'expand then compare',zh:'展开后比较'},params:{mode:'expand'},
           concept:{ko:'괄호를 먼저 전개해 x항과 상수항으로 정리한 뒤, 양변의 x계수끼리·상수항끼리 짝지어 비교합니다.',
             en:'Expand the brackets first and tidy into x terms and constants, then match x coefficients with x coefficients and constants with constants.',
             zh:'先展开括号整理成x项与常数项，再把两边的x系数与x系数、常数与常数分别对应比较。'}},
          {id:3,label:{ko:'전개 후 비교(실전 범위)',en:'expand then compare (main range)',zh:'展开后比较(实战范围)'},params:{mode:'expandWide'},
           concept:{ko:'수가 커져도 같습니다. 전개한 뒤 x계수끼리 한 식, 상수항끼리 한 식 — 두 식을 함께 풀면 두 빈칸이 정해집니다.',
             en:'Bigger numbers change nothing: after expanding you get one equation from the x coefficients and one from the constants; solve them together.',
             zh:'数变大也一样：展开后x系数给一个方程、常数项给一个方程，联立求解就能定出两个空格。'}}] },

MD24:{ name:{ko:'나머지정리',en:'The Remainder Theorem',zh:'余数定理'}, gen:'md24_remainderTheorem', prereq:['MD21'],
  unit:'M-24',
  concept:{ko:'P(x)를 (x-a)로 나눈 나머지는 나눗셈을 다 하지 않아도 P(a)만 계산하면 바로 나옵니다 — 대입 한 번으로 끝나는 지름길입니다.',
    en:'The remainder of P(x) divided by (x-a) is just P(a) — no long division needed, one substitution is the whole shortcut.',
    zh:'P(x)除以(x-a)的余数，不用做完整除法，只要算P(a)就行——一次代入就是捷径。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'이차식 대입(연습)',en:'quadratic substitution (practice)',zh:'二次式代入(练习)'},params:{mode:'direct'}},
          {id:2,label:{ko:'삼차식 대입',en:'cubic substitution',zh:'三次式代入'},params:{mode:'directCubic'},
           concept:{ko:'삼차식도 대입 한 번이면 끝입니다. x³·x²·x 자리에 차례로 넣고 더합니다 — P(3)이면 2·27−2·9+12·3+15=87입니다.',
             en:'A cubic needs just one substitution: put the number into x³, x² and x in turn and add — P(3) gives 2·27−2·9+12·3+15 = 87.',
             zh:'三次式也只需代入一次：依次代入x³、x²、x再相加——P(3)是2·27−2·9+12·3+15=87。'}},
          {id:3,label:{ko:'나머지로 계수 역산(실전)',en:'find the coefficient from the remainder (main)',zh:'由余数反求系数(实战)'},params:{mode:'findUnknown'},
           concept:{ko:'나머지가 주어지면 P(a)를 미지수로 세워 등식을 풉니다 — P(6)=222이면 6³+6□−6=222에서 □=2입니다.',
             en:'When the remainder is given, set P(a) equal to it and solve: P(6)=222 means 6³+6□−6=222, so □=2.',
             zh:'已知余数时把P(a)列成等式再解：P(6)=222就是6³+6□−6=222，得□=2。'}}] },

MD25:{ name:{ko:'인수분해 심화',en:'Advanced Factoring',zh:'因式分解进阶'}, gen:'md25_factorAdvanced', prereq:['MD20'],
  unit:'M-25', lineage:['place-magic'],
  concept:{ko:'x³±a³ = (x±a)(x²∓ax+a²) — 합·차의 세제곱 공식을 거꾸로 읽습니다. 사차식은 x²를 t로 놓으면 t²+bt+c 꼴이 되어 다시 두 수 찾기로 돌아갑니다.',
    en:'x³±a³ = (x±a)(x²∓ax+a²) — read the sum/difference-of-cubes formula backward. For a quartic, treat x² as t to get t²+bt+c, back to finding two numbers.',
    zh:'x³±a³ = (x±a)(x²∓ax+a²)——把立方和差公式反着读。四次式把x²看成t，就变成t²+bt+c，又回到找两个数的问题。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'합의 세제곱 인수분해(연습)',en:'factor a sum of cubes (practice)',zh:'立方和的因式分解(练习)'},params:{mode:'sumCube'}},
          {id:2,label:{ko:'차의 세제곱 인수분해',en:'factor a difference of cubes',zh:'立方差的因式分解'},params:{mode:'diffCube'},
           concept:{ko:'차의 세제곱은 부호가 엇갈립니다 — x³−a³=(x−a)(x²+ax+a²)로, 앞 괄호는 빼기·뒤 괄호는 모두 더하기입니다.',
             en:'For a difference of cubes the signs cross over: x³−a³=(x−a)(x²+ax+a²) — minus in the first bracket, all plus in the second.',
             zh:'立方差的符号是交错的：x³−a³=(x−a)(x²+ax+a²)，前括号是减、后括号全是加。'}},
          {id:3,label:{ko:'치환을 이용한 사차식(실전)',en:'quartic via substitution (main)',zh:'换元法解四次式(实战)'},params:{mode:'quarticSub'},
           concept:{ko:'x²를 t로 놓으면 사차식이 t²+bt+c 꼴이 됩니다. 더해서 b, 곱해서 c인 두 수를 찾아 다시 x²로 되돌리면 끝입니다.',
             en:'Let t stand for x² and the quartic becomes t²+bt+c. Find the two numbers that add to b and multiply to c, then put x² back.',
             zh:'令t代表x²，四次式就变成t²+bt+c。找出相加得b、相乘得c的两个数，再把x²换回去即可。'}}] },

MD26:{ name:{ko:'이차방정식의 판별식',en:'The Discriminant',zh:'二次方程的判别式'}, gen:'md26_discriminant', prereq:['MD1'],
  unit:'M-26',
  concept:{ko:'근을 구하기 전에 판별식 D=b²-4ac부터 계산합니다 — D>0이면 서로 다른 두 실근, D=0이면 중근, D<0이면 실근이 없습니다. 근을 몇 개 가질지 미리 아는 정찰병입니다.',
    en:'Before finding the roots, compute the discriminant D=b²-4ac — D>0 gives two distinct roots, D=0 a repeated root, D<0 no real roots. It scouts ahead and tells you the count.',
    zh:'求根之前先算判别式D=b²-4ac——D>0是两个不同实根，D=0是重根，D<0则没有实根。它像侦察兵一样提前告诉你有几个根。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'D값 계산(연습)',en:'compute D (practice)',zh:'计算D值(练习)'},params:{mode:'value'}},
          {id:2,label:{ko:'실근의 개수 판정',en:'determine the number of roots',zh:'判定实根个数'},params:{mode:'count'},
           concept:{ko:'D의 부호만 보면 됩니다. D>0이면 두 개, D=0이면 하나(중근), D<0이면 없습니다 — 4x²+16x+16은 D=0이라 1개입니다.',
             en:'Only the sign of D matters: D>0 gives two roots, D=0 gives one (a repeated root) and D<0 gives none — 4x²+16x+16 has D=0, so one.',
             zh:'只看D的符号：D>0有两个根，D=0有一个（重根），D<0没有实根——4x²+16x+16的D=0，所以是1个。'}},
          {id:3,label:{ko:'중근 조건으로 계수 역산(실전)',en:'find the coefficient for a repeated root (main)',zh:'由重根条件反求系数(实战)'},params:{mode:'unknownK'},
           concept:{ko:'중근이 되려면 D=0이어야 합니다. b²−4ac=0에서 b를 거꾸로 구하면 부호가 둘이라 ±로 묶습니다 — x²+kx+25는 k²=100이니 ±10입니다.',
             en:'A repeated root needs D=0, so solve b²−4ac=0 for b; both signs work, so answer with ± — x²+kx+25 gives k²=100, so ±10.',
             zh:'要有重根就必须D=0，从b²−4ac=0反解b，两个符号都成立所以写成±——x²+kx+25得k²=100，即±10。'}}] },

MD27:{ name:{ko:'근과 계수의 관계',en:'Sum & Product of Roots',zh:'根与系数的关系'}, gen:'md27_rootsSumProduct', prereq:['MD26'],
  unit:'M-27', lineage:['rainbow-sum'],
  concept:{ko:'근을 직접 구하지 않아도 α+β=-b/a, αβ=c/a — 계수만 보고 두 근의 합과 곱을 바로 알 수 있습니다. α²+β²처럼 합·곱으로 바꿔 쓸 수 있는 식도 마찬가지입니다.',
    en:'Without solving for the roots, α+β=-b/a and αβ=c/a — the coefficients alone reveal the sum and product. Expressions like α²+β² that rewrite in terms of sum and product follow the same trick.',
    zh:'不用直接求根，α+β=-b/a，αβ=c/a——只看系数就能知道两根之和与积。像α²+β²这类能改写成和、积的式子也是同样的技巧。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'합과 곱(연습, a=1)',en:'sum & product (practice, a=1)',zh:'和与积(练习, a=1)'},params:{mode:'sumProduct'}},
          {id:2,label:{ko:'합과 곱(x²계수≠1)',en:'sum & product (leading coeff ≠1)',zh:'和与积(x²系数≠1)'},params:{mode:'sumProductA'},
           concept:{ko:'x²의 계수가 1이 아니어도 공식은 그대로입니다. 합은 −b/a, 곱은 c/a — 3x²−21x−45는 합 7, 곱 −15입니다.',
             en:'The formulas hold even when the x² coefficient is not 1: the sum is −b/a and the product c/a — 3x²−21x−45 gives 7 and −15.',
             zh:'x²的系数不是1时公式依然成立：和是−b/a、积是c/a——3x²−21x−45的和是7、积是−15。'}},
          {id:3,label:{ko:'α²+β² 구하기(실전)',en:'find α²+β² (main)',zh:'求α²+β²(实战)'},params:{mode:'sumSquares'},
           concept:{ko:'α²+β²은 (α+β)²−2αβ로 바꿔 쓸 수 있습니다. 근을 구하지 않고 합과 곱만으로 계산됩니다 — x²−2x−9는 2²−2(−9)=22입니다.',
             en:'Rewrite α²+β² as (α+β)²−2αβ, so the sum and product alone are enough — x²−2x−9 gives 2²−2(−9)=22.',
             zh:'α²+β²可以改写成(α+β)²−2αβ，只用和与积就能算——x²−2x−9是2²−2(−9)=22。'}}] },

MD28:{ name:{ko:'근의 공식',en:'The Quadratic Formula',zh:'求根公式'}, gen:'md28_quadraticFormula', prereq:['MD26'],
  unit:'M-28',
  concept:{ko:'x=(-b±√(b²-4ac))/(2a) — 근의 공식에 그대로 대입합니다. 답은 [p,q,r](x=(p±√q)/r) 세 정수로, 기약하지 않은 형태 그대로가 정답입니다.',
    en:'x=(-b±√(b²-4ac))/(2a) — plug straight into the quadratic formula. The answer is three integers [p,q,r] for x=(p±√q)/r, unreduced.',
    zh:'x=(-b±√(b²-4ac))/(2a)——直接代入求根公式。答案是三个整数[p,q,r]，对应x=(p±√q)/r，不用化简。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'x²계수=1(연습)',en:'leading coeff =1 (practice)',zh:'x²系数=1(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'x²계수≠1',en:'leading coeff ≠1',zh:'x²系数≠1'},params:{mode:'general'},
           concept:{ko:'x²의 계수가 1이 아니면 분모의 2a가 달라집니다. a·b·c를 그대로 공식에 넣고 기약하지 않은 형태로 씁니다 — 5x²+9x−7은 (−9±√221)/10입니다.',
             en:'When the x² coefficient is not 1, the 2a underneath changes. Put a, b and c straight into the formula and leave it unreduced — 5x²+9x−7 gives (−9±√221)/10.',
             zh:'x²的系数不是1时分母的2a随之改变。把a、b、c直接代入公式并保持未约分的形式——5x²+9x−7是(−9±√221)/10。'}},
          {id:3,label:{ko:'더 큰 범위(실전)',en:'wider range (main)',zh:'更大范围(实战)'},params:{mode:'wide'},
           concept:{ko:'수가 커져도 대입만 정확하면 됩니다. b²−4ac를 먼저 계산해 근호 안에 넣고, 분모는 2a 그대로입니다.',
             en:'Bigger numbers only need careful substitution: work out b²−4ac for under the radical and leave 2a underneath.',
             zh:'数变大只要代入准确即可：先算出b²−4ac放进根号，分母保持2a。'}}] },

MD29:{ name:{ko:'이차부등식',en:'Quadratic Inequalities',zh:'二次不等式'}, gen:'md29_quadIneq', prereq:['MD20'],
  unit:'M-29',
  concept:{ko:'(x-p)(x-q)<0의 해는 두 근 사이(p<x<q)입니다 — 두 인수의 부호가 다를 때만 곱이 음수가 되기 때문입니다. 전개된 식이면 먼저 인수분해부터 합니다.',
    en:'The solution of (x-p)(x-q)<0 lies between the two roots (p<x<q) — the product is negative only when the two factors have opposite signs. If it\'s expanded, factor first.',
    zh:'(x-p)(x-q)<0的解在两根之间(p<x<q)——只有两因式符号相反时乘积才是负。如果是展开式，先因式分解。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'인수분해된 형태(연습)',en:'already factored (practice)',zh:'已因式分解(练习)'},params:{mode:'between'}},
          {id:2,label:{ko:'전개된 형태(먼저 인수분해)',en:'expanded form (factor first)',zh:'展开式(先因式分解)'},params:{mode:'expandForm'},
           concept:{ko:'전개된 식은 먼저 인수분해해 두 근을 찾습니다. 그다음 부등호 방향대로 두 근 사이인지 바깥인지 고르면 됩니다 — x²−12x+35≤0은 5≤x≤7입니다.',
             en:'Factor the expanded form first to find the two roots, then read the inequality: between the roots or outside them — x²−12x+35≤0 gives 5≤x≤7.',
             zh:'展开形式要先因式分解找出两个根，再按不等号方向判断在两根之间还是之外——x²−12x+35≤0是5≤x≤7。'}},
          {id:3,label:{ko:'x²계수≠1(실전)',en:'leading coeff ≠1 (main)',zh:'x²系数≠1(实战)'},params:{mode:'withCoeff'},
           concept:{ko:'x²의 계수가 1이 아니면 그 수로 양변을 먼저 나눕니다. 양수로 나누면 부등호 방향은 그대로입니다 — 5x²−15x+10<0은 x²−3x+2<0과 같습니다.',
             en:'When the x² coefficient is not 1, divide both sides by it first; dividing by a positive keeps the inequality direction — 5x²−15x+10<0 is the same as x²−3x+2<0.',
             zh:'x²的系数不是1时先用它除两边；除以正数时不等号方向不变——5x²−15x+10<0与x²−3x+2<0相同。'}}] },

MD30:{ name:{ko:'행렬의 덧셈·뺄셈·곱셈',en:'Matrix Addition, Subtraction & Multiplication',zh:'矩阵的加减乘法'}, gen:'md30_matrix2x2', prereq:['MD1'],
  unit:'M-30',
  concept:{ko:'행렬의 덧셈·뺄셈은 같은 자리(성분)끼리만 계산합니다. 행렬곱은 앞 행렬의 행과 뒤 행렬의 열을 하나씩 짝지어 곱하고 더합니다. 답은 2×2 성분 4개를 순서대로 입력합니다.',
    en:'Matrix addition/subtraction works entry by entry. Matrix multiplication pairs each row of the first matrix with each column of the second, multiplies, and adds. The answer is four 2×2 entries, in order.',
    zh:'矩阵加减法只对相同位置的元素分别运算。矩阵乘法把前者的行与后者的列逐个配对相乘再相加。答案是2×2的4个元素，按顺序输入。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'덧셈·뺄셈(연습, 4다칸)',en:'addition/subtraction (practice, 4 slots)',zh:'加减法(练习，4格)'},params:{mode:'addSub'}},
          {id:2,label:{ko:'스칼라곱',en:'scalar multiplication',zh:'数乘'},params:{mode:'scalarMul'},
           concept:{ko:'스칼라곱은 밖의 수를 **네 성분 모두에** 곱합니다 — 4를 곱하면 −8은 −32, 2는 8이 됩니다.',
             en:'A scalar multiplies every one of the four entries: times 4 turns −8 into −32 and 2 into 8.',
             zh:'数乘要乘到全部四个元素上：乘4时−8变成−32、2变成8。'}},
          {id:3,label:{ko:'행렬곱(실전)',en:'matrix multiplication (main)',zh:'矩阵乘法(实战)'},params:{mode:'matMul'},
           concept:{ko:'행렬곱은 같은 자리끼리 곱하는 것이 아닙니다. 앞 행렬의 한 행과 뒤 행렬의 한 열을 차례로 곱해 더한 값이 그 자리의 성분이 됩니다.',
             en:'Matrix multiplication is not entry by entry: take a row of the first matrix and a column of the second, multiply them term by term and add — that sum is the entry.',
             zh:'矩阵乘法不是对应位置相乘：取前一个矩阵的一行与后一个矩阵的一列，逐项相乘再相加，得到的和就是那个位置的元素。'}}] },

/* ── MD 고등 W12(공통수학2) 신규 5종 (2026-08-25) ── 근거:
   MASTER-ROADMAP.md §6(W12 공통수학2) — 2022 개정 교육과정 공통수학2
   '도형의 방정식' 성취기준 범위의 표준 연산 유형을 자체 설계(교과서
   문장 인용 없음). 집합과 명제·함수(유리·무리)는 비연산/범위 밖이라
   제외(작업지시). gen 함수는 engine/threads/mid5.js. unit은
   data/units/M-31.js~M-35.js. 2022 개정 과목명 준수 — "고1" 표기 없음. */
MD31:{ name:{ko:'두 점 사이의 거리',en:'Distance Between Two Points',zh:'两点间的距离'}, gen:'md31_distance', prereq:['MD16'],
  unit:'M-31',
  concept:{ko:'두 점 사이의 거리는 가로·세로 차를 각각 제곱해 더한 뒤 제곱근을 씌웁니다(피타고라스 정리). 답은 근호 정리와 같은 [계수,근호안] 두 정수입니다.',
    en:'The distance between two points: square the horizontal and vertical differences, add, then take the square root (Pythagorean theorem). The answer is [coefficient, radicand], the same convention as simplifying radicals.',
    zh:'两点间距离：把横、纵坐标差分别平方后相加，再开平方(勾股定理)。答案是[系数,根号内]两个整数，和根号化简同一规约。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'작은 좌표(연습)',en:'small coordinates (practice)',zh:'较小坐标(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'더 큰 좌표',en:'bigger coordinates',zh:'更大坐标'},params:{mode:'wide'},
           concept:{ko:'좌표가 커져도 방법은 같습니다. 가로 차와 세로 차를 각각 제곱해 더하고 근호를 씌운 뒤 근호를 정리합니다 — (0,4)와 (6,−13)은 √(36+289)=√325=5√13입니다.',
             en:'Bigger coordinates change nothing: square the horizontal and vertical gaps, add, take the root and simplify — (0,4) to (6,−13) is √(36+289) = √325 = 5√13.',
             zh:'坐标变大方法不变：把横差与纵差分别平方相加、开方再化简——(0,4)到(6,−13)是√(36+289)=√325=5√13。'}},
          {id:3,label:{ko:'음수 좌표 위주(실전)',en:'mostly negative coordinates (main)',zh:'以负坐标为主(实战)'},params:{mode:'signed'},
           concept:{ko:'음수 좌표는 뺄 때 부호에 주의합니다. 12−(−7)=19처럼 차가 커지고, 제곱하면 부호는 사라집니다.',
             en:'With negative coordinates watch the signs when subtracting: 12−(−7)=19 makes the gap larger, and squaring removes the sign anyway.',
             zh:'坐标是负数时相减要注意符号：12−(−7)=19会让差变大，平方后符号自然消失。'}}] },

MD32:{ name:{ko:'중점과 내분점·외분점',en:'Midpoints & Division Points',zh:'中点与内分点·外分点'}, gen:'md32_midSection', prereq:['MD31'],
  unit:'M-32',
  concept:{ko:'중점은 두 좌표를 더해 2로 나눕니다. m:n으로 내분하는 점은 먼 쪽 점에 가까운 쪽 비율을 곱해 더한 뒤 (m+n)으로 나눕니다. 외분점은 분모가 (m-n)으로 바뀝니다.',
    en:'The midpoint: add the coordinates and divide by 2. A point dividing internally in ratio m:n weights each point by the far ratio, sums, and divides by (m+n). External division uses (m-n) instead.',
    zh:'中点：坐标相加除以2。按m:n内分的点，两点各按对侧比例加权求和后除以(m+n)。外分点则把分母换成(m-n)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'중점(연습)',en:'midpoint (practice)',zh:'中点(练习)'},params:{mode:'midpoint'}},
          {id:2,label:{ko:'내분점(m:n)',en:'internal division (m:n)',zh:'内分点(m:n)'},params:{mode:'section'},
           concept:{ko:'m:n 내분점은 (n×A + m×B) ÷ (m+n)입니다 — 먼 쪽 점에 가까운 쪽 비율을 곱해 더한 뒤 비의 합으로 나눕니다.',
             en:'The point dividing internally in m:n is (n×A + m×B) ÷ (m+n): weight each endpoint by the far part of the ratio, add, then divide by m+n.',
             zh:'m:n的内分点是(n×A + m×B) ÷ (m+n)：每个端点乘以对面的比再相加，最后除以m+n。'}},
          {id:3,label:{ko:'외분점(실전)',en:'external division (main)',zh:'外分点(实战)'},params:{mode:'external'},
           concept:{ko:'m:n 외분점은 (m×B − n×A) ÷ (m − n)입니다 — 내분과 달리 분자도 더하기가 아니라 빼기로 바뀝니다.',
             en:'The point dividing externally in m:n is (m×B − n×A) ÷ (m − n) — unlike internal division, the top becomes a subtraction too.',
             zh:'m:n的外分点是(m×B − n×A) ÷ (m − n)——与内分不同，分子也从加号变成减号。'}}] },

MD33:{ name:{ko:'직선의 방정식',en:'The Equation of a Line',zh:'直线的方程'}, gen:'md33_lineEquation', prereq:['MD32'],
  unit:'M-33',
  concept:{ko:'기울기는 y의 변화량÷x의 변화량, y절편은 기울기를 구한 뒤 한 점을 대입해 찾습니다. 일반형 Ax+By=C는 y항만 남기고 이항한 뒤 B로 나누면 y=ax+b가 됩니다.',
    en:'Slope is the change in y over the change in x; find the y-intercept by substituting one point. The general form Ax+By=C becomes y=ax+b by isolating the y term and dividing by B.',
    zh:'斜率是y的变化量除以x的变化量，代入一点求y轴截距。一般式Ax+By=C只留下y项、移项后除以B，就变成y=ax+b。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'두 점 통과(연습)',en:'through two points (practice)',zh:'过两点(练习)'},params:{mode:'twoPoints'}},
          {id:2,label:{ko:'일반형→기울기절편형',en:'general form → slope-intercept form',zh:'一般式→斜截式'},params:{mode:'standardForm'},
           concept:{ko:'일반형은 y항만 남기고 넘긴 뒤 y의 계수로 양변을 나눕니다 — 4x+4y=16은 4y=−4x+16, y=−x+4입니다.',
             en:'From the standard form, move everything but the y term and divide by the coefficient of y: 4x+4y=16 gives 4y=−4x+16, so y=−x+4.',
             zh:'一般式要把除y项以外的都移过去，再除以y的系数：4x+4y=16得4y=−4x+16，即y=−x+4。'}},
          {id:3,label:{ko:'일반형→기울기절편형(실전 범위)',en:'general form → slope-intercept form (main range)',zh:'一般式→斜截式(实战范围)'},params:{mode:'standardFormWide'},
           concept:{ko:'수가 커져도 같습니다. 나눌 때 부호까지 함께 나눠야 기울기 부호가 맞습니다 — −45x+9y=−90은 y=5x−10입니다.',
             en:'Bigger numbers change nothing — divide the signs along with the numbers so the slope keeps its sign: −45x+9y=−90 gives y=5x−10.',
             zh:'数变大也一样——除的时候要连符号一起除，斜率的符号才正确：−45x+9y=−90得y=5x−10。'}}] },

MD34:{ name:{ko:'두 직선의 평행과 수직',en:'Parallel & Perpendicular Lines',zh:'两直线的平行与垂直'}, gen:'md34_parallelPerp', prereq:['MD33'],
  unit:'M-34',
  concept:{ko:'두 직선 Ax+By+C=0, kx+Dy+E=0이 평행하려면 A:B=k:D, 수직이려면 Ak+BD=0입니다. 나눗셈 대신 곱셈으로 역산하면 k가 항상 정수로 나옵니다.',
    en:'For lines Ax+By+C=0 and kx+Dy+E=0: parallel needs A:B=k:D, perpendicular needs Ak+BD=0. Working backward with multiplication instead of division keeps k an integer.',
    zh:'两直线Ax+By+C=0与kx+Dy+E=0：平行需要A:B=k:D，垂直需要Ak+BD=0。用乘法而不是除法反推，k总是整数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'평행 조건(연습)',en:'parallel condition (practice)',zh:'平行条件(练习)'},params:{mode:'parallel'}},
          {id:2,label:{ko:'수직 조건',en:'perpendicular condition',zh:'垂直条件'},params:{mode:'perpendicular'},
           concept:{ko:'수직이려면 두 직선의 x계수끼리·y계수끼리 곱한 값을 더해 0이어야 합니다(Ak+BD=0) — −3x−3y−1=0과 kx+6y−8=0은 −3k−18=0이라 k=−6입니다.',
             en:'Perpendicular means the x coefficients times each other plus the y coefficients times each other is 0 (Ak+BD=0): −3k−18=0, so k=−6.',
             zh:'垂直的条件是x系数相乘加上y系数相乘等于0（Ak+BD=0）：−3k−18=0，所以k=−6。'}},
          {id:3,label:{ko:'평행·수직 혼합(실전)',en:'parallel/perpendicular mixed (main)',zh:'平行·垂直混合(实战)'},params:{mode:'mixed'},
           concept:{ko:'평행인지 수직인지 먼저 읽고 조건을 고릅니다. 평행이면 A:B=k:D, 수직이면 Ak+BD=0입니다.',
             en:'Read whether the lines are parallel or perpendicular first, then pick the condition: A:B=k:D for parallel, Ak+BD=0 for perpendicular.',
             zh:'先看是平行还是垂直再选条件：平行用A:B=k:D，垂直用Ak+BD=0。'}}] },

MD35:{ name:{ko:'원의 방정식',en:'The Equation of a Circle',zh:'圆的方程'}, gen:'md35_circleEquation', prereq:['MD31'],
  unit:'M-35',
  concept:{ko:'x²+y²+Ax+By+C=0을 x항·y항끼리 완전제곱으로 묶으면 (x-a)²+(y-b)²=r² 꼴이 되어 중심(a,b)과 반지름 r이 바로 보입니다. x²,y² 앞에 공통계수가 있으면 먼저 나눕니다.',
    en:'Grouping x²+y²+Ax+By+C=0 into perfect squares gives (x-a)²+(y-b)²=r², revealing the center (a,b) and radius r directly. If x² and y² share a common coefficient, divide it out first.',
    zh:'把x²+y²+Ax+By+C=0的x项、y项配成完全平方，就变成(x-a)²+(y-b)²=r²，中心(a,b)和半径r一目了然。x²、y²前有公共系数就先除掉。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'완성형(연습)',en:'complete the square (practice)',zh:'配方(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'더 큰 범위',en:'wider range',zh:'更大范围'},params:{mode:'wide'},
           concept:{ko:'수가 커져도 완전제곱으로 묶는 방법은 같습니다. x계수의 반을 제곱해 더하고 빼면 (x−a)² 꼴이 나옵니다 — a는 x계수의 반에 −를 붙인 값입니다.',
             en:'Bigger numbers do not change completing the square: halve the x coefficient, square it, add and subtract — a is minus half the x coefficient.',
             zh:'数变大配方法不变：取x系数的一半平方后加减——a就是x系数一半取负。'}},
          {id:3,label:{ko:'공통계수 나누기(실전)',en:'divide out the common coefficient (main)',zh:'先除公共系数(实战)'},params:{mode:'leadingCoeff'},
           concept:{ko:'x²·y² 앞에 같은 수가 붙어 있으면 **먼저 그 수로 양변을 나눠요**. x²+y² 꼴로 만든 뒤에야 완전제곱으로 묶을 수 있습니다 — 3x²+3y²+…=0은 3으로 나누고 시작합니다.',
             en:'When x² and y² share a coefficient, divide the whole equation by it first — only once the form is x²+y²+… can you complete the square. So 3x²+3y²+…=0 starts with dividing by 3.',
             zh:'x²与y²前有相同系数时要先用它除整个方程——化成x²+y²+…之后才能配方。3x²+3y²+…=0先除以3。'}}] },

/* ── MD 고등 W13(대수) 신규 7종 (2026-08-25) ── 근거:
   MASTER-ROADMAP.md §6(W13 대수) — 2022 개정 교육과정 '대수' 과목의
   표준 연산 유형을 자체 설계(교재 원문 없음). gen 함수는
   engine/threads/mid6.js. unit은 data/units/M-36.js~M-42.js. 2022
   개정 과목명 준수 — "고3" 표기 없음. log(MD37)·Σ(MD42)는 §13 기호
   전환 교육 대상이라 유닛 practice가 mode:'decode'를 쓴다(아래
   레벨은 전부 실제 계산 모드). */
MD36:{ name:{ko:'거듭제곱근과 유리수 지수',en:'Radicals & Rational Exponents',zh:'方根与有理数指数'}, gen:'md36_rationalExponent', prereq:['MD15'],
  unit:'M-36',
  concept:{ko:'ⁿ√(aᵐ)은 a^(m/n)과 같습니다 — 근호의 지수(n)는 분모로, 거듭제곱의 지수(m)는 분자로 가고, 기약분수로 줄입니다.',
    en:'The nth root of aᵐ equals a raised to m/n — the root index (n) becomes the denominator, the power (m) the numerator, reduced to lowest terms.',
    zh:'aᵐ的n次方根等于a的m/n次方——根指数(n)作分母，幂指数(m)作分子，并约分到最简。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'표기법 익히기(연습)',en:'learn the notation (practice)',zh:'熟悉记法(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'약분이 필요한 경우',en:'needs reducing',zh:'需要约分'},params:{mode:'reduce'},
           concept:{ko:'지수를 분수로 옮긴 뒤 **기약분수로 줄여요** — ⁶√(10¹⁰)은 10^(10/6)이고 약분해서 10^(5/3)입니다.',
             en:'Move the exponents into a fraction and then reduce it: ⁶√(10¹⁰) is 10^(10/6), which reduces to 10^(5/3).',
             zh:'把指数写成分数后要约分：⁶√(10¹⁰)是10^(10/6)，约分后是10^(5/3)。'}},
          {id:3,label:{ko:'더 큰 범위(실전)',en:'wider range (main)',zh:'更大范围(实战)'},params:{mode:'wide'},
           concept:{ko:'수가 커져도 같습니다. 근호의 지수가 분모, 거듭제곱의 지수가 분자 — 그다음 약분합니다.',
             en:'Bigger numbers change nothing: the root index goes underneath, the power on top, then reduce.',
             zh:'数变大也一样：根指数作分母、幂指数作分子，然后约分。'}}] },

MD37:{ name:{ko:'로그의 정의',en:'The Definition of Logarithms',zh:'对数的定义'}, gen:'md37_logDefinition', prereq:['MD10'],
  unit:'M-37', symbols:[{sym:'log',read:'로그',translate:'"몇 번 곱해야 이 수가 되는가"를 묻는 지수 사다리의 반대 방향',birth:'로그를 발명한 네이피어(1614)는 큰 수의 곱셈을 덧셈으로 바꾸려 했다 — log는 logos(비율)+arithmos(수)의 합성어'}],
  concept:{ko:'log_a N = x는 "a를 x번 곱하면 N"이라는 뜻입니다(a^x=N) — 지수 사다리를 오르며 몇 번째 칸인지 찾는 거입니다.',
    en:'log_a N = x means "a multiplied by itself x times gives N" (a^x=N) — you climb the exponent ladder to find which rung.',
    zh:'log_a N = x的意思是"a自乘x次得到N"(a^x=N)——沿着指数梯子往上爬，找出是第几级。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'로그값 구하기(연습)',en:'find the log value (practice)',zh:'求对数值(练习)'},params:{mode:'value'}},
          {id:2,label:{ko:'진수 구하기(반대 방향)',en:'find N (the other direction)',zh:'求真数(反方向)'},params:{mode:'findN'},
           concept:{ko:'이번엔 진수를 찾습니다. log_7 □ = 4는 7을 네 번 곱한 수를 구하는 것이니 7⁴=2401입니다.',
             en:'This time the number inside is missing: log_7 □ = 4 asks for 7 multiplied four times, so 7⁴ = 2401.',
             zh:'这次要找真数：log_7 □ = 4就是求7乘四次，所以7⁴=2401。'}},
          {id:3,label:{ko:'더 큰 범위(실전)',en:'wider range (main)',zh:'更大范围(实战)'},params:{mode:'wide'},
           concept:{ko:'수가 커져도 세는 방법은 같습니다. 밑을 거듭 곱해 가며 몇 번째에 진수가 되는지 세요 — 7을 다섯 번 곱하면 16807입니다.',
             en:'Bigger numbers still just get counted: keep multiplying the base until you reach the number inside — five 7s make 16807.',
             zh:'数变大数法不变：把底数不断相乘，数到第几次得到真数——7乘五次是16807。'}}] },

MD38:{ name:{ko:'로그의 성질',en:'Properties of Logarithms',zh:'对数的性质'}, gen:'md38_logProperties', prereq:['MD37'],
  unit:'M-38',
  concept:{ko:'log_a X + log_a Y = log_a(XY), log_a X - log_a Y = log_a(X÷Y) — 로그의 덧뺄셈은 안의 수의 곱나눗이 됩니다. 밑변환도 정수로 떨어지는 경우만 다룹니다.',
    en:'log_a X + log_a Y = log_a(XY), log_a X - log_a Y = log_a(X÷Y) — adding/subtracting logs multiplies/divides what\'s inside. Change-of-base is limited to cases landing on integers.',
    zh:'log_a X + log_a Y = log_a(XY)，log_a X - log_a Y = log_a(X÷Y)——对数的加减对应真数的乘除。换底只处理结果为整数的情形。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'덧셈 성질(연습)',en:'the addition property (practice)',zh:'加法性质(练习)'},params:{mode:'sumProduct'}},
          {id:2,label:{ko:'뺄셈 성질',en:'the subtraction property',zh:'减法性质'},params:{mode:'diffQuotient'},
           concept:{ko:'로그의 뺄셈은 안의 수의 나눗셈이 됩니다 — log_6 36 − log_6 6 = log_6 (36÷6) = log_6 6입니다.',
             en:'Subtracting logs divides the numbers inside: log_6 36 − log_6 6 = log_6 (36÷6) = log_6 6.',
             zh:'对数相减就是真数相除：log_6 36 − log_6 6 = log_6 (36÷6) = log_6 6。'}},
          {id:3,label:{ko:'밑변환(정수만, 실전)',en:'change of base (integers only, main)',zh:'换底(仅整数，实战)'},params:{mode:'changeBase'},
           concept:{ko:'log_b N은 밑 b를 몇 번 곱해야 N이 되는지 세는 거입니다 — 6을 여섯 번 곱하면 46656이니 log_6 46656 = 6입니다.',
             en:'log_b N counts how many times you multiply the base b to reach N — six 6s make 46656, so log_6 46656 = 6.',
             zh:'log_b N 就是数底数b要乘几次才得到N——6乘六次是46656，所以log_6 46656 = 6。'}}] },

MD39:{ name:{ko:'삼각함수의 값(특수각)',en:'Trig Values of Special Angles',zh:'特殊角三角函数值'}, gen:'md39_trigSpecialAngle', prereq:['MD15'],
  unit:'M-39',
  concept:{ko:'0°·30°·45°·60°·90°의 sin·cos·tan 값은 정삼각형·직각이등변삼각형의 변의 비에서 나옵니다. 근호가 있는 값은 [계수,근호안,분모] 순서로 그대로 받습니다.',
    en:'sin·cos·tan values at 0°,30°,45°,60°,90° come from the side ratios of equilateral and right-isosceles triangles. Values with a root are entered as [coefficient, radicand, denominator], in order.',
    zh:'0°、30°、45°、60°、90°的sin·cos·tan值来自等边三角形和等腰直角三角形的边比。带根号的值按[系数,根号内,分母]顺序输入。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'정수·기약분수(연습)',en:'integers & simple fractions (practice)',zh:'整数与简单分数(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'근호가 있는 값',en:'values with a root',zh:'带根号的值'},params:{mode:'mixed'},
           concept:{ko:'30°·45°·60°의 값에는 근호가 들어 있습니다. tan30°=√3/3, sin60°=√3/2, cos45°=√2/2를 그대로 곱합니다.',
             en:'The values at 30°, 45° and 60° carry radicals: tan30°=√3/3, sin60°=√3/2 and cos45°=√2/2 — just multiply through.',
             zh:'30°、45°、60°的值带根号：tan30°=√3/3、sin60°=√3/2、cos45°=√2/2，直接相乘即可。'}},
          {id:3,label:{ko:'전체 혼합(실전)',en:'all mixed (main)',zh:'全部混合(实战)'},params:{mode:'wide'},
           concept:{ko:'0°·90°처럼 값이 정수인 각과 근호가 있는 각이 섞여 나옵니다. 각의 값을 먼저 떠올린 뒤 앞의 수를 곱합니다.',
             en:'Angles with whole-number values (0°, 90°) are mixed in with the ones carrying radicals: recall the value first, then multiply by the number in front.',
             zh:'值为整数的角（0°、90°）与带根号的角混在一起：先想出角的值，再乘前面的数。'}}] },

MD40:{ name:{ko:'등차수열',en:'Arithmetic Sequences',zh:'等差数列'}, gen:'md40_arithmeticSeq', prereq:['MD1'],
  unit:'M-40', lineage:['rainbow-sum'],
  concept:{ko:'등차수열의 일반항은 aₙ=a₁+(n-1)d, 합은 Sₙ=n(2a₁+(n-1)d)÷2입니다. 두 항을 알면 d와 a₁을 거꾸로 구할 수도 있습니다.',
    en:'The general term of an arithmetic sequence is aₙ=a₁+(n-1)d, and its sum is Sₙ=n(2a₁+(n-1)d)÷2. Given two terms, you can work backward to find d and a₁.',
    zh:'等差数列的通项是aₙ=a₁+(n-1)d，求和是Sₙ=n(2a₁+(n-1)d)÷2。知道两项也能反过来求d和a₁。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'일반항 값 구하기(연습)',en:'find a term (practice)',zh:'求项值(练习)'},params:{mode:'nthTerm'}},
          {id:2,label:{ko:'두 항으로 a₁,d 구하기',en:'find a₁,d from two terms',zh:'由两项求a₁,d'},params:{mode:'findRule'},
           concept:{ko:'이웃한 두 항의 차가 곧 공차 d입니다. 항 번호가 두 칸 떨어져 있으면 그 차를 2로 나눕니다 — a₄=−16, a₆=−28이면 d=(−28−(−16))÷2=−6입니다.',
             en:'The gap between neighbouring terms is d; if the two given terms are two steps apart, halve that gap — a₄=−16 and a₆=−28 give d=(−28−(−16))÷2=−6.',
             zh:'相邻两项之差就是公差d；若给的两项相隔两位就把差除以2——a₄=−16、a₆=−28时d=(−28−(−16))÷2=−6。'}},
          {id:3,label:{ko:'합 구하기(실전)',en:'find the sum (main)',zh:'求和(实战)'},params:{mode:'sum',wide:true},
           concept:{ko:'등차수열의 합은 Sₙ = n(2a₁+(n−1)d)÷2입니다 — a₁=18, d=1, n=9면 9×(36+8)÷2=198입니다.',
             en:'The sum of an arithmetic sequence is Sₙ = n(2a₁+(n−1)d)÷2 — with a₁=18, d=1 and n=9 that is 9×(36+8)÷2 = 198.',
             zh:'等差数列的和是Sₙ = n(2a₁+(n−1)d)÷2——a₁=18、d=1、n=9时是9×(36+8)÷2=198。'}}] },

MD41:{ name:{ko:'등비수열',en:'Geometric Sequences',zh:'等比数列'}, gen:'md41_geometricSeq', prereq:['MD1'],
  unit:'M-41',
  concept:{ko:'등비수열의 일반항은 aₙ=a₁×r^(n-1)입니다. 합은 각 항을 직접 나열해 더한 것과 같습니다 — a₁+a₁r+a₁r²+….',
    en:'The general term of a geometric sequence is aₙ=a₁×r^(n-1). Its sum is just each term added one by one — a₁+a₁r+a₁r²+….',
    zh:'等比数列的通项是aₙ=a₁×r^(n-1)。求和就是把每一项依次相加——a₁+a₁r+a₁r²+…。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'일반항 값 구하기(연습)',en:'find a term (practice)',zh:'求项值(练习)'},params:{mode:'nthTerm'}},
          {id:2,label:{ko:'두 항으로 a₁,r 구하기',en:'find a₁,r from two terms',zh:'由两项求a₁,r'},params:{mode:'findRule'},
           concept:{ko:'이웃한 두 항의 비가 곧 공비 r입니다. r을 구한 뒤 a₁=X÷r^(p−1)로 되돌아갑니다 — a₂=6, a₃=−18이면 r=−3, a₁=−2입니다.',
             en:'The ratio of two neighbouring terms is r; then work back with a₁ = X ÷ r^(p−1) — a₂=6 and a₃=−18 give r=−3 and a₁=−2.',
             zh:'相邻两项之比就是公比r，再用a₁=X÷r^(p−1)倒推——a₂=6、a₃=−18时r=−3、a₁=−2。'}},
          {id:3,label:{ko:'합 구하기(실전)',en:'find the sum (main)',zh:'求和(实战)'},params:{mode:'sum',wide:true},
           concept:{ko:'항을 직접 나열해 더하면 합입니다 — a₁=5, r=4이면 5+20+80+320=425입니다.',
             en:'Write the terms out and add them: a₁=5 with r=4 gives 5+20+80+320 = 425.',
             zh:'把各项列出来相加就是和：a₁=5、r=4时是5+20+80+320=425。'}}] },

MD42:{ name:{ko:'Σ(시그마) 계산',en:'Sigma Notation',zh:'Σ(求和符号)计算'}, gen:'md42_sigmaSum', prereq:['MD40'],
  unit:'M-42', lineage:['rainbow-sum'], symbols:[{sym:'Σ',read:'시그마',translate:'k에 시작부터 끝까지 하나씩 넣어서 다 더해라',birth:'오일러(1755)가 합(Sum)을 뜻하는 그리스 대문자 Σ(시그마)를 처음 이 용도로 썼다'}],
  concept:{ko:'Σk(k=1~n)=n(n+1)÷2는 무지개 덧셈법과 똑같은 공식이고, Σk²=n(n+1)(2n+1)÷6은 제곱수의 합과 같습니다 — 이미 아는 마법에 새 기호 옷을 입힌 거입니다.',
    en:'Σk from 1 to n equals n(n+1)÷2, the exact same formula as the rainbow-sum trick, and Σk² equals n(n+1)(2n+1)÷6, the sum-of-squares formula — the same magic wearing a new symbol.',
    zh:'Σk(k=1~n)=n(n+1)÷2和彩虹加法法是同一个公式，Σk²=n(n+1)(2n+1)÷6就是平方数之和——是同一套魔法换了个符号的新衣服。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'Σk(무지개 덧셈법, 연습)',en:'Σk (rainbow sum, practice)',zh:'Σk(彩虹加法法，练习)'},params:{mode:'sumK'}},
          {id:2,label:{ko:'Σk²(제곱수의 합)',en:'Σk² (sum of squares)',zh:'Σk²(平方数之和)'},params:{mode:'sumK2'},
           concept:{ko:'제곱수의 합은 Σk²=n(n+1)(2n+1)÷6입니다 — n=9면 9×10×19÷6=285입니다.',
             en:'The sum of squares is Σk² = n(n+1)(2n+1)÷6 — for n=9 that is 9×10×19÷6 = 285.',
             zh:'平方和是Σk²=n(n+1)(2n+1)÷6——n=9时是9×10×19÷6=285。'}},
          {id:3,label:{ko:'Σ(pk+q) 쪼개기(실전)',en:'split Σ(pk+q) (main)',zh:'拆分Σ(pk+q)(实战)'},params:{mode:'sumAffine',wide:true},
           concept:{ko:'Σ(pk+q)는 pΣk + q×n으로 쪼갭니다 — 상수 q는 n번 더해지니까 q에 항의 개수 n을 곱합니다.',
             en:'Σ(pk+q) splits into pΣk + q×n — the constant q is added n times, so multiply q by the number of terms.',
             zh:'Σ(pk+q)可以拆成pΣk + q×n——常数q被加了n次，所以要乘以项数n。'}}] },

/* ── MD 고등 W14(미적분Ⅰ) 신규 4종 (2026-08-25) ── 근거:
   MASTER-ROADMAP.md §6(W14 미적분Ⅰ) — 2022 개정 교육과정 '미적분Ⅰ'
   과목의 표준 연산 유형을 자체 설계(교재 원문 없음). 연속 조건
   상수 결정·극값·넓이는 이번 범위에서 제외(작업지시). gen 함수는
   engine/threads/mid7.js. unit은 data/units/M-43.js~M-46.js.
   lim(MD43)·f′,d/dx(MD44)·∫(MD46)은 §13 기호 전환 교육 대상이라
   유닛 practice가 mode:'decode'를 쓴다(아래 레벨은 전부 실제 계산
   모드). */
MD43:{ name:{ko:'함수의 극한값 계산',en:'Evaluating Limits',zh:'函数极限值的计算'}, gen:'md43_limit', prereq:['MD21'],
  unit:'M-43', symbols:[{sym:'lim',read:'리미트',translate:'x가 그 값에 한없이 가까워질 때 식이 어디로 다가가는지',birth:'"한계(limit)"의 준말 — 다가가는 화살표(→) 표기는 20세기 초에 정착됐다'}],
  concept:{ko:'다항식은 x=a를 그대로 대입하면 극한값이 나옵니다. 0/0 꼴이면 분자를 인수분해해서 분모와 같은 인수를 약분한 뒤 다시 대입합니다.',
    en:'For polynomials, substitute x=a directly to get the limit. For a 0/0 form, factor the numerator, cancel the factor matching the denominator, then substitute again.',
    zh:'多项式直接代入x=a就是极限值。遇到0/0型，先把分子因式分解，约去和分母相同的因式，再代入。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'대입형(연습)',en:'direct substitution (practice)',zh:'直接代入型(练习)'},params:{mode:'directSub'}},
          {id:2,label:{ko:'약분형(0/0 꼴)',en:'0/0 form, factor & cancel',zh:'约分型(0/0型)'},params:{mode:'factorCancel'},
           concept:{ko:'대입했을 때 0/0이 되면 분자를 인수분해합니다. 분모와 같은 인수가 약분되고 남은 식에 다시 대입하면 값이 나옵니다 — (x²−3x−18)/(x+3)은 x−6이라 −9입니다.',
             en:'If substituting gives 0/0, factor the top: the factor matching the bottom cancels and you substitute again — (x²−3x−18)/(x+3) becomes x−6, so −9.',
             zh:'代入后出现0/0就把分子因式分解：与分母相同的因式约掉后再代入——(x²−3x−18)/(x+3)化成x−6，得−9。'}},
          {id:3,label:{ko:'더 큰 범위(실전)',en:'wider range (main)',zh:'更大范围(实战)'},params:{mode:'factorCancel',wide:true},
           concept:{ko:'수가 커져도 같습니다. 분모가 (x−a)면 분자도 반드시 (x−a)를 인수로 가지므로 약분이 됩니다.',
             en:'Bigger numbers change nothing: if the bottom is (x−a) the top must also have (x−a) as a factor, so it cancels.',
             zh:'数变大也一样：分母是(x−a)时分子一定含有(x−a)这个因式，所以能约掉。'}}] },

MD44:{ name:{ko:'미분계수와 도함수',en:'Derivatives',zh:'导数与导函数'}, gen:'md44_derivative', prereq:['MD43'],
  unit:'M-44', symbols:[{sym:"f'",read:'프라임',translate:'순간의 기울기(도함수)를 구하라',birth:'라이프니츠는 d(작은 차이)로, 라그랑주는 프라임(′)으로 썼다 — 같은 것의 두 옷'},{sym:'d/dx',read:'디엑스분의디',translate:'x가 아주 조금 변할 때 y가 얼마나 변하는지의 비율',birth:'라이프니츠(1670년대)가 만든 표기 — dx는 "아주 작은 x 조각"'}],
  concept:{ko:'axⁿ의 도함수는 naxⁿ⁻¹ — 지수를 앞으로 곱해 내리고 1 줄입니다. f\'(x₀)는 도함수에 x₀를 대입한 값입니다.',
    en:'The derivative of ax^n is n·a·x^(n-1) — bring the exponent down as a multiplier and reduce it by 1. f\'(x₀) is the derivative evaluated at x₀.',
    zh:'ax^n的导数是n·a·x^(n-1)——把指数乘到前面再减1。f\'(x₀)就是把x₀代入导函数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'이차함수 도함수(연습, 2다칸)',en:'derivative of a quadratic (practice, 2 slots)',zh:'二次函数的导数(练习，2格)'},params:{mode:'polyPrime'}},
          {id:2,label:{ko:'삼차함수 도함수(3다칸)',en:'derivative of a cubic (3 slots)',zh:'三次函数的导数(3格)'},params:{mode:'polyPrime',cubic:true}},
          {id:3,label:{ko:'미분계수 f\'(a)(실전)',en:'derivative value f\'(a) (main)',zh:'导数值f\'(a)(实战)'},params:{mode:'evalPrime',wide:true},
           concept:{ko:'도함수를 먼저 구한 뒤 그 자리의 x값을 넣습니다 — f(x)=−6x²+5x의 도함수는 −12x+5이고, f′(2)=−24+5=−19입니다.',
             en:'Differentiate first, then put the x value in: f(x)=−6x²+5x has f′(x)=−12x+5, so f′(2)=−24+5=−19.',
             zh:'先求导函数再代入该点的x值：f(x)=−6x²+5x的导函数是−12x+5，所以f′(2)=−24+5=−19。'}}] },

MD45:{ name:{ko:'접선의 기울기와 방정식',en:'Tangent Line Slope & Equation',zh:'切线的斜率与方程'}, gen:'md45_tangentLine', prereq:['MD44'],
  unit:'M-45',
  concept:{ko:'접선의 기울기는 그 점에서의 미분계수 f\'(x₀)입니다. 접선의 방정식 y=mx+n은 m=f\'(x₀), n=f(x₀)-m·x₀로 구합니다.',
    en:'The slope of the tangent line is the derivative f\'(x₀) at that point. The tangent line y=mx+n has m=f\'(x₀) and n=f(x₀)-m·x₀.',
    zh:'切线的斜率就是该点的导数f\'(x₀)。切线方程y=mx+n中，m=f\'(x₀)，n=f(x₀)-m·x₀。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'기울기만(연습)',en:'slope only (practice)',zh:'仅求斜率(练习)'},params:{mode:'slope'}},
          {id:2,label:{ko:'접선의 방정식(2다칸)',en:'tangent line equation (2 slots)',zh:'切线方程(2格)'},params:{mode:'lineEq'},
           concept:{ko:'기울기 m=f′(x₀)를 구한 뒤 n=f(x₀)−m·x₀로 y절편을 구합니다. 두 값이 곧 접선 y=mx+n입니다.',
             en:'Find the slope m=f′(x₀), then the intercept n=f(x₀)−m·x₀ — those two numbers are the tangent line y=mx+n.',
             zh:'先求斜率m=f′(x₀)，再求截距n=f(x₀)−m·x₀，这两个数就是切线y=mx+n。'}},
          {id:3,label:{ko:'더 큰 범위(실전)',en:'wider range (main)',zh:'更大范围(实战)'},params:{mode:'lineEq',wide:true},
           concept:{ko:'수가 커져도 두 걸음은 같습니다. m을 먼저, 그다음 접점의 y값에서 m·x₀를 빼 n을 구합니다.',
             en:'Bigger numbers keep the same two steps: m first, then n by subtracting m·x₀ from the y value at the point.',
             zh:'数变大两个步骤不变：先求m，再用切点的y值减去m·x₀得到n。'}}] },

MD46:{ name:{ko:'다항함수의 적분',en:'Integrating Polynomials',zh:'多项式函数的积分'}, gen:'md46_polyIntegral', prereq:['MD44'],
  unit:'M-46', symbols:[{sym:'∫',read:'인테그랄',translate:'잘게 쪼개 다 더해라',birth:'라이프니츠(1675)가 합(summa)의 첫 글자 S를 길게 늘여 만든 글자'}],
  concept:{ko:'∫axⁿdx = (a÷(n+1))xⁿ⁺¹(+C) — 계수를 (n+1)로 나누고 지수를 하나 늘립니다. 정적분 ∫[p,q]f(x)dx는 원시함수 F로 F(q)-F(p)를 계산합니다.',
    en:'∫ax^n dx = (a÷(n+1))x^(n+1) (+C) — divide the coefficient by (n+1) and raise the exponent by one. A definite integral ∫[p,q]f(x)dx equals F(q)-F(p) for the antiderivative F.',
    zh:'∫ax^n dx = (a÷(n+1))x^(n+1)(+C)——系数除以(n+1)，指数加1。定积分∫[p,q]f(x)dx用原函数F计算F(q)-F(p)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'일차식의 부정적분(연습, 2다칸)',en:'antiderivative of a linear function (practice, 2 slots)',zh:'一次式的不定积分(练习，2格)'},params:{mode:'antiderivative'}},
          {id:2,label:{ko:'이차식의 부정적분(3다칸)',en:'antiderivative of a quadratic (3 slots)',zh:'二次式的不定积分(3格)'},params:{mode:'antiderivative',deg2:true}},
          {id:3,label:{ko:'정적분 값(실전)',en:'definite integral value (main)',zh:'定积分值(实战)'},params:{mode:'definiteInt',wide:true},
           concept:{ko:'정적분은 원시함수 F를 구해 F(위끝)−F(아래끝)입니다. 위끝이 아래끝보다 작으면 값이 음수가 될 수 있습니다.',
             en:'A definite integral is F(upper) − F(lower) once you have the antiderivative F; if the upper limit is smaller than the lower, the value can come out negative.',
             zh:'定积分是求出原函数F后计算F(上限)−F(下限)；上限比下限小时值可能为负。'}}] },

/* ── MD 심화 유형 2차(2026-08-27) ── 작업지시로 채우는 세 구간.
   A. 중1 문자와 식(W8, tier:middle1, MD47~51) — 원본 없이 자체 설계
      (engine/threads/mid.js가 애초에 MD1~9만 다뤘던 이유는 이 파일
      상단 주석 참조 — W8에 남아 있던 마지막 미구현 구간).
   B. 대수 심화(tier:algebra, MD52~57) — mid6.js(MD36~42)가 작업지시로
      제외했던 지수·로그 방정식/부등식·사인법칙·코사인법칙·삼각함수
      최대최소주기.
   C. 미적분Ⅰ 심화(tier:calculus1, MD58~62) — mid7.js(MD43~46)가
      작업지시로 제외했던 유리화형 극한·연속조건·극값·넓이·속도.
   gen 함수는 engine/threads/mid8.js. unit은 data/units/M-47.js~
   M-62.js. */
MD47:{ name:{ko:'문자식 표현',en:'Algebraic Expression Notation',zh:'代数式的表示'}, gen:'md47_expressionNotation', prereq:['MD1'],
  unit:'M-47',
  concept:{ko:'문자식에서는 곱셈 기호(×)를 생략하고 숫자를 문자 앞에 씁니다. 같은 문자를 여러 번 곱한 건 지수로, 나눗셈은 분수로 나타냅니다.',
    en:'In algebraic notation, drop the multiplication sign(×) and put the number before the letter. A repeated letter becomes an exponent, and division becomes a fraction.',
    zh:'代数式中省略乘号(×)，数字写在字母前面。同一字母连乘写成指数，除法写成分数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'한 문자(연습, 2다칸)',en:'one letter (practice, 2 slots)',zh:'一个字母(练习，2格)'},params:{mode:'singleVar'}},
          {id:2,label:{ko:'나눗셈→분수 계수',en:'division becomes a fraction',zh:'除法→分数系数'},params:{mode:'withDivision'},
           concept:{ko:'나눗셈은 분수로 적습니다. 숫자끼리 약분한 뒤 문자를 붙입니다 — y×8÷6은 8/6 y이고 약분하면 4/3 y입니다.',
             en:'Write division as a fraction, reduce the numbers, then attach the letter: y×8÷6 is 8/6 y, which reduces to 4/3 y.',
             zh:'除法写成分数，先把数字约分再写字母：y×8÷6是8/6 y，约分后是4/3 y。'}},
          {id:3,label:{ko:'두 문자(3다칸, 실전)',en:'two letters (3 slots, main)',zh:'两个字母(3格，实战)'},params:{mode:'twoVars'},
           concept:{ko:'문자가 둘이면 문자마다 몇 번 곱했는지 따로 세어 지수로 적습니다 — 2×x×x×x×a는 2x³a입니다.',
             en:'With two letters, count how many times each appears and write that as its exponent: 2×x×x×x×a is 2x³a.',
             zh:'有两个字母时分别数各自出现几次并写成指数：2×x×x×x×a是2x³a。'}}] },

MD48:{ name:{ko:'식의 값',en:'Evaluating Expressions',zh:'代数式的值'}, gen:'md48_expressionValue', prereq:['MD47'],
  unit:'M-48',
  concept:{ko:'문자에 수를 넣을 땐 곱셈 기호를 살려서 대입합니다 — x=−3처럼 음수를 넣을 땐 괄호로 감싸서 계산하면 실수를 줄일 수 있습니다.',
    en:'When substituting a number for a letter, restore the multiplication sign — wrapping a negative value like x=−3 in parentheses helps avoid mistakes.',
    zh:'代入数值时要把乘号补回来——代入像x=−3这样的负数时，用括号括起来能减少出错。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'일차식(연습)',en:'linear expression (practice)',zh:'一次式(练习)'},params:{mode:'linear'}},
          {id:2,label:{ko:'이차식(음수 대입)',en:'quadratic expression (negative substitution)',zh:'二次式(代入负数)'},params:{mode:'quadratic'},
           concept:{ko:'음수를 넣을 땐 괄호로 감쌉니다. x=−3이면 x²은 (−3)²=9라 양수가 됩니다.',
             en:'Wrap a negative in brackets before substituting: with x=−3, x² is (−3)² = 9, which is positive.',
             zh:'代入负数时要加括号：x=−3时x²是(−3)²=9，结果为正。'}},
          {id:3,label:{ko:'문자 두 개(실전)',en:'two letters (main)',zh:'两个字母(实战)'},params:{mode:'twoVars'},
           concept:{ko:'문자가 둘이면 각 문자에 제 값을 넣습니다 — x=2, y=−1일 때 x−5y는 2−5×(−1)=7입니다.',
             en:'With two letters, substitute each one’s own value: with x=2 and y=−1, x−5y is 2−5×(−1) = 7.',
             zh:'有两个字母时各自代入自己的值：x=2、y=−1时x−5y是2−5×(−1)=7。'}}] },

MD49:{ name:{ko:'일차식의 계산',en:'Linear Expression Operations',zh:'一次式的运算'}, gen:'md49_linearExprOps', prereq:['MD48'],
  unit:'M-49',
  concept:{ko:'괄호 앞의 수는 분배법칙으로 괄호 안 모든 항에 하나씩 곱합니다. 문자와 차수가 같은 항(동류항)끼리만 더하거나 뺍니다.',
    en:'The number in front of parentheses multiplies every term inside via the distributive law. Only like terms (same letter, same degree) can be added or subtracted.',
    zh:'括号前的数用分配律分别乘到括号里每一项。只有文字和次数相同的项(同类项)才能相加或相减。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'분배법칙 전개(연습, 2다칸)',en:'expand with the distributive law (practice, 2 slots)',zh:'分配律展开(练习，2格)'},params:{mode:'distribute'}},
          {id:2,label:{ko:'두 일차식 덧뺄(동류항)',en:'add/subtract two linear expressions (like terms)',zh:'两个一次式加减(同类项)'},params:{mode:'addSub'},
           concept:{ko:'괄호 앞이 −면 괄호 안 모든 항의 부호가 바뀝니다. 그 뒤에 x항끼리·상수항끼리 모읍니다 — (−4x−6)−(x+5)는 −5x−11입니다.',
             en:'A minus before a bracket flips every term inside; then gather x terms with x terms and constants with constants — (−4x−6)−(x+5) is −5x−11.',
             zh:'括号前是减号时括号里每项都变号，然后x项与x项、常数与常数分别合并——(−4x−6)−(x+5)是−5x−11。'}},
          {id:3,label:{ko:'분배 후 동류항 정리(실전)',en:'distribute then combine like terms (main)',zh:'先分配后合并同类项(实战)'},params:{mode:'mixed'},
           concept:{ko:'괄호 앞의 수를 먼저 분배한 다음 동류항을 모읍니다 — 4(−3x+8)−(−5x+5)는 −12x+32+5x−5이니 −7x+27입니다.',
             en:'Distribute the number in front first, then gather like terms: 4(−3x+8)−(−5x+5) is −12x+32+5x−5, so −7x+27.',
             zh:'先把括号前的数分配出去，再合并同类项：4(−3x+8)−(−5x+5)是−12x+32+5x−5，即−7x+27。'}}] },

MD50:{ name:{ko:'일차방정식 풀이',en:'Solving Linear Equations',zh:'一元一次方程的解法'}, gen:'md50_linearEquation', prereq:['MD49'],
  unit:'M-50',
  concept:{ko:'등식의 성질로 양변에 같은 조작을 해서 x만 남깁니다 — 상수항은 반대쪽으로 이항하고, 마지막엔 x의 계수로 나눕니다.',
    en:'Use the properties of equality — apply the same operation to both sides to isolate x: move constants to the other side, then divide by x\'s coefficient.',
    zh:'用等式的性质对两边做相同的操作来只留下x——把常数项移到另一边，最后除以x的系数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'한 단계(ax=c, 연습)',en:'one step (ax=c, practice)',zh:'一步(ax=c，练习)'},params:{mode:'oneStep'}},
          {id:2,label:{ko:'두 단계(ax+b=c)',en:'two steps (ax+b=c)',zh:'两步(ax+b=c)'},params:{mode:'twoStep',wide:true},
           concept:{ko:'상수항을 먼저 반대쪽으로 넘기고, 남은 x의 계수로 양변을 나눕니다 — −9x+1=73은 −9x=72, x=−8입니다.',
             en:'Move the constant across first, then divide both sides by the coefficient of x: −9x+1=73 gives −9x=72 and x=−8.',
             zh:'先把常数项移到另一边，再用x的系数除两边：−9x+1=73得−9x=72，x=−8。'}},
          {id:3,label:{ko:'양변에 미지수(실전)',en:'x on both sides (main)',zh:'两边都有未知数(实战)'},params:{mode:'bothSides',wide:true},
           concept:{ko:'양변에 모두 x가 있으면 x항은 한쪽으로, 상수항은 반대쪽으로 모은 뒤 x의 계수로 나눕니다. 등호를 넘어가는 항은 부호가 바뀝니다.',
             en:'When x sits on both sides, gather the x terms on one side and the constants on the other, then divide by the coefficient of x. A term that crosses the equals sign flips its sign.',
             zh:'两边都有x时，把x项收到一边、常数项收到另一边，再除以x的系数。越过等号的项要变号。'}}] },

MD51:{ name:{ko:'정비례·반비례 값',en:'Direct & Inverse Proportion',zh:'正比例·反比例的值'}, gen:'md51_proportion', prereq:['MD50'],
  unit:'M-51',
  concept:{ko:'정비례 y=ax는 x와 y의 비율(a)이 항상 일정합니다. 반비례 y=a/x는 x와 y의 곱(a)이 항상 일정합니다.',
    en:'Direct proportion y=ax keeps the ratio(a) of y to x constant. Inverse proportion y=a/x keeps the product(a) of x and y constant.',
    zh:'正比例y=ax中y与x的比值(a)恒定。反比例y=a/x中x与y的乘积(a)恒定。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'정비례(연습)',en:'direct proportion (practice)',zh:'正比例(练习)'},params:{mode:'direct',wide:true}},
          {id:2,label:{ko:'반비례(약수에서 값 선택)',en:'inverse proportion (pick from divisors)',zh:'反比例(从约数中取值)'},params:{mode:'inverse'},
           concept:{ko:'반비례는 x와 y의 **곱**이 늘 같습니다. 지나는 점에서 a=x×y를 구한 뒤, 새 x로 나누면 y가 나옵니다 — (2,5)를 지나면 a=10이고 x=10일 때 y=1입니다.',
             en:'In inverse proportion the product x×y stays the same: find a=x×y from the given point, then divide by the new x — through (2,5) gives a=10, so x=10 makes y=1.',
             zh:'反比例中x与y的乘积始终不变：由已知点求a=x×y，再用新的x去除——过(2,5)时a=10，x=10时y=1。'}},
          {id:3,label:{ko:'정비례·반비례 혼합(실전)',en:'direct/inverse mixed (main)',zh:'正比例·反比例混合(实战)'},params:{mode:'mixed',wide:true},
           concept:{ko:'정비례인지 반비례인지 식을 먼저 읽습니다. y=ax면 x를 곱하고, y=a/x면 x로 나눕니다.',
             en:'Read the formula first: y=ax means multiply by x, while y=a/x means divide by x.',
             zh:'先看式子是正比例还是反比例：y=ax就乘以x，y=a/x就除以x。'}}] },

MD52:{ name:{ko:'지수방정식',en:'Exponential Equations',zh:'指数方程'}, gen:'md52_expEquation', prereq:['MD37'],
  unit:'M-52',
  concept:{ko:'밑이 같으면 지수함수는 일대일 대응이라 지수끼리 등식이 성립합니다 — 우변이 아직 밑으로 안 풀린 수면 먼저 같은 밑의 거듭제곱으로 바꿉니다(밑 통일).',
    en:'When the bases match, the exponential function is one-to-one, so the exponents themselves form an equation — if the right side isn\'t yet a power of that base, rewrite it first (unify the base).',
    zh:'底数相同时，指数函数是一一对应的，所以指数本身构成等式——如果右边还不是那个底数的幂，就先化成同底的幂(统一底数)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'밑이 같은 식(연습)',en:'same base (practice)',zh:'同底的式子(练习)'},params:{mode:'sameBaseSimple'}},
          {id:2,label:{ko:'계수가 있는 지수식',en:'exponent with a coefficient',zh:'带系数的指数式'},params:{mode:'sameBaseGeneral',wide:true},
           concept:{ko:'밑이 같으면 지수끼리 같다고 놓습니다. 그다음은 일차방정식입니다 — 9^(3x−18)=9⁶은 3x−18=6이니 x=8입니다.',
             en:'With the same base, set the exponents equal and solve the linear equation: 9^(3x−18)=9⁶ gives 3x−18=6, so x=8.',
             zh:'底数相同时令指数相等，之后就是一次方程：9^(3x−18)=9⁶得3x−18=6，所以x=8。'}},
          {id:3,label:{ko:'밑 통일부터(실전)',en:'unify the base first (main)',zh:'先统一底数(实战)'},params:{mode:'unifyBase',wide:true},
           concept:{ko:'오른쪽이 거듭제곱 꼴이 아니면 **먼저 같은 밑으로 바꿔요** — 59049는 9⁵이니 9^(4x+21)=9⁵에서 4x+21=5입니다.',
             en:'If the right side is not yet a power, rewrite it with the same base first: 59049 is 9⁵, so 9^(4x+21)=9⁵ gives 4x+21=5.',
             zh:'右边还不是幂的形式时要先化成同底：59049是9⁵，所以9^(4x+21)=9⁵得4x+21=5。'}}] },

MD53:{ name:{ko:'로그방정식',en:'Logarithmic Equations',zh:'对数方程'}, gen:'md53_logEquation', prereq:['MD38'],
  unit:'M-53',
  concept:{ko:'log_a N = k는 a^k=N — 진수를 그 값으로 바꾼 뒤 x에 대해 풉니다. 로그의 덧셈·뺄셈 성질로 여러 로그를 하나로 합칠 수도 있습니다.',
    en:'log_a N = k means a^k=N — replace the argument with that value, then solve for x. The addition/subtraction properties of logs can also combine several logs into one.',
    zh:'log_a N = k即a^k=N——把真数换成那个值，再解出x。对数的加减性质也能把几个对数合并成一个。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'로그의 정의로 풀기(연습)',en:'solve with the definition (practice)',zh:'用定义求解(练习)'},params:{mode:'basic',wide:true}},
          {id:2,label:{ko:'로그의 덧셈 성질',en:'the addition property',zh:'对数的加法性质'},params:{mode:'sumEq',wide:true},
           concept:{ko:'로그의 덧셈은 진수의 곱입니다. log₂x+log₂5=log₂45는 5x=45이니 x=9입니다.',
             en:'Adding logs multiplies what is inside: log₂x+log₂5=log₂45 means 5x=45, so x=9.',
             zh:'对数相加就是真数相乘：log₂x+log₂5=log₂45就是5x=45，所以x=9。'}},
          {id:3,label:{ko:'로그의 뺄셈 성질(실전)',en:'the subtraction property (main)',zh:'对数的减法性质(实战)'},params:{mode:'wide'},
           concept:{ko:'로그의 뺄셈은 진수의 나눗셈입니다. 하나로 합친 뒤 log_a N=k를 a^k=N으로 풉니다 — log₂(3x−15)−log₂3=2는 (3x−15)/3=4입니다.',
             en:'Subtracting logs divides what is inside; combine into one log, then turn log_a N=k into a^k=N — log₂(3x−15)−log₂3=2 means (3x−15)/3=4.',
             zh:'对数相减就是真数相除；先合成一个对数，再把log_a N=k化成a^k=N——log₂(3x−15)−log₂3=2就是(3x−15)/3=4。'}}] },

MD54:{ name:{ko:'지수·로그 부등식',en:'Exponential & Log Inequalities',zh:'指数·对数不等式'}, gen:'md54_expLogInequality', prereq:['MD52'],
  unit:'M-54',
  concept:{ko:'밑이 1보다 크면 지수함수·로그함수 둘 다 증가함수입니다 — 등호가 성립하는 경계값을 구하면 부등식의 해가 그 값을 기준으로 나뉩니다.',
    en:'When the base exceeds 1, both exponential and log functions are increasing — find the boundary value where equality holds, and the inequality\'s solution splits at that point.',
    zh:'底数大于1时，指数函数和对数函数都是增函数——求出等号成立的边界值，不等式的解就以它为界分开。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'지수부등식(연습)',en:'exponential inequality (practice)',zh:'指数不等式(练习)'},params:{mode:'expBasic',wide:true}},
          {id:2,label:{ko:'지수부등식(계수 있음)',en:'exponential inequality (with coefficient)',zh:'指数不等式(带系数)'},params:{mode:'expWide',wide:true},
           concept:{ko:'x의 계수가 1이 아니면 경계값을 구한 뒤 그 계수로 나눕니다. 양수로 나누면 부등호 방향은 그대로입니다 — 8^(3x+16)≥8⁷은 3x+16≥7이니 x≥−3입니다.',
             en:'When the coefficient of x is not 1, find the boundary then divide by it; dividing by a positive keeps the direction — 8^(3x+16)≥8⁷ gives 3x+16≥7, so x≥−3.',
             zh:'x的系数不是1时先求边界值再除以它；除以正数方向不变——8^(3x+16)≥8⁷得3x+16≥7，即x≥−3。'}},
          {id:3,label:{ko:'로그부등식(실전)',en:'logarithmic inequality (main)',zh:'对数不等式(实战)'},params:{mode:'logIneq',wide:true},
           concept:{ko:'로그부등식은 먼저 양쪽을 로그 꼴로 맞춥니다. log₄(3x+37)≤2는 3x+37≤4²=16이니 x≤−7입니다.',
             en:'For a log inequality, put both sides in log form first: log₄(3x+37)≤2 means 3x+37 ≤ 4² = 16, so x≤−7.',
             zh:'对数不等式要先把两边化成对数形式：log₄(3x+37)≤2就是3x+37≤4²=16，所以x≤−7。'}}] },

MD55:{ name:{ko:'사인법칙',en:'Law of Sines',zh:'正弦定理'}, gen:'md55_lawOfSines', prereq:['MD39'],
  unit:'M-55',
  concept:{ko:'사인법칙 a/sinA = 2R — 한 변과 그 대각을 알면 외접원의 지름(2R)을 구할 수 있습니다. 30°·90°는 정수로, 45°는 [계수,근호안]으로 딱 떨어집니다.',
    en:'The law of sines a/sinA = 2R — knowing one side and its opposite angle gives the diameter of the circumscribed circle(2R). 30° and 90° land on an integer; 45° lands on [coefficient, radicand].',
    zh:'正弦定理a/sinA = 2R——已知一边和它的对角，就能求出外接圆的直径(2R)。30°和90°得到整数；45°得到[系数,根号内]。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'30°·90°(연습, 정수)',en:'30°/90° (practice, integer)',zh:'30°·90°(练习，整数)'},params:{mode:'basic',wide:true}},
          {id:2,label:{ko:'45°(근호가 있는 값)',en:'45° (a value with a root)',zh:'45°(带根号的值)'},params:{mode:'root',wide:true},
           concept:{ko:'sin45°=√2/2이므로 나누면 √2를 곱하는 것과 같습니다 — 46÷sin45°는 46√2입니다.',
             en:'Since sin45° = √2/2, dividing by it is the same as multiplying by √2 — 46÷sin45° is 46√2.',
             zh:'因为sin45°=√2/2，除以它就等于乘以√2——46÷sin45°是46√2。'}},
          {id:3,label:{ko:'거꾸로 — 2R에서 변 구하기(실전)',en:'reverse — find the side from 2R (main)',zh:'反过来——由2R求边(实战)'},params:{mode:'reverse',wide:true},
           concept:{ko:'이번엔 2R에서 변을 거꾸로 구합니다. a = 2R×sinA이니 A=90°면 a=2R, A=45°면 2R의 반에 √2를 곱합니다.',
             en:'This time work back from 2R: a = 2R×sinA, so A=90° gives a=2R and A=45° gives half of 2R times √2.',
             zh:'这次由2R倒推边长：a = 2R×sinA，A=90°时a=2R，A=45°时是2R的一半乘√2。'}}] },

MD56:{ name:{ko:'코사인법칙',en:'Law of Cosines',zh:'余弦定理'}, gen:'md56_lawOfCosines', prereq:['MD39'],
  unit:'M-56',
  concept:{ko:'코사인법칙 a²=b²+c²-2bc·cosA — 두 변과 낀각을 알면 나머지 한 변을 구합니다. cos90°=0이면 피타고라스 정리와 같아지고, 60°·120°는 정수 삼조로 딱 떨어지는 경우만 다룹니다.',
    en:'The law of cosines a²=b²+c²-2bc·cosA — knowing two sides and the included angle gives the third side. cos90°=0 reduces it to the Pythagorean theorem; 60° and 120° use only the cases landing on integer triples.',
    zh:'余弦定理a²=b²+c²-2bc·cosA——已知两边及夹角，就能求出第三边。cos90°=0时就变成勾股定理；60°和120°只处理刚好得到整数三元组的情形。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'90°(연습, 피타고라스와 같음)',en:'90° (practice, same as Pythagoras)',zh:'90°(练习，与勾股定理相同)'},params:{mode:'right',wide:true}},
          {id:2,label:{ko:'60°',en:'60°',zh:'60°'},params:{mode:'sixty'},
           concept:{ko:'cos60°=1/2이므로 마지막 항이 −bc가 됩니다 — a²=b²+c²−bc입니다.',
             en:'Since cos60° = 1/2, the last term becomes −bc: a² = b²+c²−bc.',
             zh:'因为cos60°=1/2，最后一项变成−bc：a²=b²+c²−bc。'}},
          {id:3,label:{ko:'120°(실전)',en:'120° (main)',zh:'120°(实战)'},params:{mode:'oneTwenty'},
           concept:{ko:'cos120°=−1/2이므로 마지막 항의 부호가 **더하기**로 바뀝니다 — a²=b²+c²+bc입니다.',
             en:'Since cos120° = −1/2, the last term turns into a plus: a² = b²+c²+bc.',
             zh:'因为cos120°=−1/2，最后一项变成加号：a²=b²+c²+bc。'}}] },

MD57:{ name:{ko:'삼각함수의 최대·최소와 주기',en:'Trig Max/Min & Period',zh:'三角函数的最大值·最小值与周期'}, gen:'md57_trigMaxMinPeriod', prereq:['MD39'],
  unit:'M-57',
  concept:{ko:'y=a·sin(bx)+c의 최댓값은 a+c, 최솟값은 c-a입니다(진폭 a가 위아래로 흔들리는 범위). 주기는 sin·cos가 2π÷b, tan은 π÷b — π의 몇 배인지 기약분수로 나타냅니다.',
    en:'For y=a·sin(bx)+c, the max is a+c and the min is c-a (the amplitude a swings up and down). The period is 2π÷b for sin/cos, but π÷b for tan — express it as a reduced fraction times π.',
    zh:'y=a·sin(bx)+c的最大值是a+c，最小值是c-a(振幅a上下摆动的范围)。周期sin·cos是2π÷b，tan是π÷b——用最简分数表示是π的几倍。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'최댓값·최솟값(연습, 2다칸)',en:'max & min (practice, 2 slots)',zh:'最大值·最小值(练习，2格)'},params:{mode:'maxmin',wide:true}},
          {id:2,label:{ko:'주기(sin·cos, 분수)',en:'period (sin/cos, fraction)',zh:'周期(sin·cos，分数)'},params:{mode:'period',wide:true},
           concept:{ko:'sin·cos의 주기는 2π÷b입니다. π의 몇 배인지 기약분수로 적습니다 — y=sin(30x)의 주기는 2π/30 = π/15입니다.',
             en:'The period of sin and cos is 2π÷b, written as a reduced fraction of π — y=sin(30x) has period 2π/30 = π/15.',
             zh:'sin与cos的周期是2π÷b，写成π的最简分数——y=sin(30x)的周期是2π/30=π/15。'}},
          {id:3,label:{ko:'최대최소·주기·tan 혼합(실전)',en:'max/min, period & tan mixed (main)',zh:'最大最小·周期·tan混合(实战)'},params:{mode:'wide'},
           concept:{ko:'tan은 주기가 π÷b로 다릅니다. sin·cos인지 tan인지부터 보고 2π나 π 중 맞는 것을 나눕니다.',
             en:'tan has period π÷b instead: check whether it is sin/cos or tan, then divide the right one of 2π or π.',
             zh:'tan的周期是π÷b：先看是sin/cos还是tan，再用2π或π去除。'}}] },

MD58:{ name:{ko:'0/0 유리화형 극한',en:'Limits via Rationalization',zh:'0/0型有理化极限'}, gen:'md58_limitRationalize', prereq:['MD43'],
  unit:'M-58',
  concept:{ko:'근호가 있는 0/0 꼴은 켤레(같은 항에서 부호만 반대인 식)를 분모·분자에 곱해 근호를 없앱니다 — 그러면 (x-a)가 약분됩니다.',
    en:'For a 0/0 form with a root, multiply top and bottom by the conjugate (the same expression with the opposite sign) to clear the root — then (x-a) cancels.',
    zh:'带根号的0/0型，把分子分母都乘以共轭式(同项但符号相反的式子)来去掉根号——这样(x-a)就能约掉。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'분모에 근호(연습, 정수)',en:'root in the denominator (practice, integer)',zh:'根号在分母(练习，整数)'},params:{mode:'denomRoot'}},
          {id:2,label:{ko:'분자에 근호(분수)',en:'root in the numerator (fraction)',zh:'根号在分子(分数)'},params:{mode:'numRoot'},
           concept:{ko:'분자에 근호가 있으면 켤레를 곱해 분자가 (x−a)로 약분됩니다. 남은 분모의 근호값이 답의 분모가 됩니다 — √(x−1)−2 꼴은 1/(2+2)=1/4입니다.',
             en:'When the radical is on top, multiplying by the conjugate cancels the numerator to (x−a) and the root’s value is left underneath — √(x−1)−2 gives 1/(2+2)=1/4.',
             zh:'根号在分子时乘以共轭式，分子约成(x−a)，根号的值留在分母——√(x−1)−2得1/(2+2)=1/4。'}},
          {id:3,label:{ko:'혼합(더 큰 범위, 실전)',en:'mixed (wider range, main)',zh:'混合(更大范围，实战)'},params:{mode:'wide'},
           concept:{ko:'근호가 분자에 있든 분모에 있든 켤레를 곱하는 것은 같습니다. 근호가 분모면 답이 정수, 분자면 분수로 나옵니다.',
             en:'Whether the radical is on top or underneath, you still multiply by the conjugate — a radical underneath gives a whole number, one on top gives a fraction.',
             zh:'不论根号在分子还是分母，都是乘以共轭式——在分母时答案是整数，在分子时是分数。'}}] },

MD59:{ name:{ko:'연속조건 상수 결정',en:'Continuity — Determining Constants',zh:'连续条件·确定常数'}, gen:'md59_continuityConstant', prereq:['MD43'],
  unit:'M-59',
  concept:{ko:'함수가 한 점에서 연속이려면 그 점의 함숫값과 그 점에서의 극한값이 같아야 합니다 — 미정계수는 그 극한값과 같게 두면 구해집니다.',
    en:'For a function to be continuous at a point, the function value there must equal the limit there — solve for the unknown constant by setting it equal to that limit.',
    zh:'函数在某点连续，需要该点的函数值等于该点的极限值——把待定常数设为等于那个极限值即可求出。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'제곱 차 인수분해형(연습)',en:'difference-of-squares form (practice)',zh:'平方差因式分解型(练习)'},params:{mode:'basic',wide:true}},
          {id:2,label:{ko:'일반 인수분해형',en:'general factoring form',zh:'一般因式分解型'},params:{mode:'quadraticPiece',wide:true},
           concept:{ko:'분모가 0이 되는 자리에서는 분자를 인수분해해 약분한 뒤 대입합니다. 그 극한값이 곧 k입니다 — (x²−8x+12)/(x−6)은 x−2라 x=6에서 4입니다.',
             en:'Where the bottom becomes 0, factor the top, cancel and substitute — that limit is k: (x²−8x+12)/(x−6) is x−2, which is 4 at x=6.',
             zh:'在分母为0的点先把分子因式分解、约分后代入，这个极限值就是k：(x²−8x+12)/(x−6)化成x−2，x=6时为4。'}},
          {id:3,label:{ko:'구간별 일차함수 경계 맞추기(실전)',en:'match piecewise-linear boundary (main)',zh:'分段一次函数边界匹配(实战)'},params:{mode:'twoPiece',wide:true},
           concept:{ko:'구간이 나뉘는 x에서 두 식의 값이 같아야 이어집니다. 양쪽에 그 x를 넣어 등식을 세우고 b를 구합니다.',
             en:'At the point where the pieces meet, both formulas must give the same value: put that x into each side and solve for b.',
             zh:'在分段点上两个式子的值必须相同：把该x代入两边列出等式求b。'}}] },

MD60:{ name:{ko:'극값(극대·극소)',en:'Extrema (Local Max & Min)',zh:'极值(极大值·极小值)'}, gen:'md60_extrema', prereq:['MD44'],
  unit:'M-60',
  concept:{ko:'f\'(x)=0이 되는 x가 극값을 갖는 자리입니다(부호가 +에서 -로 바뀌면 극대, -에서 +로 바뀌면 극소). 그 x를 f(x)에 다시 대입하면 극댓값·극솟값이 나옵니다.',
    en:'The x-values where f\'(x)=0 are where extrema occur (sign + to - is a local max, - to + is a local min). Substituting that x back into f(x) gives the local max/min values.',
    zh:'f\'(x)=0的x就是取极值的位置(符号由+变-是极大，由-变+是极小)。把那个x代回f(x)就能得到极大值·极小值。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'극값을 갖는 x좌표(연습, 2다칸)',en:'x-coordinates of extrema (practice, 2 slots)',zh:'取极值的x坐标(练习，2格)'},params:{mode:'points'}},
          {id:2,label:{ko:'극댓값·극솟값',en:'local max & min values',zh:'极大值·极小值'},params:{mode:'values'},
           concept:{ko:'f′(x)=0인 x를 구한 뒤 그 x를 **f(x)에 다시 넣어** 극댓값·극솟값을 구합니다. 왼쪽 x가 극대, 오른쪽 x가 극소입니다(x³의 계수가 양수일 때).',
             en:'Find the x values where f′(x)=0, then put them back into f(x) for the maximum and minimum — with a positive x³ coefficient the left one is the maximum.',
             zh:'先求f′(x)=0的x，再把它代回f(x)求极大值与极小值——x³系数为正时左边的是极大值。'}},
          {id:3,label:{ko:'더 큰 범위(실전)',en:'wider range (main)',zh:'更大范围(实战)'},params:{mode:'wide'},
           concept:{ko:'x³의 계수가 1이 아니어도 같습니다. f′(x)=0을 풀고 두 x를 f(x)에 넣어 값을 비교합니다.',
             en:'A non-1 coefficient on x³ changes nothing: solve f′(x)=0 and substitute both x values into f(x).',
             zh:'x³的系数不是1也一样：解f′(x)=0，把两个x代入f(x)比较。'}}] },

MD61:{ name:{ko:'곡선과 x축 사이의 넓이',en:'Area Between a Curve & the x-axis',zh:'曲线与x轴之间的面积'}, gen:'md61_areaUnderCurve', prereq:['MD46'],
  unit:'M-61',
  concept:{ko:'곡선과 x축으로 둘러싸인 넓이는 두 교점을 구간으로 삼은 정적분값입니다 — 원시함수 F를 구해 F(오른쪽 교점)-F(왼쪽 교점)을 계산합니다.',
    en:'The area enclosed by a curve and the x-axis is the definite integral over the interval between the two intersection points — find the antiderivative F, then compute F(right point)-F(left point).',
    zh:'曲线与x轴围成的面积，就是以两个交点为区间的定积分——求出原函数F后计算F(右交点)-F(左交点)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'양의 교점(연습)',en:'positive intersection points (practice)',zh:'正的交点(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'음수 교점 포함',en:'includes a negative intersection point',zh:'含负交点'},params:{mode:'wide'},
           concept:{ko:'교점이 음수여도 방법은 같습니다. F를 구해 F(오른쪽 교점)−F(왼쪽 교점)을 계산하면 됩니다.',
             en:'Negative intersection points change nothing: find F and work out F(right) − F(left).',
             zh:'交点是负数也一样：求出F后计算F(右交点)−F(左交点)。'}},
          {id:3,label:{ko:'더 큰 범위(실전)',en:'wider range (main)',zh:'更大范围(实战)'},params:{mode:'wider'},
           concept:{ko:'수가 커져도 두 걸음은 같습니다. 원시함수 F를 먼저 구하고, 두 교점을 넣어 뺍니다.',
             en:'Bigger numbers keep the same two steps: get the antiderivative F first, then subtract its values at the two intersections.',
             zh:'数变大步骤不变：先求原函数F，再代入两个交点相减。'}}] },

MD62:{ name:{ko:'속도와 거리 활용',en:'Velocity & Distance Applications',zh:'速度与距离应用'}, gen:'md62_velocityDistance', prereq:['MD46'],
  unit:'M-62',
  concept:{ko:'속도는 위치함수를 미분한 것(s\'(t)), 이동 거리는 속도를 적분한 것입니다 — 속도가 항상 0 이상이면 거리는 위치의 변화량과 같습니다.',
    en:'Velocity is the derivative of the position function(s\'(t)); distance traveled is the integral of velocity — when velocity stays nonnegative, distance equals the change in position.',
    zh:'速度是位置函数的导数(s\'(t))，移动距离是速度的积分——当速度始终不小于0时，距离就等于位置的变化量。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'위치→속도(연습)',en:'position → velocity (practice)',zh:'位置→速度(练习)'},params:{mode:'velocity',wide:true}},
          {id:2,label:{ko:'속도→거리(0부터 T까지)',en:'velocity → distance (0 to T)',zh:'速度→距离(0到T)'},params:{mode:'distance',wide:true},
           concept:{ko:'속도를 적분하면 이동 거리입니다. 0부터 T까지 v(t)를 적분합니다 — v=10t+2면 5T²+2T이고 T=6에서 192입니다.',
             en:'Integrating velocity gives distance travelled: integrate v(t) from 0 to T — v=10t+2 gives 5T²+2T, which is 192 at T=6.',
             zh:'对速度积分得到路程：从0到T对v(t)积分——v=10t+2得5T²+2T，T=6时是192。'}},
          {id:3,label:{ko:'구간 [t1,t2] 거리(실전)',en:'distance over [t1,t2] (main)',zh:'区间[t1,t2]的距离(实战)'},params:{mode:'wide'},
           concept:{ko:'구간이 0부터가 아니면 원시함수에 두 끝을 넣어 뺍니다 — ∫[2,3]은 S(3)−S(2)입니다.',
             en:'When the interval does not start at 0, substitute both ends into the antiderivative and subtract: ∫[2,3] is S(3) − S(2).',
             zh:'区间不是从0开始时，把两个端点代入原函数再相减：∫[2,3]是S(3)−S(2)。'}}] },

/* ── NL 수의 나라 (유아 5~7세) ─────────────────────────────
   engine/threads/nl.js의 16개 생성기 등록(2026-08-29). 생성기는 이미 완성돼
   town-game(BASIC 등급, data/units/N-01~N-15.js)에서 쓰이고 있었지만 여기 threads.js에
   등록된 적이 없어 drill.html 문제은행·인쇄에는 한 번도 노출되지 않았다.
   ⚠️ 여기 unit N-xx는 회의상 존재하지 않는다 — data/units/의 'N-01'~'N-15'는 완전히 다른
   레지스트리(마을 게임 유닛 id)라 unit 필드에 재사용하면 혼동을 준다. 대신 다른 스레드
   다수처럼 unit 필드를 생략했다. mode/level 값은 전부 nl.js 코드가 실제로 읽는 값만 사용. */
NL1:{ name:{ko:'수 세기와 개수',en:'Counting & Quantity',zh:'数数与数量'}, gen:'nl1_count', prereq:[],
  instr:{ko:'알맞은 개수를 세어 쓰시오.',en:'Count and write how many.',zh:'数一数，写出个数。'},
  concept:{ko:'물건을 하나씩 짚어 가며 세면 모두 몇 개인지 알 수 있어요. 사과를 하나, 둘, 셋 세면 모두 3개예요.',
    en:'Point to each thing and count one by one to find how many there are in all. Counting apples one, two, three tells you there are 3.',
    zh:'一个一个指着数，就能知道一共有多少个。数苹果时数一、二、三，一共就是3个。'},
  widgets:['tapCount','tapMake'],
  levels:[{id:1,label:{ko:'세기(5까지)',en:'Counting (to 5)',zh:'数数(到5)'},params:{mode:'count',level:'practice'}},
          {id:2,label:{ko:'세기(9까지)',en:'Counting (to 9)',zh:'数数(到9)'},params:{mode:'count',level:'main'}},
          {id:3,label:{ko:'개수만큼 만들기',en:'Make that many',zh:'做出对应的数量'},params:{mode:'make',level:'main'},
           concept:{ko:'세는 것과 반대로, 이번엔 말한 수만큼 만들어요. 하나씩 놓으며 세다가 그 수가 되면 멈춰요.',
             en:'This time you make the amount instead of counting it: place them one at a time and stop when you reach the number.',
             zh:'这次不是数数而是做出那么多：一个一个放，数到那个数就停。'}}] },
NL2:{ name:{ko:'모으기와 가르기',en:'Compose & Split',zh:'合与分'}, gen:'nl4_bond', prereq:[],
  instr:{ko:'모으거나 갈라서 빈칸을 채우시오.',en:'Gather or split to fill the blank.',zh:'合起来或分开，填空。'},
  concept:{ko:'두 수를 모으면 하나의 큰 수가 되고, 큰 수는 다시 두 수로 가를 수 있어요. 4개와 2개를 모으면 6개, 6개는 4개와 2개로 갈라져요.',
    en:'Two numbers join into one bigger number, and a bigger number can split back into two. 4 and 2 join to make 6, and 6 splits into 4 and 2.',
    zh:'两个数合起来变成一个更大的数，大数也能再分成两个数。4和2合起来是6，6能分成4和2。'},
  widgets:['numberBond'],
  levels:[{id:1,label:{ko:'가르기(5까지)',en:'Split (to 5)',zh:'分一分(到5)'},params:{mode:'split',level:'practice'}},
          {id:2,label:{ko:'가르기(9까지, 0 포함)',en:'Split (to 9, with 0)',zh:'分一分(到9，含0)'},params:{mode:'split',level:'main'}},
          {id:3,label:{ko:'모으기',en:'Join',zh:'合一合'},params:{mode:'join',level:'main'},
           concept:{ko:'두 묶음을 모으면 하나의 큰 수가 돼요. 5개와 1개를 모으면 6개예요.',
             en:'Putting two groups together makes one bigger number: 5 and 1 together make 6.',
             zh:'把两堆合起来就成为一个更大的数：5个和1个合起来是6个。'}}] },
NL3:{ name:{ko:'무당벌레 가르기',en:'Ladybug Split',zh:'瓢虫分点'}, gen:'nl4_ladybug', prereq:['NL2'],
  instr:{ko:'무당벌레 점을 좌우로 갈라 쓰시오.',en:'Split the ladybug dots left and right.',zh:'把瓢虫的点左右分开写。'},
  concept:{ko:'전체 개수를 알면 한쪽을 보고 다른 쪽이 몇 개인지 구할 수 있어요. 점이 7개인데 왼쪽 날개에 3개면 오른쪽 날개는 4개예요.',
    en:'If you know the whole amount, seeing one part tells you the other part. With 7 spots total, if the left wing has 3, the right wing has 4.',
    zh:'知道总数后，看到一部分就能算出另一部分是多少。一共7个点，左边翅膀有3个，右边翅膀就是4个。'},
  widgets:['numberBond'],
  levels:[{id:1,label:{ko:'점 5까지',en:'Spots to 5',zh:'点数到5'},params:{level:'practice'}},
          {id:2,label:{ko:'점 9까지',en:'Spots to 9',zh:'点数到9'},params:{level:'main'}}] },
NL4:{ name:{ko:'수의 순서',en:'Number Order',zh:'数的顺序'}, gen:'nl2_seq', prereq:[],
  instr:{ko:'순서에 맞게 빈칸의 수를 쓰시오.',en:'Write the missing number in order.',zh:'按顺序写出空格里的数。'},
  concept:{ko:'수는 정해진 순서대로 나열돼요. 1, 2, 3, 4 다음에는 5가 와요.',
    en:'Numbers follow a fixed order. After 1, 2, 3, 4 comes 5.',
    zh:'数字按照固定的顺序排列。1、2、3、4后面是5。'},
  widgets:['seqFill','dotToDot'],
  levels:[{id:1,label:{ko:'수열 빈칸(쉬움)',en:'Fill the blank (easy)',zh:'数列填空(简单)'},params:{mode:'gap',level:'practice'}},
          {id:2,label:{ko:'수열 빈칸(거꾸로·뛰어세기)',en:'Fill the blank (backward/skip)',zh:'数列填空(倒数·跳数)'},params:{mode:'gap',level:'main'}},
          {id:3,label:{ko:'점 잇기',en:'Connect the dots',zh:'连点成画'},params:{mode:'dots',level:'main'},
           concept:{ko:'1부터 차례대로 점을 이으면 그림이 나타나요. 다음에 올 수를 찾아 이어 가요.',
             en:'Join the dots in order from 1 and a picture appears — find the next number each time.',
             zh:'从1开始按顺序连点，图案就出现了——每次找出下一个数。'}}] },
NL5:{ name:{ko:'이웃 수 더하기',en:'Neighbor Sums',zh:'相邻数相加'}, gen:'nl9_chain', prereq:['NL2'],
  instr:{ko:'이웃한 두 수를 더해 쓰시오.',en:'Add the two neighbours and write the sum.',zh:'把相邻两数相加写出来。'},
  concept:{ko:'이웃한 두 수를 더하면 그 위의 수가 돼요. 2와 3을 더하면 위에 놓일 수는 5예요.',
    en:'Adding two neighboring numbers gives the number that sits above them. Adding 2 and 3 gives 5.',
    zh:'相邻两个数相加，就是上面那个数。2加3等于5，就是上面那块。'},
  widgets:['pyramid','tapCount'],
  levels:[{id:1,label:{ko:'수 피라미드(쉬움)',en:'Number pyramid (easy)',zh:'数字金字塔(简单)'},params:{mode:'pyramid',level:'practice'}},
          {id:2,label:{ko:'수 피라미드(어려움)',en:'Number pyramid (hard)',zh:'数字金字塔(较难)'},params:{mode:'pyramid',level:'main'}},
          {id:3,label:{ko:'동전 뛰어세기(10원)',en:'Skip-count coins (by 10)',zh:'跳数硬币(每次10)'},params:{mode:'coins',level:'main'},
           concept:{ko:'10원짜리는 10, 20, 30…처럼 10씩 뛰어세요. 여덟 닢이면 80원이에요.',
             en:'Ten-won coins are counted in tens — 10, 20, 30 … — so eight coins make 80 won.',
             zh:'10元硬币要10、20、30…每次跳10地数，八枚就是80元。'}}] },
NL6:{ name:{ko:'10까지의 수 관계',en:'Relations to 10',zh:'10以内数的关系'}, gen:'nl7_relation', prereq:['NL2'],
  instr:{ko:'10까지의 수에서 빈칸을 채우시오.',en:'Fill the blank with numbers up to 10.',zh:'用10以内的数填空。'},
  concept:{ko:'어떤 수에 얼마를 더해야 10이 되는지, 또 1 크거나 작은 수가 무엇인지 알면 수 사이의 관계가 보여요. 7의 10 짝꿍은 3이고, 7보다 1 큰 수는 8이에요.',
    en:"Knowing how much to add to reach 10, and what number is 1 more or less, shows how numbers relate. 7's partner to 10 is 3, and the number 1 more than 7 is 8.",
    zh:'知道一个数要加多少才能凑成10，还有比它大1或小1的数是几，就能看出数字间的关系。7凑十的好朋友是3，比7大1的数是8。'},
  widgets:['tenframe','tapCount'],
  levels:[{id:1,label:{ko:'10의 짝꿍',en:"Partner to 10",zh:'凑十好朋友'},params:{mode:'tenpair'}},
          {id:2,label:{ko:'1 큰 수·1 작은 수',en:'1 more / 1 less',zh:'大1·小1'},params:{mode:'oneStep'},
           concept:{ko:'1 큰 수는 바로 다음에 오는 수, 1 작은 수는 바로 앞에 오는 수예요 — 7보다 1 작은 수는 6이에요.',
             en:'One more is the very next number and one less is the one just before: one less than 7 is 6.',
             zh:'大1就是紧接着的下一个数，小1就是前面那个数：比7小1是6。'}}] },
NL7:{ name:{ko:'이어 세기와 점 매칭',en:'Counting On & Dot Match',zh:'接着数与点数配对'}, gen:'nl11_arrange', prereq:['NL4'],
  instr:{ko:'이어 세어 빈칸을 채우시오.',en:'Count on and fill the blank.',zh:'接着数，填空。'},
  concept:{ko:'수를 순서대로 이어 세면 다음에 올 수를 알 수 있고, 같은 개수를 나타내는 숫자와 점 그림은 서로 짝이 돼요. 5 다음은 6이고, 숫자 5는 점 5개와 짝이에요.',
    en:'Counting on in order tells you what comes next, and a number matches the dot picture showing the same amount. After 5 comes 6, and the number 5 matches 5 dots.',
    zh:'按顺序接着数就能知道下一个是几，表示相同数量的数字和点图是一对。5后面是6，数字5和5个点的图是一对。'},
  widgets:['seqFill','matchLine'],
  levels:[{id:1,label:{ko:'이어 세기(쉬움)',en:'Count on (easy)',zh:'接着数(简单)'},params:{mode:'seq',level:'practice'}},
          {id:2,label:{ko:'이어 세기(어려움)',en:'Count on (hard)',zh:'接着数(较难)'},params:{mode:'seq',level:'main'}},
          {id:3,label:{ko:'수-점 매칭',en:'Match numbers to dots',zh:'数字点图配对'},params:{mode:'match',level:'main'},
           concept:{ko:'같은 개수를 나타내는 숫자와 점 그림을 짝지어요. 점을 세어 보면 어느 숫자와 짝인지 알 수 있어요.',
             en:'Match each number with the dot picture showing the same amount — count the dots to find its partner.',
             zh:'把数字和表示相同数量的点图配对——数一数点就知道和哪个数字是一对。'}}] },
NL8:{ name:{ko:'몇째와 칸 세기',en:'Ordinal & Counting Boxes',zh:'第几与数格子'}, gen:'nl3_ordinal', prereq:[],
  instr:{ko:'몇째인지, 몇 칸인지 세어 쓰시오.',en:'Count which place, or how many spaces.',zh:'数一数第几个、几格。'},
  concept:{ko:"순서를 셀 때는 '몇째'라는 말을 쓰고, 정해진 개수만큼 정확히 세어 표시할 수 있어요. 왼쪽에서 셋째 칸을 짚거나, 정확히 4칸만 색칠할 수 있어요.",
    en:"We use words like 'third' to count order, and we can mark an exact number of things by counting carefully. Point to the third box from the left, or paint exactly 4 boxes.",
    zh:'数顺序时会用"第几"这样的说法，也能准确数出规定的数量并标记出来。可以指出从左边数第三格，也能正好涂4格。'},
  widgets:['gridPaint'],
  levels:[{id:1,label:{ko:'몇째 찾기(쉬움)',en:'Find the ordinal (easy)',zh:'找第几个(简单)'},params:{mode:'position',level:'practice'}},
          {id:2,label:{ko:'몇째 찾기(어려움)',en:'Find the ordinal (hard)',zh:'找第几个(较难)'},params:{mode:'position',level:'main'}},
          {id:3,label:{ko:'정확히 칠하기',en:'Paint the exact count',zh:'正好涂色'},params:{mode:'paint',level:'main'},
           concept:{ko:'말한 개수만큼만 정확히 칠해요. 하나씩 세면서 칠하다가 그 수가 되면 멈춰요.',
             en:'Colour in exactly as many squares as asked: count as you go and stop at that number.',
             zh:'只涂出说的那么多格：一边数一边涂，数到那个数就停。'}}] },
NL9:{ name:{ko:'줄서기와 계단',en:'Lining Up & Stairs',zh:'排队与台阶'}, gen:'nl5_story', prereq:['NL8'],
  instr:{ko:'이야기를 읽고 답을 쓰시오.',en:'Read the story and write the answer.',zh:'读一读，写出答案。'},
  concept:{ko:'생활 속 줄이나 계단에서도 순서를 세어 몇째인지 알 수 있어요. 줄의 왼쪽에서 둘째 친구, 아래에서 셋째 계단처럼요.',
    en:'Even in everyday lines or staircases, counting the order tells you which one it is — like the second friend from the left, or the third step from the bottom.',
    zh:'在生活中排队或台阶上，也能数出顺序是第几。比如队伍左边数第二个朋友，或者从下面数第三级台阶。'},
  widgets:['storyCard'],
  levels:[{id:1,label:{ko:'줄서기(쉬움)',en:'Lining up (easy)',zh:'排队(简单)'},params:{mode:'lineup',level:'practice'}},
          {id:2,label:{ko:'줄서기(어려움)',en:'Lining up (hard)',zh:'排队(较难)'},params:{mode:'lineup',level:'main'}},
          {id:3,label:{ko:'계단 몇째',en:'Which step',zh:'第几级台阶'},params:{mode:'stairs',level:'main'},
           concept:{ko:'계단은 아래에서부터 세어요. 첫째 칸이 맨 아래이고 위로 갈수록 하나씩 늘어나요.',
             en:'Stairs are counted from the bottom: the first step is the lowest and each step up adds one.',
             zh:'楼梯要从下往上数：第一级在最下面，往上每级加1。'}}] },
NL10:{ name:{ko:'양팔저울 비교',en:'Balance Scale',zh:'天平比较'}, gen:'nl12_scale', prereq:[],
  instr:{ko:'저울을 보고 더 무거운 쪽을 고르시오.',en:'Look at the scale and pick the heavier side.',zh:'看天平，选出更重的一边。'},
  concept:{ko:'양쪽 개수를 비교하면 어느 쪽이 더 많은지(무거운지), 더 적은지(가벼운지) 알 수 있어요. 왼쪽에 5개, 오른쪽에 3개면 왼쪽이 더 무거워요.',
    en:'Comparing the amounts on each side shows which is more (heavier) and which is less (lighter). With 5 on the left and 3 on the right, the left side is heavier.',
    zh:'比较两边的数量，就能知道哪边更多(更重)，哪边更少(更轻)。左边5个、右边3个，左边就更重。'},
  widgets:['balanceScale'],
  levels:[{id:1,label:{ko:'저울 비교(5까지)',en:'Balance scale (to 5)',zh:'天平比较(到5)'},params:{level:'practice'}},
          {id:2,label:{ko:'저울 비교(9까지)',en:'Balance scale (to 9)',zh:'天平比较(到9)'},params:{level:'main'}}] },
NL11:{ name:{ko:'수 기계 규칙',en:'Number Machine Rules',zh:'数字机器规则'}, gen:'nl8_machine', prereq:['NL5'],
  instr:{ko:'수 기계의 규칙을 찾아 빈칸을 채우시오.',en:'Find the machine\u2019s rule and fill the blank.',zh:'找出数字机器的规律，填空。'},
  concept:{ko:"정해진 규칙대로 수를 넣으면 규칙에 따라 바뀐 수가 나와요. 규칙이 '+2'면 3을 넣었을 때 5가 나와요.",
    en:"When you put a number into a machine with a fixed rule, a changed number comes out following that rule. If the rule is '+2', putting in 3 gives you 5.",
    zh:'按照固定的规则放入一个数，就会按规则变成另一个数出来。规则是"+2"时，放入3就会出来5。'},
  widgets:['numberMachine'],
  levels:[{id:1,label:{ko:'규칙 보임(쉬움)',en:'Rule shown (easy)',zh:'规则可见(简单)'},params:{mode:'apply',level:'practice'}},
          {id:2,label:{ko:'규칙 보임(어려움)',en:'Rule shown (hard)',zh:'规则可见(较难)'},params:{mode:'apply',level:'main'}},
          {id:3,label:{ko:'숨은 규칙 추리',en:'Guess the hidden rule',zh:'推理隐藏规则'},params:{mode:'guess',level:'main'},
           concept:{ko:'이번엔 규칙이 숨어 있어요. 앞의 예시에서 들어간 수와 나온 수를 견주어 규칙을 먼저 찾아요.',
             en:'This time the rule is hidden: compare the numbers going in and coming out in the examples to work it out first.',
             zh:'这次规则是隐藏的：先比较例子里进去的数和出来的数，找出规则。'}}] },
NL12:{ name:{ko:'길 잇기와 십자 퍼즐',en:'Path & Cross Puzzle',zh:'连路与十字谜题'}, gen:'nl13_puzzle', prereq:['NL4'],
  instr:{ko:'길을 잇거나 십자 칸을 채우시오.',en:'Join the path, or fill the cross.',zh:'连一连路线，或填十字格。'},
  concept:{ko:'순서를 따라 길을 잇거나, 위와 아래를 더한 값이 왼쪽과 오른쪽을 더한 값과 같도록 빈칸을 채울 수 있어요. 위 2, 아래 3이면 둘을 더한 5가 왼쪽 오른쪽의 합과 같아야 해요.',
    en:'You can connect a path in order, or fill a blank so the top plus the bottom equals the left plus the right. If the top is 2 and the bottom is 3, their sum 5 must match the left-right sum.',
    zh:'可以按顺序连接道路，也能填空让上加下等于左加右。上面是2、下面是3，它们的和5要等于左右两边的和。'},
  widgets:['dotToDot','crossSum'],
  levels:[{id:1,label:{ko:'길 잇기',en:'Connect the path',zh:'连路'},params:{mode:'path',level:'main'}},
          {id:2,label:{ko:'십자 퍼즐(쉬움)',en:'Cross puzzle (easy)',zh:'十字谜题(简单)'},params:{mode:'cross',level:'practice'},
           concept:{ko:'위와 아래를 더한 수가 왼쪽과 오른쪽을 더한 수와 같아야 해요. 아래 3, 왼쪽 4, 오른쪽 2면 4+2=6이니 위는 3이에요.',
             en:'Top plus bottom must equal left plus right. With bottom 3, left 4 and right 2, the sides make 6, so the top is 3.',
             zh:'上面加下面要等于左边加右边。下面3、左边4、右边2时两边是6，所以上面是3。'}},
          {id:3,label:{ko:'십자 퍼즐(어려움)',en:'Cross puzzle (hard)',zh:'十字谜题(较难)'},params:{mode:'cross',level:'main'}}] },
NL13:{ name:{ko:'이야기 셈과 분류',en:'Story Math & Sorting',zh:'故事算术与分类'}, gen:'nl15_logic', prereq:['NL2'],
  instr:{ko:'이야기를 읽고 세어서 답을 쓰시오.',en:'Read, count and write the answer.',zh:'读一读，数一数，写出答案。'},
  concept:{ko:'이야기 속에서 더 받거나 나눠 준 상황을 듣고 남은 개수를 구하거나, 섞인 것을 종류대로 나눠 세어 볼 수 있어요. 4개가 있었는데 2개를 받으면 모두 6개예요.',
    en:'You can figure out how many are left after a story says something was given or received, or sort mixed things by kind and count them. If there were 4 and 2 more were given, there are 6 in all.',
    zh:'听故事里得到或送出的情况，算出剩下多少，也能把混在一起的东西按种类分开数一数。原来有4个，又得到2个，一共是6个。'},
  widgets:['storyCard','sortBasket'],
  levels:[{id:1,label:{ko:'이야기 셈(쉬움)',en:'Story math (easy)',zh:'故事算术(简单)'},params:{mode:'story',level:'practice'}},
          {id:2,label:{ko:'이야기 셈(어려움)',en:'Story math (hard)',zh:'故事算术(较难)'},params:{mode:'story',level:'main'}},
          {id:3,label:{ko:'분류하기',en:'Sort into baskets',zh:'分类装篮'},params:{mode:'sort',level:'main'},
           concept:{ko:'섞여 있는 것을 종류별로 나눠 담은 뒤, 물어본 종류만 세어요.',
             en:'Sort the mixed things into their kinds first, then count only the kind you were asked about.',
             zh:'先把混在一起的东西按种类分开，再只数被问到的那一种。'}}] },
NL14:{ name:{ko:'탤리로 수 만들기',en:'Build with Tally Marks',zh:'用计数符号做数'}, gen:'nl_tallybuild', prereq:[],
  instr:{ko:'탤리를 그려 수를 만드시오.',en:'Draw tally marks to make the number.',zh:'画计数符号表示这个数。'},
  concept:{ko:'막대를 하나씩 그어 수를 나타낼 수 있어요(탤리). 막대 4개를 그으면 4를 나타내요.',
    en:'You can show a number by drawing strokes one at a time — this is a tally mark. Drawing 4 strokes shows the number 4.',
    zh:'可以一笔一笔画出符号来表示数字，这叫计数符号。画4笔就表示4。'},
  widgets:['tallyBuild','matchLine'],
  levels:[{id:1,label:{ko:'탤리 만들기(쉬움)',en:'Build a tally (easy)',zh:'做计数符号(简单)'},params:{mode:'build',level:'practice'}},
          {id:2,label:{ko:'탤리 만들기(어려움)',en:'Build a tally (hard)',zh:'做计数符号(较难)'},params:{mode:'build',level:'main'}},
          {id:3,label:{ko:'수-탤리 매칭',en:'Match numbers to tallies',zh:'数字符号配对'},params:{mode:'match',level:'main'},
           concept:{ko:'같은 수를 나타내는 숫자와 탤리 그림을 짝지어요. 막대를 세어 보면 어느 숫자와 짝인지 알 수 있어요.',
             en:'Match each number with the tally picture that shows the same amount — count the strokes to find its partner.',
             zh:'把数字和表示相同数量的计数符号图配对——数一数笔画就知道和哪个数字是一对。'}}] },
NL15:{ name:{ko:'분류하고 세기',en:'Sort & Count',zh:'分类计数'}, gen:'nl10_data', prereq:[],
  instr:{ko:'종류별로 나누어 세어 쓰시오.',en:'Sort by kind and count each.',zh:'分类数一数，写出个数。'},
  concept:{ko:'섞여 있는 것을 종류별로 나눠 담으면 각각 몇 개인지 세거나 어느 쪽이 더 많은지 비교할 수 있어요. 사과 5개와 바나나 3개로 나누면 사과 바구니가 더 많아요.',
    en:'Sorting mixed things into groups lets you count how many of each kind, or compare which group has more. Sorted into 5 apples and 3 bananas, the apple basket has more.',
    zh:'把混在一起的东西按种类分开装，就能数出各有多少，或者比较哪边更多。分成5个苹果和3个香蕉，苹果篮子更多。'},
  widgets:['sortBasket'],
  levels:[{id:1,label:{ko:'분류하고 세기(쉬움)',en:'Sort & count (easy)',zh:'分类计数(简单)'},params:{mode:'sort',level:'practice'}},
          {id:2,label:{ko:'분류하고 세기(어려움)',en:'Sort & count (hard)',zh:'分类计数(较难)'},params:{mode:'sort',level:'main'}},
          {id:3,label:{ko:'더 많은 쪽 비교',en:'Compare which has more',zh:'比较更多的一边'},params:{mode:'compare',level:'main'},
           concept:{ko:'나눠 담은 두 바구니를 세어 보고 더 많은 쪽을 골라요.',
             en:'Count both baskets after sorting, then pick the one with more.',
             zh:'分好后数一数两个篮子，再选出更多的那个。'}}] },
NL16:{ name:{ko:'탤리 읽기와 규칙',en:'Read Tally & Patterns',zh:'读计数符号与规律'}, gen:'nl14_pattern', prereq:['NL14'],
  instr:{ko:'탤리를 읽고 규칙을 찾아 쓰시오.',en:'Read the tally and find the pattern.',zh:'读计数符号，找出规律。'},
  concept:{ko:'그어진 막대(탤리)를 세어 수를 읽거나, 화살표를 따라 1씩 커지거나 작아지는 규칙을 찾을 수 있어요. 화살표를 따라 3, 4, 5처럼 1씩 늘어나요.',
    en:'You can read a number by counting drawn tally strokes, or find a rule where numbers grow or shrink by 1 along an arrow. Following the arrow, numbers grow by 1 like 3, 4, 5.',
    zh:'可以数一数画好的计数符号来读出数字，也能找出沿箭头每次加1或减1的规律。沿着箭头，数字像3、4、5这样每次加1。'},
  widgets:['tallyBuild','seqFill'],
  levels:[{id:1,label:{ko:'탤리 읽기(쉬움)',en:'Read the tally (easy)',zh:'读计数符号(简单)'},params:{mode:'read',level:'practice'}},
          {id:2,label:{ko:'탤리 읽기(어려움)',en:'Read the tally (hard)',zh:'读计数符号(较难)'},params:{mode:'read',level:'main'}},
          {id:3,label:{ko:'화살표 규칙',en:'Arrow pattern rule',zh:'箭头规律'},params:{mode:'arrow',level:'main'},
           concept:{ko:'화살표를 따라가며 1씩 줄어들어요. 앞 칸의 탤리를 세고 하나를 덜어 내면 다음 칸이 돼요.',
             en:'Follow the arrows: each step goes down by one — count the tally before it and take one away.',
             zh:'顺着箭头每次减少1：数出前一格的计数符号再去掉一笔就是下一格。'}}] },

/* ── WP 문장제 (문장제-설계.md) ─────────────────────
   상황 하나(주체·대상·n1·n2·연산·의미유형·단위)에서 두 스레드가 파생된다.
   생성기는 engine/threads/wp.js. 의미 유형은 합병·첨가·구잔·구차 + 배수·등분·포함. */
WP1:{ name:{ko:'문장제 — 문제 이해',en:'Word Problems — Understand',zh:'应用题 — 理解题意'},
  gen:'wp1_understand', prereq:['AD1','SB1'],
  concept:{ko:'문장제는 계산부터 하는 게 아니라 먼저 읽어요. 주어진 것(문제가 알려 준 수)과 구하는 것(문제가 묻는 것)을 갈라 보면 무엇을 해야 할지 보여요. "민수는 8개, 지우는 3개 가지고 있어요"는 주어진 것이고, "민수는 지우보다 몇 개 더 많을까요?"가 구하는 것이에요.',
    en:'A word problem starts with reading, not calculating. Separate what is given (the numbers the problem tells you) from what is asked (what the problem wants). "Minsu has 8 and Jiwoo has 3" is given; "how many more does Minsu have?" is what is asked.',
    zh:'应用题要先读，不是先算。把已知的（题目给出的数）和要求的（题目问的）分开，就能看清该做什么。"民秀有8个，智友有3个"是已知的，"民秀比智友多几个"才是要求的。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'자연수 + − ×',en:'Whole numbers + - x',zh:'自然数 + - ×'},params:{range:'A'},
           concept:{ko:'주어진 것과 구하는 것을 먼저 갈라요. 문제에 나온 수라고 다 쓰는 것도 아니에요 — 나이나 버스 번호처럼 구하는 것과 이어지지 않는 수는 식에 넣지 않아요.',
             en:'First separate what you are given from what you are asked. Not every number in the story is used — an age or a bus number that has nothing to do with the question stays out of the equation.',
             zh:'先分清题目给了什么、问的是什么。题里出现的数并不都要用——像年龄、公交车号这种与所求无关的数不进算式。'}},
          {id:2,label:{ko:'자연수 + − × ÷',en:'Whole numbers + - x /',zh:'自然数 + - × ÷'},params:{range:'B'}},
          {id:3,label:{ko:'분수·소수 + −',en:'Fractions & decimals + -',zh:'分数·小数 + -'},params:{range:'C'}}] },
WP3:{ name:{ko:'문장제 — 연산 찾기',en:'Word Problems — Choose the Operation',zh:'应用题 — 选择运算'},
  gen:'wp3_operation', prereq:['WP1'],
  concept:{ko:'낱말만 보고 연산을 고르면 걸려요. "더 받았어요"는 더하기지만 "~보다 몇 개 더 많을까요?"는 둘 다 \'더\'가 들어가도 빼기예요. 상황이 늘어나는지, 줄어드는지, 몇 씩 몇 묶음인지를 보고 골라요.',
    en:'Choosing an operation by keywords alone will trip you up. "Got more" means adding, but "how many more than" is subtracting even though both say "more". Look at the situation: is it growing, shrinking, or so many in each of so many groups?',
    zh:'只看词语选运算会上当。"又得到了"是加法，但"比…多几个"虽然也有"多"，却要用减法。要看情况：是变多、变少，还是每几个一组、共几组。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'자연수 + − ×',en:'Whole numbers + - x',zh:'自然数 + - ×'},params:{range:'A'}},
          {id:2,label:{ko:'자연수 + − × ÷',en:'Whole numbers + - x /',zh:'自然数 + - × ÷'},params:{range:'B'}},
          {id:3,label:{ko:'분수·소수 + −',en:'Fractions & decimals + -',zh:'分数·小数 + -'},params:{range:'C'}}] },
WP4:{ name:{ko:'문장제 — 식으로 나타내기',en:'Word Problems — Write the Equation',zh:'应用题 — 列算式'},
  gen:'wp4_equation', prereq:['WP3'],
  concept:{ko:'연산을 골랐으면 이제 식으로 옮겨요. 수를 문제에 나온 차례대로 넣는 것이 먼저예요 — "20개 중 8개를 주었다"는 8 − 20이 아니라 20 − 8이에요. 문제에 나온 수라고 다 쓰는 것도 아니에요(나이·층수는 식에 들어가지 않아요). 뺄셈 상황은 덧셈식으로도 쓸 수 있어요: "8개 더 많다"는 8 + □ = 20이에요.',
    en:'Once you have chosen the operation, write it as a number sentence. Put the numbers in the order the problem gives them — "gave away 8 of the 20" is 20 - 8, not 8 - 20. And not every number in the story belongs in the sentence (an age or a floor number does not). A subtraction situation can also be written as an addition with a box: "8 more than" is 8 + [] = 20.',
    zh:'选好运算以后，就要写成算式。先按题目给出的顺序填数——"20个里送出8个"是20−8，不是8−20。题目里的数也不是都要用（年龄、楼层不进算式）。减法的情况还可以写成带□的加法：“多8个”就是8+□=20。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'자연수 + − ×',en:'Whole numbers + - x',zh:'自然数 + - ×'},params:{range:'A'}},
          {id:2,label:{ko:'자연수 + − × ÷',en:'Whole numbers + - x /',zh:'自然数 + - × ÷'},params:{range:'B'}},
          {id:3,label:{ko:'분수·소수 + −',en:'Fractions & decimals + -',zh:'分数·小数 + -'},params:{range:'C'}}] },
WP5:{ name:{ko:'문장제 — 점검하기',en:'Word Problems — Check Your Work',zh:'应用题 — 检查'},
  gen:'wp5_check', prereq:['WP4'],
  concept:{ko:'답을 구했으면 끝이 아니에요. 두 가지를 다시 봐요. 첫째, 연산을 바르게 골랐나 — 계산이 맞아도 더하기 자리에 빼기를 썼으면 틀린 답이에요. 둘째, 그 답이 무엇을 나타내나 — "17"이 지금 가진 수인지 더 받은 수인지 말할 수 있어야 해요. 계산하기 전에 어림해 두면 더 쉬워요: 더하면 처음보다 커지고, 빼면 작아져요.',
    en:'Getting an answer is not the end. Check two things. First, did you pick the right operation? An answer can be calculated correctly and still be wrong if you subtracted where you should have added. Second, what does the answer stand for? You should be able to say whether 17 is what she has now or what she was given. Estimating first makes this easier: adding makes it bigger than you started with, subtracting makes it smaller.',
    zh:'算出答案还不算完，要再看两件事。第一，运算选对了吗——就算算得对，该加的地方用了减，答案也是错的。第二，这个答案表示什么——要能说出17是现在有的数，还是又得到的数。先估一估会更容易：加会比原来大，减会比原来小。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'자연수 + − ×',en:'Whole numbers + - x',zh:'自然数 + - ×'},params:{range:'A'}},
          {id:2,label:{ko:'자연수 + − × ÷',en:'Whole numbers + - x /',zh:'自然数 + - × ÷'},params:{range:'B'}},
          {id:3,label:{ko:'분수·소수 + −',en:'Fractions & decimals + -',zh:'分数·小数 + -'},params:{range:'C'}}] },
/* ── 중등 교과 연산 3차(2026-09-20) ── 원장 지시: "교과연산과 창의연산이
   같이 되어야 한다. 교과 연산 후 문장제·창의연산 혼합 컨셉이었는데."
   점검 결과 중등 교과 연산의 기둥 다섯이 비어 있었다 — 연립방정식·
   일차부등식·일차함수(중2), 이차방정식 풀이·이차함수 꼭짓점(중3).
   중2 과정 33에 유형이 둘(MD13·MD14)밖에 없던 것이 그 증거다.
   gen 함수는 engine/threads/mid9.js. unit은 data/units/M-63.js~M-67.js. */
MD63:{ name:{ko:'연립방정식 풀이',en:'Solving Systems of Equations',zh:'二元一次方程组的解法'}, gen:'md63_simultaneous', prereq:['MD50'],
  unit:'M-63',
  concept:{ko:'미지수가 둘이면 식도 둘 있어야 답이 하나로 정해집니다. 푸는 요령은 하나뿐 — 한 문자를 없애서 일차방정식으로 만드는 거입니다. 없애는 방법이 대입법과 가감법 두 가지입니다.',
    en:'Two unknowns need two equations before the answer is pinned down. There is really only one method — get rid of one letter so it becomes a single linear equation. Substitution and elimination are two ways to do that.',
    zh:'有两个未知数就要有两个方程，答案才能唯一确定。解法其实只有一个——消去一个字母，变成一元一次方程。代入法和加减法就是两种消去的办法。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'대입법(연습, 2다칸)',en:'substitution (practice, 2 slots)',zh:'代入法(练习，2格)'},params:{mode:'substitution'}},
          {id:2,label:{ko:'가감법(계수 맞추기)',en:'elimination (match the coefficients)',zh:'加减法(配系数)'},params:{mode:'elimination',wide:true},
           concept:{ko:'두 식의 한 문자 계수를 같게 만든 뒤 빼면 그 문자가 사라집니다. 계수가 2와 3이면 3배·2배 해서 둘 다 6으로 맞춥니다.',
             en:'Make one letter’s coefficients equal in both equations, then subtract to make it vanish: if they are 2 and 3, multiply by 3 and by 2 so both become 6.',
             zh:'把两式中某个字母的系数变成相同，再相减就能消去它：系数是2和3时，分别乘3和乘2，都变成6。'}},
          {id:3,label:{ko:'두 방법 혼합(실전)',en:'both methods mixed (main)',zh:'两种方法混合(实战)'},params:{mode:'mixed',wide:true},
           concept:{ko:'계수를 먼저 보고 고르면 빠릅니다 — 한 식이 y=…꼴이거나 계수가 1이면 대입법, 그렇지 않으면 가감법이 편합니다.',
             en:'Look at the coefficients first: substitution is quicker when one equation is already y=… or a coefficient is 1; otherwise elimination is easier.',
             zh:'先看系数再选：有一式已是y=…或系数为1时用代入法更快，否则加减法更方便。'}}] },

MD64:{ name:{ko:'일차부등식',en:'Linear Inequalities',zh:'一元一次不等式'}, gen:'md64_linearInequality', prereq:['MD50'],
  unit:'M-64',
  concept:{ko:'부등식은 방정식과 똑같이 풉니다. 딱 하나만 다릅니다 — 양변을 음수로 곱하거나 나누면 부등호의 방향이 뒤집힙니다. 3<5의 양변에 −1을 곱하면 −3>−5가 되는 것과 같습니다.',
    en:'Solve an inequality exactly like an equation, with one difference: multiplying or dividing both sides by a negative flips the inequality sign. Multiply 3<5 by −1 and it becomes −3>−5.',
    zh:'不等式和方程的解法完全一样，只有一点不同——两边同乘或同除以负数时，不等号方向要反过来。3<5两边乘−1就变成−3>−5。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'양수 계수(방향 그대로, 연습)',en:'positive coefficient (sign unchanged, practice)',zh:'正系数(方向不变，练习)'},params:{mode:'positive'}},
          {id:2,label:{ko:'음수 계수(방향 뒤집힘)',en:'negative coefficient (sign flips)',zh:'负系数(方向反转)'},params:{mode:'flip',wide:true},
           concept:{ko:'x의 계수가 음수면 마지막에 음수로 나누게 되고, 그때 부등호가 뒤집힙니다 — −2x>6은 x<−3입니다.',
             en:'A negative coefficient means you divide by a negative at the last step, and that is when the sign flips: −2x>6 gives x<−3.',
             zh:'x的系数是负数时，最后一步要除以负数，这时不等号就要反转——−2x>6得x<−3。'}},
          {id:3,label:{ko:'양변에 x · 정수해(실전)',en:'x on both sides, integer solution (main)',zh:'两边有x·整数解(实战)'},params:{mode:'integer',wide:true},
           concept:{ko:'x항을 한쪽으로 모으면 계수가 음수가 될 수 있습니다. 방향을 뒤집어 x<(어떤 수)를 얻었다면, 이를 만족하는 가장 큰 정수는 그 수보다 하나 작은 수입니다.',
             en:'Gathering the x terms can leave a negative coefficient. Once the flip gives x<(some number), the largest integer that works is one less than that number.',
             zh:'把x项收到一边后系数可能变成负数。反转后得到x<(某个数)时，满足它的最大整数就是比那个数小1的数。'}},
          {id:4,label:{ko:'부등호 방향 직접 고르기',en:'choose the inequality direction',zh:'直接选择不等号方向'},params:{mode:'chooseSign'},
           concept:{ko:'a<b의 양변에 같은 수를 더하거나 빼면 방향은 그대로입니다. 같은 양수로 곱하거나 나누어도 그대로이고, 같은 음수로 곱하거나 나눌 때만 방향을 뒤집습니다.',
             en:'Adding or subtracting the same number keeps a<b in the same direction. Multiplying or dividing by the same positive also keeps it; only a negative flips it.',
             zh:'a<b两边同加或同减一个数，方向不变；同乘或同除以正数也不变，只有同乘或同除以负数时方向反转。'}}] },

MD65:{ name:{ko:'일차함수의 기울기와 절편',en:'Slope & Intercept of a Linear Function',zh:'一次函数的斜率与截距'}, gen:'md65_linearFunction', prereq:['MD51'],
  unit:'M-65',
  concept:{ko:'y=ax+b에서 a는 기울기(오른쪽으로 1칸 갈 때 위아래로 몇 칸인지), b는 y절편(x=0일 때의 높이)입니다. 기울기는 두 점만 있으면 (y의 증가량)÷(x의 증가량)으로 구합니다.',
    en:'In y=ax+b, a is the slope (how far up or down you go for each step right) and b is the y-intercept (the height when x=0). Two points are enough for the slope: (change in y) ÷ (change in x).',
    zh:'y=ax+b中，a是斜率(向右走1格时上下走几格)，b是y截距(x=0时的高度)。只要有两个点就能求斜率：(y的增量)÷(x的增量)。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'두 점에서 기울기(연습)',en:'slope from two points (practice)',zh:'由两点求斜率(练习)'},params:{mode:'slope'}},
          {id:2,label:{ko:'기울기와 한 점 → y절편',en:'slope and a point → y-intercept',zh:'斜率和一点→y截距'},params:{mode:'intercept',wide:true},
           concept:{ko:'점이 그래프 위에 있다는 건 그 좌표를 식에 넣으면 등식이 성립한다는 뜻입니다. y=3x+b에 (2,5)를 넣으면 5=6+b, b=−1입니다.',
             en:'A point being on the graph means its coordinates satisfy the equation: putting (2,5) into y=3x+b gives 5=6+b, so b=−1.',
             zh:'点在图象上，就是说把它的坐标代入式子后等式成立：把(2,5)代入y=3x+b得5=6+b，所以b=−1。'}},
          {id:3,label:{ko:'두 점 → 식 세우기(실전, 2다칸)',en:'two points → the equation (main, 2 slots)',zh:'两点→列出式子(实战，2格)'},params:{mode:'fromPoints',wide:true},
           concept:{ko:'기울기를 먼저 구하고, 그 기울기와 두 점 중 아무 점이나 하나를 써서 y절편을 구합니다 — 어느 점을 써도 b는 같습니다.',
             en:'Find the slope first, then use it with either of the two points to get the y-intercept — both points give the same b.',
             zh:'先求斜率，再用斜率和两点中任意一点求y截距——用哪个点求出的b都一样。'}},
          /* 레벨 4·5(2026-09-21, 원장 "일차함수 그래프는") — 위 셋은 좌표를 숫자로만
             줬다. 기울기가 "오른쪽 1칸에 위로 몇 칸"이라는 건 격자 위에서만 보인다.
             widget:'graphPlane' 이 화면에, exam.js graphSvg 가 학습지에 같은 그림을 그린다. */
          {id:4,label:{ko:'그래프에서 기울기 읽기',en:'read the slope off the graph',zh:'从图象读出斜率'},params:{mode:'readSlope'},
           concept:{ko:'격자 한 칸이 1입니다. 직선을 따라 오른쪽으로 한 칸 간 뒤, 위나 아래로 몇 칸 움직였는지 세면 그게 기울기입니다. 내려가면 음수입니다.',
             en:'One square of the grid is 1. Follow the line one square to the right and count how many squares you moved up or down — that is the slope, and it is negative when the line goes down.',
             zh:'格子一格就是1。沿直线向右走一格，数一数上下移动了几格，那就是斜率；向下走就是负数。'}},
          {id:5,label:{ko:'그래프에서 식 읽기(2다칸)',en:'read the equation off the graph (2 slots)',zh:'从图象读出式子(2格)'},params:{mode:'readEquation'},
           concept:{ko:'그래프가 y축을 지나는 높이가 b입니다. 거기서 오른쪽으로 한 칸 가서 세로로 몇 칸인지 세면 a가 나옵니다 — 두 수를 y=ax+b에 그대로 넣습니다.',
             en:'The height where the graph crosses the y-axis is b. From there, move one square right and count the vertical squares to get a — then put both numbers into y=ax+b.',
             zh:'图象穿过y轴的高度就是b。从那里向右走一格，数出竖直的格数就是a——把两个数填进y=ax+b。'}}] },

MD66:{ name:{ko:'이차방정식 풀이',en:'Solving Quadratic Equations',zh:'一元二次方程的解法'}, gen:'md66_quadEquation', prereq:['MD20'],
  unit:'M-66',
  concept:{ko:'AB=0이면 A=0이거나 B=0입니다 — 이것 하나로 이차방정식이 풀립니다. 좌변을 인수분해해 (x−p)(x−q)=0 꼴로 만들면 근은 p와 q입니다. 인수분해가 안 되면 완전제곱꼴로 고칩니다.',
    en:'If AB=0 then A=0 or B=0 — that single fact solves quadratics. Factor the left side into (x−p)(x−q)=0 and the roots are p and q. When it will not factor, complete the square instead.',
    zh:'若AB=0则A=0或B=0——仅凭这一点就能解一元二次方程。把左边因式分解成(x−p)(x−q)=0，根就是p和q。不能因式分解时就配方。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'인수분해로 풀기(연습, 2다칸)',en:'solve by factoring (practice, 2 slots)',zh:'用因式分解求解(练习，2格)'},params:{mode:'factor'}},
          {id:2,label:{ko:'완전제곱꼴로 고치기',en:'complete the square',zh:'配成完全平方'},params:{mode:'completeSquare',wide:true},
           concept:{ko:'x의 계수의 절반을 제곱해 더하고 빼면 (x+p)²=(어떤 수) 꼴이 됩니다 — x²+6x+2=0은 (x+3)²=7입니다.',
             en:'Halve the coefficient of x, square it, add and subtract it, and you reach (x+p)²=(some number): x²+6x+2=0 becomes (x+3)²=7.',
             zh:'把x的系数取一半再平方，加上又减去，就变成(x+p)²=(某个数)：x²+6x+2=0变成(x+3)²=7。'}},
          {id:3,label:{ko:'x²의 계수가 1이 아닐 때(실전)',en:'leading coefficient ≠ 1 (main)',zh:'x²系数不为1时(实战)'},params:{mode:'leadCoef',wide:true},
           concept:{ko:'세 항에 공통인수가 있으면 먼저 묶어냅니다. 2x²−10x+12=0은 2(x²−5x+6)=0이고, 2는 0이 아니니 x²−5x+6=0만 풀면 됩니다.',
             en:'Pull out a common factor first: 2x²−10x+12=0 is 2(x²−5x+6)=0, and since 2 is not zero you only need to solve x²−5x+6=0.',
             zh:'三项有公因数时先提取：2x²−10x+12=0就是2(x²−5x+6)=0，因为2不为0，只需解x²−5x+6=0。'}},
          /* 2026-09-21 — 앞의 세 레벨은 전부 "어떻게든 인수분해되는 식"이라, 인수분해가
             안 되는 이차방정식이 한 번도 안 나왔다. 근은 무리수라 숫자 칸으로 못 받으므로
             원장 지시대로 **D와 분모 두 정수**만 받는다(근의 모양은 문제 tex가 보여 준다). */
          {id:4,label:{ko:'근의 공식(D와 분모)',en:'the quadratic formula (D and denominator)',zh:'求根公式(D与分母)'},params:{mode:'formula',wide:true},
           concept:{ko:'인수분해도 안 되고 완전제곱도 번거로우면 근의 공식을 씁니다. x=(−b±√D)/2a 이고 D=b²−4ac입니다 — 2x²+3x−4=0은 D=9+32=41, 분모는 2×2=4입니다.',
             en:'When it will not factor and completing the square is awkward, use the formula x=(−b±√D)/2a with D=b²−4ac — for 2x²+3x−4=0, D=9+32=41 and the denominator is 2×2=4.',
             zh:'既不能因式分解、配方又麻烦时就用求根公式x=(−b±√D)/2a，其中D=b²−4ac——2x²+3x−4=0的D=9+32=41，分母是2×2=4。'}},
          /* 2026-09-21 — 디딤돌 개념연산 중3-1B 대조(p.9·42·46)로 찾은 세 구멍. 앞의
             네 레벨은 전부 "어떻게 푸느냐"였고, 중근·근의 개수·거꾸로 방정식 만들기는
             근의 공식 자체가 아니라 **근을 둘러싼 개념**이라 따로 필요하다. */
          {id:5,label:{ko:'중근',en:'double root',zh:'重根'},params:{mode:'doubleRoot',wide:true},
           concept:{ko:'이차방정식의 두 해가 중복되어 서로 같을 때, 이 해를 중근이라고 합니다. (완전제곱식)=0 꼴로 인수분해되면 그 해가 중근입니다 — x²−2x+1=0은 (x−1)²=0이니 중근은 1입니다.',
             en:'When both roots of a quadratic are the same, that root is called a double root. If it factors to (perfect square)=0, that root is the double root — x²−2x+1=0 is (x−1)²=0, so the double root is 1.',
             zh:'一元二次方程的两个根相同时，这个根叫做重根。若能因式分解成(完全平方式)=0，那个根就是重根——x²−2x+1=0是(x−1)²=0，重根是1。'}},
          {id:6,label:{ko:'근의 개수(판별식)',en:'number of roots (discriminant)',zh:'根的个数(判别式)'},params:{mode:'discriminantCount'},
           concept:{ko:'이차방정식 ax²+bx+c=0의 근의 개수는 판별식 D=b²−4ac의 부호로 압니다. D>0이면 서로 다른 두 근, D=0이면 한 개의 근(중근), D<0이면 근이 없습니다.',
             en:'The number of roots of ax²+bx+c=0 is found from the sign of the discriminant D=b²−4ac. D>0 gives two different roots, D=0 gives one (double) root, D<0 gives no roots.',
             zh:'一元二次方程ax²+bx+c=0的根的个数由判别式D=b²−4ac的符号决定。D>0是两个不同的根，D=0是一个根(重根)，D<0则无根。'}},
          {id:7,label:{ko:'이차방정식 구하기',en:'building the equation from its roots',zh:'求作一元二次方程'},params:{mode:'fromRoots',wide:true},
           concept:{ko:'두 근이 p, q이고 x²의 계수가 a인 이차방정식은 a(x−p)(x−q)=0을 펼쳐서 구합니다 — 두 근이 1, 2이면 (x−1)(x−2)=0이니 x²−3x+2=0입니다.',
             en:'For two roots p, q with leading coefficient a, the equation is found by expanding a(x−p)(x−q)=0 — roots 1 and 2 give (x−1)(x−2)=0, that is x²−3x+2=0.',
             zh:'已知两根p、q和x²系数a，展开a(x−p)(x−q)=0就能求出方程——两根为1、2时是(x−1)(x−2)=0，即x²−3x+2=0。'}}] },

MD67:{ name:{ko:'이차함수의 꼭짓점',en:'The Vertex of a Quadratic',zh:'二次函数的顶点'}, gen:'md67_quadVertex', prereq:['MD66'],
  unit:'M-67',
  concept:{ko:'y=a(x−p)²+q의 그래프는 꼭짓점이 (p, q)인 포물선입니다. (x−p)²는 절대 음수가 될 수 없어서 x=p일 때 0으로 가장 작아지고, 그때 y가 q가 됩니다. 괄호 안의 부호는 반대로 읽습니다.',
    en:'The graph of y=a(x−p)²+q is a parabola with vertex (p, q). Since (x−p)² can never be negative, it is smallest (zero) at x=p, and y is q there. Read the sign inside the brackets the opposite way.',
    zh:'y=a(x−p)²+q的图象是顶点为(p, q)的抛物线。因为(x−p)²不可能为负，所以在x=p时取最小值0，此时y就是q。括号里的符号要反过来读。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'표준형에서 읽기(연습, 2다칸)',en:'read it off the vertex form (practice, 2 slots)',zh:'从标准式读出(练习，2格)'},params:{mode:'vertexForm'}},
          {id:2,label:{ko:'y=x²+bx+c 완전제곱',en:'complete the square for y=x²+bx+c',zh:'y=x²+bx+c配方'},params:{mode:'complete',wide:true},
           concept:{ko:'x의 계수의 절반이 p입니다(부호는 반대). y=x²−6x+11은 y=(x−3)²+2이니 꼭짓점은 (3, 2)입니다.',
             en:'Half of the coefficient of x gives p (with the sign flipped): y=x²−6x+11 is y=(x−3)²+2, so the vertex is (3, 2).',
             zh:'x的系数的一半就是p(符号相反)：y=x²−6x+11就是y=(x−3)²+2，所以顶点是(3, 2)。'}},
          {id:3,label:{ko:'x²의 계수가 있을 때(실전)',en:'with a leading coefficient (main)',zh:'带x²系数时(实战)'},params:{mode:'withCoef',wide:true},
           concept:{ko:'x²의 계수를 먼저 묶어낸 다음 괄호 안에서 완전제곱을 만듭니다. 그 계수가 양수면 아래로 볼록해 꼭짓점이 최솟값, 음수면 위로 볼록해 최댓값입니다.',
             en:'Factor out the coefficient of x² first, then complete the square inside the brackets. A positive coefficient opens upward so the vertex is the minimum; a negative one opens downward so it is the maximum.',
             zh:'先提取x²的系数，再在括号内配方。系数为正时开口向上，顶点是最小值；为负时开口向下，顶点是最大值。'}},
          /* 레벨 4(2026-09-21) — MD65 와 같은 좌표평면 위젯. 꼭짓점은 그림 하나로
             끝나는 개념이라 식만 주고 끝내면 절반만 가르친 셈이다. */
          {id:4,label:{ko:'그래프에서 꼭짓점 읽기',en:'read the vertex off the graph',zh:'从图象读出顶点'},params:{mode:'readVertex'},
           concept:{ko:'포물선이 방향을 바꾸는 단 한 점이 꼭짓점입니다. 아래로 볼록하면 가장 낮은 점, 위로 볼록하면 가장 높은 점이고, 거기서 가로·세로 좌표를 읽습니다.',
             en:'The one point where the parabola changes direction is the vertex — the lowest point when it opens upward, the highest when it opens downward. Read its x and y off the grid.',
             zh:'抛物线改变方向的那唯一一点就是顶点——开口向上时是最低点，向下时是最高点，从格子上读出它的横纵坐标。'}}] },

/* ── 중등 교과 연산 4차(2026-09-21) ── 원장 "한 단원씩이 아니잖아. 어떻게 일차함수
   그래프를 한 번에 배워. 정비례 반비례는? 이차함수도 세부화해야지. 일차방정식의
   활용도 거리·속력·시간, 원가·정가 등 놓치지 마."
   3차(mid9.js)가 한 단원을 한 스레드에 뭉쳐 놓았던 것을 교과 차시대로 쪼개고,
   통째로 없던 **활용(문장제)** 다섯을 새로 넣는다. gen 함수는 engine/threads/mid10.js,
   unit 은 data/units/M-68.js~M-81.js. */
MD68:{ name:{ko:'좌표와 사분면',en:'Coordinates & Quadrants',zh:'坐标与象限'}, gen:'md68_coordinate', prereq:['MD1'],
  unit:'M-68',
  concept:{ko:'가로(x)와 세로(y) 두 수를 짝지어 평면 위의 한 점을 정합니다. 두 축이 평면을 넷으로 나누고, 오른위부터 시계 반대 방향으로 제1·2·3·4사분면입니다.',en:'A pair of numbers, across (x) and up (y), pins down one point on the plane. The two axes cut the plane into four parts, numbered 1 to 4 counter-clockwise from the top right.',zh:'用横(x)、纵(y)两个数配成一对，就确定了平面上的一个点。两条轴把平面分成四部分，从右上开始逆时针依次是第1、2、3、4象限。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'그래프에서 좌표 읽기(연습, 2다칸)',en:'read a point off the graph (practice, 2 slots)',zh:'从图象读出坐标(练习，2格)'},params:{mode:'readPoint'}},
          {id:2,label:{ko:'사분면 판정',en:'which quadrant',zh:'判定象限'},params:{mode:'quadrant'},
           concept:{ko:'x가 양수면 오른쪽, 음수면 왼쪽. y가 양수면 위, 음수면 아래입니다. 두 부호를 합치면 어느 사분면인지 바로 나옵니다 — (+,+)는 1, (−,+)는 2, (−,−)는 3, (+,−)는 4입니다.',en:'Positive x is right and negative x is left; positive y is up and negative y is down. Put the two signs together and the quadrant follows: (+,+) is 1, (-,+) is 2, (-,-) is 3, (+,-) is 4.',zh:'x为正在右、为负在左；y为正在上、为负在下。把两个符号合起来就知道是第几象限：(+,+)是1，(−,+)是2，(−,−)是3，(+,−)是4。'}},
          {id:3,label:{ko:'대칭점 구하기(실전, 2다칸)',en:'reflected points (main, 2 slots)',zh:'求对称点(实战，2格)'},params:{mode:'symmetry'},
           concept:{ko:'x축에 비추면 위아래만 뒤집히니 y의 부호만 바뀝니다. y축에 비추면 x의 부호만, 원점에 대해 비추면 둘 다 바뀝니다.',en:'Reflecting in the x-axis flips up and down, so only y changes sign. In the y-axis only x changes, and through the origin both change.',zh:'关于x轴对称只上下翻转，所以只有y变号；关于y轴对称只有x变号；关于原点对称两个都变号。'}}] },

MD69:{ name:{ko:'정비례·반비례의 그래프',en:'Graphs of Direct & Inverse Proportion',zh:'正比例·反比例的图象'}, gen:'md69_proportionGraph', prereq:['MD51','MD68'],
  unit:'M-69',
  concept:{ko:'정비례 y=ax의 그래프는 원점을 지나는 곧은 직선이고, 반비례 y=a/x의 그래프는 두 가지로 갈라진 곡선입니다. 어느 쪽이든 그래프 위의 점 하나만 알면 a를 구할 수 있습니다.',en:'A direct proportion y=ax draws a straight line through the origin; an inverse proportion y=a/x draws a curve in two separate branches. Either way, one point on the graph is enough to find a.',zh:'正比例y=ax的图象是过原点的直线，反比例y=a/x的图象是分成两支的曲线。不论哪一种，只要知道图象上的一个点就能求出a。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'정비례 그래프에서 a 읽기(연습)',en:'read a off a direct-proportion graph (practice)',zh:'从正比例图象读出a(练习)'},params:{mode:'directGraph'}},
          {id:2,label:{ko:'반비례 그래프에서 a 읽기',en:'read a off an inverse-proportion graph',zh:'从反比例图象读出a'},params:{mode:'inverseGraph'},
           concept:{ko:'반비례 그래프에서는 x와 y를 **곱하면** 비례상수 a가 나옵니다. **a>0이면 제1·3사분면**, **a<0이면 제2·4사분면**을 지납니다. 두 좌표의 부호가 같은지 다른지로 확인하세요.',en:'On an inverse-proportion graph, multiplying x by y always gives the same number, and that number is a. Direct proportion divided; this one multiplies.',zh:'在反比例图象上，x乘以y总得到同一个数，那个数就是a。正比例是相除，这里正好相反。'}},
          {id:3,label:{ko:'그래프에서 값 읽기(실전)',en:'read a value off the graph (main)',zh:'从图象读出值(实战)'},params:{mode:'readValue'},
           concept:{ko:'식을 먼저 알아낸 다음 x를 넣습니다. 정비례면 곱하고 반비례면 나눕니다 — 그래프 모양만 봐도 어느 쪽인지 알 수 있습니다.',en:'Work out the formula first, then substitute x: multiply for direct proportion, divide for inverse. The shape of the graph alone tells you which it is.',zh:'先求出式子再代入x：正比例就乘，反比例就除。单看图象的形状就能判断是哪一种。'}}] },

MD70:{ name:{ko:'일차방정식의 활용',en:'Linear Equations in Use',zh:'一元一次方程的应用'}, gen:'md70_linearApply', prereq:['MD50'],
  unit:'M-70',
  concept:{ko:'말로 된 문제를 푸는 순서는 늘 같습니다. ①구하려는 것을 x로 놓고 ②문장을 식으로 옮기고 ③식을 풀고 ④답이 말이 되는지 확인합니다. 거리=속력×시간, 정가=원가×(1+이익률)처럼 관계식을 기억해 두면 ②가 쉬워집니다.',en:'Word problems always follow the same order: let x be what you are asked for, turn the sentences into an equation, solve it, then check the answer makes sense. Knowing the standard relations - distance = speed x time, price = cost x (1 + markup) - makes the second step easy.',zh:'解应用题的顺序总是一样：①把要求的量设为x ②把句子translate成算式 ③解方程 ④检验答案是否合理。记住常用关系式(路程=速度×时间、定价=成本×(1+利润率))，第②步就容易了。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'수와 나이(연습)',en:'numbers and ages (practice)',zh:'数与年龄(练习)'},params:{mode:'number'}},
          {id:2,label:{ko:'거리·속력·시간',en:'distance, speed and time',zh:'路程·速度·时间'},params:{mode:'speed'},
           concept:{ko:'거리=속력×시간 하나만 알면 나머지 둘은 옮기면 됩니다. 같은 길을 두 가지 방법으로 갔다면 **거리가 같거나 시간이 같다**는 데서 식이 나옵니다.',en:'Distance = speed x time is the only relation you need; the other two come from rearranging it. When the same route is travelled two ways, the equation comes from the distance being equal, or the time being equal.',zh:'只要记住路程=速度×时间，其余两个移项即可。同一段路用两种方式走时，等量关系就在"路程相同"或"时间相同"上。'}},
          {id:3,label:{ko:'원가·정가·할인(실전)',en:'cost, marked price and discount (main)',zh:'成本·定价·折扣(实战)'},params:{mode:'price'},
           concept:{ko:'원가에 이익을 붙인 것이 정가, 정가에서 할인한 것이 판매가입니다. %는 100으로 나눈 비율이라 20% 이익은 ×1.2, 10% 할인은 ×0.9입니다. 이익=판매가−원가라는 것을 놓치지 마세요.',en:'Cost plus profit gives the marked price, and the marked price minus the discount gives what it sells for. A percent is a hundredth, so a 20% markup is x1.2 and a 10% discount is x0.9. Remember that profit is selling price minus cost.',zh:'成本加利润是定价，定价打折后是售价。百分数就是百分之几，所以加价20%是×1.2，打九折是×0.9。别忘了利润=售价−成本。'}}] },

MD71:{ name:{ko:'일차부등식의 활용',en:'Linear Inequalities in Use',zh:'一元一次不等式的应用'}, gen:'md71_inequalityApply', prereq:['MD64'],
  unit:'M-71',
  concept:{ko:'"최대 몇 개", "적어도 몇 점"처럼 **범위**를 묻는 문제는 등식이 아니라 부등식으로 세웁니다. 답은 범위로 나오지만 개수·점수는 정수라, 마지막에 그 범위 안의 가장 큰(또는 가장 작은) 정수를 고르는 한 걸음이 더 있습니다.',en:'Questions that ask "at most how many" or "at least what score" are set up as inequalities, not equations. The answer comes out as a range, but counts and scores are whole numbers, so there is one more step: pick the largest (or smallest) integer in that range.',zh:'问"最多几个""至少多少分"这类**范围**的问题，要列不等式而不是方程。答案是一个范围，但个数、分数都是整数，所以最后还要一步：在范围里取最大(或最小)的整数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'예산 안에서 최대 개수(연습)',en:'greatest number within a budget (practice)',zh:'预算内最多买几个(练习)'},params:{mode:'maxCount'}},
          {id:2,label:{ko:'평균 조건',en:'average conditions',zh:'平均分条件'},params:{mode:'average'},
           concept:{ko:'평균이 기준 이상이 되려면 (모두의 합)÷(개수) ≥ 기준입니다. 분모를 양변에 곱해 없앤 다음 푸는데, 개수는 양수라 부등호 방향이 바뀌지 않습니다.',en:'For an average to reach a target, (total) / (how many) >= target. Multiply both sides by the count to clear the fraction - the count is positive, so the inequality sign does not flip.',zh:'要使平均数达到标准，就是(总和)÷(个数) ≥ 标准。两边同乘个数去掉分母；个数是正数，所以不等号方向不变。'}},
          {id:3,label:{ko:'두 요금제 비교(실전)',en:'comparing two plans (main)',zh:'比较两种收费(实战)'},params:{mode:'compare'},
           concept:{ko:'어느 쪽이 싼지 묻는 문제는 두 비용을 각각 식으로 쓴 뒤 부등호로 잇습니다. 경계가 되는 수를 구한 다음, 그 수를 넘는 가장 작은 정수가 답입니다.',en:'To find which option is cheaper, write each cost as an expression and join them with an inequality. Find the boundary value, then the smallest integer past it is the answer.',zh:'比较哪种更便宜，就把两种花费分别写成式子再用不等号连接。求出临界值后，超过它的最小整数就是答案。'}}] },

MD72:{ name:{ko:'연립방정식의 활용',en:'Systems of Equations in Use',zh:'二元一次方程组的应用'}, gen:'md72_systemApply', prereq:['MD63'],
  unit:'M-72',
  concept:{ko:'모르는 것이 둘이면 x와 y 둘 다 놓고, 문장에서 **서로 다른 두 관계**를 찾아 식을 두 개 세웁니다. 개수와 금액, 거리와 시간, 소금물의 양과 소금의 양처럼 보통 "전체"와 "속내용" 한 쌍입니다.',en:'When two things are unknown, name both x and y and look for two different relations in the wording. They usually come as a pair: how many and how much, distance and time, the amount of solution and the amount of salt in it.',zh:'有两个未知量时就都设出来(x和y)，再从题目中找出**两个不同的关系**列两个方程。通常是"总量"和"内含量"这一对：个数与金额、路程与时间、盐水的量与盐的量。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'개수와 금액(연습)',en:'how many and how much (practice)',zh:'个数与金额(练习)'},params:{mode:'countSum'}},
          {id:2,label:{ko:'거리·속력·시간',en:'distance, speed and time',zh:'路程·速度·时间'},params:{mode:'speed'},
           concept:{ko:'구간마다 속력이 다르면 거리를 x, y로 놓습니다. 그러면 거리의 합이 첫 식, 시간의 합(=각 거리÷속력)이 둘째 식이 됩니다.',en:'When the speed changes between stretches, let the distances be x and y. The distances add up to give one equation, and the times - each distance divided by its speed - add up to give the other.',zh:'各段速度不同时就把路程设为x和y：路程之和是第一个方程，时间之和(各段路程÷速度)是第二个方程。'}},
          {id:3,label:{ko:'농도(실전)',en:'concentration (main)',zh:'浓度(实战)'},params:{mode:'mixture'},
           concept:{ko:'소금물 문제는 **소금의 양**이 열쇠입니다. 소금의 양 = 소금물의 양 × 농도(%)÷100이고, 섞기 전후로 소금의 양이 변하지 않습니다. 소금물의 양의 합이 첫 식, 소금의 양의 합이 둘째 식입니다.',en:'In a mixing problem the key is the amount of salt: amount of salt = amount of solution x percent / 100, and mixing does not change how much salt there is. The solutions add up for one equation, and the salt adds up for the other.',zh:'盐水问题的关键是**盐的量**：盐的量 = 盐水的量 × 浓度(%)÷100，混合前后盐的总量不变。盐水的量之和是第一个方程，盐的量之和是第二个方程。'}}] },

MD73:{ name:{ko:'함수와 함숫값',en:'Functions & Function Values',zh:'函数与函数值'}, gen:'md73_functionValue', prereq:['MD48'],
  unit:'M-73',
  concept:{ko:'f(x)는 "x를 넣으면 나오는 값"이라는 뜻입니다. f(3)은 x 자리에 3을 넣어 계산한 결과지, f와 3을 곱한 것이 아닙니다. 거꾸로 f(x)의 값이 주어지면 x를 찾는 일차방정식이 됩니다.',en:'f(x) means "the value that comes out when you put x in". So f(3) is what you get by substituting 3 for x - it is not f times 3. Read it backwards, and finding x from a given f(x) is just a linear equation.',zh:'f(x)表示"代入x后得到的值"。所以f(3)是把3代入x算出的结果，不是f乘以3。反过来，已知f(x)的值求x，就是解一元一次方程。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'f(k) 구하기(연습)',en:'finding f(k) (practice)',zh:'求f(k)(练习)'},params:{mode:'value'}},
          {id:2,label:{ko:'함숫값에서 x 찾기',en:'finding x from f(x)',zh:'由函数值求x'},params:{mode:'inverse'},
           concept:{ko:'f(x)=7처럼 나온 값이 주어지면 그 자리에 식을 넣어 방정식으로 풉니다 — 지금까지 푼 일차방정식과 똑같습니다.',en:'When a value like f(x)=7 is given, put the formula in its place and solve the equation - exactly the linear equations you have been solving.',zh:'给出f(x)=7这样的值时，把式子代进去当方程解——和一直在解的一元一次方程完全一样。'}},
          {id:3,label:{ko:'두 함숫값으로 식 세우기(실전, 2다칸)',en:'building f from two values (main, 2 slots)',zh:'由两个函数值求式子(实战，2格)'},params:{mode:'findCoef'},
           concept:{ko:'f(1)과 f(2)의 차가 곧 a입니다(x가 1 늘 때 y가 얼마나 느는지). a를 알면 f(1)에서 b가 나옵니다 — 두 점으로 직선을 정하는 것과 같은 일입니다.',en:'The difference between f(1) and f(2) is a - how much y grows when x grows by one. With a known, f(1) gives b. It is the same work as pinning a line down with two points.',zh:'f(1)与f(2)之差就是a(x增加1时y增加多少)。求出a后，由f(1)就能得到b——这和用两点确定一条直线是同一件事。'}}] },

MD74:{ name:{ko:'일차함수의 그래프와 절편',en:'Graphs & Intercepts of Linear Functions',zh:'一次函数的图象与截距'}, gen:'md74_lineGraph', prereq:['MD73'],
  unit:'M-74',
  /* 2026-09-21 다시 짬 — 원장 "일차함수 그래프 그리려면 두 점을 찾는 것부터 하고 대입하거나
     기울기를 구하고 대입하기". 전에는 첫 레벨이 평행이동뿐이라 그리는 방법이 없었다. 순서는
     교과서·단원테스트 해설 그대로: 두 점 대입 → 두 절편 → 기울기로 둘째 점 → 그래프 읽기 →
     평행이동은 마지막에 성질로만. 레벨마다 갈래(mode)가 다르므로 자동 램프는 안 탄다. */
  concept:{ko:'일차함수의 그래프는 직선이라 두 점만 찾으면 그릴 수 있습니다. x에 수를 넣어 y를 구하면 점 하나가 나옵니다 — 두 번 하면 두 점입니다. y=0을 넣어 x절편, x=0을 넣어 y절편을 구하는 것도 두 점을 찾는 한 방법입니다. 두 점을 찍고 자로 이으면 그래프입니다.',
    en:'The graph of a linear function is a straight line, so two points are enough to draw it. Put a number in for x and work out y — that is one point; do it twice and you have two. Finding the x-intercept (y=0) and the y-intercept (x=0) is another way to get two points. Plot them and join with a ruler.',
    zh:'一次函数的图象是一条直线，所以只要找到两个点就能画出来。把一个数代入x求出y，就得到一个点——做两次就有两个点。令y=0求x截距、令x=0求y截距，也是找两个点的办法。描出两点，用尺子连起来就是图象。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'두 점 찾기 — x에 대입(연습, 2다칸)',en:'find two points by substituting x (practice, 2 slots)',zh:'找两个点——代入x(练习，2格)'},params:{mode:'twoPoints'}},
          {id:2,label:{ko:'x절편·y절편 구하기(2다칸)',en:'find the x- and y-intercepts (2 slots)',zh:'求x截距、y截距(2格)'},params:{mode:'intercepts'},
           concept:{ko:'y=0을 넣어 x절편을, x=0을 넣어 y절편을 구합니다 — 이 둘도 두 점이라 그래프를 그릴 수 있습니다. y절편은 상수항 그대로고, x절편은 한 번 풀어야 나옵니다.',
             en:'Put y=0 for the x-intercept and x=0 for the y-intercept — these are two points too, so they draw the graph. The y-intercept is just the constant term; the x-intercept takes one step of solving.',
             zh:'令y=0求x截距，令x=0求y截距——这两个也是点，同样能画出图象。y截距就是常数项，x截距要解一步才得到。'}},
          {id:3,label:{ko:'기울기로 두 번째 점 찾기(2다칸)',en:'use the slope to find the second point (2 slots)',zh:'用斜率找第二个点(2格)'},params:{mode:'slopePoint'},
           concept:{ko:'기울기를 알면 y절편 (0, b)에서 오른쪽으로 1칸, 위아래로 a칸 간 곳이 두 번째 점 (1, a+b)입니다. 두 점이 나왔으니 잇습니다.',
             en:'If you know the slope, start at the y-intercept (0, b), move 1 to the right and a up or down — that is the second point (1, a+b). Two points: join them.',
             zh:'知道斜率后，从y截距(0,b)向右走1格、上下走a格，就是第二个点(1,a+b)。有了两点，连起来。'}},
          {id:4,label:{ko:'그래프에서 두 절편 읽기(실전, 2다칸)',en:'read both intercepts off the graph (main, 2 slots)',zh:'从图象读出两个截距(实战，2格)'},params:{mode:'readIntercepts'},
           concept:{ko:'그래프에서는 두 절편이 눈에 그대로 보입니다 — 직선이 가로축을 뚫는 자리와 세로축을 뚫는 자리입니다. 이 두 점만 찍으면 직선을 그릴 수 있습니다.',
             en:'On the graph both intercepts are right there to read: where the line crosses the horizontal axis and where it crosses the vertical axis. These two points alone draw the line.',
             zh:'在图象上两个截距一眼就能看到——直线穿过横轴的地方和穿过纵轴的地方。只要这两点就能画出直线。'}},
          {id:5,label:{ko:'평행이동(성질)',en:'translation (a property)',zh:'平移(性质)'},params:{mode:'translate'},
           concept:{ko:'y=ax+b의 그래프는 y=ax의 그래프를 y축의 방향으로 b만큼 평행이동한 거입니다. 기울기가 같으니 두 직선은 평행합니다 — y=2x, y=2x+3, y=2x−5는 모두 평행합니다.',
             en:'The graph of y=ax+b is the graph of y=ax translated b along the y-axis. Same slope means the two lines are parallel — y=2x, y=2x+3 and y=2x−5 are all parallel.',
             zh:'y=ax+b的图象是把y=ax的图象沿y轴方向平移b得到的。斜率相同，两条直线平行——y=2x、y=2x+3、y=2x−5都互相平行。'}}] },

MD75:{ name:{ko:'일차함수와 일차방정식',en:'Linear Functions & Linear Equations',zh:'一次函数与一次方程'}, gen:'md75_lineEquation', prereq:['MD74','MD63'],
  unit:'M-75',
  concept:{ko:'ax+by+c=0은 사실 직선의 방정식이고, y에 대해 풀면 일차함수 y=mx+n이 됩니다. 그래서 **두 직선이 만나는 점이 곧 연립방정식의 해**입니다 — 그림과 식이 같은 것을 말하고 있었던 거입니다.',en:'The equation ax+by+c=0 is really the equation of a line; solve it for y and it becomes the linear function y=mx+n. That is why the point where two lines meet is exactly the solution of the system - the picture and the algebra were saying the same thing all along.',zh:'ax+by+c=0其实就是直线的方程，解出y就变成一次函数y=mx+n。所以**两直线的交点正是方程组的解**——图象和式子说的本来就是同一件事。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'일반형을 y=ax+b로(연습, 2다칸)',en:'general form to y=ax+b (practice, 2 slots)',zh:'一般式化为y=ax+b(练习，2格)'},params:{mode:'toSlope'}},
          {id:2,label:{ko:'두 직선의 교점(2다칸)',en:'where two lines meet (2 slots)',zh:'两直线的交点(2格)'},params:{mode:'intersect'},
           concept:{ko:'교점은 두 식을 **모두** 만족하는 점입니다. y를 같게 놓고 x를 구한 뒤, 그 x를 아무 식에나 넣어 y를 구합니다 — 연립방정식을 푸는 것과 똑같습니다.',en:'The meeting point satisfies both equations. Set the two y expressions equal, solve for x, then put that x into either equation to get y - exactly like solving a system.',zh:'交点同时满足两个式子。令两个y相等求出x，再把x代入任一式求y——和解方程组完全一样。'}},
          {id:3,label:{ko:'평행 조건으로 계수 구하기(실전)',en:'a coefficient from a parallel condition (main)',zh:'由平行条件求系数(实战)'},params:{mode:'parallel'},
           concept:{ko:'평행한 두 직선은 기울기가 같습니다(y절편만 달라요). 일반형은 먼저 y=mx+n 꼴로 고친 뒤 기울기끼리 비교합니다.',en:'Parallel lines have equal slopes and differ only in their y-intercepts. Rewrite a general form as y=mx+n first, then compare the slopes.',zh:'平行的两条直线斜率相同，只有y截距不同。一般式要先化成y=mx+n再比较斜率。'}}] },

MD76:{ name:{ko:'일차함수의 활용',en:'Linear Functions in Use',zh:'一次函数的应用'}, gen:'md76_lineApply', prereq:['MD74'],
  unit:'M-76',
  concept:{ko:'처음에 있던 양이 y절편(b), 한 단위마다 늘거나 주는 양이 기울기(a)입니다. 그래서 "처음 ○이고 1분마다 △씩"이라는 말은 그대로 y=△x+○이 됩니다. 줄어들면 기울기가 음수입니다.',en:'Whatever there was to begin with is the y-intercept, and however much it grows or shrinks each unit is the slope. So "starts at 10 and gains 3 a minute" is simply y=3x+10 - and if it shrinks, the slope is negative.',zh:'最初的量就是y截距(b)，每单位增加或减少的量就是斜率(a)。所以"起初是○，每分钟△"直接写成y=△x+○；如果是减少，斜率就是负数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'물통에 물 채우기(연습)',en:'filling a tank (practice)',zh:'往水桶里加水(练习)'},params:{mode:'water'}},
          {id:2,label:{ko:'짧아지는 양초',en:'a burning candle',zh:'越烧越短的蜡烛'},params:{mode:'candle'},
           concept:{ko:'줄어드는 상황은 기울기가 음수입니다. 처음 길이에서 "1분에 줄어드는 양 × 시간"을 빼면 남은 길이가 나옵니다.',en:'When something shrinks the slope is negative: take the starting length and subtract the amount lost per minute times the time.',zh:'减少的情况斜率为负：用最初的长度减去"每分钟减少的量×时间"就是剩下的长度。'}},
          {id:3,label:{ko:'기본요금이 있는 요금(실전)',en:'a charge with a base fee (main)',zh:'含基本费的收费(实战)'},params:{mode:'fee'},
           concept:{ko:'기본요금은 쓰지 않아도 내는 돈이라 y절편이고, 단위마다 붙는 요금이 기울기입니다. 0에서 시작하지 않는 것이 정비례와 다른 점입니다.',en:'A base fee is paid even for zero use, so it is the y-intercept, and the rate per unit is the slope. Not starting from zero is exactly what separates this from a direct proportion.',zh:'基本费是不使用也要付的钱，所以是y截距；每单位的费用是斜率。不从0开始，正是它与正比例的区别。'}}] },

MD77:{ name:{ko:'이차방정식의 활용',en:'Quadratic Equations in Use',zh:'一元二次方程的应用'}, gen:'md77_quadApply', prereq:['MD66'],
  unit:'M-77',
  concept:{ko:'넓이나 곱처럼 **두 양을 곱하는** 상황에서 이차방정식이 나옵니다. 푸는 순서는 일차방정식과 같지만 한 가지가 더 있습니다 — 근이 두 개 나오면 길이·개수·시간으로 말이 되는 쪽만 답입니다(음수 길이는 없어요).',en:'A quadratic turns up whenever two quantities are multiplied - an area, or a product of numbers. The steps are the same as for a linear equation with one addition: two roots come out, and only the one that makes sense as a length, a count or a time can be the answer.',zh:'面积、乘积这类**两个量相乘**的情形会出现一元二次方程。解题步骤和一次方程相同，只多一步——会得到两个根，只有作为长度、个数、时间说得通的那个才是答案(没有负的长度)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'연속하는 두 수(연습)',en:'two consecutive numbers (practice)',zh:'两个连续的数(练习)'},params:{mode:'consecutive'}},
          {id:2,label:{ko:'도형의 넓이',en:'the area of a shape',zh:'图形的面积'},params:{mode:'area'},
           concept:{ko:'직사각형 넓이=가로×세로입니다. 한 변을 x로 놓고 다른 변을 x로 나타내면 x에 대한 이차식이 됩니다. 음수 근은 길이가 될 수 없으니 버립니다.',en:'The area of a rectangle is width times height. Let one side be x, write the other in terms of x, and you get a quadratic. A negative root cannot be a length, so discard it.',zh:'长方形面积=长×宽。把一边设为x，另一边也用x表示，就得到关于x的二次式。负根不能作为长度，舍去。'}},
          {id:3,label:{ko:'쏘아 올린 물체(실전)',en:'an object thrown upward (main)',zh:'向上抛出的物体(实战)'},params:{mode:'projectile'},
           concept:{ko:'높이가 0이 되는 순간이 땅에 닿는 때입니다. 두 근 중 하나는 쏘아 올린 순간(t=0)이라 답이 아닙니다 — 나머지 하나가 다시 떨어지는 시각입니다.',en:'The object is on the ground when the height is zero. One of the two roots is the moment it was launched (t=0), so the other one is when it lands.',zh:'高度为0的时刻就是落地的时刻。两个根中有一个是抛出的瞬间(t=0)，另一个才是重新落地的时间。'}}] },

MD78:{ name:{ko:'이차함수 y=ax²의 그래프',en:'The Graph of y=ax²',zh:'二次函数y=ax²的图象'}, gen:'md78_quadBasic', prereq:['MD67'],
  unit:'M-78',
  concept:{ko:'y=ax²의 그래프는 원점을 꼭짓점으로 하는 포물선입니다. a가 양수면 아래로 볼록(위로 열림), 음수면 위로 볼록이고, a의 절댓값이 클수록 폭이 좁아집니다. x가 −3이든 3이든 제곱하면 같으니 y축에 대해 좌우가 똑같습니다.',en:'The graph of y=ax2 is a parabola with its vertex at the origin. A positive a opens upward and a negative a opens downward, and the bigger the size of a the narrower it gets. Since -3 and 3 square to the same thing, the two sides mirror each other across the y-axis.',zh:'y=ax²的图象是以原点为顶点的抛物线。a为正时开口向上，为负时开口向下；|a|越大开口越窄。因为−3和3的平方相同，所以图象关于y轴左右对称。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'함숫값 구하기(연습)',en:'finding the value (practice)',zh:'求函数值(练习)'},params:{mode:'value'}},
          {id:2,label:{ko:'지나는 점으로 a 구하기',en:'finding a from a point',zh:'由经过的点求a'},params:{mode:'findA'},
           concept:{ko:'그래프가 어떤 점을 지난다는 것은 그 좌표를 넣으면 등식이 성립한다는 뜻입니다. y=ax²에 넣으면 a만 남으니, y를 x의 제곱으로 나누면 됩니다.',en:'A graph passing through a point means its coordinates satisfy the formula. Substituting into y=ax2 leaves only a, so divide y by x squared.',zh:'图象经过某点，就是说把坐标代入后等式成立。代入y=ax²只剩下a，所以用y除以x的平方即可。'}},
          {id:3,label:{ko:'그래프에서 a 읽기(실전)',en:'read a off the graph (main)',zh:'从图象读出a(实战)'},params:{mode:'readA'},
           concept:{ko:'그래프에서 x=1이나 x=2인 자리의 y를 읽으면 a가 바로 나옵니다. 볼록한 방향으로 부호를, 폭으로 크기를 짐작할 수 있습니다.',en:'Read y at x=1 or x=2 on the graph and a follows at once. The direction it opens tells you the sign, and how narrow it is tells you the size.',zh:'在图象上读出x=1或x=2处的y，a就出来了。开口方向告诉你符号，开口宽窄告诉你大小。'}},
          {id:4,label:{ko:'x=−2~2 대응표와 좌우 대칭',en:'the x=−2 to 2 table and symmetry',zh:'x=−2到2的对应表与左右对称'},params:{mode:'symmetryTable'},
           concept:{ko:'x=−2,−1,0,1,2를 차례로 넣으면 양쪽 y값이 짝을 이룹니다. (−x)²=x²이므로 y(−x)=y(x)이고, 이 표가 포물선이 y축에 대칭인 이유를 보여 줍니다.',en:'Substituting −2, −1, 0, 1 and 2 makes matching pairs of y-values. Since (−x)²=x², y(−x)=y(x), which is why the parabola is symmetric about the y-axis.',zh:'依次代入−2、−1、0、1、2，左右的y值成对相等。因为(−x)²=x²，所以y(−x)=y(x)，这正说明抛物线关于y轴对称。'}}] },

MD79:{ name:{ko:'이차함수의 평행이동',en:'Translating a Parabola',zh:'二次函数的平移'}, gen:'md79_quadShift', prereq:['MD78'],
  unit:'M-79',
  concept:{ko:'y=ax²를 위아래로 q만큼 옮기면 뒤에 +q가 붙고, 좌우로 p만큼 옮기면 괄호 안이 (x−p)가 됩니다. 위아래는 보이는 대로지만 **좌우는 부호가 반대로** 들어가는 것이 이 단원에서 가장 자주 틀리는 자리입니다.',en:'Sliding y=ax2 up by q adds +q at the end; sliding it sideways by p turns the bracket into (x-p). Up and down reads as you would expect, but sideways goes in with the opposite sign - and that is where most mistakes in this topic happen.',zh:'把y=ax²上下平移q，后面加上+q；左右平移p，括号里变成(x−p)。上下是所见即所得，但**左右要反号**——这是本单元最容易错的地方。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'위아래 평행이동(연습)',en:'sliding up and down (practice)',zh:'上下平移(练习)'},params:{mode:'upDown'}},
          {id:2,label:{ko:'좌우 평행이동',en:'sliding sideways',zh:'左右平移'},params:{mode:'leftRight'},
           concept:{ko:'오른쪽으로 3만큼 옮기면 (x−3)²입니다. "오른쪽인데 왜 빼지?"는 x=3일 때 괄호 안이 0이 되어 그 자리가 꼭짓점이 되기 때문입니다.',en:'Sliding 3 to the right gives (x-3)2. Why a minus for a move to the right? Because the bracket is zero at x=3, and that is exactly where the vertex now sits.',zh:'向右平移3就是(x−3)²。"向右为什么用减？"——因为x=3时括号里为0，那里正好成为顶点。'}},
          {id:3,label:{ko:'두 방향 모두(실전, 2다칸)',en:'both directions (main, 2 slots)',zh:'两个方向都平移(实战，2格)'},params:{mode:'both'},
           concept:{ko:'두 방향을 함께 옮기면 y=a(x−p)²+q가 되고 꼭짓점은 (p, q)입니다. 옮긴 만큼이 그대로 꼭짓점의 좌표가 되는 셈입니다.',en:'Move in both directions and you get y=a(x-p)2+q, with the vertex at (p, q) - the amounts you moved are simply the vertex coordinates.',zh:'两个方向一起平移就得到y=a(x−p)²+q，顶点是(p, q)——平移了多少，顶点坐标就是多少。'}},
          {id:4,label:{ko:'주어진 x의 y값·지나는 점',en:'a y-value and a point on the shifted graph',zh:'平移图象上给定x的y值与点'},params:{mode:'pointValue'},
           concept:{ko:'그래프 위의 점은 항상 함수식을 만족합니다. 주어진 x를 x−p에 대입한 뒤, ① 괄호 안 ② 제곱 ③ a를 곱하고 q를 더하는 순서로 y좌표를 구합니다.',en:'Every point on the graph satisfies the formula. Substitute the given x into x−p, then work in the order: bracket, square, multiply by a, and add q.',zh:'图象上的每个点都满足函数式。把给定的x代入x−p，再按括号、平方、乘a、加q的顺序求y坐标。'}}] },

MD80:{ name:{ko:'이차함수의 최대·최소와 축과의 교점',en:'Extremes & Axis Crossings of a Parabola',zh:'二次函数的最值与轴交点'}, gen:'md80_quadExtrema', prereq:['MD79'],
  unit:'M-80',
  concept:{ko:'꼭짓점의 y값이 최솟값(아래로 볼록) 또는 최댓값(위로 볼록)입니다. x축과 만나는 곳은 y=0인 자리라 이차방정식의 근이고, y축과 만나는 곳은 x=0인 자리라 상수항 그대로입니다.',en:'The y-coordinate of the vertex is the minimum when the parabola opens upward and the maximum when it opens downward. Where it meets the x-axis is where y=0 - the roots of the quadratic - and where it meets the y-axis is where x=0, which is just the constant term.',zh:'顶点的y值：开口向上时是最小值，开口向下时是最大值。与x轴的交点是y=0的地方，也就是二次方程的根；与y轴的交点是x=0的地方，就是常数项。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'최댓값·최솟값(연습)',en:'maximum and minimum (practice)',zh:'最大值与最小值(练习)'},params:{mode:'maxMin'}},
          {id:2,label:{ko:'x축과의 교점(2다칸)',en:'where it crosses the x-axis (2 slots)',zh:'与x轴的交点(2格)'},params:{mode:'xAxis'},
           concept:{ko:'y=0으로 놓으면 그대로 이차방정식입니다. 인수분해해서 나온 두 근이 x축과 만나는 두 점의 x좌표입니다 — 그래서 이차함수와 이차방정식이 한 몸입니다.',en:'Setting y=0 gives exactly a quadratic equation, and its two roots are the x-coordinates where the curve crosses the axis. That is why quadratic functions and quadratic equations are one and the same thing.',zh:'令y=0就是一个二次方程，因式分解得到的两个根就是与x轴交点的横坐标——所以二次函数和二次方程本是一体。'}},
          {id:3,label:{ko:'y축과의 교점(실전)',en:'where it crosses the y-axis (main)',zh:'与y轴的交点(实战)'},params:{mode:'yAxis'},
           concept:{ko:'x=0을 넣으면 x가 들어간 항은 모두 사라지고 상수항만 남습니다. 그래서 y절편은 계산하지 않아도 식에서 바로 읽힙니다.',en:'Put x=0 and every term with an x disappears, leaving the constant. So the y-intercept can be read straight off the formula with no working at all.',zh:'代入x=0后含x的项全部消失，只剩常数项。所以y截距不用计算，直接从式子里读出来。'}}] },

MD81:{ name:{ko:'이차함수의 식 구하기',en:'Building the Formula of a Parabola',zh:'求二次函数的解析式'}, gen:'md81_quadFind', prereq:['MD80'],
  unit:'M-81',
  concept:{ko:'그래프를 보고 식을 거꾸로 세우는 자리입니다. 주어진 것이 무엇이냐에 따라 시작하는 꼴이 다릅니다 — 꼭짓점을 알면 y=a(x−p)²+q, x축과의 두 교점을 알면 y=a(x−p)(x−q)로 시작하고, 남은 a는 지나는 점 하나로 정합니다.',en:'This is reading a graph backwards into a formula. Which form you start from depends on what you are given: a vertex means y=a(x-p)2+q, two x-intercepts mean y=a(x-p)(x-q), and one more point on the curve fixes the remaining a.',zh:'这是看图反过来求式子。已知什么就从什么形式入手：知道顶点用y=a(x−p)²+q，知道与x轴的两个交点用y=a(x−p)(x−q)，剩下的a由图象上另一个点确定。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'꼭짓점과 한 점(연습)',en:'the vertex and one point (practice)',zh:'顶点与一个点(练习)'},params:{mode:'vertexPoint'}},
          {id:2,label:{ko:'x축과의 두 교점과 한 점',en:'two x-intercepts and one point',zh:'两个x轴交点与一个点'},params:{mode:'twoRoots'},
           concept:{ko:'x축과 만나는 두 점을 알면 y=a(x−p)(x−q) 꼴이 바로 나옵니다. 이 꼴은 인수분해된 모습 그대로라, 근을 알 때 가장 편합니다.',en:'Two x-intercepts hand you y=a(x-p)(x-q) straight away. That form is already factored, which makes it the easiest one to use when you know the roots.',zh:'知道与x轴的两个交点就直接得到y=a(x−p)(x−q)。这个形式本身就是因式分解好的，已知根时最方便。'}},
          {id:3,label:{ko:'꼭짓점 → 일반형(실전, 2다칸)',en:'vertex form to general form (main, 2 slots)',zh:'顶点式→一般式(实战，2格)'},params:{mode:'general'},
           concept:{ko:'표준형을 전개하면 일반형이 됩니다. (x−p)²을 펴면 x²−2px+p²이니 b는 −2p, c는 p²+q입니다 — 완전제곱을 만들던 과정을 거꾸로 밟는 것입니다.',en:'Expanding the vertex form gives the general form: (x-p)2 opens out to x2-2px+p2, so b is -2p and c is p2+q. It is completing the square, walked backwards.',zh:'把顶点式展开就是一般式：(x−p)²展开为x²−2px+p²，所以b是−2p，c是p²+q——这正是配方过程倒着走一遍。'}}] },

/* ── 수직선 위의 위치(2026-09-21) ── 원장 "정수 또는 유리수도 위치 찾기 연습도 있어야
   하고 절댓값도 위치 찾기가 되어야지". MD1 은 절댓값을 **계산**만 시켰고, 수직선 위
   어디인지를 묻는 자리가 없었다. 좌표평면(MD68)의 바로 앞 단계이기도 하다 —
   1차원에서 자리를 읽을 줄 알아야 2차원에서 (x, y) 를 읽는다. gen: mid10.js. */
MD82:{ name:{ko:'수직선 위의 위치',en:'Positions on the Number Line',zh:'数轴上的位置'}, gen:'md82_numberLine', prereq:['MD1'],
  unit:'M-82',
  concept:{ko:'수직선은 0(원점)을 기준으로 오른쪽이 양수, 왼쪽이 음수입니다. 3에서 왼쪽으로 5만큼 가면 −2, −1에서 오른쪽으로 3만큼 가면 +2입니다. 한 칸을 더 잘게 나누면 정수 사이의 유리수도 자리를 가집니다. 절댓값은 원점에서 그 수까지의 거리라, 같은 절댓값을 가진 수는 0의 양쪽에 하나씩 둘입니다.',
    en:'On the number line, right of 0 (the origin) is positive and left is negative. From 3, five steps left lands on −2; from −1, three steps right lands on +2. Split a unit into smaller marks and the rational numbers between integers get places too. The absolute value is the distance from the origin, so two numbers share one absolute value — one on each side of 0.',
    zh:'数轴以0(原点)为界，右边是正数，左边是负数。从3向左走5到−2，从−1向右走3到+2。把一格再细分，整数之间的有理数也有了位置。绝对值是从原点到这个数的距离，所以绝对值相同的数有两个，0的两边各一个。'},
  widgets:['numpad','graphPlane'],
  levels:[{id:1,label:{ko:'정수의 위치 읽기(연습)',en:'read an integer off the line (practice)',zh:'读出整数的位置(练习)'},params:{mode:'integer'}},
          {id:2,label:{ko:'유리수의 위치(분수, 2다칸)',en:'a rational on the line (fraction, 2 slots)',zh:'有理数的位置(分数，2格)'},params:{mode:'rational'},
           concept:{ko:'한 칸을 등분한 작은 눈금을 0에서부터 셉니다. 세 칸을 4등분한 눈금에서 7칸이면 7/4입니다 — 약분하지 않고 "몇 등분한 것 중 몇 칸"을 그대로 적습니다.',
             en:'Count the small marks from zero. Seven marks on a line cut into quarters is 7/4 - write it as "how many of how many", without reducing.',
             zh:'从0开始数细分的小刻度。把一格四等分后数到7格就是7/4——不约分，照"几等分中的几格"写出来。'}},
          {id:3,label:{ko:'절댓값이 같은 두 수 찾기(실전)',en:'the two numbers with a given absolute value (main)',zh:'找绝对值相同的两个数(实战)'},params:{mode:'absolute'},
           concept:{ko:'|x|=5라면 0에서 5칸 떨어진 자리 둘 — 오른쪽 5와 왼쪽 −5입니다. 절댓값은 거리라 언제나 0 이상이고, 0의 절댓값만 0입니다.',
             en:'If |x|=5 there are two places five steps from zero: 5 on the right and -5 on the left. An absolute value is a distance, so it is never negative, and only zero has an absolute value of zero.',
             zh:'若|x|=5，离0有5格的位置有两个：右边的5和左边的−5。绝对值是距离，所以从不为负；只有0的绝对值是0。'}}] },

/* ── MD84 — 대표값: 중앙값·최빈값과 종합 ──
   디딤돌 개념연산 중1-2 p.224~230에서 확인한 평균·중앙값·최빈값만 다룬다.
   p.231 이후는 원본이 절단되어 도수표·그래프 등은 추측해 추가하지 않는다. */
MD84:{ name:{ko:'대표값: 평균·중앙값·최빈값',en:'Measures of Center: Mean, Median & Mode',zh:'代表值：平均数·中位数·众数'}, gen:'md84_center', prereq:[],
  unit:'M-84',
  concept:{ko:'자료를 대표하는 값에는 평균, 중앙값, 최빈값이 있습니다. 중앙값은 자료를 크기순으로 놓았을 때 한가운데 값이고, 자료가 짝수 개면 가운데 두 값의 평균입니다. 최빈값은 가장 많이 나타난 값이며 둘 이상일 수도 있고, 수가 아닌 범주 자료에도 쓸 수 있습니다.',
    en:'Mean, median, and mode are measures that represent data. The median is the middle after sorting; with an even number of values, average the two middle values. The mode is the most frequent value, can have more than one answer, and can also describe categories.',
    zh:'平均数、中位数和众数都可代表数据。中位数是排序后正中间的数；数据个数为偶数时，取中间两个数的平均数。众数是出现次数最多的值，可以有多个，也可用于类别数据。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'홀수 개 자료의 중앙값(기본 12)',en:'median of odd-sized data (12 basics)',zh:'奇数个数据的中位数(基础12题)'},params:{mode:'medianOdd'}},
          {id:2,label:{ko:'짝수 개 자료의 중앙값(기본 12)',en:'median of even-sized data (12 basics)',zh:'偶数个数据的中位数(基础12题)'},params:{mode:'medianEven'},
           concept:{ko:'자료가 짝수 개이면 한가운데 값이 하나가 아닙니다. 크기순으로 놓고 가운데 두 값의 평균을 중앙값으로 정합니다.',en:'With an even number of values there is no single middle, so sort the data and average the two middle values.',zh:'数据个数为偶数时没有唯一的正中间，因此排序后取中间两个数的平均数。'}},
          {id:3,label:{ko:'최빈값 하나(기본 12)',en:'one mode (12 basics)',zh:'一个众数(基础12题)'},params:{mode:'modeSingle'},
           concept:{ko:'자료의 각 값이 몇 번씩 나타나는지 세어 횟수가 가장 큰 값을 고릅니다. 한 값만 가장 많이 나타나면 그 값이 하나뿐인 최빈값입니다.',en:'Count how often each value appears. If one value alone has the greatest frequency, it is the single mode.',zh:'统计各数出现的次数。若只有一个数的次数最多，它就是唯一的众数。'}},
          {id:4,label:{ko:'최빈값 둘(집중 24)',en:'two modes (24 focused)',zh:'两个众数(集中24题)'},params:{mode:'modeMultiple'},
           concept:{ko:'가장 많이 나타난 횟수가 같은 값이 둘 이상이면 최빈값도 둘 이상입니다. 하나만 고르지 말고 모두 씁니다.',en:'If two or more values tie for the highest frequency, every tied value is a mode.',zh:'如果有两个或更多数并列出现次数最多，它们都是众数。'}},
          {id:5,label:{ko:'범주 자료의 최빈값(집중 24)',en:'mode of categorical data (24 focused)',zh:'类别数据的众数(集中24题)'},params:{mode:'modeCategory'},
           concept:{ko:'최빈값은 숫자 계산이 아니라 횟수 비교이므로 좋아하는 운동·색깔처럼 수가 아닌 자료에서도 구할 수 있습니다. 화면에서는 A~E 항목을 1~5 번호로 입력합니다.',en:'Mode compares frequencies rather than calculating with the values, so it also works for categories such as sports or colors. Enter category A-E as number 1-5.',zh:'众数比较的是出现次数，不是对数值做运算，因此运动、颜色等类别资料也能求众数。A至E请按1至5输入。'}},
          {id:6,label:{ko:'평균·중앙값·최빈값 종합(집중 24)',en:'mean, median & mode together (24 focused)',zh:'平均数·中位数·众数综合(集中24题)'},params:{mode:'summary'},
           concept:{ko:'평균은 합÷개수, 중앙값은 정렬 뒤 가운데, 최빈값은 횟수의 최댓값입니다. 세 값은 같은 자료에서도 서로 다를 수 있으므로 정의를 섞지 않고 차례로 구합니다.',en:'Mean is sum divided by count, median is the middle after sorting, and mode is the most frequent. They can differ in the same data set, so apply each definition separately.',zh:'平均数是总和除以个数，中位数是排序后的中间值，众数是出现次数最多的值。同一组数据中三者可能不同。'}}] },

/* ── MD85 — 산포도(2026-09-24) ── 디딤돌 개념연산 중3-2
   인쇄 p.112~125의 편차·분산·표준편차·두 자료 비교만 재구성한다. */
MD85:{ name:{ko:'산포도: 편차·분산·표준편차',en:'Dispersion: Deviations, Variance & Standard Deviation',zh:'离散程度：偏差·方差·标准差'}, gen:'md85_dispersion', prereq:['MD84'],
  unit:'M-85',
  concept:{ko:'편차는 변량에서 평균을 뺀 값이며 합은 항상 0입니다. 분산은 편차 제곱의 평균이고, 표준편차는 분산의 양의 제곱근입니다. 평균은 중심을, 분산과 표준편차는 평균 주위에 흩어진 정도를 설명합니다.',
    en:'A deviation is a value minus the mean, and all deviations sum to zero. Variance is the mean of squared deviations, and standard deviation is the positive square root of the variance. The mean locates the center; variance and standard deviation describe spread around it.',
    zh:'偏差是变量减去平均数，所有偏差之和恒为0。方差是偏差平方的平均数，标准差是方差的正平方根。平均数表示中心，方差和标准差表示数据在中心周围的分散程度。'},
  widgets:['numpad'],
  levels:[
    {id:1,label:{ko:'편차 구하기(기본 12문항)',en:'find a deviation (12 basics)',zh:'求偏差(基础12题)'},params:{mode:'deviation'}},
    {id:2,label:{ko:'편차의 합과 빠진 편차(핵심 24문항)',en:'sum and missing deviation (24 core)',zh:'偏差之和与缺少的偏差(核心24题)'},params:{mode:'missingDeviation'},
      concept:{ko:'편차는 모두 더하면 0입니다. 빠진 편차는 보이는 편차의 합에 반대 부호를 붙여 구합니다.',en:'All deviations add to zero. The missing deviation is the opposite of the sum of the visible deviations.',zh:'所有偏差的和为0。缺少的偏差等于已知偏差和的相反数。'}},
    {id:3,label:{ko:'분산과 표준편차(핵심 24문항)',en:'variance and standard deviation (24 core)',zh:'方差与标准差(核心24题)'},params:{mode:'varianceStd'},
      concept:{ko:'평균 → 편차 → 편차 제곱의 합 → 개수로 나눈 분산 → 분산의 양의 제곱근인 표준편차 순서로 계산합니다. 분산은 제곱 단위이고 표준편차는 원래 자료와 같은 단위입니다.',en:'Work in order: mean, deviations, squared deviations, variance by dividing by the count, then the positive square root for standard deviation. Variance uses squared units; standard deviation has the data\'s original unit.',zh:'依次计算平均数、偏差、偏差平方和、除以个数得到方差，再取方差的正平方根得到标准差。方差是平方单位，标准差与原数据单位相同。'}},
    {id:4,label:{ko:'두 자료의 평균·산포도 비교(핵심 24문항)',en:'compare centers and spread (24 core)',zh:'比较两组数据的平均数与离散程度(核心24题)'},params:{mode:'compare'},
      concept:{ko:'평균이 큰 자료와 더 고른 자료는 같은 뜻이 아닙니다. 중심은 평균끼리, 고른 정도는 분산 또는 표준편차끼리 따로 비교하고, 값이 작은 쪽이 평균 가까이에 더 모여 있습니다.',en:'A larger mean does not mean a more consistent set. Compare means for center and variances or standard deviations for consistency; the smaller spread is more tightly clustered around its mean.',zh:'平均数较大不等于数据更均匀。中心用平均数比较，均匀程度用方差或标准差比较；离散程度较小的一组更集中在平均数附近。'}}
  ] },

/* ── MD86 — 사분위수와 상자그림(2026-09-24) ── 중3-2 p.128~143. */
MD86:{ name:{ko:'사분위수와 상자그림',en:'Quartiles & Box Plots',zh:'四分位数与箱形图'}, gen:'md86_quartileBox', prereq:['MD84'],
  unit:'M-86', widgets:['numpad','graphPlane'],
  levels:[
    {id:1,label:{ko:'홀수 개 자료의 사분위수(기본 12문항)',en:'quartiles of odd-sized data (12 basics)',zh:'奇数个数据的四分位数(基础12题)'},params:{mode:'quartilesOdd'},concept:{ko:'자료를 정렬해 중앙값 Q2를 찾고, Q2를 제외한 아래쪽과 위쪽 절반의 중앙값을 각각 Q1, Q3으로 정합니다.',en:'Sort the data, find Q2, then exclude it and take the medians of the lower and upper halves as Q1 and Q3.',zh:'数据排序后先求Q2，再排除Q2，分别取下半部和上半部的中位数作为Q1、Q3。'}},
    {id:2,label:{ko:'짝수 개 자료의 사분위수(기본 12문항)',en:'quartiles of even-sized data (12 basics)',zh:'偶数个数据的四分位数(基础12题)'},params:{mode:'quartilesEven'},concept:{ko:'자료가 짝수 개이면 가운데에서 같은 개수로 둘로 나눈 뒤, 각 절반의 중앙값을 Q1과 Q3으로 구합니다.',en:'For an even-sized data set, split it into equal lower and upper halves and find the median of each half.',zh:'数据个数为偶数时，从中间等分为上下两半，再分别求两半的中位数。'}},
    {id:3,label:{ko:'범위와 사분위수 범위(집중 24문항)',en:'range and interquartile range (24 focused)',zh:'极差与四分位距(集中24题)'},params:{mode:'spread'},concept:{ko:'범위는 최댓값−최솟값이고, 사분위수 범위는 Q3−Q1입니다. 가운데 절반의 퍼진 정도는 IQR로 비교합니다.',en:'Range is maximum minus minimum, while interquartile range is Q3 minus Q1 and measures the spread of the middle half.',zh:'极差=最大值−最小值，四分位距=Q3−Q1，用来表示中间一半数据的分散程度。'}},
    {id:4,label:{ko:'다섯 수 요약(집중 24문항)',en:'five-number summary (24 focused)',zh:'五数概括(集中24题)'},params:{mode:'fiveNumber'},concept:{ko:'최솟값, Q1, 중앙값, Q3, 최댓값을 차례로 쓰면 상자그림을 그리는 다섯 수 요약이 됩니다.',en:'Minimum, Q1, median, Q3 and maximum form the five-number summary used for a box plot.',zh:'最小值、Q1、中位数、Q3、最大值依次组成绘制箱形图的五数概括。'}},
    {id:5,label:{ko:'상자그림 읽기(집중 24문항)',en:'read a box plot (24 focused)',zh:'读取箱形图(集中24题)'},params:{mode:'boxRead'},concept:{ko:'수염 끝은 최솟값·최댓값, 상자의 양 끝은 Q1·Q3, 상자 안 선은 중앙값입니다. 평균이나 자료 개수는 상자그림만으로 알 수 없습니다.',en:'Whisker ends show minimum and maximum, box edges show Q1 and Q3, and the line in the box is the median. A box plot alone does not reveal the mean or sample size.',zh:'须端表示最小值和最大值，箱体两端表示Q1和Q3，箱内线表示中位数。仅凭箱形图不能知道平均数或数据个数。'}},
    {id:6,label:{ko:'상자그림 직접 그리기(집중 24문항)',en:'draw a box plot (24 focused)',zh:'绘制箱形图(集中24题)'},params:{mode:'boxDraw'},concept:{ko:'눈금 위에 다섯 수를 먼저 표시하고 Q1~Q3 상자, 중앙값 선, 최솟값·최댓값까지의 수염 순서로 그립니다.',en:'Mark the five values first, then draw the Q1-to-Q3 box, median line and whiskers to the minimum and maximum.',zh:'先在刻度上标出五个数，再画Q1到Q3的箱体、中位数线以及连到最小值和最大值的须。'}}
  ] },

/* ── MD87 — 산점도와 상관관계(2026-09-24) ── 중3-2 p.144~153. */
MD87:{ name:{ko:'산점도와 상관관계',en:'Scatter Plots & Correlation',zh:'散点图与相关关系'}, gen:'md87_scatter', prereq:['MD85'],
  unit:'M-87', widgets:['numpad','graphPlane'], instr:{ko:'표의 순서쌍을 점으로 나타내거나 산점도를 읽어 답하시오.',en:'Plot the ordered pairs or read the scatter plot and answer.',zh:'描出有序数对，或观察散点图作答。'},
  levels:[
    {id:1,label:{ko:'순서쌍 직접 찍기(기본 12문항)',en:'plot ordered pairs (12 basics)',zh:'描有序数对(基础12题)'},params:{mode:'plot'}},
    {id:2,label:{ko:'조건에 맞는 점 세기(집중 24문항)',en:'count points meeting a condition (24 focused)',zh:'数满足条件的点(集中24题)'},params:{mode:'read'},concept:{ko:'부등식의 경계선을 눈으로 세운 뒤 조건을 만족하는 쪽의 점만 하나씩 셉니다. ≥와 ≤이면 경계 위 점도 포함합니다.',en:'Locate the inequality boundary, then count only points on the satisfying side. Include points on the boundary for ≥ and ≤.',zh:'先确定不等式的边界线，再逐个数满足条件一侧的点。使用≥或≤时要包括边界上的点。'}},
    {id:3,label:{ko:'양·음·무상관 판단(기본 12문항)',en:'positive, negative or no correlation (12 basics)',zh:'判断正相关·负相关·无相关(基础12题)'},params:{mode:'correlation'},concept:{ko:'x가 커질수록 점구름이 대체로 올라가면 양의 상관, 내려가면 음의 상관입니다. 한 방향이 보이지 않으면 상관관계가 없습니다.',en:'A cloud that generally rises as x increases has positive correlation; one that falls has negative correlation. With no overall direction, there is no correlation.',zh:'随着x增大，点云整体上升是正相关，整体下降是负相关；看不出总体方向则没有相关关系。'}},
    {id:4,label:{ko:'방향과 강도 판단(집중 24문항)',en:'direction and strength (24 focused)',zh:'判断方向与强弱(集中24题)'},params:{mode:'strength'},concept:{ko:'상관의 방향과 강도는 따로 봅니다. 같은 방향이라도 점들이 좁은 띠에 모일수록 강하고, 넓게 흩어질수록 약합니다.',en:'Judge direction and strength separately. For the same direction, a tighter band means stronger correlation and a wider cloud means weaker correlation.',zh:'相关的方向和强弱要分别判断。同一方向上，点越集中成窄带相关越强，越分散则越弱。'}}
  ] },

/* ── MD88 — 경우의 수(2026-09-24) ── 디딤돌수학 개념연산 중2-2
   인쇄 p.216~230에서 확인한 계산 유형만 구현한다. p.232 이후와 확률은
   근거 범위 밖이라 넣지 않는다. gen: mid11.js. */
MD88:{ name:{ko:'경우의 수',en:'Counting Possibilities',zh:'情况数'}, gen:'md88_countingCases', prereq:['MD4'],
  unit:'M-88',
  concept:{ko:'경우의 수는 가능한 결과를 빠짐없이, 겹치지 않게 센 수입니다. 먼저 한 사건의 결과를 직접 세고, 겹치지 않는 A 또는 B는 더하며, A 다음 B처럼 두 단계를 모두 거치면 곱합니다.',
    en:'A number of possibilities counts every possible result once. Count one event directly; add for non-overlapping A or B; multiply when both stages A then B must happen.',
    zh:'情况数就是把所有可能结果不重不漏地数出来。先直接数一个事件；互不重叠的A或B用加法；必须依次完成A和B两个步骤时用乘法。'},
  widgets:['numpad'],
  levels:[
    {id:1,label:{ko:'사건의 결과 개수(기본 12문항)',en:'count outcomes (12 basics)',zh:'数事件结果(基础12题)'},params:{mode:'eventCount'}},
    {id:2,label:{ko:'배타적인 A 또는 B — 덧셈법칙(24문항)',en:'exclusive A or B — addition rule (24)',zh:'互斥的A或B——加法法则(24题)'},params:{mode:'either'},
      concept:{ko:'A를 고르는 방법과 B를 고르는 방법이 서로 겹치지 않고 둘 중 하나만 택한다면 전체 경우의 수는 A의 경우의 수+B의 경우의 수입니다. 동시에 고를 수 있는 상황에는 그대로 쓰면 안 됩니다.',
        en:'If choosing A and choosing B do not overlap and exactly one is chosen, add their counts. Do not use this unchanged when the choices can occur together.',
        zh:'如果选A与选B互不重叠且只能选一个，总情况数就是A的情况数加B的情况数。两者可以同时发生时不能直接套用。'}},
    {id:3,label:{ko:'A와 B 동시 — 곱셈법칙·경로(24문항)',en:'both A and B — product rule and routes (24)',zh:'同时经过A和B——乘法法则与路线(24题)'},params:{mode:'both'},
      concept:{ko:'첫 단계의 각 방법마다 둘째 단계의 모든 방법이 이어지면 곱합니다. A→B가 3가지이고 B→C가 4가지이면 각 앞길마다 뒷길 4개가 붙으므로 3×4=12가지입니다.',
        en:'Multiply when every first-stage choice can be followed by every second-stage choice. Three A-to-B routes followed by four B-to-C routes give 3×4=12 routes.',
        zh:'第一步的每种方法都能接上第二步的所有方法时用乘法。A到B有3条路，B到C有4条路，共3×4=12条。'}},
    {id:4,label:{ko:'한 줄 세우기(24문항)',en:'lineups (24)',zh:'排成一列(24题)'},params:{mode:'lineup'},
      concept:{ko:'서로 다른 사람을 한 줄로 세울 때는 앞자리부터 고릅니다. n명 중 r명을 세우면 첫 자리는 n가지, 다음 자리는 n−1가지로 줄어 n×(n−1)×…을 계산합니다.',
        en:'For a lineup of distinct people, fill positions from the front. Choosing and lining up r of n gives n choices, then n−1, and so on, so multiply the descending choices.',
        zh:'不同的人排成一列时从第一个位置开始选。从n人中选r人排队，第一位有n种，下一位有n−1种，依次相乘。'}},
    {id:5,label:{ko:'특정 자리 고정(24문항)',en:'fixed positions (24)',zh:'固定位置(24题)'},params:{mode:'fixedSeat'},
      concept:{ko:'조건이 정한 사람을 먼저 자리에 고정하고 남은 사람만 남은 자리에 세웁니다. A와 B가 양 끝처럼 서로 자리를 바꿀 수 있으면 끝자리 배치 2가지를 먼저 곱합니다.',
        en:'Place the people fixed by the condition first, then arrange only the remaining people in the remaining positions. If A and B may swap the two ends, multiply by the two end assignments.',
        zh:'先把条件指定的人固定在位置上，再把其余人排进剩余位置。若A、B可互换两端，先乘两种端点安排。'}}
  ] },

/* ── MD89·MD90 중등 적용(2026-09-25) — 회차 세 층 검사가 과정 29·35 에 적용 문제가 한 회차도
   없다고 잡았다. 그 과정의 교과 연산을 그대로 쓰는 적용만 넣는다. gen: engine/threads/mid16.js */
MD89:{ name:{ko:'정수의 활용',en:'Integers in Context',zh:'整数的应用'}, gen:'md89_intApply', prereq:['MD2'],
  concept:{ko:'기준을 0으로 정하면 기준보다 높거나 따뜻한 쪽은 양수, 낮거나 차가운 쪽은 음수입니다. 올라가면 더하고 내려가면 뺍니다. 두 값의 차는 큰 값에서 작은 값을 뺍니다.',
    en:'Once a reference is set to 0, above or warmer is positive and below or colder is negative. Going up adds, going down subtracts, and a difference is the larger value minus the smaller.',
    zh:'把基准定为0，高于或暖于基准为正数，低于或冷于基准为负数。上升就加，下降就减；两个值的差用大数减小数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'기온의 변화와 차',en:'temperature change and gap',zh:'气温变化与温差'},params:{mode:'temp'}},
          {id:2,label:{ko:'해발과 해저',en:'above and below sea level',zh:'海拔与海面以下'},params:{mode:'altitude'},
           concept:{ko:'해수면을 0m로 두면 해발은 양수, 해저는 음수입니다. 해발 50m와 해저 20m의 높이 차는 50−(−20)=70m입니다.',
             en:'With sea level at 0 m, heights above are positive and depths below are negative: 50 m up and 20 m down are 50−(−20)=70 m apart.',
             zh:'以海平面为0m，海拔为正数，海面以下为负数。海拔50m与海面下20m的高度差是50−(−20)=70m。'}},
          {id:3,label:{ko:'여러 번 오르내림',en:'several ups and downs',zh:'多次升降'},params:{mode:'level'},
           concept:{ko:'여러 번 오르내리면 처음 값에 올라간 만큼 더하고 내려간 만큼 빼면서 왼쪽부터 차례로 계산합니다.',
             en:'For several ups and downs, start from the first value and add each rise and subtract each drop, left to right.',
             zh:'多次升降时，从最初的值开始，上升的加、下降的减，从左到右依次计算。'}}] },
MD90:{ name:{ko:'제곱근의 활용',en:'Square Roots in Context',zh:'平方根的应用'}, gen:'md90_rootApply', prereq:['MD83'],
  concept:{ko:'정사각형의 한 변은 넓이의 양의 제곱근입니다. 넓이가 18이면 한 변은 √18=3√2입니다. 길이를 더하거나 뺄 때는 근호를 먼저 정리해 같은 근호끼리 계산합니다.',
    en:'The side of a square is the positive square root of its area: area 18 gives side √18=3√2. To add or subtract lengths, simplify the roots first and combine like roots.',
    zh:'正方形的边长是面积的正平方根：面积为18时边长是√18=3√2。长度相加减时，先把根号化简，再合并同类根式。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'넓이에서 한 변',en:'side from area',zh:'由面积求边长'},params:{mode:'side'}},
          {id:2,label:{ko:'두 정사각형을 이어 붙인 길이',en:'two squares side by side',zh:'两个正方形拼接的长度'},params:{mode:'joined'},
           concept:{ko:'이어 붙인 길이는 두 한 변의 합입니다. √12+√27=2√3+3√3=5√3처럼 먼저 정리한 뒤 계수끼리 더합니다.',
             en:'The joined length is the sum of the two sides: √12+√27=2√3+3√3=5√3 — simplify first, then add the coefficients.',
             zh:'拼接后的长度是两条边长之和：√12+√27=2√3+3√3=5√3，先化简再把系数相加。'}},
          {id:3,label:{ko:'한 변의 길이의 차',en:'difference of sides',zh:'边长之差'},params:{mode:'diff'},
           concept:{ko:'한 변의 길이의 차는 큰 쪽에서 작은 쪽을 뺍니다. √50−√8=5√2−2√2=3√2입니다.',
             en:'The difference of sides is the larger minus the smaller: √50−√8=5√2−2√2=3√2.',
             zh:'边长之差用大的减小的：√50−√8=5√2−2√2=3√2。'}}] },

/* ── MD91~MD100 공통수학1 새 유형(2026-09-29) — docs/high-build-spec.md 앞 10개.
   교재는 챕터 제목만 근거로 쓰고 문제는 새로 만든다. gen: engine/threads/mid17.js */
MD91:{ name:{ko:'곱셈공식의 변형',en:'Rearranging Multiplication Formulas',zh:'乘法公式的变形'}, gen:'md91_formulaVariant', prereq:['MD22'],
  unit:'M-91',
  concept:{ko:'a+b와 ab만 알아도 a²+b²를 구할 수 있습니다. (a+b)²=a²+2ab+b²에서 2ab를 빼면 a²+b²=(a+b)²−2ab입니다. a, b를 하나씩 구하지 않고 합과 곱으로 바로 계산합니다.',
    en:'Knowing only a+b and ab is enough to find a²+b²: subtract 2ab from (a+b)²=a²+2ab+b² to get a²+b²=(a+b)²−2ab. You compute straight from the sum and product without finding a and b.',
    zh:'只知道a+b和ab就能求a²+b²：从(a+b)²=a²+2ab+b²中减去2ab，得a²+b²=(a+b)²−2ab。不必分别求出a、b，直接用和与积计算。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'a²+b² 구하기(연습)',en:'find a²+b² (practice)',zh:'求a²+b²(练习)'},params:{mode:'sq'}},
          {id:2,label:{ko:'a−b와 (a+b)² 구하기',en:'find a−b and (a+b)²',zh:'求a−b与(a+b)²'},params:{mode:'diff'},
           concept:{ko:'(a+b)²과 (a−b)²은 4ab만큼 차이 납니다. (a−b)²=(a+b)²−4ab이고, a>b이면 a−b는 그 양의 제곱근입니다 — a+b=5, ab=6이면 (a−b)²=25−24=1이라 a−b=1입니다.',
             en:'(a+b)² and (a−b)² differ by 4ab: (a−b)²=(a+b)²−4ab, and if a>b then a−b is its positive square root — a+b=5, ab=6 give (a−b)²=25−24=1, so a−b=1.',
             zh:'(a+b)²与(a−b)²相差4ab：(a−b)²=(a+b)²−4ab，若a>b，a−b就是它的正平方根——a+b=5、ab=6时(a−b)²=25−24=1，所以a−b=1。'}},
          {id:3,label:{ko:'a³+b³ 꼴과 x+1/x 꼴(실전)',en:'a³+b³ and x+1/x forms (main)',zh:'a³+b³型与x+1/x型(实战)'},params:{mode:'cube'},
           concept:{ko:'a³+b³=(a+b)³−3ab(a+b)입니다. x+1/x 꼴은 a=x, b=1/x로 보면 ab=1이라 더 간단합니다 — x+1/x=3이면 x²+1/x²=9−2=7, x³+1/x³=27−9=18입니다.',
             en:'a³+b³=(a+b)³−3ab(a+b). For x+1/x, take a=x and b=1/x so ab=1 — if x+1/x=3 then x²+1/x²=9−2=7 and x³+1/x³=27−9=18.',
             zh:'a³+b³=(a+b)³−3ab(a+b)。x+1/x型可看作a=x、b=1/x，ab=1更简单——x+1/x=3时x²+1/x²=9−2=7，x³+1/x³=27−9=18。'}}] },

MD92:{ name:{ko:'이차식으로 나눈 나머지',en:'Remainders on Division by a Quadratic',zh:'除以二次式的余式'}, gen:'md92_quadRemainder', prereq:['MD24'],
  unit:'M-92',
  concept:{ko:'이차식으로 나눈 나머지는 일차 이하라서 ax+b로 둡니다. P(x)=(x−α)(x−β)Q(x)+ax+b에 x=α, x=β를 넣으면 몫 부분이 0이 되어 aα+b=P(α), aβ+b=P(β)라는 연립방정식이 남습니다.',
    en:'A remainder on division by a quadratic has degree at most 1, so write it as ax+b. Putting x=α and x=β into P(x)=(x−α)(x−β)Q(x)+ax+b kills the quotient part and leaves the system aα+b=P(α), aβ+b=P(β).',
    zh:'除以二次式的余式次数不超过1，设为ax+b。把x=α、x=β代入P(x)=(x−α)(x−β)Q(x)+ax+b，商的部分变为0，剩下方程组aα+b=P(α)、aβ+b=P(β)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'나머지의 일차항 계수 a(연습)',en:'the coefficient a of the remainder (practice)',zh:'余式的一次项系数a(练习)'},params:{mode:'coefA'}},
          {id:2,label:{ko:'나머지의 상수항 b',en:'the constant b of the remainder',zh:'余式的常数项b'},params:{mode:'coefB'},
           concept:{ko:'두 식을 빼서 a를 먼저 구하고, 한 식에 다시 넣어 b를 구합니다 — 2a+b=7, −a+b=1이면 3a=6에서 a=2, b=7−4=3입니다.',
             en:'Subtract the two equations to get a first, then substitute back for b — 2a+b=7 and −a+b=1 give 3a=6, so a=2 and b=7−4=3.',
             zh:'两式相减先求a，再代回一式求b——2a+b=7、−a+b=1时3a=6，a=2，b=7−4=3。'}},
          {id:3,label:{ko:'a, b 모두 구하기(실전, 2다칸)',en:'find both a and b (main, 2 slots)',zh:'同时求a和b(实战，2格)'},params:{mode:'both'},
           concept:{ko:'나누는 식이 전개된 꼴이면 먼저 인수분해해 0이 되는 두 값을 찾습니다. x²−x−2=(x−2)(x+1)이면 x=2, x=−1을 넣습니다.',
             en:'If the divisor is expanded, factor it first to find the two values that make it 0: x²−x−2=(x−2)(x+1), so substitute x=2 and x=−1.',
             zh:'除式是展开形式时，先因式分解找出使它为0的两个值：x²−x−2=(x−2)(x+1)，代入x=2和x=−1。'}}] },

MD93:{ name:{ko:'인수정리',en:'The Factor Theorem',zh:'因式定理'}, gen:'md93_factorTheorem', prereq:['MD24'],
  unit:'M-93',
  concept:{ko:'P(α)=0이면 P(x)는 x−α로 나누어떨어지고, x−α는 P(x)의 인수입니다. 나머지정리에서 나머지가 0인 경우입니다.',
    en:'If P(α)=0, then P(x) is divisible by x−α, so x−α is a factor of P(x). It is the remainder theorem with remainder 0.',
    zh:'若P(α)=0，则P(x)能被x−α整除，x−α是P(x)的因式。这就是余数定理中余数为0的情形。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'미정계수 구하기(연습)',en:'find the unknown coefficient (practice)',zh:'求待定系数(练习)'},params:{mode:'coef'}},
          {id:2,label:{ko:'정수 근 찾기',en:'find the integer root',zh:'找整数根'},params:{mode:'findRoot'},
           concept:{ko:'최고차항의 계수가 1이면 정수 근은 상수항의 약수 중에 있습니다. ±1, ±2, …를 차례로 넣어 P(α)=0이 되는 α를 찾습니다.',
             en:'When the leading coefficient is 1, any integer root divides the constant term. Try ±1, ±2, … in turn until P(α)=0.',
             zh:'最高次项系数为1时，整数根一定是常数项的约数。依次代入±1、±2、…，找出使P(α)=0的α。'}},
          {id:3,label:{ko:'인수분해 결과 읽기(실전)',en:'read off the factorization (main)',zh:'读出因式分解结果(实战)'},params:{mode:'factorConst'},
           concept:{ko:'정수 근 α를 찾았으면 조립제법으로 P(x)를 x−α로 나눕니다. 몫이 남은 이차식입니다 — x³−1은 x=1이 근이라 (x−1)(x²+x+1)입니다.',
             en:'Once you have an integer root α, divide P(x) by x−α with synthetic division; the quotient is the remaining quadratic — x³−1 has root 1, so it is (x−1)(x²+x+1).',
             zh:'找到整数根α后，用综合除法把P(x)除以x−α，商就是剩下的二次式——x³−1有根1，所以等于(x−1)(x²+x+1)。'}}] },

MD94:{ name:{ko:'인수분해를 이용한 수의 계산',en:'Arithmetic by Factoring',zh:'利用因式分解计算'}, gen:'md94_factorArith', prereq:['MD25'],
  unit:'M-94',
  concept:{ko:'큰 수의 계산도 인수분해 공식으로 바꾸면 쉬워집니다. a²−b²=(a+b)(a−b)이므로 a+b가 딱 떨어지는 수가 되게 묶으면 곱셈 한 번으로 끝납니다.',
    en:'Big-number arithmetic gets easy once you rewrite it with a factoring formula. Since a²−b²=(a+b)(a−b), grouping so that a+b is a round number leaves a single multiplication.',
    zh:'大数计算用因式分解公式改写就变简单了。因为a²−b²=(a+b)(a−b)，凑成a+b为整数，只需一次乘法。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'a²−b² 꼴(연습)',en:'the form a²−b² (practice)',zh:'a²−b²型(练习)'},params:{mode:'diffSq'}},
          {id:2,label:{ko:'완전제곱식 이용',en:'using perfect squares',zh:'利用完全平方式'},params:{mode:'perfectSq'},
           concept:{ko:'깔끔한 수에 가까운 수는 (a±b)²=a²±2ab+b²로 펼칩니다. 102²=(100+2)²=10000+400+4=10404입니다. 거꾸로 a²+2ab+b²는 (a+b)²로 묶습니다.',
             en:'Expand a number near a round one with (a±b)²=a²±2ab+b²: 102²=(100+2)²=10000+400+4=10404. In reverse, group a²+2ab+b² as (a+b)².',
             zh:'接近整数的数用(a±b)²=a²±2ab+b²展开：102²=(100+2)²=10000+400+4=10404。反过来把a²+2ab+b²合成(a+b)²。'}},
          {id:3,label:{ko:'세제곱 공식 이용(실전)',en:'using cube formulas (main)',zh:'利用立方公式(实战)'},params:{mode:'cube'},
           concept:{ko:'(a±b)³=a³±3a²b+3ab²±b³입니다. 11³=(10+1)³=1000+300+30+1=1331처럼 펼치거나, 거꾸로 네 항을 (a+b)³으로 묶습니다.',
             en:'(a±b)³=a³±3a²b+3ab²±b³. Expand as in 11³=(10+1)³=1000+300+30+1=1331, or group four terms back into (a+b)³.',
             zh:'(a±b)³=a³±3a²b+3ab²±b³。像11³=(10+1)³=1000+300+30+1=1331那样展开，或把四项合成(a+b)³。'}}] },

MD95:{ name:{ko:'복소수의 사칙계산',en:'Arithmetic with Complex Numbers',zh:'复数的四则运算'}, gen:'md95_complexArith', prereq:['MD22'],
  unit:'M-95',
  concept:{ko:'복소수 a+bi는 i를 문자처럼 다루어 계산하고, i²이 나오면 −1로 바꿉니다. 덧셈·뺄셈은 실수부분끼리, 허수부분끼리 합니다. 답은 실수부분과 허수부분 두 칸에 씁니다.',
    en:'Treat i like a letter when working with a+bi, and replace i² with −1 whenever it appears. Add or subtract real parts with real parts and imaginary parts with imaginary parts. Enter the real part and the imaginary part in two boxes.',
    zh:'计算复数a+bi时把i当作字母，出现i²就换成−1。加减时实部与实部、虚部与虚部分别计算。答案分实部、虚部两格填写。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'덧셈과 뺄셈(연습, 2다칸)',en:'addition and subtraction (practice, 2 slots)',zh:'加法与减法(练习，2格)'},params:{mode:'addSub'}},
          {id:2,label:{ko:'곱셈(2다칸)',en:'multiplication (2 slots)',zh:'乘法(2格)'},params:{mode:'mul'},
           concept:{ko:'다항식처럼 전개한 뒤 i²=−1로 바꿉니다. (1+2i)(3−i)=3−i+6i−2i²=3+5i+2=5+5i입니다.',
             en:'Expand like a polynomial, then replace i² with −1: (1+2i)(3−i)=3−i+6i−2i²=3+5i+2=5+5i.',
             zh:'像多项式一样展开后把i²换成−1：(1+2i)(3−i)=3−i+6i−2i²=3+5i+2=5+5i。'}},
          {id:3,label:{ko:'나눗셈 — 켤레복소수 곱하기(실전, 2다칸)',en:'division by the conjugate (main, 2 slots)',zh:'除法——乘共轭复数(实战，2格)'},params:{mode:'div'},
           concept:{ko:'c+di의 켤레복소수는 c−di이고, 둘을 곱하면 c²+d²으로 실수가 됩니다. 분모·분자에 분모의 켤레를 곱해 분모를 실수로 만든 뒤 나눕니다.',
             en:'The conjugate of c+di is c−di, and their product c²+d² is real. Multiply top and bottom by the conjugate of the denominator to make it real, then divide.',
             zh:'c+di的共轭复数是c−di，两者之积c²+d²是实数。分子分母同乘分母的共轭，使分母变成实数后再除。'}}] },

MD96:{ name:{ko:'복소수가 서로 같을 조건',en:'When Two Complex Numbers Are Equal',zh:'复数相等的条件'}, gen:'md96_complexEqual', prereq:['MD95'],
  unit:'M-96',
  concept:{ko:'a, b, c, d가 실수일 때 a+bi=c+di이면 a=c이고 b=d입니다. 복소수 등식 하나가 실수 등식 두 개가 됩니다.',
    en:'For real a, b, c, d, a+bi=c+di means a=c and b=d. One complex equation becomes two real equations.',
    zh:'a、b、c、d为实数时，a+bi=c+di意味着a=c且b=d。一个复数等式变成两个实数等式。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'미지수 하나(연습)',en:'one unknown (practice)',zh:'一个未知数(练习)'},params:{mode:'one'}},
          {id:2,label:{ko:'미지수 둘(2다칸)',en:'two unknowns (2 slots)',zh:'两个未知数(2格)'},params:{mode:'two'},
           concept:{ko:'실수부분끼리 한 식, 허수부분끼리 한 식을 세워 따로 풉니다 — (x+1)+(2y)i=4+6i이면 x+1=4, 2y=6입니다.',
             en:'Write one equation for the real parts and one for the imaginary parts and solve each — (x+1)+(2y)i=4+6i gives x+1=4 and 2y=6.',
             zh:'实部列一个式子，虚部列一个式子，分别求解——(x+1)+(2y)i=4+6i得x+1=4、2y=6。'}},
          {id:3,label:{ko:'전개한 뒤 비교하기(실전, 2다칸)',en:'expand, then compare (main, 2 slots)',zh:'展开后比较(实战，2格)'},params:{mode:'mixed'},
           concept:{ko:'좌변을 먼저 실수부분과 허수부분으로 정리합니다. x(1+i)+y(2−i)=5+2i는 (x+2y)+(x−y)i=5+2i이므로 x+2y=5, x−y=2를 연립합니다.',
             en:'First sort the left side into real and imaginary parts: x(1+i)+y(2−i)=5+2i becomes (x+2y)+(x−y)i=5+2i, so solve x+2y=5 and x−y=2 together.',
             zh:'先把左边整理成实部和虚部：x(1+i)+y(2−i)=5+2i即(x+2y)+(x−y)i=5+2i，联立x+2y=5、x−y=2。'}}] },

MD97:{ name:{ko:'i의 거듭제곱과 음수의 제곱근',en:'Powers of i & Square Roots of Negatives',zh:'i的幂与负数的平方根'}, gen:'md97_iPower', prereq:['MD95'],
  unit:'M-97',
  concept:{ko:'i, i²=−1, i³=−i, i⁴=1이 네 번마다 되풀이됩니다. 그래서 iⁿ은 n을 4로 나눈 나머지만 보면 됩니다. 음수 −a(a>0)의 제곱근은 √a·i입니다.',
    en:'i, i²=−1, i³=−i, i⁴=1 repeat every four steps, so iⁿ depends only on the remainder of n divided by 4. A square root of a negative −a (a>0) is √a·i.',
    zh:'i、i²=−1、i³=−i、i⁴=1每四次循环一遍，所以iⁿ只看n除以4的余数。负数−a(a>0)的平方根是√a·i。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'i의 거듭제곱(연습, 2다칸)',en:'powers of i (practice, 2 slots)',zh:'i的幂(练习，2格)'},params:{mode:'power'}},
          {id:2,label:{ko:'거듭제곱의 합(2다칸)',en:'sums of powers (2 slots)',zh:'幂的和(2格)'},params:{mode:'sum'},
           concept:{ko:'i+i²+i³+i⁴=i−1−i+1=0입니다. 연속한 네 항씩 묶으면 0이 되므로 마지막에 남은 항만 더합니다.',
             en:'i+i²+i³+i⁴=i−1−i+1=0, so every run of four consecutive terms is 0; add only the terms left at the end.',
             zh:'i+i²+i³+i⁴=i−1−i+1=0，连续四项一组为0，只加最后剩下的项。'}},
          {id:3,label:{ko:'음수의 제곱근 계산(실전)',en:'computing with roots of negatives (main)',zh:'负数平方根的计算(实战)'},params:{mode:'negRoot'},
           concept:{ko:'√(−a)를 먼저 √a·i로 바꾼 뒤 계산합니다. √(−2)·√(−8)=√2i·√8i=4i²=−4입니다. 둘 다 음수일 때 √(−2)·√(−8)을 √16으로 합치면 틀립니다.',
             en:'Rewrite √(−a) as √a·i before computing: √(−2)·√(−8)=√2i·√8i=4i²=−4. Merging it into √16 when both are negative is wrong.',
             zh:'先把√(−a)写成√a·i再计算：√(−2)·√(−8)=√2i·√8i=4i²=−4。两者都为负数时合并成√16是错的。'}}] },

MD98:{ name:{ko:'두 수를 근으로 하는 이차방정식',en:'Building a Quadratic from Its Roots',zh:'以两数为根的二次方程'}, gen:'md98_buildQuadratic', prereq:['MD27'],
  unit:'M-98',
  concept:{ko:'두 수 α, β를 근으로 하고 x²의 계수가 1인 이차방정식은 x²−(α+β)x+αβ=0입니다. 두 근의 합과 곱만 알면 방정식을 세울 수 있습니다.',
    en:'The quadratic with leading coefficient 1 and roots α and β is x²−(α+β)x+αβ=0. The sum and product of the roots are all you need to build it.',
    zh:'以α、β为根且x²系数为1的二次方程是x²−(α+β)x+αβ=0。只要知道两根之和与积就能列出方程。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'두 정수 근(연습, 2다칸)',en:'two integer roots (practice, 2 slots)',zh:'两个整数根(练习，2格)'},params:{mode:'intRoots'}},
          {id:2,label:{ko:'근의 합·곱으로 새 방정식(2다칸)',en:'a new equation from sum and product (2 slots)',zh:'由根的和·积列新方程(2格)'},params:{mode:'shifted'},
           concept:{ko:'원래 방정식에서 α+β, αβ를 구하고 새 두 근의 합과 곱을 계산합니다. 두 근이 α+1, β+1이면 합은 (α+β)+2, 곱은 αβ+(α+β)+1입니다.',
             en:'Get α+β and αβ from the original equation, then compute the sum and product of the new roots. For α+1 and β+1 the sum is (α+β)+2 and the product is αβ+(α+β)+1.',
             zh:'由原方程求α+β、αβ，再算新两根的和与积。两根为α+1、β+1时，和为(α+β)+2，积为αβ+(α+β)+1。'}},
          {id:3,label:{ko:'켤레근(실전, 2다칸)',en:'conjugate roots (main, 2 slots)',zh:'共轭根(实战，2格)'},params:{mode:'conjugate'},
           concept:{ko:'계수가 유리수이면 m+√n과 m−√n이 함께 근이고, 계수가 실수이면 m+ni와 m−ni가 함께 근입니다. 두 근의 합 2m과 곱으로 a, b를 구합니다.',
             en:'With rational coefficients m+√n and m−√n are roots together; with real coefficients m+ni and m−ni are roots together. Use the sum 2m and the product to find a and b.',
             zh:'系数为有理数时m+√n与m−√n同为根；系数为实数时m+ni与m−ni同为根。用两根之和2m与积求a、b。'}}] },

MD99:{ name:{ko:'이차함수의 그래프와 직선의 위치 관계',en:'A Parabola and a Line: Relative Position',zh:'二次函数图象与直线的位置关系'}, gen:'md99_graphLine', prereq:['MD26'],
  unit:'M-99',
  concept:{ko:'이차함수의 그래프와 직선(또는 x축)의 교점은 두 식을 같다고 놓은 이차방정식의 실근입니다. 판별식 D>0이면 두 점에서 만나고, D=0이면 접하고, D<0이면 만나지 않습니다.',
    en:'The common points of a parabola and a line (or the x-axis) are the real roots of the quadratic you get by setting the two equal. D>0 means two points, D=0 means they touch, and D<0 means they do not meet.',
    zh:'二次函数图象与直线(或x轴)的交点，是令两式相等所得二次方程的实根。判别式D>0有两个交点，D=0相切，D<0不相交。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'교점의 개수(연습)',en:'the number of common points (practice)',zh:'交点的个数(练习)'},params:{mode:'count'}},
          {id:2,label:{ko:'접할 조건의 k',en:'k for tangency',zh:'相切条件中的k'},params:{mode:'tangent'},
           concept:{ko:'접하려면 D=0입니다. y=x²+2x+k와 y=0이면 D=4−4k=0에서 k=1입니다.',
             en:'Tangency means D=0: for y=x²+2x+k and y=0, D=4−4k=0 gives k=1.',
             zh:'相切即D=0：y=x²+2x+k与y=0时，D=4−4k=0，得k=1。'}},
          {id:3,label:{ko:'k의 범위의 끝값(실전)',en:'the endpoint of the range of k (main)',zh:'k的范围的端点(实战)'},params:{mode:'range'},
           concept:{ko:'두 점에서 만나려면 D>0, 만나지 않으려면 D<0입니다. 부등식을 k에 대해 풀어 경계값을 구합니다 — D=4−4k>0이면 k<1입니다.',
             en:'Two common points need D>0 and none need D<0. Solve the inequality for k to find the boundary — D=4−4k>0 gives k<1.',
             zh:'两个交点需D>0，没有交点需D<0。解关于k的不等式求出边界值——D=4−4k>0得k<1。'}}] },

MD100:{ name:{ko:'제한된 범위에서 이차함수의 최대·최소',en:'Max & Min of a Quadratic on an Interval',zh:'限定范围内二次函数的最值'}, gen:'md100_rangeExtrema', prereq:['MD80'],
  unit:'M-100',
  concept:{ko:'x의 범위가 정해지면 최댓값·최솟값은 꼭짓점과 양 끝점 가운데에서 나옵니다. 먼저 y=a(x−p)²+q로 고쳐 꼭짓점이 범위 안에 있는지 확인합니다.',
    en:'When x is restricted to an interval, the maximum and minimum come from the vertex and the two endpoints. First rewrite as y=a(x−p)²+q and check whether the vertex lies in the interval.',
    zh:'x的范围确定后，最大值和最小值出现在顶点与两个端点之中。先化成y=a(x−p)²+q，看顶点是否在范围内。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'꼭짓점이 범위 안(연습)',en:'vertex inside the interval (practice)',zh:'顶点在范围内(练习)'},params:{mode:'inside'}},
          {id:2,label:{ko:'꼭짓점이 범위 밖',en:'vertex outside the interval',zh:'顶点在范围外'},params:{mode:'outside'},
           concept:{ko:'꼭짓점이 범위 밖이면 그 범위에서 그래프는 한쪽으로만 올라가거나 내려갑니다. 그래서 최댓값·최솟값은 양 끝점에서 나옵니다.',
             en:'If the vertex is outside the interval, the graph only rises or only falls there, so the maximum and minimum occur at the two endpoints.',
             zh:'顶点在范围外时，图象在该范围内只升或只降，所以最值出现在两个端点。'}},
          {id:3,label:{ko:'최댓값·최솟값으로 상수 구하기(실전)',en:'find the constant from an extreme value (main)',zh:'由最值求常数(实战)'},params:{mode:'unknown'},
           concept:{ko:'상수항 k는 그래프를 위아래로만 옮기므로 최댓값·최솟값이 나오는 x는 그대로입니다. k를 뺀 식의 최댓값·최솟값을 구한 뒤 주어진 값과 같게 놓습니다.',
             en:'The constant k only moves the graph up or down, so the x where the extreme occurs stays the same. Find the extreme value without k, then set it plus k equal to the given value.',
             zh:'常数k只使图象上下平移，取得最值的x不变。先求不含k部分的最值，再令它加k等于给定值。'}}] },

/* ── MD101~MD114 공통수학1 새 유형(2026-09-29) — docs/high-build-spec.md 뒤 14개.
   교재는 챕터 제목만 근거로 쓰고 문제는 새로 만든다. gen: engine/threads/mid18.js */
MD101:{ name:{ko:'고차방정식',en:'Higher-Degree Equations',zh:'高次方程'}, gen:'md101_higherEq', prereq:['MD93'],
  unit:'M-101',
  concept:{ko:'삼차·사차방정식은 인수분해해서 일차·이차방정식으로 쪼개어 풉니다. 인수정리로 P(a)=0 인 a 를 찾으면 x−a 가 인수이고, 조립제법으로 나머지 식을 구합니다.',
    en:'Solve cubic and quartic equations by factoring them into linear and quadratic pieces. If P(a)=0 then x−a is a factor (factor theorem), and synthetic division gives the rest.',
    zh:'三次、四次方程通过因式分解拆成一次、二次方程来解。由因式定理，若P(a)=0则x−a是因式，再用综合除法求出其余部分。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'정수 근 하나 찾기(연습)',en:'find the one integer root (practice)',zh:'求唯一的整数根(练习)'},params:{mode:'oneRoot'}},
          {id:2,label:{ko:'세 근 중 가장 큰 근·작은 근',en:'largest or smallest of three roots',zh:'三个根中最大或最小的根'},params:{mode:'largest'},
           concept:{ko:'근 하나를 찾아 (x−a)(이차식)=0 으로 만든 뒤 이차식을 다시 인수분해하면 세 근이 모두 나옵니다. x³−2x²−5x+6=0 은 x=1 을 넣으면 0 이므로 (x−1)(x²−x−6)=(x−1)(x+2)(x−3)=0 입니다.',
             en:'Find one root to get (x−a)(quadratic)=0, then factor the quadratic to get all three roots. x³−2x²−5x+6=0 is 0 at x=1, so it becomes (x−1)(x²−x−6)=(x−1)(x+2)(x−3)=0.',
             zh:'找到一个根化成(x−a)(二次式)=0，再把二次式分解就得到全部三个根。x³−2x²−5x+6=0在x=1时为0，所以(x−1)(x²−x−6)=(x−1)(x+2)(x−3)=0。'}},
          {id:3,label:{ko:'복이차방정식 — 치환(실전)',en:'biquadratic equations by substitution (main)',zh:'双二次方程——换元(实战)'},params:{mode:'biquad'},
           concept:{ko:'x⁴+ax²+b=0 은 x²=t 로 두면 t²+at+b=0 이 됩니다. t 를 구한 뒤 x²=t 를 풀고, t<0 이면 실근이 없습니다. x⁴−5x²+4=0 은 (t−1)(t−4)=0 이므로 x=±1, ±2 입니다.',
             en:'For x⁴+ax²+b=0 put t=x² to get t²+at+b=0. Solve for t, then x²=t; if t<0 there is no real root. x⁴−5x²+4=0 gives (t−1)(t−4)=0, so x=±1, ±2.',
             zh:'x⁴+ax²+b=0令t=x²得t²+at+b=0。求出t后解x²=t，t<0时没有实根。x⁴−5x²+4=0得(t−1)(t−4)=0，所以x=±1、±2。'}}] },

MD102:{ name:{ko:'삼차방정식의 근과 계수의 관계',en:'Roots and Coefficients of a Cubic',zh:'三次方程的根与系数的关系'}, gen:'md102_cubicVieta', prereq:['MD101'],
  unit:'M-102',
  concept:{ko:'ax³+bx²+cx+d=0 의 세 근을 α, β, γ 라 하면 α+β+γ=−b/a, αβ+βγ+γα=c/a, αβγ=−d/a 입니다. 근을 하나도 구하지 않고 계수만으로 계산합니다.',
    en:'If α, β, γ are the roots of ax³+bx²+cx+d=0, then α+β+γ=−b/a, αβ+βγ+γα=c/a and αβγ=−d/a. You compute from the coefficients alone, without finding any root.',
    zh:'设ax³+bx²+cx+d=0的三个根为α、β、γ，则α+β+γ=−b/a，αβ+βγ+γα=c/a，αβγ=−d/a。不必求出任何一个根，只用系数计算。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'세 근의 합(연습)',en:'sum of the roots (practice)',zh:'三根之和(练习)'},params:{mode:'sum'}},
          {id:2,label:{ko:'세 근의 곱',en:'product of the roots',zh:'三根之积'},params:{mode:'product'},
           concept:{ko:'세 근의 곱은 αβγ=−d/a 입니다. 부호에 주의합니다 — 2x³−x+6=0 이면 αβγ=−6/2=−3 입니다.',
             en:'The product of the roots is αβγ=−d/a. Mind the sign: for 2x³−x+6=0, αβγ=−6/2=−3.',
             zh:'三根之积αβγ=−d/a，注意符号——2x³−x+6=0时αβγ=−6/2=−3。'}},
          {id:3,label:{ko:'두 근씩 곱의 합과 식의 값(실전)',en:'sum of pairwise products and related values (main)',zh:'两两之积的和及式子的值(实战)'},params:{mode:'pair'},
           concept:{ko:'αβ+βγ+γα=c/a 입니다. 이것과 합·곱을 묶으면 α²+β²+γ²=(α+β+γ)²−2(αβ+βγ+γα), 1/α+1/β+1/γ=(αβ+βγ+γα)/αβγ 도 구할 수 있습니다.',
             en:'αβ+βγ+γα=c/a. Combined with the sum and product it also gives α²+β²+γ²=(α+β+γ)²−2(αβ+βγ+γα) and 1/α+1/β+1/γ=(αβ+βγ+γα)/αβγ.',
             zh:'αβ+βγ+γα=c/a。与和、积结合，还能求α²+β²+γ²=(α+β+γ)²−2(αβ+βγ+γα)和1/α+1/β+1/γ=(αβ+βγ+γα)/αβγ。'}}] },

MD103:{ name:{ko:'x³=1 의 허근 ω',en:'The Complex Cube Root of Unity ω',zh:'x³=1的虚根ω'}, gen:'md103_omega', prereq:['MD101'],
  unit:'M-103',
  concept:{ko:'x³−1=(x−1)(x²+x+1)=0 에서 허근 ω 는 x²+x+1=0 의 근입니다. 그래서 ω³=1 이고 ω²+ω+1=0 입니다. 이 두 식으로 ω 가 들어간 식을 간단히 합니다.',
    en:'From x³−1=(x−1)(x²+x+1)=0, the imaginary root ω is a root of x²+x+1=0. So ω³=1 and ω²+ω+1=0, and these two facts simplify any expression in ω.',
    zh:'由x³−1=(x−1)(x²+x+1)=0，虚根ω是x²+x+1=0的根，所以ω³=1且ω²+ω+1=0。用这两个式子化简含ω的式子。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'ω²+ω+1=0 과 ω³=1 쓰기(연습)',en:'using ω²+ω+1=0 and ω³=1 (practice)',zh:'利用ω²+ω+1=0与ω³=1(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'ω 의 거듭제곱의 합',en:'sums of powers of ω',zh:'ω的幂的和'},params:{mode:'powerSum'},
           concept:{ko:'ωⁿ 은 n 을 3으로 나눈 나머지에 따라 1, ω, ω² 가 되풀이됩니다. 연속한 세 항 ωᵏ+ωᵏ⁺¹+ωᵏ⁺²=ωᵏ(1+ω+ω²)=0 이므로 셋씩 묶어 지웁니다.',
             en:'ωⁿ cycles through 1, ω, ω² according to the remainder of n divided by 3. Three consecutive terms ωᵏ+ωᵏ⁺¹+ωᵏ⁺²=ωᵏ(1+ω+ω²)=0, so cancel them in groups of three.',
             zh:'ωⁿ按n除以3的余数在1、ω、ω²之间循环。连续三项ωᵏ+ωᵏ⁺¹+ωᵏ⁺²=ωᵏ(1+ω+ω²)=0，三个一组消去。'}},
          {id:3,label:{ko:'ω 가 들어간 식의 값(실전)',en:'values of expressions in ω (main)',zh:'含ω的式子的值(实战)'},params:{mode:'expr'},
           concept:{ko:'1+ω=−ω², 1+ω²=−ω, ω+ω̄=−1, ωω̄=1 로 바꾸면 분수와 곱이 정리됩니다. (2+ω)(2+ω²)=4+2(ω+ω²)+ω³=4−2+1=3 입니다.',
             en:'Replacing 1+ω=−ω², 1+ω²=−ω, ω+ω̄=−1 and ωω̄=1 tidies fractions and products: (2+ω)(2+ω²)=4+2(ω+ω²)+ω³=4−2+1=3.',
             zh:'把1+ω换成−ω²、1+ω²换成−ω，并用ω+ω̄=−1、ωω̄=1，分式和乘积就能化简：(2+ω)(2+ω²)=4+2(ω+ω²)+ω³=4−2+1=3。'}}] },

MD104:{ name:{ko:'연립이차방정식',en:'Systems with a Quadratic Equation',zh:'二元二次方程组'}, gen:'md104_simulQuad', prereq:['MD98'],
  unit:'M-104',
  concept:{ko:'일차방정식이 있으면 한 문자를 다른 문자로 나타내어 이차방정식에 넣습니다. 둘 다 이차이면 인수분해되는 식을 찾아 일차식 두 개로 나눕니다. 답은 x, y 두 칸에 씁니다.',
    en:'If one equation is linear, write one variable in terms of the other and substitute into the quadratic. If both are quadratic, factor one of them into two linear equations. Enter x and y in two boxes.',
    zh:'若有一次方程，用一个字母表示另一个，代入二次方程。两个都是二次时，找能因式分解的方程拆成两个一次方程。答案分x、y两格填写。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'일차식과 이차식(연습, 2다칸)',en:'one linear, one quadratic (practice, 2 slots)',zh:'一次与二次(练习，2格)'},params:{mode:'linQuad'}},
          {id:2,label:{ko:'이차식과 이차식(2다칸)',en:'two quadratics (2 slots)',zh:'两个二次方程(2格)'},params:{mode:'quadQuad'},
           concept:{ko:'우변이 0 인 이차식이 인수분해되면 일차식 두 개가 됩니다. x²−xy−2y²=0 은 (x−2y)(x+y)=0 이므로 x=2y 또는 x=−y 를 다른 식에 넣습니다.',
             en:'A quadratic equal to 0 that factors splits into two linear equations: x²−xy−2y²=0 is (x−2y)(x+y)=0, so substitute x=2y or x=−y into the other equation.',
             zh:'右边为0的二次式能因式分解时就变成两个一次式：x²−xy−2y²=0即(x−2y)(x+y)=0，把x=2y或x=−y代入另一个方程。'}},
          {id:3,label:{ko:'대칭형 — 합과 곱(실전, 2다칸)',en:'symmetric systems via sum and product (main, 2 slots)',zh:'对称型——和与积(实战，2格)'},params:{mode:'symmetric'},
           concept:{ko:'x+y=u, xy=v 를 알면 x, y 는 t²−ut+v=0 의 두 근입니다. x²+y² 이 주어지면 xy={(x+y)²−(x²+y²)}÷2 로 먼저 구합니다.',
             en:'If x+y=u and xy=v, then x and y are the roots of t²−ut+v=0. If x²+y² is given instead, first find xy={(x+y)²−(x²+y²)}÷2.',
             zh:'知道x+y=u、xy=v，则x、y是t²−ut+v=0的两个根。若给出x²+y²，先求xy={(x+y)²−(x²+y²)}÷2。'}}] },

MD105:{ name:{ko:'부정방정식',en:'Indeterminate Equations',zh:'不定方程'}, gen:'md105_indefinite', prereq:['MD104'],
  unit:'M-105',
  concept:{ko:'미지수보다 방정식이 적으면 해가 하나로 정해지지 않습니다. 이때 "자연수", "정수", "실수" 같은 조건을 써서 해를 좁힙니다.',
    en:'With fewer equations than unknowns the solution is not fixed. Conditions such as "natural number", "integer" or "real" narrow it down.',
    zh:'方程个数少于未知数时解不唯一。这时利用"自然数""整数""实数"等条件缩小范围。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'자연수 해의 개수(연습)',en:'number of natural-number solutions (practice)',zh:'自然数解的个数(练习)'},params:{mode:'intCount'}},
          {id:2,label:{ko:'곱의 꼴로 묶기',en:'grouping into a product',zh:'整理成积的形式'},params:{mode:'product'},
           concept:{ko:'xy−bx−ay 꼴은 ab 를 더해 (x−a)(y−b) 로 묶습니다. 곱이 정해진 정수이므로 약수를 짝지어 x, y 를 찾습니다 — xy−x−y=5 는 (x−1)(y−1)=6 입니다.',
             en:'For xy−bx−ay, add ab to group it as (x−a)(y−b). The product is a fixed integer, so pair up its divisors to find x and y — xy−x−y=5 becomes (x−1)(y−1)=6.',
             zh:'xy−bx−ay型加上ab整理成(x−a)(y−b)。积是确定的整数，把约数配对求x、y——xy−x−y=5即(x−1)(y−1)=6。'}},
          {id:3,label:{ko:'실수 조건 — 제곱의 합(실전, 2다칸)',en:'real condition: sum of squares (main, 2 slots)',zh:'实数条件——平方和(实战，2格)'},params:{mode:'real'},
           concept:{ko:'실수 A, B 에 대해 A²+B²=0 이면 A=0, B=0 입니다. x²+y²−2x+4y+5=0 은 (x−1)²+(y+2)²=0 이므로 x=1, y=−2 입니다.',
             en:'For real A and B, A²+B²=0 forces A=0 and B=0. x²+y²−2x+4y+5=0 is (x−1)²+(y+2)²=0, so x=1 and y=−2.',
             zh:'实数A、B满足A²+B²=0时A=0且B=0。x²+y²−2x+4y+5=0即(x−1)²+(y+2)²=0，所以x=1、y=−2。'}}] },

MD106:{ name:{ko:'식의 값의 범위',en:'Ranges of Expressions',zh:'式子的取值范围'}, gen:'md106_exprRange', prereq:['MD64'],
  unit:'M-106',
  concept:{ko:'x, y 의 범위가 주어지면 x+y, x−y, xy 의 범위를 끝값으로 구합니다. 더할 때는 작은 끝끼리·큰 끝끼리, 뺄 때는 작은 끝에서 큰 끝을 뺍니다. 답은 아래끝과 위끝 두 칸에 씁니다.',
    en:'Given ranges for x and y, find the ranges of x+y, x−y and xy from the endpoints. Add small end to small end and large to large; for a difference subtract the large end from the small end. Enter the lower and upper ends in two boxes.',
    zh:'给出x、y的范围，由端点求x+y、x−y、xy的范围。相加时小端加小端、大端加大端；相减时用小端减大端。答案分下端、上端两格填写。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'합의 범위(연습, 2다칸)',en:'range of a sum (practice, 2 slots)',zh:'和的范围(练习，2格)'},params:{mode:'sum'}},
          {id:2,label:{ko:'차의 범위(2다칸)',en:'range of a difference (2 slots)',zh:'差的范围(2格)'},params:{mode:'diff'},
           concept:{ko:'x−y 는 x+(−y) 입니다. 1≤y≤3 이면 −3≤−y≤−1 로 끝이 뒤바뀝니다. 그래서 x−y 의 아래끝은 (x 의 아래끝)−(y 의 위끝) 입니다.',
             en:'x−y is x+(−y). If 1≤y≤3 then −3≤−y≤−1, so the ends swap. The lower end of x−y is (lower end of x)−(upper end of y).',
             zh:'x−y就是x+(−y)。1≤y≤3时−3≤−y≤−1，两端互换。所以x−y的下端是(x的下端)−(y的上端)。'}},
          {id:3,label:{ko:'곱의 범위(실전, 2다칸)',en:'range of a product (main, 2 slots)',zh:'积的范围(实战，2格)'},params:{mode:'prod'},
           concept:{ko:'곱은 부호가 섞이면 끝끼리 곱한 값의 크기 순서가 바뀝니다. 끝값끼리의 곱 네 개를 모두 계산해 가장 작은 값과 가장 큰 값을 고릅니다.',
             en:'With mixed signs the order of the endpoint products can flip. Compute all four products of endpoints and take the smallest and the largest.',
             zh:'符号不同时端点乘积的大小顺序会变。把四个端点乘积都算出来，取最小值和最大值。'}}] },

MD107:{ name:{ko:'연립일차부등식',en:'Systems of Linear Inequalities',zh:'一元一次不等式组'}, gen:'md107_linSystem', prereq:['MD64'],
  unit:'M-107',
  concept:{ko:'연립부등식의 해는 각 부등식의 해의 공통부분입니다. 각각 풀어 수직선에 나타내고 겹치는 부분을 읽습니다. 음수를 곱하거나 나누면 부등호 방향이 바뀝니다.',
    en:'The solution of a system of inequalities is the common part of the individual solutions. Solve each, draw them on a number line and read the overlap. Multiplying or dividing by a negative number reverses the inequality.',
    zh:'不等式组的解是各不等式解的公共部分。分别求解后画在数轴上读出重叠部分。乘以或除以负数时不等号方向改变。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'정수해의 개수(연습)',en:'number of integer solutions (practice)',zh:'整数解的个数(练习)'},params:{mode:'count'}},
          {id:2,label:{ko:'가장 큰·작은 정수해',en:'largest or smallest integer solution',zh:'最大或最小的整数解'},params:{mode:'largest'},
           concept:{ko:'공통부분의 끝에 등호가 있으면 그 수도 해입니다. −1<x≤4 에서 가장 큰 정수는 4, 가장 작은 정수는 0 입니다.',
             en:'If an end of the common part has an equals sign, that number is a solution too. In −1<x≤4 the largest integer is 4 and the smallest is 0.',
             zh:'公共部分的端点带等号时，该数也是解。−1<x≤4中最大的整数是4，最小的是0。'}},
          {id:3,label:{ko:'해가 주어질 때 미정계수(실전)',en:'find the constant from the solution (main)',zh:'由解求待定系数(实战)'},params:{mode:'unknown'},
           concept:{ko:'a 가 있는 부등식도 x 에 대해 풀면 x>(a 의 식) 꼴이 됩니다. 그 끝값이 주어진 해의 끝값과 같다고 놓습니다 — 2x>a+4 의 해가 x>3 이면 (a+4)÷2=3 에서 a=2 입니다.',
             en:'Solving the inequality with a for x gives x>(expression in a). Set that end equal to the given end — if 2x>a+4 has solution x>3, then (a+4)÷2=3, so a=2.',
             zh:'含a的不等式对x求解得x>(含a的式子)。令此端点等于已知解的端点——2x>a+4的解为x>3时，由(a+4)÷2=3得a=2。'}}] },

MD108:{ name:{ko:'절댓값을 포함한 부등식',en:'Inequalities with Absolute Values',zh:'含绝对值的不等式'}, gen:'md108_absIneq', prereq:['MD107'],
  unit:'M-108',
  concept:{ko:'c>0 일 때 |A|<c 는 −c<A<c 이고, |A|>c 는 A<−c 또는 A>c 입니다. 절댓값 안이 0 이 되는 값을 기준으로 구간을 나누어 풀 수도 있습니다.',
    en:'For c>0, |A|<c means −c<A<c, and |A|>c means A<−c or A>c. You can also split into intervals at the values that make the inside 0.',
    zh:'c>0时，|A|<c即−c<A<c，|A|>c即A<−c或A>c。也可以以使绝对值内为0的值为界分区间求解。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'|ax−b|<c 꼴(연습, 2다칸)',en:'the form |ax−b|<c (practice, 2 slots)',zh:'|ax−b|<c型(练习，2格)'},params:{mode:'linear'}},
          {id:2,label:{ko:'정수해의 개수',en:'number of integer solutions',zh:'整数解的个数'},params:{mode:'count'},
           concept:{ko:'|x−1|+|x−5|≤6 처럼 절댓값이 둘이면 x<1, 1≤x<5, x≥5 로 나누어 풀고 합칩니다. 해의 끝이 분수여도 그 안의 정수만 셉니다.',
             en:'With two absolute values, as in |x−1|+|x−5|≤6, split into x<1, 1≤x<5 and x≥5, solve each and combine. Even if an end is a fraction, count only the integers inside.',
             zh:'像|x−1|+|x−5|≤6这样有两个绝对值时，分x<1、1≤x<5、x≥5求解再合并。端点是分数也只数其中的整数。'}},
          {id:3,label:{ko:'이차식과 절댓값(실전)',en:'absolute values with quadratics (main)',zh:'二次式与绝对值(实战)'},params:{mode:'quad'},
           concept:{ko:'x²=|x|² 이므로 x²−|x|−6<0 은 |x|=t 로 두면 (t−3)(t+2)<0, 곧 |x|<3 입니다. |x²−5|<4 는 1<x²<9 로 바꾸어 풉니다.',
             en:'Since x²=|x|², put t=|x| in x²−|x|−6<0 to get (t−3)(t+2)<0, that is |x|<3. Solve |x²−5|<4 as 1<x²<9.',
             zh:'因为x²=|x|²，x²−|x|−6<0令t=|x|得(t−3)(t+2)<0，即|x|<3。|x²−5|<4化成1<x²<9来解。'}}] },

MD109:{ name:{ko:'연립이차부등식',en:'Systems with Quadratic Inequalities',zh:'一元二次不等式组'}, gen:'md109_quadSystem', prereq:['MD107'],
  unit:'M-109',
  concept:{ko:'이차부등식은 인수분해해 두 근을 찾고, (x−α)(x−β)<0 이면 α<x<β, >0 이면 바깥쪽입니다(α<β). 연립이차부등식은 각 해의 공통부분을 구합니다.',
    en:'Factor a quadratic inequality to find its two roots α<β: (x−α)(x−β)<0 gives α<x<β, and >0 gives the outside. For a system, take the common part of the solutions.',
    zh:'二次不等式先因式分解求出两根α<β：(x−α)(x−β)<0得α<x<β，>0得两侧。不等式组取各解的公共部分。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'정수해의 개수(연습)',en:'number of integer solutions (practice)',zh:'整数解的个数(练习)'},params:{mode:'count'}},
          {id:2,label:{ko:'가장 작은 정수해',en:'smallest integer solution',zh:'最小的整数解'},params:{mode:'minInt'},
           concept:{ko:'두 해를 수직선에 겹쳐 그린 뒤 공통부분의 왼쪽 끝부터 정수를 확인합니다. 끝에 등호가 없으면 그 수는 빠집니다.',
             en:'Overlay both solutions on a number line and check integers from the left end of the common part. If an end has no equals sign, that number is excluded.',
             zh:'把两个解画在同一数轴上，从公共部分左端开始检查整数。端点不带等号时该数不算。'}},
          {id:3,label:{ko:'해가 없을 조건(실전)',en:'condition for no solution (main)',zh:'无解的条件(实战)'},params:{mode:'empty'},
           concept:{ko:'1≤x≤4 와 x>a 의 공통부분이 없으려면 a 가 4 이상이어야 합니다(a=4 이면 x>4 와 겹치지 않습니다). 끝값에서 등호가 있는지 꼭 따집니다.',
             en:'For 1≤x≤4 and x>a to have no common part, a must be at least 4 (with a=4, x>4 does not overlap). Always check the equals sign at the end.',
             zh:'要使1≤x≤4与x>a没有公共部分，a须不小于4(a=4时x>4不重叠)。一定要检查端点是否带等号。'}}] },

MD110:{ name:{ko:'합의 법칙과 곱의 법칙',en:'The Addition and Multiplication Rules',zh:'加法原理与乘法原理'}, gen:'md110_sumProduct', prereq:['MD88'],
  unit:'M-110',
  concept:{ko:'두 사건이 동시에 일어나지 않으면 경우의 수를 더하고(합의 법칙), 잇달아 일어나면 곱합니다(곱의 법칙). 겹치는 경우가 있으면 한 번만 세도록 뺍니다.',
    en:'If two events cannot happen together, add the counts (addition rule); if they happen one after another, multiply (multiplication rule). Subtract any overlap so it is counted once.',
    zh:'两件事不能同时发生时方法数相加(加法原理)，接连发生时相乘(乘法原理)。有重叠时减去，使其只算一次。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'합의 법칙(연습)',en:'addition rule (practice)',zh:'加法原理(练习)'},params:{mode:'sum'}},
          {id:2,label:{ko:'곱의 법칙',en:'multiplication rule',zh:'乘法原理'},params:{mode:'product'},
           concept:{ko:'A→B 가 3가지, B→C 가 4가지이면 A→B→C 는 3×4=12가지입니다. (a+b)(x+y+z) 를 전개한 항의 개수도 2×3=6 입니다.',
             en:'With 3 ways A→B and 4 ways B→C there are 3×4=12 ways A→B→C. Likewise (a+b)(x+y+z) expands into 2×3=6 terms.',
             zh:'A→B有3种、B→C有4种，则A→B→C有3×4=12种。(a+b)(x+y+z)展开的项数也是2×3=6。'}},
          {id:3,label:{ko:'약수의 개수와 총합(실전)',en:'number and sum of divisors (main)',zh:'约数的个数与总和(实战)'},params:{mode:'divisors'},
           concept:{ko:'72=2³×3² 의 약수는 2 의 지수 0~3 과 3 의 지수 0~2 를 하나씩 골라 만드므로 (3+1)×(2+1)=12개입니다. 총합은 (1+2+4+8)(1+3+9)=195 입니다.',
             en:'A divisor of 72=2³×3² picks an exponent 0–3 for 2 and 0–2 for 3, so there are (3+1)×(2+1)=12. Their sum is (1+2+4+8)(1+3+9)=195.',
             zh:'72=2³×3²的约数由2的指数0~3与3的指数0~2各取一个构成，共(3+1)×(2+1)=12个。总和为(1+2+4+8)(1+3+9)=195。'}}] },

MD111:{ name:{ko:'순열',en:'Permutations',zh:'排列'}, gen:'md111_perm', prereq:['MD110'],
  unit:'M-111',
  concept:{ko:'서로 다른 n 개에서 r 개를 골라 한 줄로 늘어놓는 경우의 수를 ₙPᵣ 라 하고, ₙPᵣ=n(n−1)(n−2)…(n−r+1) 입니다. 특히 ₙPₙ=n! 입니다.',
    en:'The number of ways to choose r of n different things and arrange them in a row is ₙPᵣ=n(n−1)(n−2)…(n−r+1). In particular ₙPₙ=n!.',
    zh:'从n个不同元素中取r个排成一列的方法数记作ₙPᵣ，ₙPᵣ=n(n−1)(n−2)…(n−r+1)。特别地ₙPₙ=n!。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'ₙPᵣ 의 값(연습)',en:'values of ₙPᵣ (practice)',zh:'ₙPᵣ的值(练习)'},params:{mode:'value'}},
          {id:2,label:{ko:'이웃하게 서는 경우',en:'arrangements with neighbours together',zh:'相邻的排列'},params:{mode:'adjacent'},
           concept:{ko:'이웃하는 것들은 한 묶음으로 보고 나머지와 함께 늘어놓은 뒤, 묶음 안에서 자리를 바꾸는 수를 곱합니다. 5명 중 A, B 가 이웃하면 4!×2!=48 입니다.',
             en:'Treat the neighbours as one block, arrange it with the others, then multiply by the ways to order inside the block. For 5 people with A and B together: 4!×2!=48.',
             zh:'把相邻的看成一组与其余一起排列，再乘以组内的排法。5人中A、B相邻：4!×2!=48。'}},
          {id:3,label:{ko:'이웃하지 않는 경우와 "적어도"(실전)',en:'not adjacent and "at least" (main)',zh:'不相邻与"至少"(实战)'},params:{mode:'apart'},
           concept:{ko:'이웃하지 않게 하려면 나머지를 먼저 세우고 그 사이사이와 양 끝에 넣습니다. "적어도"는 전체에서 반대 경우를 빼면 쉽습니다.',
             en:'To keep items apart, first line up the others and place the items in the gaps and at the ends. For "at least", subtract the opposite case from the total.',
             zh:'要使它们不相邻，先排好其余的，再插入空隙和两端。"至少"用全部减去相反情况更简单。'}}] },

MD112:{ name:{ko:'사전식 배열과 자연수의 개수',en:'Dictionary Order & Counting Numbers',zh:'字典排列与自然数的个数'}, gen:'md112_lexOrder', prereq:['MD111'],
  unit:'M-112',
  concept:{ko:'사전식으로 늘어놓으면 맨 앞자리가 작은 것부터 묶음으로 나옵니다. 맨 앞자리가 정해지면 나머지 (n−1) 자리는 (n−1)! 가지이므로 묶음 크기로 순서를 셉니다.',
    en:'In dictionary order the items come in blocks by first symbol, smallest first. Once the first place is fixed the other n−1 places give (n−1)! arrangements, so count positions block by block.',
    zh:'按字典顺序排列时，按首位从小到大成组出现。首位确定后其余n−1位有(n−1)!种，按组的大小数位置。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'몇 번째인가·몇 번째 수(연습)',en:'position of an item, item at a position (practice)',zh:'第几个·第几个数(练习)'},params:{mode:'rank'}},
          {id:2,label:{ko:'짝수·홀수·5의 배수의 개수',en:'counting even, odd or multiples of 5',zh:'偶数、奇数、5的倍数的个数'},params:{mode:'even'},
           concept:{ko:'짝수는 일의 자리가 짝수입니다. 일의 자리를 먼저 정하고 남은 카드로 나머지 자리를 채웁니다 — 1~5 에서 세 자리 짝수는 2×₄P₂=24 개입니다.',
             en:'An even number has an even ones digit. Fix the ones digit first, then fill the other places with the remaining cards — from 1–5 there are 2×₄P₂=24 three-digit even numbers.',
             zh:'偶数的个位是偶数。先定个位，再用剩下的卡片填其余位——用1~5组成的三位偶数有2×₄P₂=24个。'}},
          {id:3,label:{ko:'0 이 들어 있는 카드(실전)',en:'cards that include 0 (main)',zh:'含0的卡片(实战)'},params:{mode:'zero'},
           concept:{ko:'맨 앞자리에는 0 이 올 수 없습니다. 짝수를 셀 때는 일의 자리가 0 인 경우와 0 이 아닌 짝수인 경우로 나누어 더합니다.',
             en:'The first digit cannot be 0. When counting even numbers, split into ones digit 0 and ones digit a nonzero even number, and add.',
             zh:'首位不能是0。数偶数时，分个位是0和个位是非零偶数两种情况相加。'}}] },

MD113:{ name:{ko:'조합',en:'Combinations',zh:'组合'}, gen:'md113_comb', prereq:['MD111'],
  unit:'M-113',
  concept:{ko:'서로 다른 n 개에서 순서를 생각하지 않고 r 개를 고르는 경우의 수를 ₙCᵣ 라 하고, ₙCᵣ=ₙPᵣ÷r! 입니다. ₙCᵣ=ₙCₙ₋ᵣ 도 성립합니다.',
    en:'The number of ways to choose r of n different things without regard to order is ₙCᵣ=ₙPᵣ÷r!. Also ₙCᵣ=ₙCₙ₋ᵣ.',
    zh:'从n个不同元素中不计顺序取r个的方法数记作ₙCᵣ，ₙCᵣ=ₙPᵣ÷r!。并且ₙCᵣ=ₙCₙ₋ᵣ。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'ₙCᵣ 의 값(연습)',en:'values of ₙCᵣ (practice)',zh:'ₙCᵣ的值(练习)'},params:{mode:'value'}},
          {id:2,label:{ko:'특정한 것을 포함·제외',en:'including or excluding specific items',zh:'包含或不含特定元素'},params:{mode:'include'},
           concept:{ko:'A 를 반드시 뽑으면 A 를 먼저 넣고 나머지 (n−1) 명에서 (r−1) 명을 뽑습니다. A 를 빼면 (n−1) 명에서 r 명을 뽑습니다.',
             en:'If A must be chosen, put A in first and choose r−1 from the other n−1. If A is excluded, choose r from the other n−1.',
             zh:'A一定被选时，先放入A，再从其余n−1人中选r−1人。A不被选时，从其余n−1人中选r人。'}},
          {id:3,label:{ko:'"적어도"와 조건 있는 뽑기(실전)',en:'"at least" and conditional choices (main)',zh:'"至少"与有条件的选取(实战)'},params:{mode:'atLeast'},
           concept:{ko:'"여학생이 적어도 한 명"은 전체에서 남학생만 뽑는 경우를 뺍니다. 남학생 2명, 여학생 1명처럼 정해지면 ₘC₂×ₖC₁ 로 곱합니다.',
             en:'"At least one girl" is the total minus the all-boys choices. For an exact split such as 2 boys and 1 girl, multiply ₘC₂×ₖC₁.',
             zh:'"至少一名女生"用全部减去只选男生的情况。像2名男生1名女生这样确定时，相乘ₘC₂×ₖC₁。'}}] },

MD114:{ name:{ko:'뽑아서 나열하기와 도형의 개수',en:'Choose-then-Arrange & Counting Figures',zh:'先选后排与图形的个数'}, gen:'md114_selectArrange', prereq:['MD113'],
  unit:'M-114',
  concept:{ko:'뽑은 뒤 늘어놓는 문제는 (조합)×(순열)로 셉니다. 점으로 만드는 직선·삼각형은 점을 고르는 조합이고, 한 직선 위의 점처럼 겹치는 경우를 빼 줍니다.',
    en:'Choose-then-arrange problems are (combination)×(permutation). Lines and triangles from points are combinations of points, minus the overcounted cases such as points on one line.',
    zh:'先选后排的问题用(组合)×(排列)计算。由点构成的直线、三角形是选点的组合，要减去共线点等重复的情况。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'뽑아서 한 줄로 세우기(연습)',en:'choose and line up (practice)',zh:'选出后排成一排(练习)'},params:{mode:'arrange'}},
          {id:2,label:{ko:'직선과 대각선의 개수',en:'counting lines and diagonals',zh:'直线与对角线的条数'},params:{mode:'lines'},
           concept:{ko:'어느 세 점도 한 직선 위에 있지 않으면 직선은 ₙC₂ 개입니다. k 개가 한 직선 위에 있으면 ₖC₂ 개가 한 직선으로 겹치므로 ₙC₂−ₖC₂+1 입니다. n 각형의 대각선은 ₙC₂−n 개입니다.',
             en:'If no three points are collinear there are ₙC₂ lines. If k points lie on one line, their ₖC₂ lines coincide, giving ₙC₂−ₖC₂+1. An n-gon has ₙC₂−n diagonals.',
             zh:'任意三点不共线时直线有ₙC₂条。若有k点共线，它们的ₖC₂条重合为一条，得ₙC₂−ₖC₂+1。n边形的对角线有ₙC₂−n条。'}},
          {id:3,label:{ko:'삼각형의 개수(실전)',en:'counting triangles (main)',zh:'三角形的个数(实战)'},params:{mode:'triangles'},
           concept:{ko:'세 점을 고르면 삼각형이 되지만, 한 직선 위의 세 점은 삼각형이 되지 않습니다. 그래서 ₙC₃ 에서 한 직선 위의 점으로 고른 ₖC₃ 을 뺍니다.',
             en:'Choosing three points gives a triangle, except when the three lie on one line. So subtract ₖC₃ (choices from the collinear points) from ₙC₃.',
             zh:'选三点就构成三角形，但共线的三点不行。所以从ₙC₃中减去从共线点中选取的ₖC₃。'}}] },

/* ── MD115~MD124 공통수학2 새 유형 1차(2026-09-29) — docs/high-build-spec.md 공통수학2 앞 10개.
   교재는 챕터 제목만 근거로 쓰고 문제는 새로 만든다. gen: engine/threads/mid19.js */
MD115:{ name:{ko:'삼각형의 무게중심',en:'The Centroid of a Triangle',zh:'三角形的重心'}, gen:'md115_centroid', prereq:['MD32'],
  unit:'M-115',
  concept:{ko:'세 꼭짓점이 A(x₁, y₁), B(x₂, y₂), C(x₃, y₃) 인 삼각형의 무게중심은 G((x₁+x₂+x₃)/3, (y₁+y₂+y₃)/3) 입니다. 답은 x 좌표, y 좌표 두 칸에 씁니다.',
    en:'The centroid of the triangle with vertices A(x₁, y₁), B(x₂, y₂), C(x₃, y₃) is G((x₁+x₂+x₃)/3, (y₁+y₂+y₃)/3). Enter the x- and y-coordinates in two boxes.',
    zh:'顶点为A(x₁, y₁)、B(x₂, y₂)、C(x₃, y₃)的三角形的重心是G((x₁+x₂+x₃)/3, (y₁+y₂+y₃)/3)。答案分x坐标、y坐标两格填写。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'무게중심의 좌표(연습, 2다칸)',en:'coordinates of the centroid (practice, 2 slots)',zh:'重心的坐标(练习，2格)'},params:{mode:'coord'}},
          {id:2,label:{ko:'무게중심으로 꼭짓점 찾기(2다칸)',en:'find a vertex from the centroid (2 slots)',zh:'由重心求顶点(2格)'},params:{mode:'vertex'},
           concept:{ko:'x₁+x₂+x₃=3×(G 의 x 좌표) 이므로 x₃=3×(G 의 x 좌표)−x₁−x₂ 입니다. A(1, 2), B(3, −1), G(2, 1) 이면 C(2, 2) 입니다.',
             en:'Since x₁+x₂+x₃=3×(x of G), x₃=3×(x of G)−x₁−x₂. With A(1, 2), B(3, −1), G(2, 1), C is (2, 2).',
             zh:'因为x₁+x₂+x₃=3×(G的x坐标)，所以x₃=3×(G的x坐标)−x₁−x₂。A(1, 2)、B(3, −1)、G(2, 1)时C(2, 2)。'}},
          {id:3,label:{ko:'미지수가 있는 꼭짓점(실전)',en:'vertices with unknowns (main)',zh:'含未知数的顶点(实战)'},params:{mode:'sum'},
           concept:{ko:'x 좌표로 식 하나, y 좌표로 식 하나를 세웁니다. A(a, 1), B(2, b), C(4, 5), G(2, 3) 이면 (a+2+4)/3=2 에서 a=0, (1+b+5)/3=3 에서 b=3 입니다.',
             en:'Write one equation from the x-coordinates and one from the y-coordinates. With A(a, 1), B(2, b), C(4, 5), G(2, 3): (a+2+4)/3=2 gives a=0 and (1+b+5)/3=3 gives b=3.',
             zh:'由x坐标列一个方程，由y坐标列一个方程。A(a, 1)、B(2, b)、C(4, 5)、G(2, 3)时，(a+2+4)/3=2得a=0，(1+b+5)/3=3得b=3。'}}] },

MD116:{ name:{ko:'점과 직선 사이의 거리',en:'Distance from a Point to a Line',zh:'点到直线的距离'}, gen:'md116_pointLine', prereq:['MD34'],
  unit:'M-116',
  concept:{ko:'점 (x₁, y₁) 과 직선 ax+by+c=0 사이의 거리는 |ax₁+by₁+c|/√(a²+b²) 입니다. 직선에 내린 수선의 길이이므로 가장 짧은 거리입니다.',
    en:'The distance from (x₁, y₁) to the line ax+by+c=0 is |ax₁+by₁+c|/√(a²+b²) — the length of the perpendicular, the shortest distance.',
    zh:'点(x₁, y₁)到直线ax+by+c=0的距离为|ax₁+by₁+c|/√(a²+b²)，即垂线段的长，是最短距离。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'점과 직선 사이의 거리(연습)',en:'distance from a point to a line (practice)',zh:'点到直线的距离(练习)'},params:{mode:'dist'}},
          {id:2,label:{ko:'평행한 두 직선 사이의 거리',en:'distance between parallel lines',zh:'两平行直线间的距离'},params:{mode:'parallel'},
           concept:{ko:'평행한 두 직선 사이의 거리는 한 직선 위의 점에서 다른 직선까지의 거리입니다. x, y 의 계수를 같게 맞추면 ax+by+c=0, ax+by+c′=0 사이의 거리는 |c−c′|/√(a²+b²) 입니다.',
             en:'The distance between parallel lines is the distance from any point of one to the other. After matching the x- and y-coefficients, the distance between ax+by+c=0 and ax+by+c′=0 is |c−c′|/√(a²+b²).',
             zh:'两平行直线间的距离是一条直线上任一点到另一条直线的距离。把x、y的系数化成相同后，ax+by+c=0与ax+by+c′=0之间的距离为|c−c′|/√(a²+b²)。'}},
          {id:3,label:{ko:'거리로 미정계수 구하기(실전)',en:'unknown coefficients from a distance (main)',zh:'由距离求待定系数(实战)'},params:{mode:'unknown'},
           concept:{ko:'거리 공식에 넣으면 절댓값이 있는 방정식 |식|=d√(a²+b²) 이 되고, 식=±d√(a²+b²) 로 답이 두 개 나옵니다. 조건(양수·음수)에 맞는 것을 고릅니다.',
             en:'The distance formula gives an absolute-value equation |expression|=d√(a²+b²), so expression=±d√(a²+b²) has two solutions; choose the one that fits the condition (positive or negative).',
             zh:'代入距离公式得到含绝对值的方程|式|=d√(a²+b²)，即式=±d√(a²+b²)，有两个解，选出符合条件(正或负)的那个。'}}] },

MD117:{ name:{ko:'좌표축에 접하는 원',en:'Circles Tangent to the Axes',zh:'与坐标轴相切的圆'}, gen:'md117_circleAxis', prereq:['MD35'],
  unit:'M-117',
  concept:{ko:'중심이 (a, b) 인 원이 x축에 접하면 반지름은 |b|, y축에 접하면 반지름은 |a| 입니다. 두 축에 모두 접하면 |a|=|b|=r 입니다.',
    en:'A circle with center (a, b) touching the x-axis has radius |b|; touching the y-axis, radius |a|. Touching both axes means |a|=|b|=r.',
    zh:'圆心为(a, b)的圆与x轴相切时半径为|b|，与y轴相切时半径为|a|。与两轴都相切时|a|=|b|=r。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'x축에 접하는 원(연습)',en:'circles tangent to the x-axis (practice)',zh:'与x轴相切的圆(练习)'},params:{mode:'xAxis'}},
          {id:2,label:{ko:'x축과 y축에 모두 접하는 원',en:'circles tangent to both axes',zh:'与两坐标轴都相切的圆'},params:{mode:'both'},
           concept:{ko:'제1사분면에서 두 축에 접하는 원은 (x−r)²+(y−r)²=r² 입니다. 사분면에 따라 중심의 부호만 바뀝니다. 점을 지나면 r 에 대한 이차방정식이 되어 원이 두 개 나옵니다.',
             en:'In the first quadrant a circle touching both axes is (x−r)²+(y−r)²=r²; other quadrants only change the signs of the center. Passing through a point gives a quadratic in r, hence two circles.',
             zh:'在第一象限与两轴都相切的圆是(x−r)²+(y−r)²=r²，其他象限只改变圆心的符号。经过一点时得到关于r的二次方程，所以有两个圆。'}},
          {id:3,label:{ko:'접하는 조건으로 미정계수 구하기(실전)',en:'unknown constants from tangency (main)',zh:'由相切条件求待定常数(实战)'},params:{mode:'unknown'},
           concept:{ko:'일반형 x²+y²+Ax+By+C=0 을 (x−a)²+(y−b)²=r² 꼴로 바꾼 뒤, x축에 접하면 r²=b², y축에 접하면 r²=a² 으로 놓습니다.',
             en:'Rewrite x²+y²+Ax+By+C=0 as (x−a)²+(y−b)²=r², then set r²=b² for the x-axis or r²=a² for the y-axis.',
             zh:'把一般式x²+y²+Ax+By+C=0化成(x−a)²+(y−b)²=r²，与x轴相切时令r²=b²，与y轴相切时令r²=a²。'}}] },

MD118:{ name:{ko:'원과 직선의 위치 관계',en:'A Circle and a Line',zh:'圆与直线的位置关系'}, gen:'md118_circleLine', prereq:['MD116','MD35'],
  unit:'M-118',
  concept:{ko:'원의 중심과 직선 사이의 거리 d 와 반지름 r 을 비교합니다. d<r 이면 두 점에서 만나고, d=r 이면 접하고, d>r 이면 만나지 않습니다. 연립한 이차방정식의 판별식 D 의 부호로도 알 수 있습니다.',
    en:'Compare the distance d from the center to the line with the radius r: d<r means two common points, d=r tangent, d>r no common point. The sign of the discriminant D of the combined quadratic tells the same.',
    zh:'比较圆心到直线的距离d与半径r：d<r时交于两点，d=r时相切，d>r时没有交点。联立所得二次方程的判别式D的符号也能判断。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'교점의 개수(연습)',en:'number of common points (practice)',zh:'交点的个数(练习)'},params:{mode:'count'}},
          {id:2,label:{ko:'접할 조건의 k',en:'k for tangency',zh:'相切条件中的k'},params:{mode:'tangent'},
           concept:{ko:'접하려면 d=r 입니다. |식+k|=r√(a²+b²) 에서 k 는 두 개이고, 조건(k>0 또는 k<0)으로 하나를 고릅니다.',
             en:'Tangency means d=r. From |expression+k|=r√(a²+b²) there are two values of k; the condition (k>0 or k<0) picks one.',
             zh:'相切时d=r。由|式+k|=r√(a²+b²)得k有两个值，用条件(k>0或k<0)选出一个。'}},
          {id:3,label:{ko:'두 점에서 만날 k 의 범위(실전, 2다칸)',en:'range of k for two common points (main, 2 slots)',zh:'交于两点时k的范围(实战，2格)'},params:{mode:'range'},
           concept:{ko:'두 점에서 만나려면 d<r 입니다. |식+k|<c 는 −c<식+k<c 이므로 k 의 범위의 양 끝을 두 칸에 씁니다.',
             en:'Two common points means d<r. |expression+k|<c is −c<expression+k<c, so enter both ends of the range of k.',
             zh:'交于两点时d<r。|式+k|<c即−c<式+k<c，把k的范围的两端填入两格。'}}] },

MD119:{ name:{ko:'원의 접선의 방정식',en:'Tangent Lines to a Circle',zh:'圆的切线方程'}, gen:'md119_tangentLine', prereq:['MD118'],
  unit:'M-119',
  concept:{ko:'접선은 접점에서 반지름에 수직입니다. 원 x²+y²=r² 위의 점 (x₁, y₁) 에서의 접선은 x₁x+y₁y=r², 기울기가 m 인 접선은 y=mx±r√(m²+1) 입니다.',
    en:'A tangent is perpendicular to the radius at the point of contact. For x²+y²=r², the tangent at (x₁, y₁) is x₁x+y₁y=r², and the tangents with slope m are y=mx±r√(m²+1).',
    zh:'切线在切点处垂直于半径。圆x²+y²=r²上点(x₁, y₁)处的切线为x₁x+y₁y=r²，斜率为m的切线为y=mx±r√(m²+1)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'원 위의 점에서의 접선(연습)',en:'tangent at a point on the circle (practice)',zh:'圆上一点处的切线(练习)'},params:{mode:'onCircle'}},
          {id:2,label:{ko:'기울기가 주어진 접선',en:'tangents with a given slope',zh:'已知斜率的切线'},params:{mode:'slope'},
           concept:{ko:'기울기가 m 인 접선은 y=mx±r√(m²+1) 입니다. 평행이면 기울기가 같고, 수직이면 기울기의 곱이 −1 입니다. x²+y²=5 에 접하고 기울기가 2 인 접선은 y=2x±5 입니다.',
             en:'The tangents with slope m are y=mx±r√(m²+1). Parallel lines share a slope; perpendicular slopes multiply to −1. For x²+y²=5 and slope 2, the tangents are y=2x±5.',
             zh:'斜率为m的切线为y=mx±r√(m²+1)。平行则斜率相同，垂直则斜率之积为−1。与x²+y²=5相切、斜率为2的切线是y=2x±5。'}},
          {id:3,label:{ko:'원 밖의 점에서 그은 접선(실전)',en:'tangents from an outside point (main)',zh:'从圆外一点引的切线(实战)'},params:{mode:'outside'},
           concept:{ko:'원 밖의 점 P 에서 접선은 두 개입니다. 접선의 길이는 PT=√(CP²−r²) 이고, 기울기는 y−q=m(x−p) 가 원에 접할 조건에서 나온 m 의 이차방정식의 두 근입니다.',
             en:'There are two tangents from an outside point P. The tangent length is PT=√(CP²−r²), and the slopes are the two roots of the quadratic in m from the condition that y−q=m(x−p) touches the circle.',
             zh:'从圆外一点P可引两条切线。切线长PT=√(CP²−r²)，斜率是y−q=m(x−p)与圆相切的条件所得关于m的二次方程的两根。'}}] },

MD120:{ name:{ko:'평행이동',en:'Translations',zh:'平移'}, gen:'md120_translate', prereq:['MD33','MD35'],
  unit:'M-120',
  concept:{ko:'평행이동 (x, y)→(x+a, y+b) 는 점의 좌표에 a, b 를 더합니다. 도형(직선·원)의 방정식은 x 대신 x−a, y 대신 y−b 를 넣어 옮깁니다.',
    en:'The translation (x, y)→(x+a, y+b) adds a and b to a point’s coordinates. For a figure (a line or circle), replace x with x−a and y with y−b in its equation.',
    zh:'平移(x, y)→(x+a, y+b)把点的坐标分别加a、b。图形(直线、圆)的方程用x−a代x、y−b代y。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'점의 평행이동(연습, 2다칸)',en:'translating a point (practice, 2 slots)',zh:'点的平移(练习，2格)'},params:{mode:'point'}},
          {id:2,label:{ko:'직선의 평행이동',en:'translating a line',zh:'直线的平移'},params:{mode:'line'},
           concept:{ko:'직선 y=2x+1 을 (x, y)→(x+3, y−2) 로 옮기면 y+2=2(x−3)+1, 곧 y=2x−7 입니다. 점과 달리 도형의 방정식에서는 부호가 반대인 수를 넣습니다.',
             en:'Moving y=2x+1 by (x, y)→(x+3, y−2) gives y+2=2(x−3)+1, i.e. y=2x−7. Unlike a point, in a figure’s equation you substitute the opposite signs.',
             zh:'把直线y=2x+1按(x, y)→(x+3, y−2)平移得y+2=2(x−3)+1，即y=2x−7。与点不同，图形方程中代入的是符号相反的数。'}},
          {id:3,label:{ko:'원의 평행이동(실전, 2다칸)',en:'translating a circle (main, 2 slots)',zh:'圆的平移(实战，2格)'},params:{mode:'circle'},
           concept:{ko:'원을 평행이동하면 반지름은 그대로이고 중심만 옮겨집니다. 일반형이면 먼저 표준형으로 바꾸어 중심을 찾습니다.',
             en:'Translating a circle keeps its radius and moves only its center. If the equation is in general form, rewrite it in standard form to find the center first.',
             zh:'平移圆时半径不变，只移动圆心。若是一般式，先化成标准式求出圆心。'}}] },

MD121:{ name:{ko:'대칭이동',en:'Reflections',zh:'对称变换'}, gen:'md121_reflect', prereq:['MD120'],
  unit:'M-121',
  concept:{ko:'x축(y=0) 대칭은 (x, y)→(x, −y), y축(x=0) 대칭은 (x, y)→(−x, y), 원점(O) 대칭은 (x, y)→(−x, −y), 직선 y=x 대칭은 (x, y)→(y, x) 입니다. 도형은 방정식의 x, y 를 같은 방법으로 바꿉니다.',
    en:'Reflection in the x-axis (y=0): (x, y)→(x, −y); in the y-axis (x=0): (x, y)→(−x, y); in the origin (O): (x, y)→(−x, −y); in y=x: (x, y)→(y, x). For a figure, change x and y in its equation the same way.',
    zh:'关于x轴(y=0)对称：(x, y)→(x, −y)；关于y轴(x=0)：(x, y)→(−x, y)；关于原点(O)：(x, y)→(−x, −y)；关于直线y=x：(x, y)→(y, x)。图形则把方程中的x、y同样替换。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'점의 대칭이동(연습, 2다칸)',en:'reflecting a point (practice, 2 slots)',zh:'点的对称变换(练习，2格)'},params:{mode:'point'}},
          {id:2,label:{ko:'직선의 대칭이동(2다칸)',en:'reflecting a line (2 slots)',zh:'直线的对称变换(2格)'},params:{mode:'line'},
           concept:{ko:'직선의 방정식에서 x, y 를 대칭점의 좌표로 바꿉니다. y=2x+3 을 x축에 대하여 대칭이동하면 −y=2x+3, 곧 y=−2x−3 이고, 직선 y=x 에 대하여 대칭이동하면 x 와 y 를 바꿉니다.',
             en:'Replace x and y in the line’s equation by the reflected coordinates. Reflecting y=2x+3 in the x-axis gives −y=2x+3, i.e. y=−2x−3; reflecting in y=x swaps x and y.',
             zh:'把直线方程中的x、y换成对称点的坐标。y=2x+3关于x轴对称得−y=2x+3，即y=−2x−3；关于直线y=x对称则交换x与y。'}},
          {id:3,label:{ko:'원의 대칭이동(실전, 2다칸)',en:'reflecting a circle (main, 2 slots)',zh:'圆的对称变换(实战，2格)'},params:{mode:'circle'},
           concept:{ko:'원을 대칭이동하면 반지름은 그대로이고 중심만 대칭이동합니다. 중심 (2, −3) 을 직선 y=x 에 대하여 대칭이동하면 (−3, 2) 입니다.',
             en:'Reflecting a circle keeps its radius; only the center is reflected. Reflecting the center (2, −3) in y=x gives (−3, 2).',
             zh:'对称变换圆时半径不变，只有圆心对称移动。圆心(2, −3)关于直线y=x对称得(−3, 2)。'}}] },

MD122:{ name:{ko:'원소의 개수와 부분집합의 개수',en:'Counting Elements & Subsets',zh:'元素个数与子集个数'}, gen:'md122_setCount', prereq:['MD88'],
  unit:'M-122',
  concept:{ko:'집합 A 의 원소의 개수를 n(A) 라 씁니다. 원소가 n 개인 집합의 부분집합은 원소마다 넣을지 뺄지 두 가지씩이므로 2ⁿ 개이고, 진부분집합(자기 자신을 뺀 것)은 2ⁿ−1 개입니다.',
    en:'n(A) is the number of elements of A. A set with n elements has 2ⁿ subsets (each element is either in or out), and 2ⁿ−1 proper subsets (all but the set itself).',
    zh:'集合A的元素个数记作n(A)。有n个元素的集合，每个元素选或不选两种，所以子集有2ⁿ个，真子集(除去自身)有2ⁿ−1个。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'원소의 개수 n(A)(연습)',en:'number of elements n(A) (practice)',zh:'元素个数n(A)(练习)'},params:{mode:'nA'}},
          {id:2,label:{ko:'부분집합·진부분집합의 개수',en:'number of subsets and proper subsets',zh:'子集与真子集的个数'},params:{mode:'subsets'},
           concept:{ko:'원소 하나마다 "넣는다/뺀다" 두 가지이므로 n(A)=n 이면 부분집합은 2ⁿ 개입니다. 진부분집합은 A 자신 하나를 빼서 2ⁿ−1 개입니다.',
             en:'Each element is either "in" or "out", so n(A)=n gives 2ⁿ subsets. Leave out A itself for 2ⁿ−1 proper subsets.',
             zh:'每个元素都有"选/不选"两种，所以n(A)=n时子集有2ⁿ个。去掉A本身，真子集有2ⁿ−1个。'}},
          {id:3,label:{ko:'특정 원소 조건이 있는 부분집합(실전)',en:'subsets with conditions on elements (main)',zh:'含特定元素条件的子集(实战)'},params:{mode:'special'},
           concept:{ko:'반드시 넣는 원소와 반드시 빼는 원소는 선택지가 없으므로 나머지 원소로만 2 의 거듭제곱을 셉니다. "적어도 하나"는 전체 2ⁿ 에서 하나도 없는 경우를 뺍니다.',
             en:'Elements that must be in or must be out have no choice, so count 2 to the power of the remaining elements. For "at least one", subtract the "none" case from 2ⁿ.',
             zh:'必须含有和必须不含的元素没有选择，只对其余元素计2的幂。"至少一个"用2ⁿ减去一个都没有的情况。'}}] },

MD123:{ name:{ko:'집합의 연산',en:'Set Operations',zh:'集合的运算'}, gen:'md123_setOps', prereq:['MD122'],
  unit:'M-123',
  concept:{ko:'합집합 A∪B 는 A 또는 B 의 원소, 교집합 A∩B 는 A 와 B 에 모두 속하는 원소, 차집합 A−B 는 A 에만 있는 원소, 여집합 A^C 는 전체집합 U 에서 A 를 뺀 것입니다.',
    en:'The union A∪B holds elements in A or B, the intersection A∩B those in both, the difference A−B those only in A, and the complement A^C is U without A.',
    zh:'并集A∪B是属于A或B的元素，交集A∩B是同时属于A和B的元素，差集A−B是只属于A的元素，补集A^C是全集U去掉A。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'합집합과 교집합(연습)',en:'union and intersection (practice)',zh:'并集与交集(练习)'},params:{mode:'basic'}},
          {id:2,label:{ko:'차집합과 여집합',en:'differences and complements',zh:'差集与补集'},params:{mode:'diff'},
           concept:{ko:'A−B=A∩B^C 입니다. U={1, 2, …, 8}, A={1, 2, 3, 4}, B={3, 4, 5} 이면 A−B={1, 2}, A^C={5, 6, 7, 8} 입니다.',
             en:'A−B=A∩B^C. With U={1, 2, …, 8}, A={1, 2, 3, 4}, B={3, 4, 5}: A−B={1, 2} and A^C={5, 6, 7, 8}.',
             zh:'A−B=A∩B^C。U={1, 2, …, 8}、A={1, 2, 3, 4}、B={3, 4, 5}时，A−B={1, 2}，A^C={5, 6, 7, 8}。'}},
          {id:3,label:{ko:'연산 법칙(실전)',en:'laws of set operations (main)',zh:'运算律(实战)'},params:{mode:'laws'},
           concept:{ko:'분배법칙 A∩(B∪C)=(A∩B)∪(A∩C), 드모르간의 법칙 (A∪B)^C=A^C∩B^C, (A∩B)^C=A^C∪B^C 를 씁니다. 괄호 안부터 차례로 원소를 나열해도 됩니다.',
             en:'Use the distributive law A∩(B∪C)=(A∩B)∪(A∩C) and De Morgan’s laws (A∪B)^C=A^C∩B^C, (A∩B)^C=A^C∪B^C — or list elements step by step from the innermost brackets.',
             zh:'用分配律A∩(B∪C)=(A∩B)∪(A∩C)与德摩根律(A∪B)^C=A^C∩B^C、(A∩B)^C=A^C∪B^C，也可以从括号内开始依次列出元素。'}}] },

MD124:{ name:{ko:'원소의 개수 공식',en:'Counting Elements of Unions',zh:'元素个数公式'}, gen:'md124_setSize', prereq:['MD123'],
  unit:'M-124',
  concept:{ko:'n(A∪B)=n(A)+n(B)−n(A∩B) 입니다. 두 번 센 공통부분을 한 번 뺍니다. 여집합은 n(A^C)=n(U)−n(A), 차집합은 n(A−B)=n(A)−n(A∩B) 입니다.',
    en:'n(A∪B)=n(A)+n(B)−n(A∩B): subtract the overlap that was counted twice. Also n(A^C)=n(U)−n(A) and n(A−B)=n(A)−n(A∩B).',
    zh:'n(A∪B)=n(A)+n(B)−n(A∩B)：减去数了两次的公共部分。另外n(A^C)=n(U)−n(A)，n(A−B)=n(A)−n(A∩B)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'두 집합의 원소의 개수(연습)',en:'two sets (practice)',zh:'两个集合(练习)'},params:{mode:'union'}},
          {id:2,label:{ko:'세 집합의 원소의 개수',en:'three sets',zh:'三个集合'},params:{mode:'three'},
           concept:{ko:'n(A∪B∪C)=n(A)+n(B)+n(C)−n(A∩B)−n(B∩C)−n(C∩A)+n(A∩B∩C) 입니다. 두 번씩 뺀 가운데 부분을 한 번 다시 더합니다.',
             en:'n(A∪B∪C)=n(A)+n(B)+n(C)−n(A∩B)−n(B∩C)−n(C∩A)+n(A∩B∩C): the middle part, removed too often, is added back once.',
             zh:'n(A∪B∪C)=n(A)+n(B)+n(C)−n(A∩B)−n(B∩C)−n(C∩A)+n(A∩B∩C)：被多减的中间部分再加回一次。'}},
          {id:3,label:{ko:'원소의 개수의 최댓값·최솟값(실전, 2다칸)',en:'greatest and least counts (main, 2 slots)',zh:'元素个数的最大值与最小值(实战，2格)'},params:{mode:'bound'},
           concept:{ko:'n(A∩B) 는 작은 집합의 원소의 개수보다 클 수 없고(최댓값 M), n(A∪B)≤n(U) 이므로 n(A)+n(B)−n(U) 보다 작을 수 없습니다(최솟값 m, 0 보다 작으면 0).',
             en:'n(A∩B) cannot exceed the smaller set (greatest value M), and since n(A∪B)≤n(U) it cannot be below n(A)+n(B)−n(U) (least value m, or 0 if that is negative).',
             zh:'n(A∩B)不能超过较小集合的元素个数(最大值M)；又因n(A∪B)≤n(U)，它不能小于n(A)+n(B)−n(U)(最小值m，若为负则为0)。'}}] },

/* ── MD125~MD133 공통수학2 새 유형 2차(2026-09-29) — docs/high-build-spec.md 공통수학2 뒤 9개.
   교재는 챕터 제목만 근거로 쓰고 문제는 새로 만든다. gen: engine/threads/mid20.js */
MD125:{ name:{ko:'진리집합과 필요충분조건',en:'Truth Sets & Necessary/Sufficient Conditions',zh:'真值集合与充要条件'}, gen:'md125_truthSet', prereq:['MD122','MD64','MD29'],
  unit:'M-125',
  concept:{ko:'조건 p 를 참이 되게 하는 전체집합의 원소의 모임이 p 의 진리집합 P 입니다. ~p 의 진리집합은 P^C, "p 이고 q" 는 P∩Q, "p 또는 q" 는 P∪Q 입니다.',
    en:'The truth set P of a condition p is the set of elements of the universal set that make p true. The truth set of ~p is P^C; "p and q" gives P∩Q and "p or q" gives P∪Q.',
    zh:'使条件p成立的全集元素组成p的真值集合P。~p的真值集合是P^C，"p且q"是P∩Q，"p或q"是P∪Q。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'진리집합의 원소의 개수(연습)',en:'counting a truth set (practice)',zh:'真值集合的元素个数(练习)'},params:{mode:'truth'}},
          {id:2,label:{ko:'충분조건·필요조건과 a 의 범위',en:'sufficient/necessary conditions and the range of a',zh:'充分·必要条件与a的范围'},params:{mode:'suff'},
           concept:{ko:'p⟹q 가 참이면 p 는 q 이기 위한 충분조건, q 는 p 이기 위한 필요조건이고, 진리집합 P 가 Q 의 부분집합입니다. 범위의 끝점이 다른 조건을 만족하도록 a 의 범위(a≥□ 또는 a≤□)를 구합니다.',
             en:'If p⟹q is true, p is sufficient for q, q is necessary for p, and the truth set P is a subset of Q. Make the end of the interval satisfy the other condition to get the range of a (a≥□ or a≤□).',
             zh:'若p⟹q为真，则p是q的充分条件，q是p的必要条件，真值集合P是Q的子集。让区间端点满足另一个条件，求a的范围(a≥□或a≤□)。'}},
          {id:3,label:{ko:'필요충분조건의 미정계수(실전, 2다칸)',en:'unknowns from p⟺q (main, 2 slots)',zh:'由充要条件求待定系数(实战，2格)'},params:{mode:'iff'},
           concept:{ko:'p⟺q 이면 두 진리집합이 같습니다. -1≤x≤5 와 같은 부등식은 (x+1)(x-5)≤0 이므로 x²-4x-5≤0 과 같고, |x-2|≤3 과도 같습니다.',
             en:'If p⟺q, the two truth sets are equal. For example −1≤x≤5 is (x+1)(x−5)≤0, i.e. x²−4x−5≤0, and also |x−2|≤3.',
             zh:'若p⟺q，两个真值集合相等。例如−1≤x≤5即(x+1)(x−5)≤0，也就是x²−4x−5≤0，也与|x−2|≤3相同。'}}] },

MD126:{ name:{ko:'절대부등식',en:'Absolute Inequalities',zh:'绝对不等式'}, gen:'md126_absIneq', prereq:['MD125','MD18'],
  unit:'M-126',
  concept:{ko:'a>0, b>0 이면 a+b≥2√(ab) 이고 등호는 a=b 일 때 성립합니다(산술평균과 기하평균의 관계). 곱이 일정한 두 양수의 합은 두 수가 같을 때 가장 작습니다. 최솟값은 m 으로 씁니다.',
    en:'If a>0 and b>0 then a+b≥2√(ab), with equality when a=b (the AM–GM inequality). Two positive numbers with a fixed product have the least sum when they are equal. Write the least value as m.',
    zh:'若a>0、b>0，则a+b≥2√(ab)，当a=b时取等号(算术平均与几何平均的关系)。积一定的两个正数相等时和最小。最小值记为m。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'산술평균과 기하평균으로 최솟값(연습)',en:'least value by AM–GM (practice)',zh:'用算术-几何平均求最小值(练习)'},params:{mode:'min'}},
          {id:2,label:{ko:'합이 일정할 때 곱의 최댓값',en:'greatest product for a fixed sum',zh:'和一定时积的最大值'},params:{mode:'prod'},
           concept:{ko:'x>0, y>0 에서 ax+by 가 일정하면 ax=by 일 때 곱 xy 가 가장 큽니다(최댓값 M). 반대로 xy 가 일정하면 ax+by 는 ax=by 일 때 가장 작습니다(최솟값 m).',
             en:'For x>0, y>0 with ax+by fixed, the product xy is greatest when ax=by (greatest value M). Conversely, with xy fixed, ax+by is least when ax=by (least value m).',
             zh:'x>0、y>0且ax+by一定时，ax=by时积xy最大(最大值M)；反之xy一定时，ax=by时ax+by最小(最小值m)。'}},
          {id:3,label:{ko:'코시-슈바르츠 부등식(실전)',en:'the Cauchy–Schwarz inequality (main)',zh:'柯西-施瓦茨不等式(实战)'},params:{mode:'cs'},
           concept:{ko:'실수 a, b, x, y 에 대하여 (a²+b²)(x²+y²)≥(ax+by)² 입니다. x²+y² 가 정해지면 ax+by 의 최댓값 M 과 최솟값 m 이 나오고, ax+by 가 정해지면 x²+y² 의 최솟값 m 이 나옵니다.',
             en:'For real a, b, x, y, (a²+b²)(x²+y²)≥(ax+by)². Fixing x²+y² gives the greatest value M and least value m of ax+by; fixing ax+by gives the least value m of x²+y².',
             zh:'对实数a、b、x、y有(a²+b²)(x²+y²)≥(ax+by)²。x²+y²一定时可求ax+by的最大值M与最小值m；ax+by一定时可求x²+y²的最小值m。'}}] },

MD127:{ name:{ko:'함수의 개수와 일대일대응',en:'Counting Functions & One-to-One Correspondences',zh:'函数的个数与一一对应'}, gen:'md127_funcCount', prereq:['MD73','MD111'],
  unit:'M-127',
  concept:{ko:'X 의 원소마다 Y 의 원소를 하나씩 고르면 함수가 됩니다. n(X)=m, n(Y)=n 이면 X 에서 Y 로의 함수는 n×n×…×n=nᵐ 개입니다.',
    en:'Choosing one element of Y for each element of X gives a function. If n(X)=m and n(Y)=n, there are n×n×…×n=nᵐ functions from X to Y.',
    zh:'为X的每个元素各选一个Y的元素就得到一个函数。若n(X)=m、n(Y)=n，则从X到Y的函数有n×n×…×n=nᵐ个。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'함수의 개수(연습)',en:'counting functions (practice)',zh:'函数的个数(练习)'},params:{mode:'count'}},
          {id:2,label:{ko:'일대일함수·일대일대응의 개수',en:'counting one-to-one functions and correspondences',zh:'单射与一一对应的个数'},params:{mode:'bij'},
           concept:{ko:'일대일함수는 서로 다른 원소에 서로 다른 값을 대응시키므로 n(n−1)(n−2)… 로 셉니다(ₙPₘ). 일대일대응은 치역이 Y 전체인 일대일함수이고, n(X)=n(Y)=n 이면 n! 개입니다.',
             en:'A one-to-one function sends different elements to different values, so count n(n−1)(n−2)… (ₙPₘ). A one-to-one correspondence is a one-to-one function whose range is all of Y; with n(X)=n(Y)=n there are n! of them.',
             zh:'单射把不同元素对应到不同的值，所以按n(n−1)(n−2)…计数(ₙPₘ)。一一对应是值域为整个Y的单射，n(X)=n(Y)=n时共有n!个。'}},
          {id:3,label:{ko:'일대일대응이 되는 조건(실전, 2다칸)',en:'conditions for a one-to-one correspondence (main, 2 slots)',zh:'成为一一对应的条件(实战，2格)'},params:{mode:'coef'},
           concept:{ko:'X 에서 Y 로의 일차함수 f(x)=ax+b 가 일대일대응이려면 정의역 양 끝의 함숫값이 Y 의 양 끝이어야 합니다. a>0 이면 f(작은 끝)=Y 의 작은 끝, a<0 이면 f(작은 끝)=Y 의 큰 끝입니다.',
             en:'For the linear f(x)=ax+b from X to Y to be a one-to-one correspondence, the values at the ends of X must be the ends of Y: if a>0, f(left end)=smallest of Y; if a<0, f(left end)=largest of Y.',
             zh:'从X到Y的一次函数f(x)=ax+b要成为一一对应，X两端的函数值必须是Y的两端：a>0时f(左端)=Y的最小值，a<0时f(左端)=Y的最大值。'}}] },

MD128:{ name:{ko:'합성함수',en:'Composite Functions',zh:'复合函数'}, gen:'md128_compose', prereq:['MD127','MD73'],
  unit:'M-128',
  concept:{ko:'(f∘g)(x)=f(g(x)) 입니다. g 를 먼저, f 를 나중에 적용합니다. 일반적으로 f∘g 와 g∘f 는 다릅니다.',
    en:'(f∘g)(x)=f(g(x)): apply g first, then f. In general f∘g and g∘f are different.',
    zh:'(f∘g)(x)=f(g(x))：先用g，再用f。一般f∘g与g∘f不同。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'합성함수의 함숫값(연습)',en:'values of composite functions (practice)',zh:'复合函数的函数值(练习)'},params:{mode:'value'}},
          {id:2,label:{ko:'합성함수의 식에서 미정계수(2다칸)',en:'unknown coefficients from a composite (2 slots)',zh:'由复合函数求待定系数(2格)'},params:{mode:'coef'},
           concept:{ko:'합성한 식을 x 에 대하여 정리하고, 주어진 식과 x 의 계수·상수항을 각각 비교합니다. f(x)=2x+1, g(x)=ax+b 에서 (f∘g)(x)=6x−3 이면 2a=6, 2b+1=−3 입니다.',
             en:'Expand the composite in x and compare the x-coefficient and constant with the given expression. With f(x)=2x+1, g(x)=ax+b and (f∘g)(x)=6x−3: 2a=6 and 2b+1=−3.',
             zh:'把复合后的式子按x整理，与已知式分别比较x的系数与常数项。f(x)=2x+1、g(x)=ax+b且(f∘g)(x)=6x−3时，2a=6，2b+1=−3。'}},
          {id:3,label:{ko:'fⁿ 의 값(실전)',en:'values of fⁿ (main)',zh:'fⁿ的值(实战)'},params:{mode:'iter'},
           concept:{ko:'fⁿ 은 f 를 n 번 합성한 함수입니다(f²=f∘f). f(x)=x+c 이면 fⁿ(x)=x+nc 이고, f²(x)=x 이면 짝수 번은 제자리입니다. 값이 되풀이되면 주기로 나눈 나머지를 봅니다.',
             en:'fⁿ is f composed n times (f²=f∘f). If f(x)=x+c then fⁿ(x)=x+nc; if f²(x)=x, an even number of steps returns to the start. When values repeat, use the remainder on division by the period.',
             zh:'fⁿ是f合成n次的函数(f²=f∘f)。f(x)=x+c时fⁿ(x)=x+nc；若f²(x)=x，偶数次回到原处。值循环时看n除以周期的余数。'}}] },

MD129:{ name:{ko:'역함수',en:'Inverse Functions',zh:'反函数'}, gen:'md129_inverse', prereq:['MD128'],
  unit:'M-129',
  concept:{ko:'일대일대응 f 에 대하여 f(a)=b 이면 f⁻¹(b)=a 입니다. 그래서 f⁻¹(b) 의 값은 f(a)=b 를 푸는 것으로 구합니다.',
    en:'For a one-to-one correspondence f, f(a)=b means f⁻¹(b)=a, so the value f⁻¹(b) is found by solving f(a)=b.',
    zh:'对一一对应f，f(a)=b即f⁻¹(b)=a，所以求f⁻¹(b)就是解f(a)=b。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'역함수의 함숫값(연습)',en:'values of an inverse (practice)',zh:'反函数的函数值(练习)'},params:{mode:'value'}},
          {id:2,label:{ko:'합성함수와 역함수',en:'composites and inverses',zh:'复合函数与反函数'},params:{mode:'compose'},
           concept:{ko:'(f∘g)⁻¹=g⁻¹∘f⁻¹ 이고 f∘f⁻¹ 은 항등함수입니다. 식을 먼저 간단히 한 뒤 안쪽부터 값을 구합니다.',
             en:'(f∘g)⁻¹=g⁻¹∘f⁻¹, and f∘f⁻¹ is the identity. Simplify first, then evaluate from the inside out.',
             zh:'(f∘g)⁻¹=g⁻¹∘f⁻¹，f∘f⁻¹是恒等函数。先化简，再从内向外求值。'}},
          {id:3,label:{ko:'역함수의 조건으로 미정계수(실전, 2다칸)',en:'unknown coefficients from inverse conditions (main, 2 slots)',zh:'由反函数条件求待定系数(实战，2格)'},params:{mode:'coef'},
           concept:{ko:'f⁻¹(p)=q 는 f(q)=p 로 바꿉니다. 역함수의 식이 주어지면 x=f⁻¹(y) 를 y 에 대하여 풀어 f 를 되찾습니다.',
             en:'Turn f⁻¹(p)=q into f(q)=p. If the inverse formula is given, solve x=f⁻¹(y) for y to recover f.',
             zh:'把f⁻¹(p)=q改写为f(q)=p。若给出反函数的式子，把x=f⁻¹(y)解成关于y的式子，还原f。'}}] },

MD130:{ name:{ko:'유리식의 계산',en:'Rational Expressions',zh:'分式的运算'}, gen:'md130_ratExpr', prereq:['MD129','MD18'],
  unit:'M-130',
  concept:{ko:'유리식의 덧셈·뺄셈은 분모를 통분하고, 곱셈·나눗셈은 인수분해해 약분합니다. 계산한 결과를 주어진 꼴과 비교해 계수를 읽습니다.',
    en:'Add and subtract rational expressions over a common denominator; multiply and divide by factoring and cancelling. Compare the result with the given form to read off the coefficients.',
    zh:'分式加减先通分，乘除先因式分解再约分。把结果与所给形式比较读出系数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'유리식의 사칙계산(연습, 2다칸)',en:'arithmetic of rational expressions (practice, 2 slots)',zh:'分式的四则运算(练习，2格)'},params:{mode:'arith'}},
          {id:2,label:{ko:'부분분수로 합 구하기(2다칸)',en:'sums by partial fractions (2 slots)',zh:'用部分分式求和(2格)'},params:{mode:'partial'},
           concept:{ko:'1/(AB)=(1/(B−A))(1/A−1/B) 로 쪼개면 이웃한 항이 지워져 처음과 끝만 남습니다. 수의 합은 a/b 를 기약분수로 씁니다.',
             en:'Splitting 1/(AB)=(1/(B−A))(1/A−1/B) makes neighbouring terms cancel, leaving only the first and last. For numerical sums, write a/b in lowest terms.',
             zh:'拆成1/(AB)=(1/(B−A))(1/A−1/B)后相邻项抵消，只剩首末两项。数的和把a/b写成最简分数。'}},
          {id:3,label:{ko:'번분수 식의 값(실전)',en:'values of complex fractions (main)',zh:'繁分式的值(实战)'},params:{mode:'complex'},
           concept:{ko:'번분수는 분자·분모에 같은 식을 곱해 작은 분수를 없애 간단히 합니다. a+1/(b+1/c) 꼴은 정수 부분을 떼고 남은 분수를 뒤집는 일을 되풀이합니다.',
             en:'Simplify a complex fraction by multiplying the numerator and denominator by the same expression to clear small fractions. For a+1/(b+1/c), repeatedly take out the whole part and flip the remainder.',
             zh:'给繁分式的分子分母同乘一个式子消去小分数来化简。对a+1/(b+1/c)型，反复取出整数部分并把剩下的分数倒过来。'}}] },

MD131:{ name:{ko:'유리함수',en:'Rational Functions',zh:'分式函数'}, gen:'md131_ratFunc', prereq:['MD130','MD120'],
  unit:'M-131',
  concept:{ko:'y=k/(x−p)+q 의 그래프는 y=k/x 의 그래프를 x축 방향으로 p, y축 방향으로 q 만큼 평행이동한 것이고, 점근선은 x=p, y=q 입니다. 답은 x=□, y=□ 두 칸에 씁니다.',
    en:'The graph of y=k/(x−p)+q is y=k/x translated by p along the x-axis and q along the y-axis; its asymptotes are x=p and y=q. Enter them in the two boxes x=□, y=□.',
    zh:'y=k/(x−p)+q的图像是把y=k/x沿x轴方向平移p、沿y轴方向平移q得到的，渐近线为x=p、y=q。答案填在x=□、y=□两格中。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'유리함수의 점근선(연습, 2다칸)',en:'asymptotes of rational functions (practice, 2 slots)',zh:'分式函数的渐近线(练习，2格)'},params:{mode:'asym'}},
          {id:2,label:{ko:'정의역·치역과 미정계수(2다칸)',en:'domain, range and unknown coefficients (2 slots)',zh:'定义域、值域与待定系数(2格)'},params:{mode:'coef'},
           concept:{ko:'y=(ax+β)/(x+b) 의 정의역은 {x | x≠−b}, 치역은 {y | y≠a} 입니다. x≠p, y≠q 로 주어지면 −b=p, a=q 입니다. 지나는 점이 주어지면 대입해 연립방정식을 풉니다.',
             en:'y=(ax+β)/(x+b) has domain {x | x≠−b} and range {y | y≠a}. Given x≠p and y≠q, −b=p and a=q. Given points on the graph, substitute and solve the system.',
             zh:'y=(ax+β)/(x+b)的定义域为{x | x≠−b}，值域为{y | y≠a}。给出x≠p、y≠q时−b=p、a=q。给出图像上的点时代入解方程组。'}},
          {id:3,label:{ko:'범위가 정해진 유리함수의 최댓값·최솟값(실전, 2다칸)',en:'greatest and least values on an interval (main, 2 slots)',zh:'给定范围的最大值与最小值(实战，2格)'},params:{mode:'range'},
           concept:{ko:'정의역이 점근선 x=p 의 한쪽에만 있으면 그래프는 그 범위에서 증가하거나 감소하기만 합니다. 양 끝의 함숫값 가운데 큰 것이 최댓값 M, 작은 것이 최솟값 m 입니다.',
             en:'If the domain lies on one side of the asymptote x=p, the graph only increases or only decreases there. The larger end value is the greatest value M and the smaller is the least value m.',
             zh:'定义域只在渐近线x=p的一侧时，图像在该范围内只增或只减。两端函数值中较大的是最大值M，较小的是最小值m。'}}] },

MD132:{ name:{ko:'무리식의 계산',en:'Irrational Expressions',zh:'无理式的运算'}, gen:'md132_radExpr', prereq:['MD18','MD131'],
  unit:'M-132',
  concept:{ko:'무리식의 값이 실수가 되려면 근호 안이 0 이상이어야 하고, 분모에 있으면 0 이 아니어야 합니다. 두 조건을 모두 만족하는 범위의 정수를 셉니다.',
    en:'For an irrational expression to be real, each radicand must be at least 0, and a denominator must not be 0. Count the integers in the range that meets every condition.',
    zh:'无理式的值为实数时，根号内要不小于0，在分母中还不能为0。数出满足全部条件的范围内的整数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'무리식이 실수가 될 조건(연습)',en:'when an irrational expression is real (practice)',zh:'无理式为实数的条件(练习)'},params:{mode:'real'}},
          {id:2,label:{ko:'분모의 유리화로 식의 값',en:'values by rationalizing denominators',zh:'用分母有理化求值'},params:{mode:'ration'},
           concept:{ko:'1/(√A+√B) 에 (√B−√A) 를 곱하면 (√B−√A)/(B−A) 입니다. 여러 항을 더하면 가운데가 지워지는 식이 됩니다.',
             en:'Multiplying 1/(√A+√B) by (√B−√A) gives (√B−√A)/(B−A). In a sum of many such terms the middle ones cancel.',
             zh:'1/(√A+√B)乘以(√B−√A)得(√B−√A)/(B−A)。许多这样的项相加时中间项相互抵消。'}},
          {id:3,label:{ko:'무리수를 넣은 식의 값(실전)',en:'values with irrational numbers substituted (main)',zh:'代入无理数求式子的值(实战)'},params:{mode:'value'},
           concept:{ko:'x=√a+√b, y=√a−√b 이면 x+y=2√a, xy=a−b 입니다. x²+y²=(x+y)²−2xy 처럼 곱셈공식의 변형으로 계산합니다. x=n+√m 이면 (x−n)²=m 을 씁니다.',
             en:'If x=√a+√b and y=√a−√b, then x+y=2√a and xy=a−b; compute with rearranged product formulas such as x²+y²=(x+y)²−2xy. If x=n+√m, use (x−n)²=m.',
             zh:'若x=√a+√b、y=√a−√b，则x+y=2√a，xy=a−b，用x²+y²=(x+y)²−2xy等乘法公式的变形计算。若x=n+√m，用(x−n)²=m。'}}] },

MD133:{ name:{ko:'무리함수',en:'Radical Functions',zh:'无理函数'}, gen:'md133_radFunc', prereq:['MD132','MD120'],
  unit:'M-133',
  concept:{ko:'y=√(a(x−p))+q 의 그래프는 y=√(ax) 를 x축 방향으로 p, y축 방향으로 q 만큼 평행이동한 것입니다. a>0 이면 정의역은 x≥p, a<0 이면 x≤p 이고, 치역은 y≥q 입니다(√ 앞이 − 이면 y≤q).',
    en:'The graph of y=√(a(x−p))+q is y=√(ax) translated by p along the x-axis and q along the y-axis. The domain is x≥p if a>0 and x≤p if a<0; the range is y≥q (y≤q if there is a minus sign before √).',
    zh:'y=√(a(x−p))+q的图像是把y=√(ax)沿x轴方向平移p、沿y轴方向平移q得到的。a>0时定义域为x≥p，a<0时为x≤p；值域为y≥q(√前为负号时y≤q)。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'정의역·치역의 끝값(연습)',en:'ends of the domain and range (practice)',zh:'定义域与值域的端点(练习)'},params:{mode:'domain'}},
          {id:2,label:{ko:'무리함수의 평행이동(2다칸)',en:'translating radical functions (2 slots)',zh:'无理函数的平移(2格)'},params:{mode:'shift'},
           concept:{ko:'화살표 위의 (m, n) 은 x축 방향으로 m, y축 방향으로 n 만큼의 평행이동입니다. y=√(ax) 는 y=√(a(x−m))+n 이 되므로 근호 안을 a 로 묶어 m 을 읽습니다.',
             en:'(m, n) over the arrow means a translation by m along the x-axis and n along the y-axis. y=√(ax) becomes y=√(a(x−m))+n, so factor a out of the radicand to read m.',
             zh:'箭头上的(m, n)表示沿x轴方向平移m、沿y轴方向平移n。y=√(ax)变为y=√(a(x−m))+n，把根号内提出a就能读出m。'}},
          {id:3,label:{ko:'무리함수와 직선이 두 점에서 만날 k 의 범위(실전, 2다칸)',en:'k for two intersections with a line (main, 2 slots)',zh:'与直线交于两点时k的范围(实战，2格)'},params:{mode:'meet'},
           concept:{ko:'직선 y=x+k 가 그래프와 서로 다른 두 점에서 만나는 k 의 범위를 구합니다. 경계는 직선이 그래프의 끝점을 지날 때(포함)와 그래프에 접할 때(판별식 D=0, 제외)입니다.',
             en:'Find the range of k for which y=x+k meets the graph at two different points. The boundaries are when the line passes through the endpoint (included) and when it is tangent (discriminant D=0, excluded).',
             zh:'求直线y=x+k与图像交于两个不同点时k的范围。边界是直线经过图像端点时(包含)与相切时(判别式D=0，不包含)。'}}] },

/* ── MD134~MD143 대수 새 유형 1차(2026-09-29) — docs/high-build-spec.md 대수 앞 10개.
   교재는 챕터 제목만 근거로 쓰고 문제는 새로 만든다. gen: engine/threads/mid21.js */
MD134:{ name:{ko:'aˣ+a⁻ˣ 꼴 식의 값',en:'Values of aˣ+a⁻ˣ',zh:'aˣ+a⁻ˣ型式子的值'}, gen:'md134_expSym', prereq:['MD36','MD91'],
  unit:'M-134',
  concept:{ko:'aˣ×a⁻ˣ=1 이므로 (aˣ+a⁻ˣ)²=a²ˣ+2+a⁻²ˣ, (aˣ−a⁻ˣ)²=a²ˣ−2+a⁻²ˣ 입니다. x^½+x^−½ 도 곱이 1 인 두 수의 합이라 같은 방법으로 풉니다.',
    en:'Since aˣ×a⁻ˣ=1, (aˣ+a⁻ˣ)²=a²ˣ+2+a⁻²ˣ and (aˣ−a⁻ˣ)²=a²ˣ−2+a⁻²ˣ. x^½+x^−½ is also a sum of two numbers whose product is 1, so it works the same way.',
    zh:'因为aˣ×a⁻ˣ=1，所以(aˣ+a⁻ˣ)²=a²ˣ+2+a⁻²ˣ，(aˣ−a⁻ˣ)²=a²ˣ−2+a⁻²ˣ。x^½+x^−½也是积为1的两个数的和，用同样的方法。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'제곱을 이용한 식의 값(연습)',en:'values by squaring (practice)',zh:'利用平方求值(练习)'},params:{mode:'sq'}},
          {id:2,label:{ko:'세제곱을 이용한 식의 값',en:'values by cubing',zh:'利用立方求值'},params:{mode:'cube'},
           concept:{ko:'곱이 1 인 두 수 u, 1/u 에서 u³+u⁻³=(u+u⁻¹)³−3(u+u⁻¹), u³−u⁻³=(u−u⁻¹)³+3(u−u⁻¹) 입니다. u³±u⁻³ 을 u±u⁻¹ 로 나누면 u²∓1+u⁻² 가 남습니다.',
             en:'For u and 1/u (product 1), u³+u⁻³=(u+u⁻¹)³−3(u+u⁻¹) and u³−u⁻³=(u−u⁻¹)³+3(u−u⁻¹). Dividing u³±u⁻³ by u±u⁻¹ leaves u²∓1+u⁻².',
             zh:'对积为1的u与1/u，u³+u⁻³=(u+u⁻¹)³−3(u+u⁻¹)，u³−u⁻³=(u−u⁻¹)³+3(u−u⁻¹)。u³±u⁻³除以u±u⁻¹余下u²∓1+u⁻²。'}},
          {id:3,label:{ko:'합·차와 몫을 이용한 식의 값(실전)',en:'values from sums, differences and quotients (main)',zh:'利用和、差与商求值(实战)'},params:{mode:'diff'},
           concept:{ko:'a²ˣ+a⁻²ˣ 가 주어지면 (aˣ+a⁻ˣ)²=a²ˣ+a⁻²ˣ+2 로 합을, (aˣ−a⁻ˣ)²=a²ˣ+a⁻²ˣ−2 로 차를 구합니다. 합은 언제나 양수이고, 차의 부호는 x>0(또는 x>1) 인지로 정합니다.',
             en:'Given a²ˣ+a⁻²ˣ, get the sum from (aˣ+a⁻ˣ)²=a²ˣ+a⁻²ˣ+2 and the difference from (aˣ−a⁻ˣ)²=a²ˣ+a⁻²ˣ−2. The sum is always positive; the sign of the difference comes from x>0 (or x>1).',
             zh:'已知a²ˣ+a⁻²ˣ时，由(aˣ+a⁻ˣ)²=a²ˣ+a⁻²ˣ+2求和，由(aˣ−a⁻ˣ)²=a²ˣ+a⁻²ˣ−2求差。和总是正数，差的符号由x>0(或x>1)决定。'}}] },

MD135:{ name:{ko:'상용로그',en:'Common Logarithms',zh:'常用对数'}, gen:'md135_commonLog', prereq:['MD38'],
  unit:'M-135',
  concept:{ko:'밑이 10 인 로그를 상용로그라 하고 log N 으로 씁니다. log N=n+α(n 은 정수, 0≤α<1) 일 때 n 을 정수 부분, α 를 소수 부분이라 합니다. 문제에 주어진 log 2, log 3 등의 값으로 계산합니다.',
    en:'A logarithm to base 10 is a common logarithm, written log N. When log N=n+α (n an integer, 0≤α<1), n is the integer part and α the decimal part. Compute with the given values such as log 2 and log 3.',
    zh:'以10为底的对数叫常用对数，记作log N。log N=n+α(n为整数，0≤α<1)时，n叫整数部分，α叫小数部分。用题中给出的log 2、log 3等的值计算。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'상용로그의 정수 부분(연습)',en:'integer parts of common logarithms (practice)',zh:'常用对数的整数部分(练习)'},params:{mode:'int'}},
          {id:2,label:{ko:'큰 수의 자릿수',en:'number of digits of a large number',zh:'大数的位数'},params:{mode:'digits'},
           concept:{ko:'N 이 n 자리의 정수이면 10ⁿ⁻¹≤N<10ⁿ 이므로 n−1≤log N<n 입니다. log N 의 정수 부분에 1 을 더하면 자릿수입니다. log 5=1−log 2 입니다.',
             en:'If N is an n-digit integer then 10ⁿ⁻¹≤N<10ⁿ, so n−1≤log N<n: the number of digits is the integer part of log N plus 1. Note log 5=1−log 2.',
             zh:'若N是n位整数，则10ⁿ⁻¹≤N<10ⁿ，所以n−1≤log N<n：位数等于log N的整数部分加1。注意log 5=1−log 2。'}},
          {id:3,label:{ko:'소수점 아래 처음으로 0 이 아닌 자리(실전)',en:'first nonzero decimal place (main)',zh:'小数点后首个非零数字的位置(实战)'},params:{mode:'decimal'},
           concept:{ko:'0<N<1 에서 10⁻ⁿ≤N<10⁻ⁿ⁺¹ 이면 소수점 아래 n 째 자리에서 처음으로 0 이 아닌 숫자가 나타납니다. log N 을 (음의 정수)+(0 이상 1 미만의 소수) 로 나타내면 그 음의 정수가 −n 입니다.',
             en:'For 0<N<1, if 10⁻ⁿ≤N<10⁻ⁿ⁺¹, the first nonzero digit of N is in the nth decimal place. Write log N as (a negative integer)+(a decimal from 0 up to 1); that negative integer is −n.',
             zh:'当0<N<1且10⁻ⁿ≤N<10⁻ⁿ⁺¹时，N在小数点后第n位首次出现不为0的数字。把log N写成(负整数)+(0以上且小于1的小数)，这个负整数就是−n。'}}] },

MD136:{ name:{ko:'지수함수의 그래프',en:'Graphs of Exponential Functions',zh:'指数函数的图像'}, gen:'md136_expGraph', prereq:['MD36','MD120'],
  unit:'M-136',
  concept:{ko:'y=k·aˣ⁻ᵖ+q 의 그래프는 y=k·aˣ 을 x축 방향으로 p, y축 방향으로 q 만큼 평행이동한 것이고 점근선은 y=q 입니다. 답은 지나는 점의 y좌표 (x, □) 와 점근선 y=□ 두 칸에 씁니다.',
    en:'The graph of y=k·aˣ⁻ᵖ+q is y=k·aˣ translated by p along the x-axis and q along the y-axis; its asymptote is y=q. Enter the y-coordinate of the point (x, □) and the asymptote y=□ in the two boxes.',
    zh:'y=k·aˣ⁻ᵖ+q的图像是把y=k·aˣ沿x轴方向平移p、沿y轴方向平移q得到的，渐近线为y=q。答案填在点(x, □)的纵坐标与渐近线y=□两格中。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'지나는 점과 점근선(연습, 2다칸)',en:'points and asymptotes (practice, 2 slots)',zh:'经过的点与渐近线(练习，2格)'},params:{mode:'point'}},
          {id:2,label:{ko:'평행이동·대칭이동한 그래프의 함숫값',en:'values after translations and reflections',zh:'平移与对称变换后的函数值'},params:{mode:'move'},
           concept:{ko:'(x, y)→(x+m, y+n) 은 평행이동, (x, y)→(−x, y) 는 y축, (x, y)→(x, −y) 는 x축, (x, y)→(−x, −y) 는 원점에 대한 대칭이동입니다. 옮긴 점 (X, Y) 에서 x, y 를 X, Y 로 나타내 원래 식에 넣으면 f(x) 가 나옵니다.',
             en:'(x, y)→(x+m, y+n) is a translation; (x, y)→(−x, y), (x, y)→(x, −y) and (x, y)→(−x, −y) are reflections in the y-axis, the x-axis and the origin. Write x and y in terms of the new point (X, Y) and substitute to get f(x).',
             zh:'(x, y)→(x+m, y+n)是平移；(x, y)→(−x, y)、(x, y)→(x, −y)、(x, y)→(−x, −y)分别是关于y轴、x轴、原点的对称变换。用新点(X, Y)表示x、y并代入原式，得到f(x)。'}},
          {id:3,label:{ko:'거듭제곱의 크기 비교(실전)',en:'comparing powers (main)',zh:'幂的大小比较(实战)'},params:{mode:'order'},
           concept:{ko:'밑을 같게 고치면 지수만 비교하면 됩니다. √[3]{4}=2^(2/3), 8^(1/2)=2^(3/2), (1/2)^(−1)=2 처럼 바꿉니다. 세 수 가운데 가장 큰 수를 M, 가장 작은 수를 m 이라 하고 M÷m 이나 M×m 을 2ᵏ 꼴로 나타냅니다.',
             en:'With a common base you only compare exponents: ∛4=2^(2/3), 8^(1/2)=2^(3/2), (1/2)^(−1)=2. Call the largest of the three M and the smallest m, and write M÷m or M×m as 2ᵏ.',
             zh:'底数化为相同后只需比较指数：∛4=2^(2/3)，8^(1/2)=2^(3/2)，(1/2)^(−1)=2。三个数中最大的记为M，最小的记为m，把M÷m或M×m写成2ᵏ的形式。'}}] },

MD137:{ name:{ko:'지수함수의 최대·최소',en:'Maxima & Minima of Exponential Functions',zh:'指数函数的最大值与最小值'}, gen:'md137_expMaxMin', prereq:['MD136','MD100'],
  unit:'M-137',
  concept:{ko:'y=aˣ 은 a>1 이면 증가, 0<a<1 이면 감소하므로 닫힌 범위에서는 양 끝에서 최댓값과 최솟값이 나옵니다. 최댓값은 M, 최솟값은 m 으로 쓰고 답은 M=□, m=□ 두 칸입니다.',
    en:'y=aˣ increases if a>1 and decreases if 0<a<1, so on a closed interval the greatest and least values occur at the ends. Write them as M and m and enter M=□, m=□ in two boxes.',
    zh:'y=aˣ在a>1时递增，0<a<1时递减，所以在闭区间上最大值与最小值在两端取得。分别记为M与m，答案填在M=□、m=□两格中。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'닫힌 범위의 최댓값·최솟값(연습, 2다칸)',en:'greatest and least values on an interval (practice, 2 slots)',zh:'闭区间上的最大值与最小值(练习，2格)'},params:{mode:'range'}},
          {id:2,label:{ko:'aˣ=t 로 치환한 이차함수(2다칸)',en:'quadratics after putting aˣ=t (2 slots)',zh:'令aˣ=t后的二次函数(2格)'},params:{mode:'quad'},
           concept:{ko:'4ˣ=(2ˣ)² 이므로 2ˣ=t 로 놓으면 y 는 t 에 대한 이차함수입니다. x 의 범위에서 t 의 범위(t>0)를 구하고, 꼭짓점이 그 범위 안이면 꼭짓점에서 m, 먼 끝에서 M 이 나옵니다.',
             en:'Since 4ˣ=(2ˣ)², putting 2ˣ=t makes y a quadratic in t. Find the range of t (t>0) from the range of x; if the vertex is inside, m is at the vertex and M at the farther end.',
             zh:'因为4ˣ=(2ˣ)²，令2ˣ=t后y是关于t的二次函数。由x的范围求t的范围(t>0)；若顶点在范围内，m在顶点处取得，M在较远的一端取得。'}},
          {id:3,label:{ko:'최댓값·최솟값이 주어질 때 미정계수(실전)',en:'unknowns from given extreme values (main)',zh:'由最值求待定系数(实战)'},params:{mode:'coef'},
           concept:{ko:'주어진 최댓값 M 또는 최솟값 m 이 범위의 어느 끝(또는 꼭짓점)에서 나오는지 먼저 정하고, 그 x 를 넣어 식을 세웁니다. y=aˣ(a>1) 에서 M 이 주어지면 aⁿ=M 을 풉니다.',
             en:'First decide at which end (or vertex) the given greatest value M or least value m occurs, then substitute that x to set up an equation. For y=aˣ (a>1) with M given, solve aⁿ=M.',
             zh:'先确定所给最大值M或最小值m在区间哪一端(或顶点)取得，再代入该x列方程。对y=aˣ(a>1)给出M时，解aⁿ=M。'}}] },

MD138:{ name:{ko:'로그함수의 그래프',en:'Graphs of Logarithmic Functions',zh:'对数函数的图像'}, gen:'md138_logGraph', prereq:['MD38','MD136'],
  unit:'M-138',
  concept:{ko:'y=k·logₐ(x−p)+q 의 그래프는 y=k·logₐx 를 x축 방향으로 p, y축 방향으로 q 만큼 평행이동한 것이고 점근선은 x=p 입니다. 답은 지나는 점의 y좌표 (x, □) 와 점근선 x=□ 두 칸에 씁니다.',
    en:'The graph of y=k·logₐ(x−p)+q is y=k·logₐx translated by p along the x-axis and q along the y-axis; its asymptote is x=p. Enter the y-coordinate of the point (x, □) and the asymptote x=□ in the two boxes.',
    zh:'y=k·logₐ(x−p)+q的图像是把y=k·logₐx沿x轴方向平移p、沿y轴方向平移q得到的，渐近线为x=p。答案填在点(x, □)的纵坐标与渐近线x=□两格中。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'지나는 점과 점근선(연습, 2다칸)',en:'points and asymptotes (practice, 2 slots)',zh:'经过的点与渐近线(练习，2格)'},params:{mode:'point'}},
          {id:2,label:{ko:'평행이동·대칭이동한 그래프의 함숫값',en:'values after translations and reflections',zh:'平移与对称变换后的函数值'},params:{mode:'move'},
           concept:{ko:'(x, y)→(x+m, y+n) 은 평행이동, (−x, y)·(x, −y)·(−x, −y) 는 y축·x축·원점 대칭이동입니다. (x, y)→(y, x) 는 직선 y=x 에 대한 대칭이동이라 y=logₐx 는 역함수 y=aˣ 이 됩니다.',
             en:'(x, y)→(x+m, y+n) is a translation; (−x, y), (x, −y) and (−x, −y) are reflections in the y-axis, the x-axis and the origin. (x, y)→(y, x) is the reflection in y=x, so y=logₐx becomes its inverse y=aˣ.',
             zh:'(x, y)→(x+m, y+n)是平移；(−x, y)、(x, −y)、(−x, −y)分别是关于y轴、x轴、原点的对称变换。(x, y)→(y, x)是关于直线y=x的对称变换，y=logₐx变为其反函数y=aˣ。'}},
          {id:3,label:{ko:'로그의 크기 비교(실전)',en:'comparing logarithms (main)',zh:'对数的大小比较(实战)'},params:{mode:'order'},
           concept:{ko:'밑을 같게 고치면 진수만 비교하면 됩니다. log₄9=log₂3, ½log₂9=log₂3, −log_(1/2)3=log₂3 처럼 바꿉니다. 가장 큰 수를 M, 가장 작은 수를 m 이라 하면 M−m=log₂(큰 진수÷작은 진수) 입니다.',
             en:'With a common base you only compare arguments: log₄9=log₂3, ½log₂9=log₂3, −log_(1/2)3=log₂3. With M the largest and m the smallest, M−m=log₂(larger argument÷smaller argument).',
             zh:'底数化为相同后只需比较真数：log₄9=log₂3，½log₂9=log₂3，−log_(1/2)3=log₂3。设最大的为M、最小的为m，则M−m=log₂(大真数÷小真数)。'}}] },

MD139:{ name:{ko:'로그함수의 최대·최소',en:'Maxima & Minima of Logarithmic Functions',zh:'对数函数的最大值与最小值'}, gen:'md139_logMaxMin', prereq:['MD138','MD100'],
  unit:'M-139',
  concept:{ko:'y=logₐx 는 a>1 이면 증가, 0<a<1 이면 감소하므로 닫힌 범위에서는 양 끝에서 최댓값과 최솟값이 나옵니다. 최댓값은 M, 최솟값은 m 으로 쓰고 답은 M=□, m=□ 두 칸입니다.',
    en:'y=logₐx increases if a>1 and decreases if 0<a<1, so on a closed interval the greatest and least values occur at the ends. Write them as M and m and enter M=□, m=□ in two boxes.',
    zh:'y=logₐx在a>1时递增，0<a<1时递减，所以在闭区间上最大值与最小值在两端取得。分别记为M与m，答案填在M=□、m=□两格中。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'닫힌 범위의 최댓값·최솟값(연습, 2다칸)',en:'greatest and least values on an interval (practice, 2 slots)',zh:'闭区间上的最大值与最小值(练习，2格)'},params:{mode:'range'}},
          {id:2,label:{ko:'logₐx=t 로 치환한 이차함수(2다칸)',en:'quadratics after putting logₐx=t (2 slots)',zh:'令logₐx=t后的二次函数(2格)'},params:{mode:'quad'},
           concept:{ko:'log₂x=t 로 놓으면 y 는 t 에 대한 이차함수입니다. 1/2≤x≤16 이면 −1≤t≤4 처럼 t 의 범위를 먼저 구하고, 꼭짓점이 그 안이면 꼭짓점에서 m, 먼 끝에서 M 이 나옵니다.',
             en:'Putting log₂x=t makes y a quadratic in t. First find the range of t (1/2≤x≤16 gives −1≤t≤4); if the vertex is inside, m is at the vertex and M at the farther end.',
             zh:'令log₂x=t后y是关于t的二次函数。先求t的范围(1/2≤x≤16时−1≤t≤4)；若顶点在范围内，m在顶点处取得，M在较远的一端取得。'}},
          {id:3,label:{ko:'최댓값·최솟값이 주어질 때 미정계수(실전)',en:'unknowns from given extreme values (main)',zh:'由最值求待定系数(实战)'},params:{mode:'coef'},
           concept:{ko:'주어진 M 또는 m 이 어디에서 나오는지 정하고 그 x 를 넣어 식을 세웁니다. logₐx+logₐ(c−x)=logₐx(c−x) 처럼 진수를 하나로 묶으면 진수가 가장 클 때 y 도 가장 큽니다(a>1).',
             en:'Decide where the given M or m occurs and substitute that x. Combining logₐx+logₐ(c−x)=logₐx(c−x), y is greatest when the argument is greatest (a>1).',
             zh:'先确定所给M或m在何处取得，再代入该x列方程。把logₐx+logₐ(c−x)合成logₐx(c−x)，真数最大时y也最大(a>1)。'}}] },

MD140:{ name:{ko:'일반각과 호도법',en:'General Angles & Radians',zh:'任意角与弧度制'}, gen:'md140_radian', prereq:['MD39'],
  unit:'M-140',
  concept:{ko:'180°=π(라디안) 이므로 1°=π/180, 1 라디안=180°/π 입니다. 라디안 답은 π 의 몇 배인지(분수는 분모가 문제에 있습니다) 쓰고, 도 답은 ° 앞의 수를 씁니다.',
    en:'180°=π radians, so 1°=π/180 and 1 radian=180°/π. For a radian answer write how many times π it is (for a fraction the denominator is shown); for a degree answer write the number before °.',
    zh:'180°=π(弧度)，所以1°=π/180，1弧度=180°/π。弧度的答案写成π的几倍(分数的分母已在题中给出)，角度的答案写°前面的数。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'도와 라디안(연습)',en:'degrees and radians (practice)',zh:'角度与弧度(练习)'},params:{mode:'convert'}},
          {id:2,label:{ko:'동경이 있는 사분면',en:'quadrant of the terminal side',zh:'终边所在的象限'},params:{mode:'quad'},
           concept:{ko:'θ=360°×n+α(0°≤α<360°) 로 나타내면 θ 의 동경은 α 의 동경과 같습니다. 0°<α<90° 이면 제1사분면, 90°<α<180° 이면 제2사분면, 180°<α<270° 이면 제3사분면, 270°<α<360° 이면 제4사분면입니다.',
             en:'Writing θ=360°×n+α (0°≤α<360°), the terminal side of θ is that of α: quadrant 1 if 0°<α<90°, 2 if 90°<α<180°, 3 if 180°<α<270°, 4 if 270°<α<360°.',
             zh:'写成θ=360°×n+α(0°≤α<360°)后，θ的终边与α的终边相同：0°<α<90°在第一象限，90°<α<180°在第二象限，180°<α<270°在第三象限，270°<α<360°在第四象限。'}},
          {id:3,label:{ko:'동경이 같은 각(실전)',en:'angles with the same terminal side (main)',zh:'终边相同的角(实战)'},params:{mode:'coterm'},
           concept:{ko:'동경이 같은 각은 360° 의 정수 배(라디안으로 2π 의 정수 배)만큼 차이 납니다. 일반각 360°×n+α 에서 α 는 0° 이상 360° 미만, n 은 정수입니다. 음의 각이면 n 이 음수입니다.',
             en:'Angles with the same terminal side differ by an integer multiple of 360° (2π in radians). In the general angle 360°×n+α, α is at least 0° and less than 360° and n is an integer; for a negative angle n is negative.',
             zh:'终边相同的角相差360°的整数倍(弧度为2π的整数倍)。在一般角360°×n+α中，α不小于0°且小于360°，n为整数；负角时n为负数。'}}] },

MD141:{ name:{ko:'부채꼴의 호의 길이와 넓이',en:'Arc Length & Area of a Sector',zh:'扇形的弧长与面积'}, gen:'md141_sector', prereq:['MD140'],
  unit:'M-141',
  concept:{ko:'반지름이 r, 중심각이 θ(라디안) 인 부채꼴의 호의 길이는 l=rθ 입니다. 중심각이 도로 주어지면 먼저 라디안으로 바꿉니다. 답이 π 의 몇 배이면 □π 꼴로 물어봅니다.',
    en:'A sector with radius r and central angle θ (radians) has arc length l=rθ. If the angle is in degrees, change it to radians first. When the answer is a multiple of π, it is asked as □π.',
    zh:'半径为r、圆心角为θ(弧度)的扇形弧长l=rθ。圆心角以度给出时先化成弧度。答案是π的倍数时以□π的形式提问。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'부채꼴의 호의 길이(연습)',en:'arc length of a sector (practice)',zh:'扇形的弧长(练习)'},params:{mode:'arc'}},
          {id:2,label:{ko:'부채꼴의 넓이',en:'area of a sector',zh:'扇形的面积'},params:{mode:'area'},
           concept:{ko:'부채꼴의 넓이는 S=½r²θ=½rl 입니다. 반지름과 중심각이 주어지면 ½r²θ, 반지름과 호의 길이가 주어지면 ½rl 을 씁니다.',
             en:'The area of a sector is S=½r²θ=½rl. Use ½r²θ when the radius and angle are given and ½rl when the radius and arc length are given.',
             zh:'扇形面积S=½r²θ=½rl。已知半径与圆心角用½r²θ，已知半径与弧长用½rl。'}},
          {id:3,label:{ko:'둘레가 일정할 때 넓이의 최댓값(실전)',en:'greatest area for a fixed perimeter (main)',zh:'周长一定时面积的最大值(实战)'},params:{mode:'max'},
           concept:{ko:'둘레 2r+l=P 가 일정하면 S=½rl=½r(P−2r)=−(r−P/4)²+P²/16 입니다. r=P/4 일 때 넓이가 최대 M=P²/16 이고, "S=M" 은 넓이가 최대일 때를 뜻합니다.',
             en:'With a fixed perimeter 2r+l=P, S=½rl=½r(P−2r)=−(r−P/4)²+P²/16. The area is greatest, M=P²/16, when r=P/4; "S=M" means the moment the area is greatest.',
             zh:'周长2r+l=P一定时，S=½rl=½r(P−2r)=−(r−P/4)²+P²/16。r=P/4时面积最大M=P²/16；"S=M"表示面积最大时。'}}] },

MD142:{ name:{ko:'삼각함수의 정의와 관계',en:'Definitions & Relations of Trig Functions',zh:'三角函数的定义与关系'}, gen:'md142_trigDef', prereq:['MD140','MD39'],
  unit:'M-142',
  concept:{ko:'원점 O 에서 점 P(x, y) 로 그은 동경이 나타내는 각을 θ, OP=r 이라 하면 sinθ=y/r, cosθ=x/r, tanθ=y/x 입니다. 부호는 P 가 있는 사분면으로 정해집니다.',
    en:'Let θ be the angle whose terminal side runs from the origin O through P(x, y), with OP=r. Then sinθ=y/r, cosθ=x/r and tanθ=y/x; the signs come from the quadrant of P.',
    zh:'设从原点O到点P(x, y)的终边表示的角为θ，OP=r，则sinθ=y/r，cosθ=x/r，tanθ=y/x；符号由P所在的象限决定。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'동경 위의 점으로 삼각함수의 값(연습)',en:'trig values from a point (practice)',zh:'由终边上的点求三角函数值(练习)'},params:{mode:'point'}},
          {id:2,label:{ko:'sin²θ+cos²θ=1 과 tanθ',en:'sin²θ+cos²θ=1 and tanθ',zh:'sin²θ+cos²θ=1与tanθ'},params:{mode:'pyth'},
           concept:{ko:'sin²θ+cos²θ=1 로 나머지 값을 구하고, θ 의 범위(사분면)로 부호를 정합니다. tanθ 가 주어진 분수식은 분자·분모를 cosθ 로 나누어 tanθ 로 바꾸고, 1/cos²θ=1+tan²θ 입니다.',
             en:'Use sin²θ+cos²θ=1 to find the other value and the range of θ (its quadrant) for the sign. With tanθ given, divide the numerator and denominator by cosθ to write in tanθ; also 1/cos²θ=1+tan²θ.',
             zh:'用sin²θ+cos²θ=1求另一个值，由θ的范围(象限)定符号。已知tanθ时，把分子分母同除以cosθ化成tanθ；另外1/cos²θ=1+tan²θ。'}},
          {id:3,label:{ko:'sinθ±cosθ 와 sinθcosθ(실전)',en:'sinθ±cosθ and sinθcosθ (main)',zh:'sinθ±cosθ与sinθcosθ(实战)'},params:{mode:'sumprod'},
           concept:{ko:'(sinθ+cosθ)²=1+2sinθcosθ, (sinθ−cosθ)²=1−2sinθcosθ 입니다. tanθ+1/tanθ=1/(sinθcosθ), sin³θ+cos³θ=(sinθ+cosθ)(1−sinθcosθ) 도 씁니다. 분수가 되는 값은 앞에 곱한 수로 정수가 되게 묻습니다.',
             en:'(sinθ+cosθ)²=1+2sinθcosθ and (sinθ−cosθ)²=1−2sinθcosθ. Also tanθ+1/tanθ=1/(sinθcosθ) and sin³θ+cos³θ=(sinθ+cosθ)(1−sinθcosθ). Fractional values are asked with a multiplier in front so the answer is an integer.',
             zh:'(sinθ+cosθ)²=1+2sinθcosθ，(sinθ−cosθ)²=1−2sinθcosθ。还用到tanθ+1/tanθ=1/(sinθcosθ)，sin³θ+cos³θ=(sinθ+cosθ)(1−sinθcosθ)。分数值前面乘上一个数，使答案为整数。'}}] },

MD143:{ name:{ko:'삼각함수의 그래프와 각의 변환',en:'Trig Graphs & Angle Transformations',zh:'三角函数的图像与角的变换'}, gen:'md143_trigGraph', prereq:['MD142','MD57'],
  unit:'M-143',
  concept:{ko:'y=a sin bx+c, y=a cos bx+c(a>0, b>0) 의 최댓값은 M=a+c, 최솟값은 m=−a+c, 주기는 p=2π/b 입니다. 주어진 값으로 a 와 b 를 구해 두 칸에 씁니다.',
    en:'For y=a sin bx+c and y=a cos bx+c (a>0, b>0), the greatest value is M=a+c, the least value is m=−a+c and the period is p=2π/b. Find a and b from the given values and enter them in the two boxes.',
    zh:'y=a sin bx+c、y=a cos bx+c(a>0，b>0)的最大值M=a+c，最小值m=−a+c，周期p=2π/b。由所给的值求a与b，填在两格中。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'최댓값·최솟값과 주기로 미정계수(연습, 2다칸)',en:'unknowns from extreme values and period (practice, 2 slots)',zh:'由最值与周期求待定系数(练习，2格)'},params:{mode:'coef'}},
          {id:2,label:{ko:'각의 변환과 삼각함수의 값',en:'angle changes and trig values',zh:'角的变换与三角函数值'},params:{mode:'value'},
           concept:{ko:'sin(π+θ)=−sinθ, cos(π−θ)=−cosθ, sin(π/2+θ)=cosθ, tan(−θ)=−tanθ 처럼 바꾸면 7π/6, 3π/4, −π/3 등의 값은 π/6, π/4, π/3 의 값에 부호를 붙인 것입니다.',
             en:'Using sin(π+θ)=−sinθ, cos(π−θ)=−cosθ, sin(π/2+θ)=cosθ, tan(−θ)=−tanθ and so on, values at 7π/6, 3π/4, −π/3, … are the values at π/6, π/4, π/3 with a sign.',
             zh:'利用sin(π+θ)=−sinθ、cos(π−θ)=−cosθ、sin(π/2+θ)=cosθ、tan(−θ)=−tanθ等，7π/6、3π/4、−π/3等的值就是π/6、π/4、π/3的值加上符号。'}},
          {id:3,label:{ko:'각의 변환으로 식 간단히 하기(실전)',en:'simplifying with angle changes (main)',zh:'用角的变换化简(实战)'},params:{mode:'simplify'},
           concept:{ko:'π±θ, −θ 는 함수 이름을 그대로 두고, π/2±θ, 3π/2±θ 는 sin↔cos, tan↔1/tan 으로 바꿉니다. 부호는 θ 를 예각으로 볼 때 그 각이 있는 사분면에서 원래 함수가 갖는 부호입니다.',
             en:'For π±θ and −θ keep the function name; for π/2±θ and 3π/2±θ swap sin↔cos and tan↔1/tan. The sign is that of the original function in the quadrant of the angle when θ is taken as acute.',
             zh:'π±θ、−θ保持函数名不变；π/2±θ、3π/2±θ把sin↔cos、tan↔1/tan互换。符号看把θ当作锐角时该角所在象限中原函数的符号。'}}] },

/* ── MD144~MD153 대수 새 유형 2차(2026-09-29) — docs/high-build-spec.md 대수 뒤 10개.
   교재는 챕터 제목만 근거로 쓰고 문제는 새로 만든다. gen: engine/threads/mid22.js */
MD144:{ name:{ko:'삼각방정식과 삼각부등식',en:'Trig Equations & Inequalities',zh:'三角方程与三角不等式'}, gen:'md144_trigEq', prereq:['MD143','MD39'],
  unit:'M-144',
  concept:{ko:'2sin x=1 처럼 삼각함수 하나를 한 값으로 정리한 뒤, 단위원이나 그래프에서 그 값을 갖는 각을 주어진 범위에서 모두 찾습니다. sin 2x 처럼 각이 bx 이면 t=bx 의 범위가 b 배로 늘어납니다.',
    en:'Rearrange so that one trig function equals one value, as in 2sin x=1, then use the unit circle or graph to find every angle in the range with that value. When the angle is bx, as in sin 2x, the range of t=bx becomes b times as long.',
    zh:'像2sin x=1那样把一个三角函数整理成等于一个值，再借助单位圆或图像在给定范围内找出所有取这个值的角。像sin 2x那样角为bx时，t=bx的范围变为b倍。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'일차식 꼴 방정식의 해의 개수(연습)',en:'number of solutions of linear-form equations (practice)',zh:'一次式形式方程的解的个数(练习)'},params:{mode:'count'}},
          {id:2,label:{ko:'해의 합과 부등식의 해(도)',en:'sums of solutions and inequality ranges (degrees)',zh:'解之和与不等式的解(度)'},params:{mode:'sum'},
           concept:{ko:'방정식은 해를 모두 찾아 더합니다. 부등식 2sin x>1 은 y=sin x 의 그래프가 직선 y=½ 보다 위에 있는 x 의 범위이므로 30°<x<150° 입니다. 등호가 있으면 끝값도 포함합니다.',
             en:'For an equation, find every solution and add them. The inequality 2sin x>1 asks where the graph of y=sin x lies above y=½, so 30°<x<150°. With an equals sign the end values are included.',
             zh:'方程要找出所有解再相加。不等式2sin x>1是y=sin x的图像在直线y=½上方的x的范围，所以30°<x<150°。带等号时端点也包括在内。'}},
          {id:3,label:{ko:'이차식 꼴 삼각방정식(실전)',en:'quadratic-form trig equations (main)',zh:'二次式形式的三角方程(实战)'},params:{mode:'quad'},
           concept:{ko:'sin²x+cos²x=1 로 한 가지 함수로 모은 뒤 sin x=t 처럼 놓고 이차방정식을 풉니다. −1≤t≤1 을 벗어난 근은 해가 없으므로 버립니다.',
             en:'Use sin²x+cos²x=1 to write everything in one function, put sin x=t and solve the quadratic. Roots outside −1≤t≤1 give no angle, so discard them.',
             zh:'用sin²x+cos²x=1化成一种函数，令sin x=t解二次方程。超出−1≤t≤1的根没有对应的角，要舍去。'}}] },

MD145:{ name:{ko:'삼각형과 사각형의 넓이',en:'Areas of Triangles & Quadrilaterals',zh:'三角形与四边形的面积'}, gen:'md145_area', prereq:['MD55','MD56'],
  unit:'M-145',
  concept:{ko:'두 변의 길이와 그 끼인각을 알면 삼각형의 넓이는 S=½ab sinC 입니다. sin 의 값이 √3/2, √2/2 이면 넓이는 □√3, □√2 꼴로 답합니다.',
    en:'Given two sides and the included angle, a triangle has area S=½ab sinC. When the sine is √3/2 or √2/2, answer in the form □√3 or □√2.',
    zh:'已知两边及其夹角，三角形面积S=½ab sinC。sin的值为√3/2、√2/2时，面积按□√3、□√2的形式作答。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'두 변과 끼인각으로 넓이(연습)',en:'area from two sides and the included angle (practice)',zh:'由两边及夹角求面积(练习)'},params:{mode:'sas'}},
          {id:2,label:{ko:'세 변으로 넓이',en:'area from three sides',zh:'由三边求面积'},params:{mode:'heron'},
           concept:{ko:'세 변만 알 때는 헤론의 공식 S=√(s(s−a)(s−b)(s−c)), s=(a+b+c)/2 를 씁니다. 넓이를 알면 내접원의 반지름은 S=rs 로, 외접원의 반지름은 S=abc/(4R) 로 구합니다.',
             en:'With only the three sides, use Heron’s formula S=√(s(s−a)(s−b)(s−c)), s=(a+b+c)/2. From the area, the inradius comes from S=rs and the circumradius from S=abc/(4R).',
             zh:'只知道三边时用海伦公式S=√(s(s−a)(s−b)(s−c))，s=(a+b+c)/2。知道面积后，由S=rs求内切圆半径，由S=abc/(4R)求外接圆半径。'}},
          {id:3,label:{ko:'평행사변형과 사각형의 넓이(실전)',en:'areas of parallelograms and quadrilaterals (main)',zh:'平行四边形与四边形的面积(实战)'},params:{mode:'quad'},
           concept:{ko:'평행사변형은 대각선으로 합동인 삼각형 두 개로 나뉘므로 S=ab sinθ 입니다. 대각선의 길이가 p, q 이고 두 대각선이 이루는 각이 θ 인 사각형은 S=½pq sinθ 입니다.',
             en:'A diagonal splits a parallelogram into two congruent triangles, so S=ab sinθ. A quadrilateral with diagonals p and q meeting at angle θ has S=½pq sinθ.',
             zh:'平行四边形被对角线分成两个全等三角形，所以S=ab sinθ。对角线长为p、q且两对角线所成角为θ的四边形，S=½pq sinθ。'}}] },

MD146:{ name:{ko:'수열의 합과 일반항의 관계',en:'Sₙ and aₙ',zh:'数列的和与通项的关系'}, gen:'md146_snAn', prereq:['MD40'],
  unit:'M-146',
  concept:{ko:'첫째항부터 제n항까지의 합을 Sₙ 이라 하면 a₁=S₁ 이고, n≥2 일 때 aₙ=Sₙ−Sₙ₋₁ 입니다. 여러 항의 합 aₘ+…+aₙ 은 Sₙ−Sₘ₋₁ 로 한 번에 구합니다.',
    en:'With Sₙ the sum from the first term to the nth, a₁=S₁ and, for n≥2, aₙ=Sₙ−Sₙ₋₁. A block of terms aₘ+…+aₙ is Sₙ−Sₘ₋₁ in one step.',
    zh:'设从首项到第n项的和为Sₙ，则a₁=S₁，n≥2时aₙ=Sₙ−Sₙ₋₁。若干项之和aₘ+…+aₙ可一次用Sₙ−Sₘ₋₁求出。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'Sₙ 에서 aₙ 구하기(연습)',en:'aₙ from Sₙ (practice)',zh:'由Sₙ求aₙ(练习)'},params:{mode:'an'}},
          {id:2,label:{ko:'a₁ 을 따로 구하는 경우',en:'when a₁ must be found separately',zh:'需要单独求a₁的情形'},params:{mode:'a1'},
           concept:{ko:'Sₙ=pn²+qn+r(r≠0) 이나 Sₙ=c·bⁿ+d 처럼 상수가 맞지 않으면 aₙ=Sₙ−Sₙ₋₁ 은 n≥2 에서만 성립합니다. a₁ 은 반드시 S₁ 로 따로 구합니다.',
             en:'If the constant does not fit, as in Sₙ=pn²+qn+r (r≠0) or Sₙ=c·bⁿ+d, then aₙ=Sₙ−Sₙ₋₁ holds only for n≥2. Always find a₁ separately as S₁.',
             zh:'若常数不吻合，如Sₙ=pn²+qn+r(r≠0)或Sₙ=c·bⁿ+d，则aₙ=Sₙ−Sₙ₋₁只在n≥2时成立。a₁一定要单独用S₁求。'}},
          {id:3,label:{ko:'첫째항부터 등차·등비가 될 조건(실전)',en:'conditions for arithmetic or geometric from the first term (main)',zh:'从首项起成等差或等比的条件(实战)'},params:{mode:'judge'},
           concept:{ko:'Sₙ=pn²+qn+r 인 수열이 첫째항부터 등차수열이면 r=0 이고, Sₙ=c·bⁿ+k 인 수열이 첫째항부터 등비수열이면 k=−c 입니다. 조건이 n=1 에서도 성립하도록 a₁=S₁ 을 n≥2 의 식에 맞춥니다.',
             en:'A sequence with Sₙ=pn²+qn+r is arithmetic from the first term exactly when r=0, and one with Sₙ=c·bⁿ+k is geometric from the first term exactly when k=−c. Make a₁=S₁ fit the formula for n≥2 so the condition holds at n=1 too.',
             zh:'Sₙ=pn²+qn+r的数列从首项起成等差数列当且仅当r=0；Sₙ=c·bⁿ+k的数列从首项起成等比数列当且仅当k=−c。让a₁=S₁符合n≥2的式子，使条件在n=1时也成立。'}}] },

MD147:{ name:{ko:'등차수열의 합의 최대·최소',en:'Max & Min of Arithmetic Series',zh:'等差数列前n项和的最值'}, gen:'md147_apExtreme', prereq:['MD40'],
  unit:'M-147',
  concept:{ko:'공차가 음수인 등차수열은 항이 점점 작아져 어느 항부터 음수가 됩니다. 일반항 aₙ=a₁+(n−1)d 로 aₙ<0 을 풀면 부호가 바뀌는 첫 항을 찾을 수 있습니다.',
    en:'An arithmetic sequence with a negative common difference keeps decreasing and becomes negative from some term on. Solving aₙ<0 with aₙ=a₁+(n−1)d finds the first term where the sign changes.',
    zh:'公差为负的等差数列项越来越小，从某一项起变为负数。用通项aₙ=a₁+(n−1)d解aₙ<0，就能找到符号改变的第一项。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'부호가 바뀌는 항(연습)',en:'where the sign changes (practice)',zh:'符号改变的项(练习)'},params:{mode:'sign'}},
          {id:2,label:{ko:'합의 최댓값·최솟값',en:'greatest and least sums',zh:'和的最大值与最小值'},params:{mode:'max'},
           concept:{ko:'감소하는 등차수열의 합 Sₙ 은 양수인 항을 모두 더했을 때 가장 큽니다. 0 인 항이 있으면 그 항을 더하기 전과 후의 합이 같아 최댓값이 되는 n 이 두 개입니다.',
             en:'For a decreasing arithmetic sequence, Sₙ is greatest once every positive term has been added. If some term is 0, the sums before and after adding it are equal, so two values of n give the maximum.',
             zh:'递减等差数列的和Sₙ在加完所有正项时最大。若有一项为0，加这一项前后的和相等，使和最大的n有两个。'}},
          {id:3,label:{ko:'조건에서 합의 최대·최소(실전)',en:'extreme sums from conditions (main)',zh:'由条件求和的最值(实战)'},params:{mode:'cond'},
           concept:{ko:'두 항이 주어지면 공차와 첫째항을 먼저 구합니다. Sₚ=S_q(p<q) 이면 aₚ₊₁+…+a_q=0 이므로 aₚ₊₁+a_q=0 이고, 합은 가운데 n=(p+q)/2 에서 최대입니다.',
             en:'Given two terms, find the common difference and first term first. If Sₚ=S_q (p<q), then aₚ₊₁+…+a_q=0, so aₚ₊₁+a_q=0 and the sum is greatest in the middle, at n=(p+q)/2.',
             zh:'给出两项时先求公差与首项。若Sₚ=S_q(p<q)，则aₚ₊₁+…+a_q=0，所以aₚ₊₁+a_q=0，和在中间n=(p+q)/2处最大。'}}] },

MD148:{ name:{ko:'원리합계',en:'Compound Savings',zh:'本利和'}, gen:'md148_annuity', prereq:['MD41'],
  unit:'M-148',
  concept:{ko:'원금 a 를 이율 r 로 n 번 복리 계산하면 원리합계는 a(1+r)ⁿ 입니다. 같은 금액을 여러 번 적립하면 각 금액의 원리합계가 등비수열을 이루므로 등비수열의 합으로 한 번에 구합니다. 거듭제곱의 값은 문제에 주어진 값을 씁니다.',
    en:'A principal a compounded n times at rate r grows to a(1+r)ⁿ. When the same amount is deposited repeatedly, the amounts form a geometric sequence, so add them with the geometric-series formula. Use the power values given in the problem.',
    zh:'本金a按利率r复利计算n次，本利和为a(1+r)ⁿ。多次存入同样的金额时，各笔的本利和成等比数列，用等比数列求和公式一次求出。幂的值用题中给出的值。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'예금과 적금의 원리합계(연습)',en:'totals of deposits and savings plans (practice)',zh:'存款与零存整取的本利和(练习)'},params:{mode:'save'}},
          {id:2,label:{ko:'적립할 금액과 갚을 금액',en:'payments to save or repay',zh:'应存入与应偿还的金额'},params:{mode:'pay'},
           concept:{ko:'매 기간 말에 a 씩 n 번 적립하면 원리합계는 a{(1+r)ⁿ−1}/r, 매 기간 초이면 여기에 (1+r) 을 곱합니다. 목표 금액이 주어지면 이 식을 a 에 대해 풉니다. 빌린 돈을 나누어 갚을 때는 빌린 돈의 원리합계와 갚은 돈의 원리합계가 같습니다.',
             en:'Depositing a at the end of each period n times gives a{(1+r)ⁿ−1}/r; at the start of each period, multiply this by (1+r). Given the target, solve for a. When repaying a loan in instalments, the loan’s total equals the total of the repayments.',
             zh:'每期期末存a共n次，本利和为a{(1+r)ⁿ−1}/r；每期期初存入则再乘(1+r)。给出目标金额时解出a。分期偿还借款时，借款的本利和等于还款的本利和。'}},
          {id:3,label:{ko:'저축 방법 비교(실전)',en:'comparing savings plans (main)',zh:'比较储蓄方式(实战)'},params:{mode:'compare'},
           concept:{ko:'단리는 원금에만 이자가 붙어 a(1+rn), 복리는 이자에도 이자가 붙어 a(1+r)ⁿ 입니다. 비교하는 두 방법을 같은 시점(마지막 해의 말)의 원리합계로 맞춘 뒤 뺍니다.',
             en:'Simple interest earns only on the principal, a(1+rn); compound interest also earns on interest, a(1+r)ⁿ. Bring both plans to the same moment (the end of the last year) before subtracting.',
             zh:'单利只对本金计息，为a(1+rn)；复利对利息也计息，为a(1+r)ⁿ。把两种方式都换算到同一时刻(最后一年年末)的本利和再相减。'}}] },

MD149:{ name:{ko:'여러 가지 수열의 합',en:'Sums of Special Sequences',zh:'各种数列的求和'}, gen:'md149_seriesSum', prereq:['MD42','MD41'],
  unit:'M-149',
  concept:{ko:'1/(k(k+1))=1/k−1/(k+1) 처럼 한 항을 두 분수의 차로 나누면, 더할 때 가운데 항이 차례로 지워지고 처음과 끝만 남습니다. 약분한 결과의 분모가 주어지면 분자를 답합니다.',
    en:'Splitting each term into a difference of two fractions, such as 1/(k(k+1))=1/k−1/(k+1), makes the middle terms cancel in turn when added, leaving only the first and last. If the reduced denominator is shown, give the numerator.',
    zh:'像1/(k(k+1))=1/k−1/(k+1)那样把每项拆成两个分数之差，相加时中间的项依次消去，只剩首尾。若给出约分后的分母，就答分子。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'부분분수로 나누어 더하기(연습)',en:'sums by partial fractions (practice)',zh:'拆项相消求和(练习)'},params:{mode:'frac'}},
          {id:2,label:{ko:'분모의 유리화로 더하기',en:'sums by rationalizing',zh:'分母有理化求和'},params:{mode:'root'},
           concept:{ko:'1/(√(k+1)+√k) 의 분모를 유리화하면 √(k+1)−√k 가 되어 합이 √(끝+1)−√(처음) 만 남습니다. 끝값이 제곱수가 되도록 문제를 만들었으므로 답은 자연수입니다.',
             en:'Rationalizing 1/(√(k+1)+√k) gives √(k+1)−√k, so the sum leaves only √(last+1)−√(first). The end values are perfect squares, so the answer is a whole number.',
             zh:'把1/(√(k+1)+√k)的分母有理化得√(k+1)−√k，和只剩√(末项+1)−√(首项)。端值都是平方数，所以答案是自然数。'}},
          {id:3,label:{ko:'(등차)×(등비) 꼴의 합(실전)',en:'sums of (arithmetic)×(geometric) terms (main)',zh:'(等差)×(等比)型数列求和(实战)'},params:{mode:'ag'},
           concept:{ko:'S=1·2+2·2²+3·2³+… 에 공비 2 를 곱한 2S 를 한 칸 밀어 쓰고 S−2S 를 계산하면 등비수열의 합과 마지막 항만 남습니다.',
             en:'For S=1·2+2·2²+3·2³+…, write 2S shifted one place and compute S−2S; what remains is a geometric sum and the last term.',
             zh:'对S=1·2+2·2²+3·2³+…，把乘以公比2的2S错开一位写出，计算S−2S，只剩一个等比数列的和与最后一项。'}}] },

MD150:{ name:{ko:'군수열',en:'Grouped Sequences',zh:'分群数列'}, gen:'md150_groupSeq', prereq:['MD42','MD40'],
  unit:'M-150',
  concept:{ko:'규칙에 따라 괄호로 묶은 수열에서 괄호 하나를 군이라 합니다. 제 g 군까지 들어 있는 항의 수(1+2+…+g 등)나 제 g 군의 마지막 수로 범위를 잡으면 어떤 수가 몇 번째 군에 있는지 알 수 있습니다.',
    en:'When a sequence is bracketed by a rule, each bracket is a group. Bounding by the number of terms up to group g (1+2+…+g and so on) or by the last number of group g tells which group a number is in.',
    zh:'按规律用括号分开的数列中，一个括号叫一个群。用到第g群为止的项数(1+2+…+g等)或第g群的最后一个数夹出范围，就知道某数在第几群。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'몇 번째 군인지 찾기(연습)',en:'which group (practice)',zh:'求在第几群(练习)'},params:{mode:'group'}},
          {id:2,label:{ko:'군 안에서의 순서와 항의 값',en:'position within a group and term values',zh:'群内的位置与项的值'},params:{mode:'pos'},
           concept:{ko:'제 (g−1) 군까지의 항의 수를 N 이라 하면 aₘ 은 제 g 군의 (m−N) 번째 항입니다. 각 군의 규칙(1, 2, …, g 또는 g, g−1, … 등)에 그 순서를 넣어 값을 구합니다.',
             en:'If N terms come before group g, then aₘ is the (m−N)th term of group g. Put that position into the group’s rule (1, 2, …, g or g, g−1, … and so on) to get the value.',
             zh:'设到第(g−1)群为止共有N项，则aₘ是第g群的第(m−N)项。把这个序号代入群的规律(1, 2, …, g或g, g−1, …等)求值。'}},
          {id:3,label:{ko:'군의 합과 첫째항부터의 합(실전)',en:'group sums and partial sums (main)',zh:'群的和与前若干项的和(实战)'},params:{mode:'gsum'},
           concept:{ko:'한 군의 합 T_g 는 그 군의 첫 수와 끝 수, 항의 수로 구합니다. 첫째항부터 aₘ 까지의 합은 완전한 군들의 합 T₁+…+T_{g−1} 에 마지막 군의 앞부분을 더합니다.',
             en:'A group sum T_g comes from the group’s first and last numbers and its number of terms. The sum up to aₘ is the full groups T₁+…+T_{g−1} plus the front part of the last group.',
             zh:'群的和T_g由该群的首末两数及项数求出。到aₘ为止的和等于完整各群的和T₁+…+T_{g−1}再加上最后一群的前一部分。'}}] },

MD151:{ name:{ko:'수열의 귀납적 정의',en:'Recursive Definitions of Sequences',zh:'数列的递推定义'}, gen:'md151_recDef', prereq:['MD40','MD41'],
  unit:'M-151',
  concept:{ko:'첫째항과 이웃한 항 사이의 관계식으로 수열을 정하는 것을 귀납적 정의라 합니다. aₙ₊₁=aₙ+d 는 공차 d 인 등차수열, 2aₙ₊₁=aₙ+aₙ₊₂ 도 등차수열입니다.',
    en:'Defining a sequence by its first term and a relation between neighbouring terms is a recursive definition. aₙ₊₁=aₙ+d is arithmetic with difference d, and so is 2aₙ₊₁=aₙ+aₙ₊₂.',
    zh:'用首项和相邻项之间的关系式确定数列，叫做递推定义。aₙ₊₁=aₙ+d是公差为d的等差数列，2aₙ₊₁=aₙ+aₙ₊₂也是等差数列。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'등차수열의 귀납적 정의(연습)',en:'arithmetic recursive definitions (practice)',zh:'等差数列的递推定义(练习)'},params:{mode:'arith'}},
          {id:2,label:{ko:'등비수열의 귀납적 정의',en:'geometric recursive definitions',zh:'等比数列的递推定义'},params:{mode:'geo'},
           concept:{ko:'aₙ₊₁=raₙ, aₙ₊₁÷aₙ=r, aₙ₊₁²=aₙaₙ₊₂ 는 등비수열을 뜻합니다. 첫째항과 공비로 aₖ=a₁rᵏ⁻¹ 을 계산하고, 값이 주어지면 거꾸로 k 를 찾습니다.',
             en:'aₙ₊₁=raₙ, aₙ₊₁÷aₙ=r and aₙ₊₁²=aₙaₙ₊₂ describe geometric sequences. Compute aₖ=a₁rᵏ⁻¹ from the first term and ratio, or work back to k from a given value.',
             zh:'aₙ₊₁=raₙ、aₙ₊₁÷aₙ=r、aₙ₊₁²=aₙaₙ₊₂表示等比数列。用首项和公比计算aₖ=a₁rᵏ⁻¹，给出值时反求k。'}},
          {id:3,label:{ko:'여러 항 사이의 관계(실전)',en:'relations among several terms (main)',zh:'多项之间的关系(实战)'},params:{mode:'two'},
           concept:{ko:'aₙ₊₂=paₙ₊₁+qaₙ 처럼 앞의 두 항으로 정해지면 n=1, 2, 3, … 을 차례로 넣습니다. aₙ₊₂=aₙ₊₁−aₙ 은 6 개마다, aₙ₊₁+aₙ=c 와 aₙaₙ₊₁=c 는 2 개마다 같은 값이 되풀이됩니다.',
             en:'When each term depends on the two before it, as in aₙ₊₂=paₙ₊₁+qaₙ, substitute n=1, 2, 3, … in order. aₙ₊₂=aₙ₊₁−aₙ repeats every 6 terms, and aₙ₊₁+aₙ=c and aₙaₙ₊₁=c repeat every 2.',
             zh:'像aₙ₊₂=paₙ₊₁+qaₙ那样由前两项决定时，依次代入n=1, 2, 3, …。aₙ₊₂=aₙ₊₁−aₙ每6项循环，aₙ₊₁+aₙ=c与aₙaₙ₊₁=c每2项循环。'}}] },

MD152:{ name:{ko:'점화식',en:'Recurrence Relations',zh:'递推公式'}, gen:'md152_recurrence', prereq:['MD151','MD42'],
  unit:'M-152',
  concept:{ko:'aₙ₊₁=aₙ+f(n) 이면 n 에 1, 2, …, k−1 을 넣은 식을 모두 더해 aₖ=a₁+f(1)+f(2)+…+f(k−1) 을 얻습니다. 계차 f(n) 의 합은 Σ 공식으로 구합니다.',
    en:'If aₙ₊₁=aₙ+f(n), add the equations for n=1, 2, …, k−1 to get aₖ=a₁+f(1)+f(2)+…+f(k−1). Sum the differences f(n) with the Σ formulas.',
    zh:'若aₙ₊₁=aₙ+f(n)，把n=1, 2, …, k−1代入的各式相加得aₖ=a₁+f(1)+f(2)+…+f(k−1)。阶差f(n)的和用Σ公式求。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'aₙ₊₁=aₙ+f(n) 꼴(연습)',en:'the form aₙ₊₁=aₙ+f(n) (practice)',zh:'aₙ₊₁=aₙ+f(n)型(练习)'},params:{mode:'add'}},
          {id:2,label:{ko:'aₙ₊₁=aₙ·f(n) 꼴',en:'the form aₙ₊₁=aₙ·f(n)',zh:'aₙ₊₁=aₙ·f(n)型'},params:{mode:'mul'},
           concept:{ko:'aₙ₊₁=aₙ·f(n) 이면 n 에 1, 2, …, k−1 을 넣은 식을 모두 곱해 aₖ=a₁·f(1)·f(2)·…·f(k−1) 입니다. f(n)=(n+1)/n 처럼 분수이면 곱할 때 분자와 분모가 엇갈려 지워집니다.',
             en:'If aₙ₊₁=aₙ·f(n), multiply the equations for n=1, 2, …, k−1 to get aₖ=a₁·f(1)·f(2)·…·f(k−1). When f(n) is a fraction such as (n+1)/n, numerators and denominators cancel crosswise.',
             zh:'若aₙ₊₁=aₙ·f(n)，把n=1, 2, …, k−1代入的各式相乘得aₖ=a₁·f(1)·f(2)·…·f(k−1)。f(n)像(n+1)/n那样是分数时，相乘时分子分母交错约去。'}},
          {id:3,label:{ko:'여러 가지 점화식의 항(실전)',en:'terms of other recurrences (main)',zh:'各种递推公式的项(实战)'},params:{mode:'term'},
           concept:{ko:'aₙ₊₁=paₙ+q 는 α=pα+q 인 α 로 aₙ₊₁−α=p(aₙ−α) 가 되어 {aₙ−α} 가 등비수열입니다. aₙ₊₁=aₙ/(caₙ+1) 은 역수를 취하면, aₙ₊₁=raₙ+rⁿ⁺¹ 은 rⁿ⁺¹ 로 나누면 등차수열이 됩니다.',
             en:'For aₙ₊₁=paₙ+q, the α with α=pα+q gives aₙ₊₁−α=p(aₙ−α), so {aₙ−α} is geometric. aₙ₊₁=aₙ/(caₙ+1) becomes arithmetic after taking reciprocals, and aₙ₊₁=raₙ+rⁿ⁺¹ after dividing by rⁿ⁺¹.',
             zh:'aₙ₊₁=paₙ+q用满足α=pα+q的α化成aₙ₊₁−α=p(aₙ−α)，{aₙ−α}成等比数列。aₙ₊₁=aₙ/(caₙ+1)取倒数、aₙ₊₁=raₙ+rⁿ⁺¹除以rⁿ⁺¹后都成等差数列。'}}] },

MD153:{ name:{ko:'수학적 귀납법',en:'Mathematical Induction',zh:'数学归纳法'}, gen:'md153_induction', prereq:['MD151','MD42'],
  unit:'M-153',
  concept:{ko:'모든 자연수 n 에 대한 명제는 ① n=1(처음 값)일 때 성립하고 ② n=k 일 때 성립하면 n=k+1 일 때도 성립함을 보이면 증명됩니다. 처음 값을 확인하는 것이 첫 단계입니다.',
    en:'A statement about every natural number n is proved by showing ① it holds for n=1 (the first value) and ② if it holds for n=k, it also holds for n=k+1. Checking the first value is the first step.',
    zh:'关于所有自然数n的命题，只要证明①n=1(最初的值)时成立，②n=k时成立则n=k+1时也成立，就得证。验证最初的值是第一步。'},
  widgets:['numpad'],
  levels:[{id:1,label:{ko:'처음 값 확인(연습)',en:'checking the first value (practice)',zh:'验证最初的值(练习)'},params:{mode:'base'}},
          {id:2,label:{ko:'n=k+1 에서 더하는 항',en:'the term added at n=k+1',zh:'n=k+1时所加的项'},params:{mode:'step'},
           concept:{ko:'n=k 일 때의 등식 양변에 (k+1) 번째 항을 더하면 n=k+1 일 때의 좌변이 됩니다. 더하는 항은 일반항의 i 자리에 k+1 을 넣은 것입니다.',
             en:'Adding the (k+1)th term to both sides of the equation for n=k gives the left side for n=k+1. The added term is the general term with k+1 in place of i.',
             zh:'在n=k时等式的两边加上第(k+1)项，就得到n=k+1时的左边。所加的项是把通项中的i换成k+1。'}},
          {id:3,label:{ko:'등식이 성립하도록 계수 정하기(실전)',en:'choosing coefficients so the identity holds (main)',zh:'确定系数使等式成立(实战)'},params:{mode:'coef'},
           concept:{ko:'빈칸의 수는 n=1, 2 를 넣어 먼저 정하고, n=k 에서 n=k+1 로 넘어갈 때도 등식이 유지되는지 확인합니다. 두 단계를 모두 통과해야 모든 자연수에서 성립합니다.',
             en:'Fix the number in the blank by substituting n=1, 2, then check the identity survives the step from n=k to n=k+1. Only after both steps does it hold for every natural number.',
             zh:'先代入n=1, 2确定空格中的数，再检验从n=k到n=k+1时等式是否仍成立。两步都通过才对所有自然数成立。'}}] },
};

if(typeof module!=='undefined'&&module.exports)module.exports=window.NM_THREADS;
})();
